INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'Al principio creó Dios el cielo y la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'La tierra era confusión y caos, y tinieblas cubrían la faz del abismo, mas el Espíritu de Dios se movía sobre las aguas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Y dijo Dios: “Haya luz”; y hubo luz.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Vio Dios que la luz era buena; y separó Dios la luz de las tinieblas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Llamó Dios a la luz día, y a las tinieblas llamó noche. Y hubo tarde y hubo mañana: primer día.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Después dijo Dios: “Haya un firmamento en medio de las aguas que separe unas aguas de otras”.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'E hizo Dios el firmamento, y separó las aguas que estaban bajo el firmamento de las aguas que estaban sobre el firmamento. Y así fue.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Llamó Dios al firmamento cielo; y hubo tarde y hubo mañana: día segundo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Y dijo Dios: “Júntense en un lugar las aguas que quedan bajo el cielo y aparezca lo seco”.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Llamó Dios a lo seco tierra, y a la reunión de las aguas llamó mares. Y vio Dios que estaba bien.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Después dijo Dios: “Brote la tierra hierba verde, plantas que den semilla, árboles frutales que produzcan fruto según su especie y cuya semilla esté en ellos sobre la tierra”. Y así fue.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'Brotó, pues, la tierra hierba verde, plantas que tenían en sí semilla según su especie, y árboles que producían frutos y cuya semilla se hallaba en ellos según su especie. Y vio Dios que estaba bien.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Y hubo tarde y hubo mañana: día tercero.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Luego dijo Dios: “Haya lumbreras en el firmamento del cielo, que separen el día de la noche y sirvan de señales y (marquen) las estaciones, días y años.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'Sirvan también de lumbreras en el firmamento del cielo para alumbrar la tierra”. Y así fue.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Hizo, pues, Dios las dos grandes lumbreras: la lumbrera mayor para presidir el día, y la lumbrera menor para presidir la noche, y las estrellas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Púsolas Dios en el firmamento del cielo para alumbrar la tierra,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'para regir el día y la noche y para separar la luz de las tinieblas. Y vio Dios que estaba bien.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Y hubo tarde y hubo mañana: día cuarto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Después dijo Dios: “Pululen las aguas multitud de seres vivientes; y vuelen aves sobre la tierra debajo del firmamento del cielo”.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Y creó Dios los grandes monstruos marinos, y todos los seres vivientes que marchan arrastrándose, de los cuales hierven las aguas, según su especie; y toda ave alada según su especie. Y vio Dios que estaba bien.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Y Dios los bendijo, diciendo: “Sed fecundos y multiplicaos y henchid las aguas en los mares; y multiplíquense las aves sobre la tierra”.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Y hubo tarde y hubo mañana: día quinto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Luego Dios dijo: “Produzca la tierra seres vivientes según su especie: animales domésticos, reptiles, bestias salvajes, según su especie”. Y así fue.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Hizo, pues, Dios las bestias salvajes según su especie, y los animales domésticos según su especie, y todo reptil de la tierra según su especie. Y vio Dios que estaba bien.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Después dijo Dios: “Hagamos al hombre a imagen nuestra, según nuestra semejanza; y domine sobre los peces del mar y las aves del cielo, sobre las bestias domésticas, y sobre toda la tierra y todo reptil que se mueve sobre la tierra”.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Y creó Dios al hombre a imagen suya; a imagen de Dios lo creó; varón y mujer los creó.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Los bendijo Dios; y les dijo Dios: “Sed fecundos y multiplicaos, y henchid la tierra y sometedla; y dominad sobre los peces del mar y las aves del cielo, y sobre todos los animales que se mueven sobre la tierra”.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Después dijo Dios: “He aquí que Yo os doy toda planta portadora de semilla sobre la superficie de toda la tierra, y todo árbol en que hay fruto de árbol con semilla, para que os sirvan de alimento.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'Y a todos los animales de la tierra, y a todas las aves del cielo, y a todo lo que se mueve sobre la tierra, que tiene en sí aliento de vida, les doy para alimento toda hierba verde”. Y así fue.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Vio Dios todo cuanto había hecho; y he aquí que estaba muy bien. Y hubo tarde y hubo mañana: día sexto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Fueron, pues, acabados el cielo y la tierra con todo el ornato de ellos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'El día séptimo terminó Dios la obra que había hecho; y descansó en el día séptimo de toda la obra que había hecho.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Y bendijo Dios el séptimo día y lo santificó; porque en él descansó Dios de toda su obra que en la creación había realizado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Esta es la historia de la creación del cielo y de la tierra. El día en que Yahvé Dios creó la tierra y el cielo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'no había aún en la tierra arbusto campestre alguno; y ninguna planta del campo había germinado todavía, pues Yahvé Dios no había hecho llover sobre la tierra, ni había hombre que labrase el suelo;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'pero brotaba una fuente de la tierra, que regaba toda la superficie de la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Y formó Yahvé Dios al hombre (del) polvo de la tierra e insufló en sus narices aliento de vida, de modo que el hombre vino a ser alma viviente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Y plantó Yahvé Dios un jardín en Edén, al oriente, donde colocó al hombre que había formado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Yahvé Dios hizo brotar de la tierra toda clase de árboles de hermoso aspecto y (de frutos) buenos para comer, y en el medio del jardín el árbol de la vida, y el árbol del conocimiento del bien y del mal.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'De Edén salía un río que regaba el jardín; y desde allí se dividía y se formaban de él cuatro brazos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'El nombre del primero es Fisón, el cual rodea toda la tierra de Havilá, donde está el oro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'El oro de aquella tierra es fino. Allí se encuentra también el bedelio y la piedra de ónice.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'El nombre del segundo río es Gihón, que circunda toda la tierra de Cus.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'El tercer río se llama Tigris, el cual corre al oriente de Asir. Y el cuarto río es el Éufrates.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Tomó, pues, Yahvé Dios al hombre y lo llevó al jardín de Edén, para que lo labrara y lo cuidase.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Y mandó Yahvé Dios al hombre, diciendo: “De cualquier árbol del jardín puedes comer,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'mas del árbol del conocimiento del bien y del mal, no comerás; porque el día en que comieres de él, morirás sin remedio”.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Entonces dijo Yahvé Dios: “No es bueno que el hombre esté solo; le haré una ayuda semejante a él”.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Formados, pues, de la tierra todos los animales del campo y todas las aves del cielo, los hizo Yahvé Dios desfilar ante el hombre para ver cómo los llamaba, y para que el nombre de todos los seres vivientes fuese aquel que les pusiera el hombre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Así, pues, el hombre puso nombres a todos los animales domésticos, y a las aves del cielo, y a todas las bestias del campo; mas para el hombre no encontró una ayuda semejante a él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Entonces Yahvé Dios hizo caer un profundo sueño sobre el hombre, el cual se durmió; y le quitó una de las costillas y cerró con carne el lugar de la misma.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'De la costilla que Yahvé Dios había tomado del hombre, formó una mujer y la condujo ante el hombre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Y dijo el hombre: “Esta vez sí es hueso de mis huesos y carne de mi carne; esta será llamada varona, porque del varón ha sido tomada”.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Por eso dejará el hombre a su padre y a su madre y se adherirá a su mujer, y vendrán a ser una sola carne.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Estaban ambos desnudos, Adán y su mujer, mas no se avergonzaban.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'La serpiente, que era el más astuto de todos los animales del campo que Yahvé Dios había hecho, dijo a la mujer: “¿Cómo es que Dios ha mandado “No comáis de ningún árbol del jardín”?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Respondió la mujer a la Serpiente: “Podemos comer del fruto de los árboles del jardín;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'mas del fruto del árbol que está en medio del jardín, ha dicho Dios: “No comáis de él, ni lo toquéis, no sea que muráis”.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Replicó la serpiente a la mujer: “De ninguna manera moriréis;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'pues bien sabe Dios que el día en que comiereis de él, se os abrirán los ojos y seréis como Dios, conocedores del bien y del mal”.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Y como viese la mujer que el árbol era bueno para comida y una delicia para los ojos, y que el árbol era apetecible para alcanzar sabiduría, tomó de su fruto y comió y dio también a su marido (que estaba) con ella, y él comió también.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Efectivamente se les abrieron a entrambos los ojos, y se dieron cuenta de que estaba desnudos; por lo cual cosieron hojas de higuera y se hicieron delantales.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Cuando oyeron el rumor de Yahvé Dios que se paseaba en el jardín al tiempo de la brisa del día, Adán y su mujer se ocultaron de la vista de Yahvé Dios por entre los árboles del jardín.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Yahvé Dios llamó a Adán y le dijo: “¿Dónde estás?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Este contestó: “Oí tu paso por el jardín y tuve miedo, porque estoy desnudo; por eso me escondí”.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Mas Él dijo: “¿Quién te ha dicho que estás desnudo? ¿Has comido acaso del árbol del cual te prohibí comer?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Respondió Adán: “La mujer que me diste por compañera me dio del árbol, y comí.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Dijo luego Yahvé Dios a la mujer: “¿Qué es lo que has hecho?” Y contestó la mujer: “La serpiente me engañó, y comí.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Entonces dijo Yahvé Dios a la serpiente: “Por haber hecho esto, serás maldita como ninguna otra bestia doméstica o salvaje. Sobre tu vientre caminarás, y polvo comerás todos los días de tu vida.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Y pondré enemistad entre ti y la mujer, y entre tu linaje y su linaje: este te aplastará la cabeza, y tú le aplastarás el calcañar.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Después dijo a la mujer: “Multiplicaré tus dolores y tus preñeces; con dolor darás hijos a luz; te sentirás atraída por tu marido, pero él te dominará.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'A Adán le dijo: “Por haber escuchado la voz de tu mujer y comido del árbol del que Yo te había prohibido comer, será maldita la tierra por tu causa; con doloroso trabajo te alimentarás de ella todos los días de tu vida;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'te producirá espinas y abrojos, y comerás de las hierbas del campo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'Con el sudor de tu rostro comerás el pan, hasta que vuelvas a la tierra; pues de ella fuiste tomado. Polvo eres y al polvo volverás.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Adán puso a su mujer el nombre de Eva, por ser ella la madre de todos los vivientes.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'E hizo Yahvé Dios para Adán y su mujer túnicas de pieles y los vistió.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Y dijo Yahvé Dios: “He aquí que el hombre ha venido a ser como uno de nosotros, conocedor del bien y del mal; ahora, pues, no vaya a extender su mano para que tome todavía del árbol de la vida, y comiendo (de él) viva para siempre.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Después Yahvé Dios lo expulsó del jardín de Edén, para que labrase la tierra de donde había sido tomado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'Y habiendo expulsado a Adán puso delante del jardín de Edén querubines, y la fulgurante espada que se agitaba, a fin de guardar el camino del árbol de la vida.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Conoció Adán a Eva, su mujer, la cual concibió y dio a luz a Caín, y dijo: “He adquirido un varón con el favor de Yahvé.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Otra vez dio a luz (y tuvo) a Abel, su hermano. Fue Abel pastor de ovejas y Caín labrador.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Pasado algún tiempo, presentó Caín a Yahvé una ofrenda de los frutos de la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'Y también Abel ofreció de los primogénitos de su rebaño, y de la grasa de los mismos. Yahvé miró a Abel y su ofrenda;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'pero no miró a Caín y su ofrenda, por lo cual se irritó Caín en gran manera, y decayó su semblante.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Entonces dijo Yahvé a Caín: “¿Por qué andas irritado, y por qué ha decaído tu semblante?');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, '¿No es cierto que si obras bien, podrás alzarlo? Mas si no obras bien, está asechando a la puerta el pecado que desea dominarte; pero tú debes dominarle a él.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Dijo después Caín a su hermano Abel: “Vamos al campo.” Y cuando estuvieron en el campo, se levantó Caín contra su hermano Abel y lo mató.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Preguntó Yahvé a Caín: “¿Dónde está Abel, tu hermano?” Contestó: “No sé. ¿Soy acaso el guarda de mi hermano?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Y dijo (Yahvé): “¿Qué has hecho? La voz de la sangre de tu hermano está clamando a Mí desde la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Por eso andarás maldito, lejos de esta tierra que abrió su boca para recibir de tu mano la sangre de tu hermano.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Cuando labres la tierra, ella no te dará más su fruto; fugitivo y errante vivirás sobre la tierra.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Entonces dijo Caín a Yahvé: “Mi culpa es demasiado grande para soportarla.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'He aquí que hoy me echas de esta tierra y he de esconderme de tu presencia; andaré fugitivo y errante por la tierra, y cualquiera que me encuentre me matará.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Yahvé le respondió: “Pues por eso, cualquiera que matare a Caín, lo pagará siete veces.” Y puso Yahvé una señal a Caín para que no lo matara quien lo hallase.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Salió entonces Caín de la presencia de Yahvé y habitó en el país de Nod, al oriente de Edén.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Conoció Caín a su mujer, la cual concibió y dio a luz a Enoc. Y edificando por entonces una ciudad, le dio el nombre de su hijo, Enoc.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'A Enoc le nació Irad, e Irad engendró a Mehuyael. Mehuyael engendró a Metusael, y Metusael engendró a Lamec.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Lamec tomó para sí dos mujeres; el nombre de la una era Adá, y el nombre de la otra Sillá.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Adá dio a luz a Jabal, el cual vino a ser padre de los que habitan en tiendas y crían ganado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'El nombre de su hermano era Jubal, el cual vino a ser padre de todos los que tocan la cítara y la flauta.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'También Sillá dio a luz; a Tubalcaín, forjador de toda herramienta de cobre y hierro. Hermana de Tubalcaín fue Naamá.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Y dijo Lamec a sus mujeres: “Adá y Sillá, escuchad mi voz; yo maté a un hombre que me hirió, y a un joven por una contusión que recibí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Caín será vengado siete veces, mas Lamec lo será setenta veces siete.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Conoció Adán de nuevo a su mujer; y ella dio a luz un hijo, al cual puso por nombre Set; porque (dijo ella) “Dios me ha dado otro hijo en lugar de Abel, a quien mató Caín”.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'También a Set le nació un hijo, a quien llamó Enós. En aquel tiempo se comenzó a invocar el nombre de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Este es el libro de los descendientes de Adán. El día en que Dios creó a Adán, lo hizo a imagen de Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Los creó varón y mujer y los bendijo: y los llamó “hombre” en el día de su creación.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Tenía Adán ciento treinta años cuando engendró un hijo a su semejanza, según su imagen, al cual puso por nombre Set.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Fueron los días de Adán, después de engendrar a Set, ochocientos años, y engendró hijos e hijas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Y fueron todos los días que vivió Adán novecientos treinta años, y murió.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Set tenía ciento cinco años cuando engendró a Enós.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Y vivió Set, después de engendrar a Enós, ochocientos siete años, y engendró hijos e hijas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Y fueron todos los días de Set novecientos doce años, y murió.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Enós tenía noventa años cuando engendró a Cainán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Vivió Enós, después de engendrar a Cainán, ochocientos quince años, y engendró hijos e hijas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Y fueron todos los días de Enós novecientos cinco años, y murió.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Cainán tenía setenta años cuando engendró a Mahalalel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Vivió Cainán, después de haber engendrado a Mahalalel, ochocientos cuarenta años, y engendró hijos e hijas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Y fueron todos los días de Cainán novecientos diez años, y murió.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Mahalalel tenía sesenta y cinco años, cuando engendró a Yared.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Vivió Mahalalel, después de engendrar a Yared, ochocientos treinta años, y engendró hijos e hijas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Y fueron todos los días de Mahalalel ochocientos noventa y cinco años, y murió.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Yared tenía ciento sesenta y dos años cuando engendró a Enoc.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Vivió Yared, después de engendrar a Enoc, ochocientos años y engendró hijos e hijas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Y fueron todos los días de Yared novecientos sesenta y dos años, y murió.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Enoc tenía sesenta y cinco años cuando engendró a Matusalén.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Anduvo Enoc con Dios, (viviendo) después de engendrar a Matusalén, trescientos años, y engendró hijos e hijas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Y fueron todos los días de Enoc trescientos sesenta y cinco años.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Enoc anduvo con Dios, y desapareció porque Dios se lo llevó.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Matusalén tenía ciento ochenta y siete años cuando engendró a Lamec.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Vivió Matusalén, después de engendrar a Lamec, setecientos ochenta y dos años, y engendró hijos e hijas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Y fueron todos los días de Matusalén novecientos sesenta y nueve años, y murió.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Lamec tenía ciento ochenta y dos años, cuando engendró un hijo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'al cual puso por nombre Noé, diciendo: Este nos consolará de nuestras fatigas y del trabajo de nuestras manos, causado por la tierra que maldijo Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Vivió Lamec, después de engendrar a Noé, quinientos noventa y cinco años, y engendró hijos e hijas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Y fueron todos los días de Lamec setecientos setenta y siete años, y murió. Noé tenía quinientos años, cuando engendró a Sem, Cam y Jafet.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Cuando los hombres comenzaron a multiplicarse sobre la tierra y les nacieron hijas,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'y vieron los hijos de Dios que las hijas de los hombres eran hermosas, tomaron de entre todas ellas por mujeres las que les agradaron.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Entonces dijo Yahvé: “No permanecerá para siempre mi espíritu en el hombre, a causa de su delito; no es más que carne, y serán sus días ciento veinte años.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'En aquellos días había gigantes en la tierra, y también después, cuando los hijos de Dios se llegaron a las hijas de los hombres y ellas les dieron hijos. Estos son los héroes, los varones famosos de la antigüedad.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Viendo, pues, Yahvé que era grande la maldad del hombre sobre la tierra, y que todos los pensamientos de su corazón se dirigían únicamente al mal, todos los días,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'Yahvé se arrepintió de haber hecho al hombre en la tierra, y se dolió en su corazón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Y dijo Yahvé: “Exterminaré de sobre la faz de la tierra al hombre que he creado, desde el hombre hasta las bestias, hasta los reptiles, y hasta las aves del cielo, porque me arrepiento de haberlo hecho.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Mas Noé halló gracia a los ojos de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'He aquí la historia de Noé. Noé fue varón justo y perfecto entre los hombres de su tiempo, pues anduvo con Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Y engendró Noé tres hijos: Sem, Cam y Jafet.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'La tierra estaba entonces corrompida delante de Dios, y llena de violencia.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Miró, pues, Dios la tierra, y he aquí que estaba depravada, porque toda carne había corrompido su camino sobre la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Dijo entonces Dios a Noé: “He decidido el fin de toda carne; porque la tierra está colmada de violencia por culpa de ellos; por eso he aquí que voy a exterminarlos juntamente con la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Hazte un arca de maderas resinosas, la cual dividirás en compartimientos y calafatearás por dentro y por fuera con betún.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'La fabricarás de esta manera: trescientos codos será la longitud del arca, cincuenta codos su anchura, y treinta codos su altura.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Harás en el arca una abertura para la luz, la cual dispondrás arriba, a un codo del techo. La puerta del arca pondrás en uno de sus costados, y harás un piso primero, un segundo y un tercero.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Pues he aquí que voy a traer un diluvio de aguas sobre la tierra, para exterminar toda carne que tiene en sí aliento de vida bajo el cielo. Todo lo que existe en la tierra, perecerá.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Pero contigo estableceré mi pacto: Entrarás en el arca tú, y tus hijos, y tu mujer, y las mujeres de tus hijos contigo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Y de todos los animales de toda carne, de toda clase (de ellos), introducirás parejas en el arca para que tengan vida contigo; serán macho y hembra;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'de las aves según su especie, de las bestias según su especie, de todos los reptiles de la tierra según su especie. Dos de cada clase vendrán a ti, para que les conserves la vida.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Provéete de todo alimento que se come, acópiate provisiones para que os sirvan de comida a ti y a ellos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Noé hizo conforme a cuanto Dios le había mandado. Así se hizo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Y dijo Yahvé a Noé: “Entra en el arca, tú y toda tu casa, porque a ti te he visto justo delante de Mí en medio de esta generación.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'De todos los animales puros te elegirás siete parejas, machos con sus hembras; y de todos los animales que no son puros, dos parejas, machos con sus hembras.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'Asimismo de las aves del cielo siete parejas, machos y hembras para que se conserve su descendencia sobre la faz de toda la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Porque de aquí a siete días haré llover sobre la tierra cuarenta días y cuarenta noches y exterminaré de la tierra todo ser viviente que he hecho.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'E hizo Noé conforme a cuanto Yahvé le había mandado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Tenía Noé seiscientos años cuando el diluvio de aguas vino sobre la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Entró Noé en el arca, y con él sus hijos, y su mujer, y las mujeres de sus hijos, para salvarse de las aguas del diluvio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'De los animales puros, y de las aves, y de todo lo que se arrastra sobre la tierra,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'llegaron a Noé al arca, parejas, machos y hembras, como Dios había ordenado a Noé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Y al cabo de siete días las aguas del diluvio vinieron sobre la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'El año seiscientos de la vida de Noé, el mes segundo, el día diez y siete del mes, en ese día prorrumpieron todas las fuentes del grande abismo, y se abrieron las cataratas del cielo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'Y estuvo lloviendo sobre la tierra cuarenta días y cuarenta noches.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'En aquel mismo día entró Noé en el arca, con Sem, Cam y Jafet, hijos de Noé, y con ellos la mujer de Noé, y las tres mujeres de sus hijos;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'ellos, con todos los animales, según su especie, y todas las bestias domésticas según su especie, y todos los reptiles que se arrastran sobre la tierra, según su especie, y todas las aves según su especie, todo pájaro, todo volátil.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'Se llegaron a Noé, al arca, de dos en dos, de toda carne en que hay aliento de vida');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Y los que habían venido, machos y hembras de toda carne, entraron como Dios había mandado. Y tras él cerró Yahvé la puerta.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'El diluvio duró cuarenta días sobre la tierra. Y crecieron las aguas y levantaron el arca, la cual se alzó sobre la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Y se aumentaron las aguas y crecieron muchísimo sobre la tierra, mientras el arca flotaba sobre las aguas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Tan desmesuradamente crecieron las aguas sobre la tierra, que quedaron cubiertos todos los montes más altos que había bajo el cielo entero.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Quince codos se alzaron sobre ellos las aguas y fueron así cubiertos los montes.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Entonces murió toda carne que se movía sobre la tierra; aves y ganados y fieras y todo reptil que se arrastraba sobre la tierra, y todos los hombres.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Todos los seres que en sus narices tenían soplo de vida, de cuantos hay en la tierra firme, perecieron.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Así fue exterminado todo ser viviente que había sobre la faz de la tierra, desde el hombre hasta la bestia, hasta los reptiles y hasta las aves del cielo. Fueron exterminados de la tierra, y quedaron solamente Noé y los que con él estaban en el arca.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Por espacio de ciento cincuenta días se alzaron las aguas sobre la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Acordose Dios de Noé y de todas las fieras y de todas las bestias que con él estaban en el arca; e hizo Dios pasar un viento sobre la tierra, y bajaron las aguas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'Entonces se cerraron las fuentes del abismo y las cataratas del cielo, y se detuvo la lluvia del cielo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Poco a poco retrocedieron las aguas de sobre la tierra; y cuando al cabo de ciento cincuenta días las aguas empezaron a menguar,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'reposó el arca sobre los montes de Ararat, en el mes séptimo, el día diecisiete del mes.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Las aguas siguieron decreciendo paulatinamente hasta el mes décimo, y el día primero del décimo mes aparecieron las cumbres de los montes.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Pasados cuarenta días, abrió Noé la ventana que había hecho en el arca,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'y soltó un cuervo, el cual yendo salía y retornaba hasta que se secaron las aguas sobre la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Después soltó Noé una paloma, para ver si se habían retirado ya las aguas de la superficie terrestre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Mas como la paloma no hallase donde poner la planta de su pie, tornó hacia él, al arca, porque había todavía agua sobre toda la tierra; y alargando él su mano, la asió y la metió consigo en el arca.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Esperó otros siete días y soltó de nuevo la paloma fuera del arca.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'La paloma volvió a él al atardecer, y he aquí que traía en su pico hoja verde de olivo, por donde conoció Noé que las aguas se habían retirado de la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Esperó todavía otros siete días y soltó la paloma, la cual no volvió más a él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'El año seiscientos uno, el día primero del primer mes, ya no había aguas sobre la tierra, y abriendo Noé la cubierta del arca miró y vio que estaba seca la superficie del suelo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'En el mes segundo, a los veintisiete días del mes, quedó seca la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Habló entonces Dios a Noé, y dijo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, '“Sal del arca, tú, y contigo tu mujer, tus hijos y las mujeres de tus hijos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Y sacarás contigo todos los animales de toda carne que te acompaña, aves, bestias y todos los reptiles que se arrastran en el suelo; pululen sobre la tierra y sean fecundos y se multipliquen sobre la tierra.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Salió, pues, Noé, y con él sus hijos, su mujer y las mujeres de sus hijos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Salieron también del arca, según sus especies, todos los animales, todos los reptiles y todas las aves, todo cuanto se mueve sobre la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Después erigió Noé un altar a Yahvé, y tomando de todos los animales puros, y de todas las aves puras, ofreció holocaustos en el altar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Al aspirar Yahvé el agradable olor dijo en su corazón: “No volveré a maldecir la tierra por causa del hombre, porque los deseos del corazón humano son malos desde su niñez, ni volveré a exterminar a todos los seres vivientes, como he hecho.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Mientras dure la tierra, no cesarán (de sucederse) sementera y siega, frío y calor, verano e invierno, día y noche.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Y bendijo Dios a Noé y a sus hijos, y les dijo: “Creced y multiplicaos y llenad la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Tengan miedo y tiemblen ante vosotros todos los animales de la tierra, y todas las aves del cielo y todo lo que se arrastra sobre el suelo, y todos los peces del mar. En vuestra mano están puestos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Todo lo que se mueve y tiene vida, os servirá de alimento. Como ya la hierba verde, así os lo entrego todo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Pero no comeréis la carne con su vida, es decir, con su sangre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Pues, en verdad, Yo pediré cuenta de vuestra sangre, para (protección) de vuestra vida; de mano de todo ser viviente la demandaré. De mano del hombre, de mano de su propio hermano, demandaré la vida del hombre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Cualquiera que derramare sangre humana, por mano de hombre será derramada su sangre; porque a imagen de Dios hizo Él al hombre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Vosotros, pues, creced y multiplicaos; dilataos sobre la tierra y aumentaos en ella.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Dijo Dios a Noé, y a sus hijos juntamente con él:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, '“He aquí que Yo establezco mi pacto con vosotros, y con vuestra descendencia después de vosotros;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'y con todo ser viviente que esté entre vosotros, aves, bestias domésticas y salvajes de la tierra que hay entre vosotros, con todo lo que sale del arca, hasta el último animal de la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Hago mi pacto con vosotros: No será exterminada ya toda carne con aguas de diluvio, ni habrá más diluvio para destruir la tierra.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Y dijo Dios: “Esta es la señal del pacto que por generaciones perpetuas establezco entre Mí y vosotros y todo ser viviente que se halla entre vosotros:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Pondré mi arco en las nubes, que servirá de señal del pacto entre Mí y la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Cuando Yo cubriere la tierra con nubes y apareciere el arco entre las nubes,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'me acordaré de mi pacto que hay entre Mí y vosotros y todo ser viviente de toda carne; y las aguas no volverán más a formar un diluvio para exterminar toda carne.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Pues cuando aparezca el arco en las nubes, Yo lo miraré, para acordarme del pacto perpetuo entre Dios y todo ser viviente, de toda carne que existe sobre la tierra.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Dijo, pues, Dios a Noé: “Esta es la señal del pacto que he establecido entre Mí y toda carne sobre la tierra.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Los hijos de Noé, que salieron del arca, eran Sem, Cam y Jafet. Cam es el padre de Canaán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Estos tres son los hijos de Noé, y por ellos ha sido poblada toda la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Noé comenzó a cultivar la tierra y plantó una viña.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Mas bebiendo del vino se embriagó, y se quedó desnudo en medio de su tienda.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Vio Cam, padre de Canaán, la desnudez de su padre, y fue a decirlo a sus dos hermanos (que estaban) afuera.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Entonces Sem y Jafet tomaron entrambos el manto (de Noé), se lo echaron sobre los hombros, y yendo hacia atrás cubrieron la desnudez de su padre. Tenían vuelto el rostro de modo que no vieron la desnudez de su padre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Cuando despertó Noé de su vino y supo lo que había hecho con él su hijo menor,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'dijo: “Maldito sea Canaán; esclavo de esclavos será para sus hermanos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Y agregó: “Bendito sea Yahvé, el Dios de Sem; y sea Canaán su esclavo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Dilate Dios a Jafet, que habitará en las tiendas de Sem; y sea Canaán su esclavo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Vivió Noé, después del diluvio, trescientos cincuenta años.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'Y fueron todos los días de Noé novecientos cincuenta años, y murió.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Estos son los descendientes de los hijos de Noé: Sem, Cam y Jafet, a quienes después del diluvio nacieron estos hijos:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Hijos de Jafet: Gómer, Magog, Madai, Javán, Tubal, Mósoc y Tirás.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Hijos de Gómer: Asquenaz, Rifat, Togormá.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Hijos de Javán: Elisá, Tarsis, Kitim y Dodanim.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Estos se propagaron sobre las islas de las gentes y en sus tierras, según sus lenguas y sus tribus y sus naciones.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Hijos de Cam: Cus, Misraim, Put y Canán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Hijos de Cus: Sabá, Havilá, Sabtá, Ragmá y Sabtecá. Hijos de Ragmá: Sabá y Dedán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Cus engendró Nimrod, el cual fue el primero que se hizo poderoso en la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Fue él un gran cazador delante de Yahvé; por lo cual suele decir: “Gran cazador delante de Yahvé, como Nimrod”.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Reinó primero en Babel, Erec, Acad y Calné, en la tierra de Sinear.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'De aquella tierra salió para Asur y edificó Nínive, Rehobot-Ir, Calah,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'y Resen, entre Nínive y Calah; aquella es la gran ciudad.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Misraim engendró a los de Ludim, los Anamim, los Lahabim, los Naftuhim,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'los Patrusim, los Casluhim, de donde salieron los Filisteos y los Caftoreos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Canaán engendró a Sidón, su primogénito, y a Het,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'y también al Jebuseo, al Amorreo, al Gergeseo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'al Heveo, al Araceo, al Sineo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'al Arvadeo, al Samareo y al Hamateo. Después se dispersaron las tribus de los cananeos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'El territorio de los cananeos se extendió desde Sidón, en dirección a Gerar, hasta Gaza; y en dirección a Sodoma, Gomorra, Adamá y Seboím, hasta Lesa.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Estos son los hijos de Cam, según sus familias y según sus lenguas, en sus territorios y según sus naciones.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Nacieron hijos también a Sem, padre de todos los hijos de Éber y hermano mayor de Jafet.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Hijos de Sem: Elam, Asur, Arfaxad, Lud y Aram.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Hijos de Aram: Us, Hul, Géter y Mas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Arfaxad engendró a Sálah, y Sálah engendró a Éber.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'A Éber le nacieron dos hijos: el nombre de uno fue Fáleg, porque en sus días fue dividida la tierra. Su hermano se llamaba Joctán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Joctán engendró a Almodad, a Sálef, a Hazarmávet, a Járah,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'a Hadoram, a Uzal, a Diklá,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'a Obal, a Abomael, a Sabá,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'a Ofir, a Havilá y a Jobab. Todos estos fueron hijos de Joctán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Su territorio se extendió desde Mesá, en dirección a Sefar, al monte del Oriente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Estos son los hijos de Sem, según sus tribus y lenguas, en sus territorios y según sus naciones.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Estas son las tribus de los hijos de Noé, según su origen y sus naciones; y de ellas se propagaron los pueblos en la tierra después del diluvio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Tenía la tierra entera una misma lengua y las mismas palabras.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Mas cuando (los hombres) emigrando desde el Oriente hallaron una llanura en la tierra de Sinear, donde se establecieron,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'se dijeron unos a otros: “Vamos, fabriquemos ladrillos, y cozámoslos bien.” Y les sirvió el ladrillo en lugar de piedra, y el betún les sirvió de argamasa.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Y dijeron, pues: “Vamos, edifiquémonos una ciudad y una torre, cuya cumbre llegue hasta el cielo; hagámonos un monumento para que no nos dispersemos sobre la superficie de toda la tierra.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Pero Yahvé descendió a ver la ciudad y la torre que estaban construyendo los hijos de los hombres.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Y dijo Yahvé: “He aquí que son un solo pueblo y tienen todos una misma lengua. ¡Y esto es solo el comienzo de sus obras! Ahora, nada les impedirá realizar sus propósitos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Ea, pues, descendamos, y confundamos allí mismo su lengua, de modo que no entienda uno el habla del otro.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Así los dispersó Yahvé de allí por la superficie de toda la tierra; y cesaron de edificar la ciudad.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Por tanto se le dio el nombre de Babel; porque allí confundió Yahvé la lengua de toda la tierra; y de allí los dispersó Yahvé sobre la faz de todo el orbe.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Estos son los descendientes de Sem. Sem tenía cien años cuando engendró a Arfaxad, dos años después del diluvio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Vivió Sem, después de haber engendrado a Arfaxad, quinientos años; y engendró hijos e hijas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Arfaxad tenía treinta y cinco cuando engendró a Sálah.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Y vivió Arfaxad, después de haber engendrado a Sálah, cuatrocientos tres años; y engendró hijos e hijas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Sálah tenía treinta años cuando engendró a Éber.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Y vivió Sálah, después de haber engendrado a Éber, cuatrocientos tres años; y engendró hijos e hijas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Éber tenía treinta y cuatro años cuando engendró a Fáleg.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Y vivió Éber, después de engendrar a Fáleg, cuatrocientos treinta años; y engendró hijos e hijas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Fáleg tenía treinta años cuando engendró a Reú.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Y vivió Fáleg, después de haber engendrado a Reú, doscientos nueve años; y engendró hijos e hijas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Reú tenía treinta y dos años cuando engendró a Sarug.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Y vivió Reú, después de haber engendrado a Sarug, doscientos siete años; y engendró hijos e hijas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Sarog tenía treinta años cuando engendró a Nacor.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Y vivió Sarug, después de haber engendrado a Nacor, doscientos años y engendró hijos e hijas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Nacor tenía veinte y nueve años cuando engendró a Táreh.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Y vivió Nacor, después de haber engendrado a Táreh, ciento diez y nueve años; y engendró hijos e hijas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Táreh tenía setenta años cuando engendró a Abram, a Nacor y a Aram.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Estos son los descendientes de Táreh. Táreh engendró a Abram, a Nacor y a Aram; Aram engendró a Lot.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Y murió Aram, antes de su padre Táreh, en el país de su nacimiento, en Ur de los caldeos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Abram y Nacor tomaron para sí mujeres. El nombre de la mujer de Abram era Sarai, y el nombre de la mujer de Nacor, Milcá, hija de Aram, padre de Milcá y padre de Jescá.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Era Sarai estéril y no tenía hijo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Y tomó Táreh a Abram su hijo, y a Lot, hijo de su hijo de Aram, su nieto, y a Sarai, su nuera, mujer de su hijo Abram; y salieron juntos de Ur de los caldeos, para dirigirse al país de Canaán. Y llegaron a Harán, donde se quedaron.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Y fueron los días de Táreh doscientos cinco años; y murió Táreh en Harán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Dijo Yahvé a Abram: “Sal de tu tierra, y de tu parentela, y de la casa de tu padre, al país que Yo te mostraré.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'Pues de ti haré una nación grande y te bendeciré; haré grande tu nombre, y serás una bendición.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Bendeciré a quienes te bendigan y maldeciré a quienes te maldigan; y en ti serán benditas todas las tribus de la tierra.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Marchó, pues, Abram, como se lo había mandado Yahvé; y con él partió Lot. Tenía Abram setenta y cinco años cuando salió de Harán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Tomó Abran a Sarai su mujer, y a Lot, hijo de su hermano, con toda la hacienda que poseían, y con las familias que habían procreado en Harán. Partieron para dirigirse a la tierra de Canaán y llegaron a la tierra de Canaán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Atravesó Abran el país hasta el lugar de Siquem, hasta la encina de Moré.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Entonces se apareció Yahvé a Abram y dijo: “A tu descendencia daré esta tierra.” Allí erigió un altar a Yahvé que se le había aparecido.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Pasó de allí a la montaña, al oriente de Betel, donde asentó su tienda, teniendo a Betel al occidente y Hai al oriente. Allí construyó un altar a Yahvé en invocó el nombre de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Después levantó Abram su tienda y se dirigió en etapas hacia el Négueb.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Mas hubo hambre en el país, por lo cual Abram bajó a Egipto para morar allí, pues era grande el hambre en el país.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Estando ya próximo a entrar en Egipto, dijo a Sarai, su mujer: “Mira, yo sé que eres mujer hermosa;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'por eso, cuando te vean los egipcios, dirán: “Esta es su mujer”; y me matarán a mí, y a ti te dejarán la vida.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Di, pues, te ruego, que eres mi hermana, a fin de que me vaya bien por causa tuya, y sea salva mi vida por amor de ti.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Efectivamente, cuando Abram entró en Egipto, vieron los egipcios que la mujer era muy hermosa.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Viéronla también los cortesanos del Faraón, los cuales se la alabaron al Faraón, de modo que la mujer fue llevada al palacio del Faraón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Este trató a Abram muy bien por causa de ella; y se le dieron ovejas y ganados y asnos y siervos y siervas y asnas y camellos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Mas Yahvé hirió al Faraón con grandes plagas, a él y a su casa, por Sarai, la mujer de Abram.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Entonces llamó el Faraón a Abram, y le dijo: “¿Qué es lo que has hecho conmigo? ¿Por qué no me dijiste que era tu mujer?');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, '¿Por qué afirmaste: “Es mi hermana”, de manera que yo la tomé por mujer? Ahora, pues, ahí tienes a tu mujer; tómala y anda.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Y el Faraón dio orden respecto de él a sus hombres, los cuales despidieron a él y a su mujer, con todo cuanto poseía.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'De Egipto subió Abram al Négueb, él su mujer y toda su hacienda, y Lot con él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Era Abram muy rico en rebaños, en plata y oro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Y se volvió, caminando por etapas, desde el Négueb hasta Betel, donde había acampado al principio, entre Betel y Hai,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'hasta el lugar del altar que alzara allí anteriormente; e invocó allí Abram el nombre de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'También Lot, que iba con Abram, poseía rebaños, vacadas y tiendas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'Mas el país no les permitía vivir juntos, porque era mucha su hacienda, de modo que no podían habitar juntamente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'De ahí nacieron contiendas entre los pastores de las greyes de Abram y los pastores de las greyes de Lot. Además, los cananeos y los fereceos habitaban en aquel tiempo en esa región.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Dijo, pues Abram a Lot: “No haya, te ruego, contienda entre mí y ti, ni entre mis pastores y tus pastores; pues somos hermanos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, '¿No está todo el país delante de ti? Sepárate, por favor, de mí. Si tú vas a la izquierda, yo iré a la derecha; y si tú vas a la derecha, yo iré a la izquierda.”.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Alzando entonces Lot sus ojos vio toda la vega del Jordán, toda ella de regadío, hasta los límites de Segor. Antes que destruyese Yahvé a Sodoma y Gomorra era esta región como el jardín de Yahvé, como la tierra de Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Eligió, pues, Lot para sí toda la vega del Jordán, y se trasladó al oriente; y así se separaron el uno del otro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abram se estableció en la tierra de Canaán, y Lot habitó en las ciudades de la Vega, donde plantó sus tiendas hasta Sodoma.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Mas los habitantes de Sodoma eran malos y grandes pecadores ante Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Dijo Yahvé a Abram, después que Lot se hubo separado de él: “Alza tus ojos y mira desde el lugar donde estás, hacia el norte y hacia el mediodía, hacia el oriente y hacia el occidente;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'pues toda la tierra que ves, te la daré a ti y a tu descendencia para siempre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'Y haré tu descendencia (tan numerosa) como el polvo de la tierra. Si fuera posible contar el polvo de la tierra, podría contarse también tu descendencia.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Levántate, recorre el país, a su largo y a su ancho; porque a ti te lo daré.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Y levantó Abram las tiendas y vino a establecerse en el encinar de Mamré, cerca de Hebrón, donde edificó un altar a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Aconteció que en los días de Amrafel, rey de Sínear; Arioc, rey de Elasar; Codorlaómer, rey de Elam, y Tidal, de Goím,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'hicieron guerra a Bera, rey de Sodoma; a Birsá, rey de Gomorra; a Sinab, rey de Adamá; a Seméber, rey de Seboím, y al rey de Bela, que es Segor.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Todos estos se juntaron en el valle de Siddim, que (ahora) es el Mar Salado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Doce años habían servido a Codorlaómer, mas el año decimotercero se rebelaron.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Vinieron, pues, en el año decimocuarto Codorlaómer, y los reyes con él coaligados y derrotaron a los refaítas en Astarot-Carnaim, a los susitas en Ham, a los emeos en Savé-Cariataim,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'y a los horreos en sus montes en Seír, hasta El-Farán, que está junto al desierto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Y volviéndose vinieron a En-Mispar, que es Cades, y derrotaron todo el campo de los amalecitas, y también a los amorreos que habitaban en Hazazón-Tamar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Salieron entonces el rey de Sodoma, y el rey de Gomorra, y el rey de Adamá, y el rey de Seboím, y el rey de Bela, que es Segor, y ordenaron batalla contra ellos en el valle de Siddim;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'esto es, contra Codorlaómer, rey de Elam; Tidal, rey de Gím; Amrafel, rey de Sinear, y Arioc, rey de Elasar; cuatro reyes contra cinco.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Ahora bien, había en el valle de Siddim muchísimos pozos de betún; cuando huyeron los reyes de Sodoma y Gomorra cayeron en ellos. Los demás huyeron a la montaña.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, '(Los invasores) se llevaron toda la hacienda de Sodoma y Gomorra y todos sus víveres y se marcharon.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Se llevaron también a Lot, hijo del hermano de Abram, y su hacienda, pues él habitaba en Sodoma, y se fueron.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Mas uno que escapó, fue a avisar a Abram el hebreo, el cual habitaba en el encinar de Mamré, el amorreo, hermano de Escol y hermano de Aner, los cuales eran aliados de Abram.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Y como oyese Abram que su hermano había sido hecho prisionero, reclutó entre los siervos nacidos en su casa a los más adiestrados, en número de trescientos diez y ocho, y persiguió (a los invasores) hasta Dan.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'Y habiendo dividió su tropa (cayó) sobre ellos durante la noche, él y sus siervos, los derrotó y los persiguió hasta Hobá, que está a la izquierda de Damasco.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Y recuperó toda la hacienda, y también a su hermano Lot con sus bienes; y asimismo a las mujeres y la gente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Cuando regresaba tras la derrota de Codorlaómer y de los reyes que con él estaba, le salió al encuentro el rey de Sodoma en el valle de Savé, que es el valle del Rey.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Entonces Melquisedec, rey de Salem, presentó pan y vino, pues era sacerdote del Dios altísimo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'Y le bendijo, diciendo “¡Bendito sea Abram del Dios altísimo, Señor del cielo y de la tierra!');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, '¡Y bendito sea el Dios altísimo, que puso tus enemigos en sus manos!” Y le dio (Abram) el diezmo de todo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Dijo luego el rey de Sodoma a Abram: “Dame la gente, mas la hacienda tómala para ti.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Pero Abram dijo al rey de Sodoma: “Levanto mi mano (jurando) por Yahvé, Dios altísimo, Señor del cielo y de la tierra,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'que ni un hilo, ni la correa de un zapato, tomaré de lo que es tuyo, no sea que digas: “Yo he enriquecido a Abram”;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'a excepción de lo que han comido los muchachos, y la porción de esos varones que vinieron conmigo, Aner, Escol y Mamré. Estos tomarán su porción.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Después de estos acontecimientos habló Yahvé a Abram en una visión, diciendo: “No temas, Abram; Yo soy tu escudo, tu recompensa sobremanera grande.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Respondió Abram: “Adonai, Yahvé, ¿qué me vas a dar, si me voy sin hijo, y el heredero de mi casa será este damasceno Eliécer?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Y repitió Abram: “Aquí me tienes, no me has dado descendencia, y así es que un hombre de mi casa me ha de heredar.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Mas he aquí que Yahvé le habló, diciendo: “No te heredará este, sino que uno que saldrá de tus entrañas, ese te ha de heredar.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Y le sacó fuera, y dijo: “Mira el cielo, y cuenta las estrellas, si puedes contarlas”, y le agregó: “Así será tu descendencia.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Y creyó a Yahvé, el cual se lo reputó por justicia.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Díjole después: “Yo soy Yahvé que te saqué de Ur de los caldeos, a fin de darte esta tierra por herencia.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Preguntó él: “Adonai, Yahvé, ¿en qué conoceré que he de heredarla?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Y le respondió: “Escógeme una novilla de tres años, un tórtola y un pichón.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Tomó entonces (Abram) todos estos (animales) y partiéndolos por el medio puso cada mitad en frente de la otra, pero sin partir las aves.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Sobre estos cuerpos muertos bajaron las aves de rapiña, mas Abram las espantaba.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Y sucedió que estando ya el sol para ponerse, cayó sobre Abram un profundo sueño, y he aquí que le sobrevino un terror, una tiniebla muy grande.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Entonces dijo (Dios) a Abram: “Ten por cierto que tus descendientes vivirán como extranjeros en una tierra no suya, donde serán reducidos a servidumbre y oprimidos durante cuatrocientos años.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Mas la nación a la cual han de servir, Yo la juzgaré; y después saldrán con grandes riquezas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Tú (entretanto) irás a tus padres en paz, y serás sepultado en buena ancianidad.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Mas a la cuarta generación volverán aquí; porque hasta el presente la maldad de los amorreos no ha llegado a su colmo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Y sucedió que, puesto ya el sol, apareció, en medio de densas tinieblas, un horno humeante y una antorcha de fuego que pasó por entre aquellos animales divididos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'En aquel día hizo Yahvé alianza con Abram, diciendo: “A tu descendencia he dado esta tierra, desde el río de Egipto hasta el río grande, el río Éufrates:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'los cineos, los ceneceos, los cadmoneos,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'los heteos, los fereceos, los refaítas,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'los amorreos, los cananeos, los gergeseos y los jebuseos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Sarai, mujer de Abram, no le daba hijos; pero tenía una sierva egipcia, que se llamaba Agar,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'y dijo Sarai a Abram: “Mira que Yahvé me ha hecho estéril; llégate, pues, te ruego, a mi esclava. Quizás podré tener hijos de ella.” Escuchó Abram la voz de Sarai.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Y así al cabo de diez años de habitar Abram en el país de Canaán, tomó Sarai, la mujer de Abram, a Agar la egipcia, su esclava, y se la dio por mujer a Abram, su marido.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Llegose, pues, él a Agar, la cual concibió; mas luego que vio que había concebido, miraba a su señora con desprecio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Dijo entonces Sarai a Abram: “El agravio hecho a mí cae sobre ti. Yo puse mi esclava en tu seno, más viéndose ella encinta me mira con desprecio. Juzgue Yahvé entre mí y ti.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Respondió Abram a Sarai: Ahí tienes a tu sierva a tu disposición. Haz con ella como bien te parezca.” Luego la maltrató Sarai; y ella huyó de su presencia.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'La encontró el Ángel de Yahvé en el desierto, junto a una fuente de agua, que está en el camino de Sur;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'y dijo: “¿Agar, esclava de Sarai, de dónde vienes y adónde vas?” Contestó ella: “Voy huyendo de la presencia de Sarai, mi señora.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, '“Vuelve a tu señora, le replicó el Ángel de Yahvé, y humíllate bajo su mano.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Y agregó el Ángel de Yahvé: “Multiplicaré de tal manera tu descendencia, que por su gran multitud no podrá contarse.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Le dijo además el Ángel de Yahvé: “Mira, has concebido, y darás a luz un hijo, al que llamarás Ismael; porque Yahvé ha oído su aflicción.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Será hombre (fiero) como el asno montés. Su mano será contra todos, y la mano de todos contra él; y frente a todos sus hermanos pondrá su morada.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Entonces ella llamó a Yahvé, que con ella hablaba, con el nombre de: “Atta El Roí”, pues dijo: “¿No he visto aquí mismo al que me ve?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Por tanto llamó a aquel pozo “Pozo del Viviente que me ve.” Es el que está entre Cades y Barad.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Y Agar le dio un hijo a Abram, el cual al hijo que Agar había dado a luz, le puso por nombre Ismael.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Tenía Abram ochenta y seis años cuando Ismael le nació de Agar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Cuando Abram tenía noventa y nueve años, se le apareció Yahvé y le dijo: “Yo soy el Dios Todopoderoso; camina en mi presencia y sé perfecto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'Yo estableceré mi pacto entre Mí y ti, y te multiplicaré sobremanera.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Entonces Abram se postró rostro en tierra, y Dios siguió diciéndole:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, '“En cuanto a Mí, he aquí mi pacto contigo: tú serás padre de una multitud de pueblos;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'y no te llamarás más Abram, sino que tu nombre será Abrahán, porque te he puesto por padre de muchos pueblos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Te haré crecer sobremanera, y te haré padre de pueblos, y reyes saldrán de ti.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Y estableceré mi pacto en Mí y ti, y tu descendencia después de ti en la serie de sus generaciones, como pacto eterno, para ser Yo el Dios tuyo y el de tu posteridad después de ti.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Y te daré a ti, y a tu descendencia después de ti, la tierra de tus peregrinaciones, toda la tierra de Canaán, en posesión perpetua; y Yo seré su Dios.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Dijo Dios a Abrahán: “Tú, pues, guarda mi pacto, y tu descendencia después de ti en la serie de sus generaciones.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Este es mi pacto que habéis de guardar entre Mí y vosotros y tu posteridad después de ti: Todo varón entre vosotros ha de ser circuncidado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Os circundaréis la carne de vuestro prepucio; y esto será en señal del pacto entre Mí y vosotros.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'A los ocho días será circuncidado entre vosotros todo varón en el transcurso de vuestras generaciones, tanto el nacido en (tu) casa como el comprado con dinero a cualquier extraño, aunque no sea de su raza,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Sí, deben ser circuncidados el nacido en tu casa y el adquirido con tu dinero, de modo que mi pacto estará en vuestra carne como alianza eterna.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'El varón incircunciso, que no se circuncidare la carne de su prepucio, será exterminado de entre su pueblo por haber quebrantado mi pacto.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Dijo Dios a Abrahán: “A Sarai, tu mujer, no la llamarás más Sarai, porque su nombre será Sara.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Yo la bendeciré, y de ella también te daré un hijo. La bendeciré, y será madre de naciones; reyes de pueblos procederán de ella.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Entonces cayo Abrahán sobre su rostro y riéndose dijo en su corazón: “¿A hombre de cien años le ha de nacer hijo, y Sara ya nonagenaria va a dar a luz?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Y dijo Abrahán a Dios: “¡Viva al menos delante de Ti Ismael!”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Respondió Dios: “De cierto que Sara tu mujer te dará a luz un hijo, y le pondrás por nombre Isaac; y Yo estableceré mi pacto con él como pacto eterno, y con su posteridad después de él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, '“En cuanto a Ismael, he otorgado tu petición. He aquí que le he bendecido; le multiplicaré y le haré crecer sobremanera. Doce príncipes engendrará y le haré padre de un gran pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Pero mi pacto lo estableceré con Isaac, que Sara te dará a luz por este tiempo el año que viene.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Y después de hablar con él, subió Dios dejando a Abrahán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Tomó entonces Abrahán a Ismael, su hijo, y a todos los nacidos en su casa, y a todos los comprados con su dinero, a todos los varones de la casa de Abrahán, y en ese mismo día les circuncidó la carne del prepucio, como Dios le había mandado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Tenía Abrahán noventa y nueve años cuando circuncidó la carne de su prepucio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'Ismael, su hijo, era de trece años cuando fue circuncidado en la carne de su prepucio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'En el mismo día fueron circuncidados Abrahán y su hijo Ismael.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'Y todos los varones de su casa, los nacidos en su casa, y los comprados a extraños por dinero, fueron circuncidados juntamente con él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Apareciósele Yahvé (a Abrahán) en el encinar de Mamré mientras estaba sentado a la entrada de la tienda, durante el calor del día.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Alzando los ojos miró, y he aquí que estaban parados delante de él tres varones. Tan pronto como los vio, corrió a su encuentro desde la entrada de su tienda, y postrándose en tierra');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'dijo: “Señor mío, si he hallado gracia a tus ojos, te ruego no pases de largo junto a tu siervo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Permitid que se traiga un poco de agua; y lavaos los pies, y descansaos debajo del árbol.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'Traeré, entretanto, un bocado de pan, y fortaleceréis vuestros corazones; después pasaréis adelante; pues por eso habéis pasado delante de vuestro siervo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Fue, pues, Abrahán apresuradamente a la tienda, a Sara, y dijo: “¡Pronto, tres medidas de flor de harina; amasa y haz tortas!”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Corrió Abrahán también a la vacada, tomó un ternero tierno y gordo, y lo dio a un mozo, el cual se apresuró a aderezarlo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Después tomó requesón y leche y el ternero que había aderezado, y se lo puso adelante; y mientras comían, él se quedó de pie junto a ellos, bajo el árbol.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Preguntáronle: “¿Dónde está Sara, tu mujer?” “Ahí, en la tienda”, contestó él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Entonces dijo (Dios): “Volveré a ti sin falta, por este mismo tiempo, y he aquí que Sara, tu mujer, tendrá un hijo.” Entretanto Sara estaba escuchando a la entrada de la tienda, detrás de él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Porque Abrahán y Sara eran ancianos, de avanzada edad, y había cesado ya en Sara la costumbre de las mujeres.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Se rió, pues Sara interiormente y dijo: “¿Con que siendo ya consumida he de tener deleite? Y también mi señor es viejo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Entonces dijo Yahvé a Abrahán: “¿Por qué se ha reído Sara, diciendo?: ‘¿Será cierto que voy a dar a luz, siendo, como soy, vieja?’');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, '¿Hay acaso para Yahvé cosa imposible? En el plazo señalado por este mismo tiempo, te visitaré otra vez, y Sara tendrá un hijo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Pero Sara negó, diciendo: “No me he reído”; pues tenía miedo. Mas Él dijo: “No, que te has reído”.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Levantáronse de allí los varones y se dirigieron hacia Sodoma, y Abrahán los acompañó para despedirlos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Entonces se dijo Yahvé: “¿He de encubrir a Abrahán lo que voy a hacer?');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Pues Abrahán ha de ser padre de una nación grande y fuerte y serán benditos en él todos los pueblos de la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Porque le he constituido para eso: que mande a sus hijos y a su casa después de él, guardar el camino de Yahvé, practicando la justicia y el derecho, a fin de que Yahvé haga venir sobre Abrahán lo que tiene prometido a su favor.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Dijo, pues, Yahvé: “El clamor de Sodoma y Gomorra es grande, y sus pecados son extraordinariamente graves.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Bajaré a comprobar si han hecho realmente según el clamor que ha llegado hasta Mí; y si no, lo sabré.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Partieron, pues, de allí los varones, y se encaminaron hacia Sodoma; mas Abrahán permanecía todavía en pie delante de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Y acercándose dijo Abrahán: “¿Es así que vas a destruir al justo con el impío?');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Quizás habrá cincuenta justos en la ciudad. ¿Los exterminarás acaso, y no perdonarás al lugar por los cincuenta justos que se hallaren allí?');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, '¡Lejos de Ti obrar de esta manera, que hagas morir al justo con el impío, y que el justo y el malvado sean tratados del mismo modo! ¡Lejos eso de Ti! ¿Acaso el Juez de toda la tierra no ha de hacer justicia?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Dijo entonces Yahvé: “Si hallare en Sodoma cincuenta justos en la ciudad, perdonaré a todo el lugar por amor de ellos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Replicó Abrahán diciendo: “Mira, te ruego, me he atrevido a hablar al Señor, aunque soy polvo y ceniza.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Quizás falten de los cincuenta justos cinco; ¿destruirás por los cinco toda la ciudad?” Respondió: “No la destruiré, si hallare allí cuarenta y cinco.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Y de nuevo le preguntó y dijo: “Quizás se encuentren allí cuarenta.” Contestó: “No lo haré por amor de los cuarenta.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Dijo entonces: “No se irrite el Señor si sigo hablando. Quizás se hallen allí treinta.” Y respondió: “No lo haré si hallare allí treinta.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Prosiguió: “Mira, ya que he osado hablar al Señor: Quizás haya allí veinte.” Respondió: “No la destruiré por amor de los veinte.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Te ruego, insistió; no se irrite el Señor si hablare una sola vez más: Quizás se encuentre allí diez.” “No la destruiré por amor de los diez”, contestó Él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Y se fue Yahvé, luego que acabó de hablar con Abrahán; y Abrahán volvió a su lugar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Llegaron los dos ángeles a Sodoma por la tarde cuando Lot estaba sentado en la puerta de Sodoma. Al verlos se levantó Lot a salirles al encuentro; y postrándose rostro en tierra,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'dijo: “Mirad, señores míos, os ruego que os dirijáis hacia la casa de vuestro siervo, para pernoctar y lavaros los pies, y de madrugada os levantaréis para seguir vuestro camino.” Mas ellos dijeron: “No, pues pasaremos la noche en la plaza.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Pero les instó de tal manera que se encaminaron y fueron a su casa, donde les preparó un banquete y coció panes ácimos; y comieron.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Mas antes que fueran a acostarse, los hombres de la ciudad, los sodomitas, que habían cercado la casa, todo el pueblo junto, desde los jóvenes hasta los viejos,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'llamaron a Lot y le dijeron: “¿Dónde están los varones que han venido a ti esta noche? Sácanoslos para que los conozcamos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Lot salió a la entrada donde ellos estaban, y cerrando tras sí la puerta,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'dijo: “Os ruego, hermanos míos, no hagáis esta maldad.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Mirad, tengo aquí dos hijas que aún no han conocido varón. Os las sacaré fuera; haced con ellas como bien os parezca, pero no hagáis nada a estos varones; pues para eso se han acogido a la sombra de mi techo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Mas ellos respondieron: “¡Quítate allá!” Y añadieron: “¡Este individuo que vino como extranjero, quiere hacerse juez! Ahora te trataremos a ti peor que a ellos.” Y arrojándose sobre el hombre, sobre Lot, con gran violencia se acercaron a forzar la puerta.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Entonces los (dos) varones alargaron la mano y metieron a Lot dentro de la casa donde estaban, y cerraron la puerta.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'Y a los hombres que estaban a la puerta de la casa los hirieron con ceguera, desde el menor hasta el mayor, de modo que se fatigaron (inútilmente) por hallar la puerta.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Luego dijeron los varones a Lot: “¿Tienes aquí todavía alguno? Sácalos a todos de aquí: los yernos, tus hijos y tus hijas, y todo cuanto tengas en la ciudad.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Pues vamos a destruir este lugar, porque se ha hecho grande su clamor delante de Yahvé, y Yahvé nos ha enviado a exterminarla.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Salió, pues, Lot y habló con sus yernos, desposados con sus hijas, diciendo: “Levantaos, salid de este lugar; porque Yahvé va a destruir la ciudad.” Mas era a los ojos de sus yernos como quien se burlaba.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Al rayar el alba, los ángeles apremiaron a Lot, diciendo: “Levántate, toma a tu mujer y a tus dos hijas que se hallan (contigo), no sea que perezcas por la maldad de la ciudad.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Y como él tardase, los varones lo asieron de la mano, y, por compasión de Yahvé hacia él, también a su mujer y a sus dos hijas. Lo sacaron, pues, y lo pusieron fuera de la ciudad.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Y mientras los sacaban fuera, dijo uno: “Ponte a salvo, por tu vida. No mires atrás, ni te pares en ningún lugar de la Vega. Huye a la montaña, no sea que perezcas.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Pero Lot les dijo: “No, por favor, Señor mío.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Veo que tu siervo ha hallado gracia a tus ojos, y le has mostrado tan grande misericordia salvándome la vida; mas no puedo escapar a la montaña, sin riesgo de que me alcance la destrucción y la muerte.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'He ahí cerca esa ciudad donde podría refugiarme. Es tan pequeña. Con tu permiso huiré a ella —¿no es ella tan pequeña?— y vivirá mi alma.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Contestole: “Bien, te concedo también esta gracia de no destruir la ciudad de la cual hablas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Date prisa, refúgiate allá; pues nada podré hacer hasta que hayas entrado en ella.” Por eso fue llamada aquella ciudad Segor.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Salía el sol sobre la tierra cuando Lot entraba en Segor.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Entonces Yahvé hizo llover sobre Sodoma y sobre Gomorra azufre y fuego que venía de Yahvé, desde el cielo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'Y destruyó aquellas ciudades y toda la Vega, con todos los habitantes de las ciudades, hasta las plantas del suelo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Mas la mujer de (Lot) miró atrás y se convirtió en estatua de sal.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Levantose Abrahán muy de mañana y se fue al lugar donde había estado en pie delante de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'Miró hacia Sodoma y Gomorra, y hacia toda la región de la Vega, y vio que de aquella tierra subía humo, como humo de un horno.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Así, pues, cuando Dios destruyó las ciudades de la Vega, se acordó de Abrahán y sacó a Lot de en medio de la ruina, al asolar las ciudades donde Lot habitaba.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Subió Lot de Segor y habitó con sus hijas en la montaña, porque tuvo miedo de quedarse en Segor. Se estableció, por eso, en una cueva, él y sus dos hijas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Y dijo la mayor a la menor: “Nuestro padre es viejo y no hay en el país hombre que se llegue a nosotras, como es costumbre en toda la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Vayamos a embriagar a nuestro padre con vino, y nos acostaremos con él, a fin de conseguir de nuestro padre descendencia.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Embriagaron, pues, con vino a su padre esa misma noche, y entró la mayor y se acostó con su padre, sin que él se diera cuenta de ello, ni cuando ella se acostó ni cuando se levantó.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Al día siguiente dijo la mayor a la menor: “Mira, yo me acosté anoche con mi padre; démosle a beber vino también esta noche, y entra tú para acostarte con él, de modo que de nuestro padre consigamos descendencia.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Embriagaron, pues, con vino, también aquella noche a su padre y fue la menor a acostarse con él, sin que él se diera cuenta de ello, ni cuando ella se acostó, ni cuando se levantó.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Y sucedió que las dos hijas de Lot concibieron de su padre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'La mayor dio a luz un hijo, a quien llamó Moab. Es el padre de los moabitas hasta hoy.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'También la menor dio a luz un hijo, el cual llamó Ben-ammi. Es el padre de los ammonitas hasta hoy.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'De allí se trasladó Abrahán a la región del Négueb, y habitó entre Cades y el Sur, morando temporalmente en Gerar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Y dijo Abrahán de Sara, su mujer: “Es mi hermana”; por lo cual Abimelec, rey de Gerar, envió a tomar a Sara.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Pero vino Dios a Abimelec en el sueño durante la noche, y le dijo: “He aquí que morirás a causa de la mujer que has tomado, porque es mujer casada.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Abimelec aún no se había acercado a ella, por lo cual dijo: “Señor, ¿matarás Tú también a gente justa?');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, '¿No me dijo él mismo: ‘Es mi hermana’, y ella también dijo: ‘Es mi hermano’? Con sencillez de mi corazón, y con manos inocentes he hecho esto.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Y le respondió Dios en sueños: “Bien sé que con sencillez de corazón has hecho esto; y Yo soy también quien te he preservado de pecar contra Mí. Por eso no te he permitido que la tocaras.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Devuélve, pues, la mujer de este hombre, porque es un profeta y rogará por ti, para que vivas; mas si no la devuelves, sabe que morirás indefectiblemente, tú con todos los tuyos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Se levantó Abimelec muy de mañana, llamó a todos sus siervos y contó a sus oídos todas estas palabras. Y quedaron muy amedrentados.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Después llamó Abimelec a Abrahán, y le dijo “¿Qué es lo que has hecho con nosotros? ¿Y en qué te he ofendido, para que hayas traído sobre mí y mi reino un pecado tan grande? Has hecho tú conmigo cosas que no deben hacerse.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Y Abimelec siguió diciendo a Abrahán: “¿Qué has visto para que hicieras esto?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Respondió Abrahán: “Pensé: Seguramente no hay temor de Dios en este lugar y me van a matar a causa de mi mujer.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Y en verdad, ella es también mi hermana, hija de mi padre, aunque no hija de mi madre; y vino a ser mi mujer.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Mas cuando Dios me hizo errar fuera de la casa de mi padre, le dije a ella: “Este es el favor que me has de hacer. En cualquier lugar a que lleguemos, dirás de mí: ‘Es mi hermano’.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Entonces Abimelec tomó ovejas y ganado y siervos y siervas, y se los dio a Abrahán. Le devolvió también a Sara, su mujer, diciéndole:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, '“He aquí que mi tierra está a tu disposición; habita en donde mejor te parezca.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Y a Sara le dijo: “Mira, he dado mil siclos de plata a tu hermano. Esto te servirá para velar tus ojos ante todos los que están contigo. Así quedas justificada.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Y rogó Abrahán a Dios, y sanó Dios a Abimelec, y a su mujer, y a sus siervas, y ellas tuvieron hijos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Porque Yahvé había cerrado completamente toda matriz en la casa de Abimelec, a causa de Sara, mujer de Abrahán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Visitó, pues, Yahvé a Sara según había dicho, y cumplió en ella lo prometido.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Concibió Sara y dio a Abrahán un hijo en su vejez, al tiempo que Dios había predicho.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Abrahán dio al hijo que le nació y cuya madre era Sara, el nombre de Isaac.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Y circuncidó Abrahán a Isaac, su hijo, a los ocho días, como Dios le había mandado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Abrahán tenía cien años cuando nació su hijo Isaac.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Y dijo Sara: “Dios me ha dado motivo para reírme; todo el que lo sepa se reirá de mí.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Y agregó: “¿Quién hubiera dicho a Abrahán que Sara amamantaría hijos?; pues le he dado un hijo en su vejez.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Creció el niño y fue destetado; y el día en que fue destetado Isaac, dio Abrahán un gran convite.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Mas cuando Sara vio que el hijo que Abrahán había recibido de Agar la egipcia, se burlaba,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'dijo a Abrahán: “Echa fuera a esta esclava y a su hijo; porque el hijo de esta esclava no ha de ser heredero con mi hijo Isaac.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Esta palabra parecía muy dura a Abrahán, por cuanto se trataba de su hijo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Pero Dios dijo a Abrahán: “No te aflijas por el niño y por tu esclava. En todo lo que dijere Sara, oye su voz; pues por Isaac será llamada tu descendencia.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Mas también del hijo de la esclava hare una nación, por ser descendiente tuyo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Se levantó, pues, Abrahán muy de mañana, tomó pan y un odre de agua, y se lo dio a Agar, poniéndolo sobre el hombro de esta; (le entregó) también el niño, y la despidió. La cual se fue y anduvo errante por el desierto de Bersabee.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Cuando se acabó el agua del odre, echó ella al niño bajo uno de los arbustos,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'y fue a sentarse frente a él, a la distancia de un tiro de arco; porque decía “No quiero ver morir al niño.” Sentada, pues en frente, alzó su voz y prorrumpió en lágrimas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Mas Dios oyó la voz del niño; y el Ángel de Dios llamó a Agar desde el cielo, y le dijo: “Qué te pasa, Agar? No temas, porque Dios ha oído la voz del niño en el lugar donde está.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Levántate, alza al niño, y tómalo de la mano, porque haré de él un gran pueblo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Y le abrió Dios los ojos, y ella vio un pozo de agua; fue y llenó el odre de agua, y dio de beber al niño.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Y Dios asistió al niño, el cual creció y habitó en el desierto, y vino a ser tirador de arco.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Se estableció en el desierto de Farán, y su madre le dio una mujer de la tierra de Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'En aquel tiempo Abimelec, acompañado de Picol, capitán de sus tropas, dijo a Abrahán: “Dios está contigo en todo lo que haces.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Ahora bien, júrame, aquí por Dios que no me engañarás, ni a mí, ni a mis hijos, ni a mis nietos, sino que me tratarás a mí y la tierra que te dio hospedaje con la bondad que yo he usado contigo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Respondió Abrahán: “Lo juraré.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Pero se quejó Abrahán ante Abimelec con motivo de un pozo de agua del que se habían apoderado los siervos de Abimelec.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'A lo cual contestó Abimelec: “No sé quien ha hecho esto; ni tú me lo has manifestado, ni yo lo he oído hasta ahora.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Tomó entonces Abrahán ovejas y ganado y se los dio a Abimelec; e hicieron los dos un pacto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Mas como Abrahán pusiese aparte siete corderas del rebaño,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'le dijo Abimelec: “¿Qué significan estas siete corderas que has puesto aparte?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Respondió: “Estas siete corderas has de aceptar de mi mano, para que me sirvan de testimonio de que yo he excavado este pozo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Por eso fue llamado aquel lugar Bersabee, porque allí juraron los dos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'Hicieron, pues alianza en Bersabee; y se levantó Abimelec, con Picol, capitán de sus tropas, y se volvieron al país de los filisteos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Después plantó (Abrahán) un tamarisco en Bersabee e invocó allí el nombre de Yahvé, el Dios eterno.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Y se detuvo Abrahán mucho tiempo en el país de los filisteos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Después de esto probó Dios a Abrahán, y le dijo “¡Abrahán!” “Heme aquí”, contestó este.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Le dijo entonces: “Toma a tu hijo único, a quien amas, a Isaac, y ve a la tierra de Moriah, y ofrécele allí en holocausto sobre uno de los montes que Yo te mostraré.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Se levantó, pues, Abrahán muy de mañana, aparejó su asno y tomó consigo dos de sus criados y a Isaac, su hijo; después de partir leña para el holocausto se puso en camino para ir al lugar que Dios le había indicado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Cuando al tercer día Abrahán alzó los ojos y vio el lugar desde lejos,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'dijo a sus mozos: “Quedaos aquí con el asno; yo y el niño iremos hasta allá para adorar, y después volveremos con vosotros.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Tomó, pues, Abrahán la leña para el holocausto, la cargó sobre Isaac, su hijo, y tomó en su mano el fuego y el cuchillo; y caminaron los dos juntos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Y se dirigió Isaac a Abrahán, su padre diciendo: “Padre mío”; el cual respondió: “Heme aquí, hijo mío”. Y dijo (Isaac): “He aquí el fuego y la leña, mas ¿dónde está el cordero para el holocausto?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Contestó Abrahán: “Dios se proveerá de cordero para el holocausto, hijo mío.” Y siguieron caminando los dos juntos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Llegado al lugar que Dios le había indicado, erigió Abrahán allí el altar, y dispuso la leña, después ató a Isaac su hijo, y le puso sobre el altar, encima de la leña.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Y alargando su mano tomó Abrahán el cuchillo para degollar a su hijo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'cuando he aquí que el Ángel de Yahvé le llamó desde el cielo, diciendo: “¡Abrahán, Abrahán!” Él respondió: “Heme aquí.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Dijo entonces (el Ángel): “No extiendas tu mano contra el niño, ni le hagas nada; pues ahora conozco que eres temeroso de Dios, ya que no has rehusado darme tu hijo, tu único.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Y alzó Abrahán los ojos y miró, y vio detrás de él un carnero, enredado por los cuernos en un zarzal. Fue Abrahán y tomó el carnero, y lo ofreció en holocausto en lugar de su hijo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Y dio Abrahán a aquel lugar el nombre de “Yahvé ve” por donde se dice hoy día: “En el monte de Yahvé se verá”.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'El Ángel de Yahvé llamó a Abrahán por segunda vez desde el cielo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'y dijo: “Por mí mismo he jurado, dice Yahvé: Por cuanto has hecho esto, y no has rehusado darme a tu hijo, tu único,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'te colmaré de bendiciones y multiplicaré grandemente tu descendencia como las estrellas del cielo, y como las arenas de la orilla del mar, y tus descendientes poseerán la puerta de sus enemigos;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'y en tu descendencia serán benditas todas las naciones de la tierra, porque has obedecido mi voz.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Luego volvió Abrahán a sus criados y levantándose se dirigieron juntos a Bersabee, y habitó Abrahán en Bersabee.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Pasadas estas cosas fue dada a Abrahán esta noticia: “También Milcá ha dado a luz hijos a Nacor, tu hermano (cuyos nombres son):');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Us, el cual es su primogénito; Buz, su hermano; Camuel, padre de Aram,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'Cased, Azau, Feldas, Jedlaf y Batuel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Batuel engendró a Rebeca. Estos ochos dio Milcá a luz a Nacor, hermano de Abrahán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Su concubina, llamada Reumá, le dio también hijos: Tábeh, Gáham, Tahas y Maaca.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Sara vivió ciento veinte y siete años; tantos fueron los años de la vida de Sara.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Murió Sara en Quiriat-Arbá, que es Hebrón, en la tierra de Canaán y vino Abrahán a llorar a Sara y hacer duelo por ella.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Después se levantó Abrahán de junto a su difunta, y habló con los hijos de Het diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, '“Extranjero y huésped soy en medio de vosotros; dadme una propiedad sepulcral entre vosotros, para que pueda enterrar a mi difunta, sacándola de mi vista.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Los hijos de Het respondieron a Abrahán, diciéndole:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, '“Óyenos, señor, tú eres un príncipe de Dios en medio de nosotros; entierra a tu difunta en el mejor de nuestros sepulcros; ninguno de nosotros te negará su sepulcro, para que entierres a tu muerta.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Entonces se levantó Abrahán, y postrándose ante el pueblo del país, los hijos de Het,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'les habló en estos términos: “Si es vuestra buena voluntad que sepulte yo a mi difunta, sacándola de mi vista, escuchadme, y rogad por mí a Etrón, hijo de Sóhar,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'que me ceda la cueva de Macpelá que es de su propiedad y que está al extremo de su campo; que me la ceda por buena plata, para poseer sepultura entre vosotros.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Efrón estaba sentado entre los hijos de Het, y respondió Efrón, el heteo, a Abrahán en presencia de los hijos de Het, de todos los que habían venido a la puerta de la ciudad, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'No, señor mío; óyeme; te doy el campo y te cedo la cueva que está en él; en presencia de los hijos de mi pueblo te la cedo; entierra a tu muerta.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Entonces Abrahán, postrándose de nuevo ante el pueblo del país,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'dijo a Efrón, oyéndolo el pueblo del país: “¡Ojalá me escucharas! Te doy el precio del campo; recíbelo de mí, y enterraré allí a mi muerta.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Respondió Efrón a Abrahán, diciéndole:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, '“Señor mío, escúchame: Un terreno de cuatrocientos siclos de plata, entre tú y yo, ¿qué es esto? Sepulta a tu muerta.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Oyó Abrahán a Efrón; y Abrahán pesó a Efrón el dinero que este había pedido en presencia de los hijos de Het: cuatrocientos siclos de plata corriente entre mercaderes.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Con esto el campo de Efrón, que estaba en Macpelá frente a Mamré, el campo y la cueva que estaba en él, con todos los árboles de ese campo, con todos sus contornos,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'vino a ser propiedad de Abrahán, estando presentes los hijos de Het, todos los que habían venido a la puerta de su ciudad.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Después de esto sepultó Abrahán a Sara, su mujer, en la cueva del campo, en Macpelá, frente a Mamré, que es Hebrón, en la tierra de Canaán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Así este campo, y la cueva que había en él, vinieron a ser propiedad de Abrahán como posesión sepulcral, adquirida de los hijos de Het.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Era Abrahán ya viejo, de edad muy avanzada; y Yahvé había bendecido a Abrahán en todo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Dijo, pues, Abrahán al siervo más viejo de su casa, el cual administraba todo lo que tenía: “Pon, te ruego, tu mano debajo de mi muslo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'para que te haga jurar por Yahvé, Dios del cielo y Dios de la tierra, de que no tomarás mujer para mi hijo de las hijas de los cananeos en medio de los cuales habito;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'sino que irás a mi tierra y a mi parentela, a fin de tomar mujer para mi hijo Isaac.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Respondiole el siervo: “Tal vez no quiera la mujer venir conmigo a este país. ¿Debo en tal caso llevar a tu hijo a la tierra de donde saliste?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Contestole Abrahán: “Guárdate de llevar allá a mi hijo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Yahvé, el Dios del cielo, que me sacó de la casa de mi padre y del país de mi nacimiento, y que me habló y me juró, diciendo: ‘A tu descendencia daré esta tierra’; Él enviará su ángel delante de ti, de modo que puedas traer de allí mujer para mi hijo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Si la mujer no quisiere venir contigo, estarás libre de este mi juramento, pero no lleves allá a mi hijo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Entonces puso el siervo su mano debajo del muslo de Abrahán, su señor, y le prestó juramento sobre estas cosas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Luego tomó el siervo diez camellos de su señor y emprendió el viaje, llevando consigo las cosas más preciosas que tenía su señor, y levantándose se dirigió a Mesopotamia, a la ciudad de Nacor.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Allí hizo arrodillar los camellos fuera de la ciudad, junto al pozo de agua, al caer la tarde, al tiempo que suelen salir las mujeres a sacar agua;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'y dijo: “Yahvé, Dios de mi señor Abrahán, concede, te ruego, que tenga suerte hoy, y ten misericordia de mi señor Abrahán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Heme aquí en pie junto a la fuente de aguas, adonde las hijas de los habitantes de la ciudad están saliendo a sacar agua.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Ahora bien, la joven a quien yo dijere: ‘Baja, por favor, tu cántaro para que yo beba’, y ella respondiere: ‘Bebe tú, y también a tus camellos daré de beber’, esa sea la que designaste para tu siervo Isaac; y en esto conoceré que has tenido misericordia de mi señor.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Aún no había acabado de hablar, cuando he aquí que salía Rebeca, hija de Batuel, el hijo de Milcá, mujer de Nacor, hermano de Abrahán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'La joven era de muy hermoso aspecto, virgen, que no había conocido varón. Bajó a la fuente, llenó su cántaro y volvió a subir.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'El siervo le salió al encuentro y dijo: “Dame de beber un poco de agua de tu cántaro.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, '“Bebe, señor mío”, respondió ella, y se apresuró a bajar el cántaro de su mano, y le dio de beber.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Y después de darle de beber, dijo: “También para tus camellos sacaré agua, hasta que acaben de beber.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Y vaciando apresuradamente su cántaro en el abrevadero, corrió otra vez al pozo para sacar agua, y sacó para todos sus camellos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Entretanto el hombre la contemplaba en silencio por saber si Yahvé había bendecido o no su camino.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Cuando los camellos acabaron de beber, tomó el hombre un anillo de oro, de medio siclo de peso, y dos brazaletes que pesaban diez siclos de oro para los brazos de ella.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'Y preguntó: “¿De quién eres hija? Dime, te ruego, ¿hay en casa de tu padre lugar para pasar la noche?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Ella le contestó: “Soy hija de Batuel, el hijo de Milcá, a quien ella dio a luz a Nacor.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Y agregó: “Tenemos paja y forraje en abundancia, y lugar para pernoctar.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Entonces se postró el hombre y adoró a Yahvé,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'y dijo: “Bendito sea Yahvé, el Dios de mi señor Abrahán, que no ha dejado de mostrar su benevolencia y su fidelidad para con mi señor, pues me ha guiado Yahvé en el camino a la casa de los hermanos de mi señor.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Entretanto, la joven se fue corriendo y contó en casa de su madre todas estas cosas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Tenía Rebeca un hermano que se llamaba Labán. Salió entonces Labán presuroso afuera en busca del hombre que estaba junto a la fuente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Había visto el anillo, y los brazaletes en las manos de su hermana, y había oído las palabras de Rebeca, su hermana, que decía: “Así me habló el hombre.” Vino, pues, al hombre cuando este estaba todavía con los camellos junto a la fuente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Y dijo: “¡Entra, bendito de Yahvé! ¿Por qué te quedas afuera?, pues tengo preparado la casa, y un lugar para los camellos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Fue el hombre a la casa, y desaparejó los camellos, Entretanto dio (Labán) paja y forraje a los camellos, y agua para que se lavasen los pies al hombre y los que le acompañaban.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Después le sirvió la comida; mas él dijo: “No comeré hasta que haya dicho mi mensaje.” A lo que respondió (Labán): “Habla.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Dijo, pues: “Yo soy siervo de Abrahán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Yahvé ha colmado de bendiciones a mi señor, el cual se ha hecho rico, pues le ha dado ovejas y ganado, plata y oro, siervos y siervas, camellos y asnos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Y Sara, mujer de mi señor, envejecida ya, dio a luz un hijo a mi señor, quien le ha dado todo cuanto posee.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Y me hizo jurar mi señor, diciendo: «No tomarás mujer para mi hijo de las hijas de los cananeos en cuya tierra habito,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'sino que irás a casa de mi padre y a mi parentela, y traerás mujer para mi hijo».');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Yo dije a mi señor: «Tal vez no quiera la mujer venir conmigo».');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Mas él respondió: «Yahvé, en cuya presencia ando, enviará su ángel contigo, y prosperará tu camino, y así tomarás mujer para mi hijo de mi parentela y de la casa de mi padre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Serás libre de mi maldición cuando llegues a mi parentela; si no te la dieren, libre quedarás entonces de mi maldición».');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Ahora bien, llegué hoy a la fuente y dije: «Yahvé, Dios de mi señor Abrahán, si en verdad Tú bendices el camino por donde yo ando,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'he aquí que me quedo junto a la fuente de agua; si saliere una doncella a sacar agua, y yo le dijere: ‘Dame de beber un poco de agua de tu cántaro’,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'y ella me respondiere: ‘Bebe tú, y también para tus camellos sacaré agua’, esa será la mujer que Yahvé ha designado para el hijo de mi señor.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Y aún no había acabado de hablar en mi corazón, cuando he aquí que salía Rebeca, con su cántaro al hombro, y ella bajó a la fuente y sacó agua. Yo le dije: «Dame, te ruego, de beber»');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'y al mismo instante ella bajó su cántaro de sobre su hombro, y dijo «Bebe, y también a tus camellos daré de beber». Bebí y ella abrevó también a los camellos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Entonces le pregunté, diciendo: «¿De quién eres hija?» Me respondió: «Soy hija de Batuel, el hijo de Nacor, para quien Milcá le dio a luz». Luego puse el anillo en su nariz, y los brazaletes en sus manos;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'y postrándome adoré a Yahvé, y bendije a Yahvé, el Dios de mi señor Abrahán, que me ha conducido por camino recto, a fin de traer la hija del hermano de mi señor, para su hijo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Por lo cual, si ahora queréis usar de benevolencia y lealtad con mi señor, decídmelo; y si no, decídmelo también, para que yo me dirija a la derecha o a la izquierda.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Respondieron Labán y Batuel, diciendo: “De Yahvé viene esto; nosotros no podemos decirte ni mal ni bien.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Ahí tienes a Rebeca, tómala y vete, y sea ella mujer del hijo de tu señor, como lo ha dispuesto Yahvé.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Cuando el siervo de Abrahán oyó lo que decían, se postró en tierra ante Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Y sacó el siervo objetos de plata y objetos de oro y vestidos y los dio a Rebeca; hizo también ricos presentes a su hermano y a su madre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Después comieron y bebieron, él y los hombres que le acompañaban y pasaron la noche. Cuando se levantaron a la mañana, dijo: “Dejadme volver a casa de mi señor.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'A lo cual respondieron el hermano de ella y su madre: “Quédese la niña con nosotros algunos días, unos diez; después partirá.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Mas él les contestó: “No me detengáis, ya que Yahvé ha bendecido mi viaje; despedidme para que vaya a mi señor.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Ellos dijeron: “Llamemos a la joven y preguntemos lo que diga ella.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Llamaron, pues, a Rebeca, y la preguntaron: “Quieres ir con este hombre.” “Iré”, contestó ella.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Entonces despidieron a Rebeca, su hermana, y a su nodriza, y al siervo de Abrahán con sus hombres.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Y bendijeron a Rebeca, diciéndole: “¡Hermana nuestra, crezcas en millares y decenas de millares, y apodérese tu descendencia de la puerta de sus enemigos!”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Después se levantó Rebeca con sus doncellas, y montadas sobre los camellos, siguieron al hombre, el cual tomó a Rebeca y partió.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Entre tanto Isaac había vuelto del pozo del “Viviente que me ve”; pues habitaba en la región del Négueb;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'y por la tarde cuando salió al campo a meditar y alzó los ojos vio que venían unos camellos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'También Rebeca alzó sus ojos y viendo a Isaac, descendió del camello;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'y preguntó al siervo: “Quién es aquel hombre que viene por el campo a nuestro encuentro” Contestó el siervo: “Es mi señor.” Entonces ella tomó su velo y se cubrió.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'El siervo contó a Isaac todo lo que había hecho;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'y condujo Isaac a Rebeca a la tienda de Sara, su madre; y tomó a Rebeca, la cual pasó a ser su mujer; y la amó; y así se consoló Isaac después de la muerte de su madre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Abrahán tomó todavía otra mujer, que se llamaba Keturá.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'De esta le nacieron Simrán, Jocsán, Madán, Madián, Jesboc y Sua.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Jocsan engendró a Sabá y a Dedán. Los hijos de Dedán fueron los Asurim, los Letusim y los Leummim.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Los hijos de Madián fueron Efá, Efer, Enoc, Abidá y Eldaá. Todos estos son hijos de Keturá.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Todo cuanto tenía dio Abrahán a Isaac.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'A los hijos de sus concubinas les hizo donaciones; y, viviendo aún él mismo, los separó de Isaac, enviándolos hacia el Oriente, a las regiones orientales.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Estos fueron los días de los años de la vida de Abrahán: ciento setenta y cinco años.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Expiró Abrahán y murió en buena vejez, anciano y satisfecho; y fue a reunirse con su pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Isaac e Ismael, sus hijos lo enterraron en la cueva de Macpelá, en el campo de Efrón, hijo de Sohar, el heteo, frente a Mamré,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'en el campo que Abrahán había comprado a los hijos de Het. Allí está sepultado Abrahán, con Sara, su mujer.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Después de la muerte de Abrahán bendijo Dios a Isaac, su hijo, el cual habitaba junto al pozo del “Viviente que me ve”.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Estos son los descendientes de Ismael, hijo de Abrahán, que le nació de Agar la egipcia, esclava de Sara.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'Y estos son los nombres de los hijos de Ismael, según los nombres de sus linajes: El primogénito de Ismael fue Nebayot; después Kedar, Abdeel, Mibsam,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'Mismá, Dumá, Masá.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Hadad, Temá, Yetur, Nafís y Kedmá.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Estos son los hijos de Ismael, y estos son sus nombres según sus poblados y sus campamentos; doce príncipes de otros tantos pueblos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Y estos fueron los años de la vida de Ismael: ciento treinta y siete años; después expiró y murió, y fue a reunirse con su pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Habitó desde Havilá hasta Sur, que está frente a Egipto, cuando uno va a Asiria, y se extendió al este de todos sus hermanos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Esta es la historia de Isaac, hijo de Abrahán: Abrahán engendró a Isaac.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Isaac tenía cuarenta años cuando tomó por mujer a Rebeca, hija de Batuel, arameo, de Mesopotamia, hermana de Labán, arameo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Rogó Isaac a Yahvé por su mujer, porque ella era estéril; y Yahvé le escuchó, y concibió Rebeca, su mujer.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Pero se chochaban los hijos en su seno, por lo cual dijo “Si es así, ¿qué será de mí?” Y se fue a consultar a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Le respondió Yahvé: “Dos pueblos están en tu seno, dos naciones que se dividirán desde tus entrañas. Y una nación será más fuerte que la otra; pues el mayor servirá al menor.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Y he aquí, cuando llegó el tiempo de dar a luz, había mellizos en su seno.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Salió el primero, rubio todo él como un manto de pelo; y le llamaron Esaú.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Después salió su hermano, que con su mano tenía agarrado el talón de Esaú; por lo cual le llamaron Jacob. Isaac contaba sesenta años cuando nacieron.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Crecieron los niños, y fue Esaú diestro en la caza, hombre del campo; Jacob, empero, hombre apacible, que quedaba en casa.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Isaac amaba a Esaú, porque comía de su caza; Rebeca, por su parte, quería a Jacob.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Ahora bien, Jacob habíase hecho un guiso; y cuando Esaú, muy fatigado, volvió del campo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'dijo a Jacob: “Por favor, déjame comer de este guiso rojo, que estoy desfallecido.” Por esto fue llamado Edom.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Respondió Jacob: “Véndeme ahora mismo tu primogenitura.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, '“Mira, dijo Esaú, yo me muero, ¿de qué me sirve la primogenitura?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Replicó Jacob: “Júramelo ahora mismo.” Y él se lo juró, vendiendo a Jacob su primogenitura.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Entonces Jacob dio a Esaú pan y el guiso de lentejas, y este comió y bebió; después se levantó y se marchó. Así despreció Esaú la primogenitura.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Vino un hambre sobre el país, fuera de la primera hambre que había habido en tiempo de Abrahán. Se fue entonces Isaac a Gerar, a Abimelec, rey de los filisteos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Pues se le apareció Yahvé, y le dijo: “No desciendas a Egipto; fija tu residencia en el país que Yo te indicaré.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Vive como extranjero en este país, y Yo estaré contigo y te bendeciré; porque a ti y a tu descendencia daré todas estas tierras, y cumpliré el juramento que hice a tu padre Abrahán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'Multiplicaré tu posteridad como las estrellas del cielo, y daré a tu descendencia todas estas tierras; y en tu descendencia serán benditas todas las naciones de la tierra,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'por haber obedecido Abrahán mi voz, y haber cumplido mi servicio, mis mandamientos, mis estatutos y mis leyes.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Habitó, pues, Isaac en Gerar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Al preguntarle los hombres del lugar acerca de su mujer, dijo: “Es mi hermana”; porque tenía miedo de que al decir: “Es mi mujer”, lo matasen los hombres del lugar a causa de Rebeca; pues ella era de hermoso aspecto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Mas como se prolongase allí su estancia, aconteció que Abimelec, rey de los filisteos, mirando por una ventana vio que Isaac acariciaba a su mujer Rebeca.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Entonces llamó Abimelec a Isaac y le dijo: “Bien veo que ella es tu mujer. ¿Por qué, pues dijiste: ‘Es mi hermana’?” Y le respondió Isaac: “Porque pensé: No vaya yo a morir por causa de ella.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Replicó Abimelec: “¿Qué es esto que nos has hecho? Fácilmente alguno del pueblo hubiera podido tomar tu mujer, y hubieras traído sobre nosotros un pecado.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Por lo cual dio Abimelec a todo el pueblo una orden que decía: “Quien tocare a este hombre o a su mujer, morirá irremisiblemente.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Sembró Isaac en aquella tierra, y cosechó aquel año el ciento por uno; pues Yahvé le bendijo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'Y el hombre se hizo rico y fue engrandeciéndose cada día más, de manera que vino a ser muy rico.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'Tenía rebaños de ovejas y de ganados y mucha servidumbre. Por lo cual los filisteos le tuvieron envidia;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'y cegaron todos los pozos que los siervos de su padre habían cavado en tiempo de Abrahán, su padre y los llenaron de tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Dijo entonces Abimelec a Isaac: “Retírate de nosotros, porque te has hecho mucho más poderoso que nosotros.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Fuése, pues, Isaac de allí, y acampó en el valle de Gerar, donde fijó su residencia.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Isaac abrió de nuevo los pozos de agua cavados en los días de Abrahán, su padre, que los filisteos habían cegado después de la muerte de Abrahán; y les dio los mismos nombres que les había puesto su padre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Después cavaron los siervos de Isaac en el valle, y hallaron allí un pozo de agua viva.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Pero riñeron los pastores de Gerar con los pastores de Isaac, diciendo: “Nuestra es el agua.” De donde llamó al pozo Esec, porque habían reñido con él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Cavaron otro pozo; y también por él se pelearon, por lo cual le puso por nombre Sitná.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Partió de allí y cavó otro pozo, por el cual no hubo altercado; por tanto lo llamó Rehobot, diciendo: “Porque ahora Yahvé nos ha dado anchura, y podremos prosperar sobre la tierra.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'De allí subió a Bersabee;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'y se le apareció Yahvé aquella noche, y dijo: “Yo soy el Dios de Abrahán, tu padre. No temas, porque Yo estoy contigo; te bendeciré, y multiplicaré tu descendencia por amor a Abrahán, mi siervo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Erigió allí un altar, donde invocó el nombre de Yahvé y plantó su tienda; y los siervos de Isaac cavaron allí un pozo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Vino entonces a él Abimelec desde Gerar, con Ahuzar, su amigo, y Picol, capitán de sus tropas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Isaac les dijo: “¿Cómo es que venís a mí, vosotros que me odiáis y me habéis echado de entre vosotros?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'Contestaron ellos: “Hemos visto claramente que Yahvé está contigo; por lo cual nos dijimos: Haya un juramento entre nosotros, entre ti y nosotros. Pactaremos alianza contigo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'de que no nos harás mal alguno, así como nosotros no te hemos tocado, pues no hemos hecho contigo sino bien, y te hemos despedido en paz. Tú eres ahora el bendito de Yahvé.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Entonces les dio un convite, y comieron y bebieron;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'y levantándose muy de mañana juraron el uno al otro. Después los despidió Isaac, y se retiraron de él en paz.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Aquel mismo día vinieron los siervos de Isaac a darle noticia del pozo que habían cavado, diciéndole: “Hemos hallado agua.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'Y lo llamó Sebá. Por eso el nombre de aquella ciudad es Bersabee hasta el día de hoy.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Cuando Esaú tenía cuarenta años, tomó por mujeres a Judit, hija de Beerí, heteo, y a Basemat, hija de Elón, heteo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'las cuales causaron a Isaac y Rebeca mucha amargura.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Cuando Isaac era viejo y se le habían debilitado los ojos, de modo que ya no veía, llamó a Esaú, su hijo mayor, y le dijo: “Hijo mío”; el cual le contestó: “Heme aquí.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Y dijo: “Mira, yo soy viejo, y no sé el día de mi muerte.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Toma, pues, ahora tus armas, tu aljaba, y tu arco, y sal al campo, cázame algo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'y prepárame un buen guiso, según mi gusto, y tráemele para comida, y mi alma te bendecirá antes de morirme.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Mas Rebeca estaba escuchando cuando Isaac hablaba a Esaú, su hijo; y cuando Esaú fue al campo a cazar una presa de casa para traérselo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'habló Rebeca con Jacob, su hijo, diciendo: “Mira, he oído a tu padre cómo hablando con Esaú tu hermano, le decía:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, '‘Tráeme caza, y hazme un buen guiso para comida, y te bendeciré delante de Yahvé antes de morirme’.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Ahora bien, hijo mío, oye mi voz en lo que te mando.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Ve al rebaño, y tráeme de allí dos buenos cabritos; y yo haré con ellos para tu padre un sabroso guiso como a él le gusta;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'y se lo presentarás a tu padre, el cual lo comerá y te bendecirá antes de su muerte”.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Contestó Jacob a Rebeca, su madre: “Mira que Esaú, mi hermano, es hombre velludo, y yo lampiño.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Quizás me palpe mi padre; seré entonces a sus ojos como quien se burla de él y me acarrearé maldición, en lugar de bendición.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Replicole su madre: “Sobre mí tu maldición, hijo mío; oye tan solo mi voz, anda y tráemelos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Fue, pues, a tomarlos, y los trajo a su madre; e hizo su madre un sabroso guiso, como le gustaba a su padre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Después tomó Rebeca vestidos de Esaú, su hijo mayor, los mejores que tenía en casa, y los vistió a Jacob, su hijo menor.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'Y con las pieles de los cabritos le cubrió las manos y la parte lisa de su cuello.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'Luego puso el guiso y el pan que había preparado, en manos de Jacob su hijo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'el cual entró donde estaba su padre, y dijo “Padre mío”, a lo que este respondió: “Heme aquí; ¿quién eres, hijo mío?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, '“Yo soy tu primogénito Esaú”, dijo Jacob a su padre. “He hecho como me dijiste; levántate, te ruego, siéntate, y come de mi caza, para que me bendiga tu alma.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Preguntó Isaac a su hijo: “¿Cómo es que has podido encontrarla tan pronto, hijo mío?” El cual respondió: “porque Yahvé, tu Dios me la puso delante.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Dijo entonces Isaac a Jacob: “Acércate, y te palparé, a ver si realmente eres o no mi hijo Esaú.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Acercose, pues Jacob a su padre Isaac, el cual lo palpó y dijo: “La voz es la voz de Jacob, pero las manos son las manos de Esaú.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Y no lo reconoció, porque sus manos estaban velludas, como las manos de su hermano Esaú y así lo bendijo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'Pero repitió la pregunta: “¿Eres tú realmente mi hijo Esaú?” Y él respondió: “Soy yo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Dijo entonces: “Acércame la caza, y comeré de ella, hijo mío, para que te bendiga mi alma.” Se la acercó, y comió; le sirvió también vino y bebió.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Después le dijo Isaac, su padre: “Acércate y bésame, hijo mío.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Se acercó y lo besó; y cuando (Isaac) sintió la fragancia de sus vestidos, le bendijo diciendo: “Mira, el olor de mi hijo es como el olor de un campo bendecido por Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, '¡Te de Dios del rocío del cielo, y de la grosura de la tierra, y abundancia de trigo y de vino!');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, '¡Sírvante pueblos, y póstrense delante de ti naciones; sé señor de tus hermanos, e inclínense ante ti los hijos de tu madre! ¡Maldito el que te maldiga, y bendito quien te bendiga!”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Apenas Isaac había acabado de bendecir a Jacob, y no bien había salido Jacob de la presencia de su padre Isaac, cuando Esaú, su hermano, volvió de su caza.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'Hizo también un sabroso guiso y presentándolo a su padre le dijo: “Levántese mi padre y coma la caza de su hijo, para que me bendiga tu alma.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Isaac, su padre, le dijo: “¿Quién eres tú?” Le contestó: “Soy tu hijo, el primogénito tuyo Esaú.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Asombrose Isaac sobremanera, hasta el extremo, y dijo: “¿Quién es, pues, aquel que fue a cazar y me trajo caza, y yo he comido de todo antes que tu vinieses, y lo he bendecido de suerte que quedará bendito?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Al oír Esaú las palabras de su padre, lanzó un grito fuerte y extremadamente amargo, y dijo a su padre: “¡Bendíceme también a mí, padre mío!”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Mas él respondió: “Ha venido tu hermano con engaño, y se ha llevado tu bendición.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Dijo entonces (Esaú): “Con razón se llama Jacob; pues me ha suplantado ya dos veces: me quitó la primogenitura, y ya ves que ahora me ha quitado la bendición.” Y añadió “¿No has reservado bendición para mí?');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Isaac respondió y dijo a Esaú: “Mira, le he puesto por señor tuyo, le he dado por siervos a todos sus hermanos y le he provisto de trigo y vino. Por ti, pues, ¿qué podré hacer ahora, hijo mío?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Dijo Esaú a su padre: “¿No tienes más que un sola bendición, padre mío? ¡Bendíceme también a mí, padre mío!” y levantó Esaú su voz y rompió a llorar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Entonces repuso Isaac, su padre, diciendo: “He aquí que lejos de la grosura de la tierra será tu morada, y lejos del rocío que baja del cielo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'De tu espada vivirás, y servirás a tu hermano, pero cuando empieces a dominar, romperás su yugo de sobre tu cerviz.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Esaú concibió odio contra Jacob a causa de la bendición con que le había bendecido su padre; y dijo Esaú en su corazón: “Se acercan ya los días en que haré duelo por mi padre; después mataré a Jacob, mi hermano.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Rebeca tuvo noticia de las palabras de Esaú, su hijo mayor; por lo cual envió a llamar a Jacob, su hijo menor, y le dijo: “Mira, tu hermano Esaú quiere vengarse de ti, matándote.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Ahora, pues, hijo mío, oye mi voz: levántate y huye a Harán, a casa de mi hermano Labán;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'y estarás con él algún tiempo, hasta que se apacigüe la cólera de tu hermano;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'hasta que la ira de tu hermano se aparte de ti, y él se olvide de lo que le has hecho. Yo entonces enviaré por ti y te traeré de allá. ¿Por qué he de quedar privada de vosotros dos en un mismo día?');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Y dijo Rebeca a Isaac: “Me da fastidio el vivir, a causa de las hijas de Het. Si Jacob toma mujer de las hijas de Het, como estas, de las hijas de este país, ¿para qué seguir viviendo?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Llamó, pues, Isaac a Jacob y lo bendijo, y le dio esta orden: “No tomes mujer de las hijas de Canaán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Levántate y ve a Mesopotamia, a casa de Batuel, padre de tu madre, y toma de allí mujer, de las hijas de Labán, hermano de tu madre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Bendígate el Dios Todopoderoso, y te haga crecer, y te multiplique, para que llegues a ser padre de muchos pueblos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'Y te conceda la bendición de Abrahán, a ti y a tu descendencia contigo; a fin de que poseas la tierra de tus peregrinaciones, que Dios ha dado a Abrahán.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Despidió, pues, Isaac a Jacob, el cual se fue a Mesopotamia, a Labán, hijo de Batuel, arameo, hermano de Rebeca, madre de Jacob y Esaú.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Vio, pues Esaú que Isaac había bendecido a Jacob, y le había enviado a Mesopotamia a fin de que allí se tomase mujer, y que al bendecirlo le había dado la orden: “No tomes mujer de las hijas de Canaán”,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'y que Jacob, obedeciendo a su padre y a su madre, había marchado a Mesopotamia,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'conoció Esaú que las hijas de Canaán eran malas a los ojos de Isaac, su padre,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'por lo cual fue Esaú a Ismael, y se tomó por mujer, sobre las mujeres que ya tenía, a Mahalat, hija de Ismael, el hijo de Abrahán y hermana de Nabayot.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Jacob salió de Bersabee y se dirigió a Harán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Llegado a cierto lugar, pasó allí la noche, porque ya se había puesto el sol. Y tomando una de las piedras del lugar, se la puso por cabezal, y se acostó en aquel sitio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Y tuvo un sueño: he aquí una escalera que se apoyaba en la tierra, y cuya cima tocaba en el cielo; los ángeles de Dios subían y bajaban por ella.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Y sobre ella estaba Yahvé, que dijo: “Yo soy Yahvé, el Dios de tu padre Abrahán, y el Dios de Isaac; la tierra en que estás acostado, te la daré a ti y a tu descendencia.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Tu posteridad será como el polvo de la tierra; y te extenderás hacia el occidente y hacia el oriente, hacia el aquilón y hacia el mediodía; y en ti y en tu descendencia serán benditas todas las tribus de la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Y he aquí que Yo estaré contigo, y te guardaré en todos tus caminos y te restituiré a esta tierra; porque no te abandonaré hasta haber cumplido cuanto te he dicho.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Cuando Jacob despertó de su sueño, exclamó: “Verdaderamente Yahvé está en este lugar y yo no lo sabía.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Y lleno de temor añadió: “¡Cuan venerable es este lugar!, no es sino la casa de Dios y la puerta del cielo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Se levantó Jacob muy de mañana, tomó la piedra que había puesto por cabezal, la erigió en monumento y derramó óleo sobre ella.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Y llamó a aquel lugar Betel —antiguamente el nombre de la ciudad era Luz—.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Y Jacob hizo un voto, diciendo: “Si Dios está conmigo, y me guarda en este viaje que hago, y me da pan que comer y ropa con que vestirme,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'y vuelvo yo en paz a la casa de mi padre, entonces será Yahvé mi Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'Esta piedra que he erigido en monumento será casa de Dios; y de todo lo que me dieres, te daré el diezmo sin falta.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Jacob prosiguió su viaje y se fue al país de los hijos de Oriente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Mirando vio en el campo un pozo y he aquí tres rebaños de ovejas sesteando junto a él; pues en aquel pozo se abrevaban los rebaños; y había una piedra grande sobre la boca del pozo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Allí se reunían todos los rebaños; (los pastores) removían la piedra de sobre la boca del pozo, para abrevar los rebaños, y después volvían aponer la piedra en su lugar sobre la boca del pozo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Díjoles Jacob: “Hermanos, ¿de dónde sois?” Contestaron: “Somos de Harán”.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Les preguntó: “¿Conocéis a Labán, hijo de Nacor?” Respondieron: “Lo conocemos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Les dijo entonces: “¿Está bien?” “Bien está, respondieron ellos, y he aquí a Raquel, su hija, que viene con su rebaño.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Entonces dijo: “Todavía es muy de día, no es hora de recoger el ganado; abrevad las ovejas, y volved a apacentarlas.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Ellos respondieron: “No podemos, hasta que se reúnan todos los rebaños y se remueva la piedra de sobre la boca del pozo para que abrevemos las ovejas.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Aún estaba hablando con ellos, cuando llegó Raquel con las ovejas de su padre, pues ella era pastora.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Como viese Jacob a Raquel, hija de Labán, hermano de su madre, se acercó y removió la piedra de sobre la boca del pozo y abrevó las ovejas de Labán, hermano de su madre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Y besó Jacob a Raquel, y alzó su voz para llorar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Luego declaró Jacob a Raquel que era hermano de su padre e hijo de Rebeca. Tras lo cual ella echó a correr y avisó a su padre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Cuando Labán oyó lo que le decía de Jacob, hijo de su hermana, corrió a su encuentro, lo abrazó, lo besó y lo condujo a su casa. Y (Jacob) contó a Labán todas estas cosas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Díjole entonces Labán: “De veras, eres hueso mío y carne mía.” Y estuvo con él por espacio de un mes.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Dijo Labán a Jacob: “¿Acaso por ser mi hermano, has de servirme de balde? Dime cuál será tu salario.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Ahora bien, tenía Labán dos hijas; el nombre de la mayor era Lía, y el nombre de la menor, Raquel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Lía tenía los ojos enfermos; Raquel, en cambio, era de buena figura y de hermoso aspecto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Jacob amaba a Raquel, por lo cual dijo: “te serviré siete años por Raquel, tu hija menor.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Labán respondió: “Mejor es dártela ti, que dársela a otro; quédate conmigo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Sirvió, pues, Jacob por Raquel siete años, que le parecieron como unos pocos días, por el amor que le tenía.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Dijo entonces Jacob a Labán: “Dame mi mujer, que se han cumplido los días, y me llegaré a ella.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Reunió, pues, Labán a toda la gente del lugar y dio un banquete.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Mas por la noche tomó a Lía, su hija, y la llevó a Jacob, y este se llegó a ella.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Y dio Labán a su hija Lía su sierva Silfá para esclava.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Llegada la mañana, vio (Jacob) que era Lía. Dijo, pues, a Labán: “¿Qué es lo que has hecho conmigo? ¿No te he servido por Raquel? ¿Por qué me has engañado?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Respondió Labán: “No es costumbre en nuestra tierra dar la menor antes que la mayor.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Cumple la semana con esta, y te daremos también la otra, por el servicio que me prestarás durante otros siete años.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Jacob lo hizo así; y habiendo cumplido la semana con ella, le dio por mujer a su hija Raquel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Y dio Labán por esclava a su hija Raquel su sierva Bilhá.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Así se llegó (Jacob) también a Raquel, a la cual amó más que a Lía y sirvió a (Labán) otros siete años.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Viendo Yahvé que Lía era menospreciada, la hizo fecunda, mientras Raquel era estéril.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Concibió Lía y dio a luz un hijo, al cual llamó Rubén, pues decía: “Yahvé ha mirado mi aflicción; ahora sí que me amará mi marido.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Concibió otra vez y dio a luz un hijo, y dijo: “Yahvé oyó que yo era menospreciada; por eso me ha dado también este.” Y le llamó Simeón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Concibió de nuevo y dio a luz un hijo, y dijo: “Ahora, esta vez, mi marido se aficionará a mí, ya que le he dado tres hijos.” Por eso le llamó Leví.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Volvió a concebir, y dio a luz un hijo, y dijo “Esta vez alabaré a Yahvé.” Por tanto, le puso por nombre Judá; y cesó de tener hijos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Viendo Raquel que no daba hijos a Jacob, tuvo envidia de su hermana, y dijo a Jacob: “Dame hijos, de lo contrario me muero.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Entonces se airó Jacob contra Raquel, y dijo: “¿Estoy yo acaso en el lugar de Dios, que te ha negado el fruto del seno?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'A lo cual ella contestó: “Ahí tienes a mi sierva Bilhá: llégate a ella para que dé a luz sobre mis rodillas. Así también yo tendré descendencia, por medio de ella.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Diole, pues, a Bilhá, su sierva, por mujer; y Jacob se llegó a ella.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Concibió Bilhá y dio a Jacob un hijo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Y dijo Raquel: “Dios me ha hecho justicia, y también ha oído mi voz, concediéndome un hijo.” Por eso le llamó Dan.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Concibió otra vez Bilhá, sierva de Raquel, y dio a Jacob un segundo hijo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Entonces dijo Raquel: “Luchas de Dios he luchado con mi hermana y he vencido.” Y le llamó Neftalí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Ahora bien, cuando Lía vio que había dejado de dar a luz, tomó a Silfá, su sierva, y se la dio a Jacob por mujer.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Y cuando Silfá, sierva de Lía, dio a Jacob un hijo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'exclamó Lía: ¡Qué buena suerte!”, y le puso por nombre Gad.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Silfá, sierva de Lía, dio a Jacob también un segundo hijo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'y dijo Lía: “¡Por dicha mía!, porque me llamarán dichosa las doncellas.” Y le llamó Aser.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Un día salió Rubén, en tiempo de la cosecha del trigo, y halló mandrágoras en el campo, que llevó a su madre Lía. Y dijo Raquel a Lía: “Dame, por favor, de las mandrágoras de tu hijo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Mas ella le contestó: “¿Te parece poco haberme quitado mi marido? ¿Quieres también quitarme las mandrágoras de mi hijo?” A lo cual contestó Raquel: “Duerma entonces contigo esta noche, a trueque de las mandrágoras de tu hijo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'A la tarde, cuando Jacob volvió del campo, salió Lía a su encuentro y le dijo: “A mí has de venir, pues te he comprado por las mandrágoras de mi hijo”; por lo cual aquella noche durmió con ella.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Y oyó Dios a Lía, que concibió y dio a Jacob un quinto hijo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Y dijo Lía. “Dios ha dado mi recompensa por haber dado mi sierva a mi marido”; y le llamó Isacar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Lía concibió otra vez y dio un sexto hijo a Jacob.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'Y dijo Lía: “Dios me ha dado un buen regalo; ahora habitará mi marido conmigo, pues le he dado seis hijos.” Y le puso por nombre Zabulón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Después dio a luz una hija, a la que llamó Dina.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Se acordó Dios también de Raquel, la oyó y la hizo fecunda.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Concibió y dio a luz un hijo, y dijo: “Ha quitado Dios mi oprobio.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Y le puso por nombre José, diciendo: “Añádame Yahvé otro hijo”.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Cuando Raquel hubo dado a luz a José, dijo Jacob a Labán: “Déjame marchar, e iré a mi lugar y a mi tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Dame mis mujeres y mis hijos, por quienes te he servido, y me iré; bien sabes los servicios que te he hecho.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Le respondió Labán: “¡Halle yo gracia a tus ojos! He observado que Yahvé me ha bendecido por tu causa.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Y agregó: “Fíjame tu salario, y lo daré.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Contestó él: “Tú sabes cómo te he servido, y cómo ha crecido tu hacienda conmigo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Poco era lo que tenías antes de mi venida, pero se ha aumentado en extremo, pues Yahvé te ha bendecido con mi llegada. Ahora, pues, ¿cuándo podré trabajar también por mi casa?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Le preguntó (Labán): “¿Qué es lo que he de darte?” “No me des nada, respondió Jacob, antes bien haz conmigo lo que te voy a decir, y volveré a pastorear y guardar tu rebaño.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Recorreré hoy toda tu grey, apartando de ella todo animal salpicado y mancho y todo animal negro entre los corderos y todo animal manchado y salpicado entre las cabras, y (esto) será mi recompensa.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Y responderá por mí mi rectitud el día de mañana, cuando se presente delante de ti mi salario: Todo lo que no fuere salpicado y manchado entre las cabras, y negro entre los corderos, será en mí un robo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, '“Bien está, dijo Labán, sea como dices.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Y aquel mismo día (Labán) separó los chivos listados y manchados y todas las cabras salpicadas y manchadas, todo lo que tenía algo de blanco, y todo lo negro entre los corderos, y lo entregó en manos de sus hijos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'Además fijó una distancia de tres jornadas entre él y Jacob, el cual siguió apacentando el resto del rebaño de Labán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Entonces tomó Jacob unas varas verdes de álamo, de almendro y de plátano, y les quitó parte de la corteza, dejando al descubierto lo blanco de las varas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'Y colocó las varas así descortezadas en los canales o abrevaderos de agua a donde venían los animales a beber. (Las colocó) a la vista de los animales, para que se encelasen al tiempo de beber.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'Y así se encelaban los animales a la vista de las varas, y parían crías listadas, salpicadas y manchadas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Y Jacob separó los corderos, dirigiendo ese ganado hacia las reses listadas y poniendo, en cambio, todo lo negro en el rebaño de Labán; y él colocó sus hatos aparte, sin ponerlos junto al rebaño de Labán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Y cada vez que se encelaban las reses robustas, ponía Jacob las varas ante los ojos del ganado en los abrevaderos, para que se encelasen ante las varas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'Mas cuando el ganado estaba débil, no las ponía, de modo que las crías débiles eran para Labán, y las robustas para Jacob.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Así el hombre se enriqueció de un modo extraordinario, y tuvo muchos rebaños, siervas y siervos, camellos y asnos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Oyó Jacob las palabras de los hijos de Labán, que decían: “Jacob se ha apoderado de todo lo que era de nuestro padre, y con la hacienda de nuestro padre ha adquirido toda esta riqueza.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Jacob observó también el rostro de Labán y vio que no era para él como antes.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Dijo, pues, Yahvé a Jacob: “Vuélvete a la tierra de tus padres y a tu parentela, y Yo estaré contigo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Entonces Jacob envió llamar a Raquel y a Lía al campo, donde estaban sus rebaños,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'y le dijo “Veo que el rostro de vuestro padre no es para mí como antes, mas el Dios de mi padre ha estado conmigo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Como sabéis he servido a vuestro padre con todas mis fuerzas;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'pero vuestro padre se ha burlado de mí, cambiando diez veces mi salario, aunque Dios no le ha permitido dañarme.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Si él decía: ‘Las ovejas salpicas serán tu salario’, todas las ovejas parían crías salpicadas. Y se decía: ‘Las listadas serán tu salario’, todas las ovejas parían crías listadas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'De esta suerte Dios ha quitado la hacienda de vuestro padre y me la ha entregado a mí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Al tiempo que las ovejas entraban en calor, alcé mis ojos y vi en sueños que los machos que cubrían el ganado eran listados, salpicados y manchados,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Y me dijo el Ángel de Dios en sueño: ‘¡Jacob!’, a lo cual yo respondí: ‘Heme aquí.’');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Y dijo Él: ‘Alza los ojos, y verás que todos los machos que cubren el ganado son listados, salpicados y manchados, porque he visto todo lo que te ha hecho Labán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Yo soy el Dios de Betel, donde ungiste un monumento, y donde me hiciste un voto. Ahora, pues, levántate, sal de esta tierra, y vuelve al país de tu nacimiento.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Respondieron Raquel y Lía, diciéndole: “¿Tenemos acaso todavía alguna parte y herencia en la casa de nuestro padre?');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, '¿No nos ha tratado como extranjeras?, pues nos vendió, y se comió por completo nuestro dinero.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Mas ahora toda la riqueza que Dios ha quitado a nuestro padre, es nuestra y de nuestros hijos. Haz, pues, cuanto te ha dicho Dios.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Se levantó entonces Jacob, hizo subir a sus hijos y a sus mujeres sobre los camellos,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'y llevándose todo su ganado, y toda su hacienda que había adquirido, los bienes que había ganado en Mesopotamia, y se fue a Isaac, su padre, al país de Canaán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Labán había ido a esquilar sus ovejas. Entre tanto robó Raquel los terafim que tenía su padre,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'y Jacob engañó a Labán, arameo, no comunicándole su huída.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Pues huyó con todo lo que era suyo, y levantándose pasó el río, y se encaminó hacia las montañas de Galaad.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'Al tercer día recibió Labán la noticia de que Jacob había escapado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Entonces tomó a sus hermanos consigo, y persiguiéndolo durante siete días, le dio alcance en la montaña de Galaad.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Mas Dios se llegó a Labán, arameo, en sueño durante la noche y le dijo: “Guárdate de decir a Jacob cosa alguna, sea buena, sea mala.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Alcanzó, pues Labán a Jacob, cuando este tenía fijadas sus tiendas en el monte, y acampó también Labán, con sus hermanos, en el monte de Galaad.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Y dijo Labán a Jacob: “¿Qué es lo que has hecho? Me engañaste y te has llevado a mis hijas como cautivas de guerra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, '¿Por qué escapaste secretamente, engañándome, y no me avisaste? Te habría despedido con alegría y cantos, con tamboriles y cítaras.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'Ni siquiera me has dejado besar a mis hijos y a mis hijas. De veras, has obrado neciamente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Está en mi mano el haceros mal; pero el Dios de vuestro padre me habló anoche, diciendo: ‘Guárdate de decir a Jacob cosa alguna, sea buena, sea mala.’');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Mas ya que has partido, porque tanto deseabas ir a la casa de tu padre, ¿por qué has robado mis dioses?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Contestó Jacob, y dijo a Labán: “Tuve miedo, pues pensaba que tal vez me quitarías tus hijas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'En cuanto a tus dioses, aquel en cuyo poder los encuentres, que muera. En presencia de nuestros hermanos haz tus pesquisas, y en caso que tengo yo algo, llévatelo.” Pues Jacob no sabía que Raquel los había robado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Entró entonces Labán en la tienda de Jacob, y en la tienda de Lía, y en la tienda de las dos siervas, y no halló nada. Salió de la tienda de Lía, y entró en la tienda de Raquel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Mas Raquel había tomado los terafim y los había metido en la albarda del camello, sentándose encima, y a Labán que registró toda la tienda, sin encontrar nada,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'le dijo: “No se irrite mi señor si no puedo levantarme delante de ti; porque estoy con la costumbre de las mujeres.” De manera que él, a pesar de escudriñarlo (todo), no halló los terafim.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Entonces Jacob, montado en cólera, recriminó a Labán; y tomando Jacob la palabro dijo a Labán: “¿Cuál es mi crimen, y cuál mi pecado, para que tanto te enardezcas en mi persecución?');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Después de registrar todo mi equipaje, ¿qué has hallado de todos los objetos de tu casa? Ponlo aquí delante de mis hermanos y de tus hermanos, y sean ellos jueces entre nosotros dos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Hace veinte años que estoy contigo, y tus ovejas y tus cabras no han abortado, y no me he comido los carneros de tu rebaño.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Lo destrozado no te lo he mostrado, pues yo mismo pagaba el daño; y lo robado de noche y lo robado de día de mi mano lo reclamabas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'De día me consumía el calor, y de noche el frío, y huía el sueño de mis ojos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Esta ha sido mi suerte por veinte años en tu casa. Catorce años te he servido por tus dos hijas, y seis años por tu rebaño; y diez veces has cambiado mi salario.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Si el Dios de mi padre, el Dios de Abrahán y el Temor de Isaac, no hubiera estado conmigo, me habrías ahora despedido con las manos vacías. Mas Dios ha visto mi aflicción, y el trabajo de mis manos; y Él (te) recriminó la noche pasada.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Respondiendo dijo Labán a Jacob: “Las hijas, hijas mías son, los hijos son hijos míos y los rebaños, rebaños míos; y todo cuanto ves, mío es. Mas ¿qué puedo hacer hoy a estas mis hijas, o a sus hijos que ellas han dado a luz?');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Ahora, ven, pues, pactemos alianza, yo y tú, que será para testimonio entre los dos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Tomó entonces Jacob una piedra, y la erigió en monumento.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Y dijo Jacob a sus hermanos: “Recoged piedras.” Y recogieron piedras e hicieron un montón; y comieron allí sobre aquel montón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Labán lo llamó “Jegar-Sahaduta”, y Jacob lo llamó “Galaad”.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Y dijo Labán: “Este majano sea hoy testigo entre mí y entre ti” Por eso se le dio el nombre de Galaad,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'y también de Masfá, porque dijo: “¡Vele Yahvé sobre nosotros dos, cuando nos hallemos separados el uno del otro!');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Si tu maltratas a mis hijas, o si tomas otras mujeres, además de mis hijas, estará entre nosotros no un hombre; mira, es Dios quien estará como testigo entre los dos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Y siguió diciendo Labán a Jacob: “He aquí este majano, y he aquí este monumento que he erigido entre mí y entre ti;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'este majano sea testigo, y testigo sea este monumento de que yo no pasaré este majano yendo contra ti, y de que tú no pasarás este majano y este monumento yendo contra mí para hacerme mal.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'El Dios de Abrahán, el Dios de Nacor y el Dios de sus padres sea juez entre nosotros”. Y Jacob juró por el Temor de su padre Isaac.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Luego ofreció Jacob un sacrificio en el monte e invitó a sus hermanos a comer. Comieron, pues, y pasaron la noche en el monte.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'A la mañana se levantó Labán muy temprano, besó a sus hijos y a sus hijas y los bendijo; luego se puso en camino para volver a su lugar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Prosiguió Jacob su camino y le salieron al encuentro ángeles de Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Al verlos, dijo Jacob: “Este es el campamento de Dios”; y llamó a aquel lugar Mahanaim.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Luego envió Jacob mensajeros delante de sí a su hermano Esaú, al país de Seír, a las campiñas de Edom,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'y les dio esta orden: “Así diréis a mi señor Esaú: Esto dice tu siervo Jacob: He estado con Labán donde me detuve como huésped hasta hoy.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'Tengo bueyes, asnos, ovejas, siervos y siervas; y ahora envío mensaje a mi señor, para hallar gracia a tus ojos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Los mensajeros volvieron a Jacob, diciendo: “Hemos ido a tu hermano Esaú, y él viene a tu encuentro con cuatrocientos hombres.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Se atemorizó entonces Jacob en gran manera, y lleno de angustia dividió la gente que tenía, incluso las ovejas, el ganado mayor y los camellos, en dos campamentos;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'pues se decía: “Si viene Esaú a uno de los dos campamentos y lo destroza, se salvará el campamento restante.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Y oró Jacob: “Oh Dios de mi padre Abrahán y Dios de mi padre Isaac, Yahvé, que me dijiste: Vuelve a tu tierra y al país de tu nacimiento, que Yo te haré bien,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, '¡qué poco merecía yo todas las mercedes y toda la fidelidad de que has hecho objeto a tu siervo! Pues con solo mi cayado pasé este Jordán, y ahora he venido a formar dos campamentos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Líbrame, te ruego, de la mano de mi hermano, de la mano de Esaú; porque le temo, no sea que venga y me destruya a mí y a las madres con los hijos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Tú mismo dijiste: Yo te colmaré de bienes y haré tu descendencia como las arenas del mar, que a causa de su muchedumbre no pueden contarse.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Habiendo pasado allí aquella noche, tomó Jacob de lo que tenía a mano para hacer un presente a Esaú, su hermano:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'doscientas cabras y veinte machos cabríos, doscientas ovejas y veinte carneros,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'treinta camellas criando con sus crías, cuarenta vacas y diez toros, veinte asnas y diez pollinos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'Los entregó a sus siervos, cada rebaño aparte, y dijo a sus siervos: “Id delante de mí, dejando un espacio entre rebaño y rebaño.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Y dio al primero esta orden: “Cuando te encontrare Esaú, mi hermano, y te preguntare: ¿De quién eres, y adónde vas, y de quién es lo (que marcha) delante de ti?,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'dirás: De tu siervo Jacob; es un presente, enviado a mi señor Esaú; y he aquí que él mismo viene detrás de nosotros.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'Y también al segundo, como asimismo al tercero, y a todos los que iban tras los rebaños, mandó: “En estos términos hablaréis a Esaú cuando lo encontrareis.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Y diréis también: “He aquí, tu siervo Jacob viene detrás de nosotros.” Porque se decía: Aplacaré su ira con el presente que va delante de mí; después veré su rostro; quizá me sea propicio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'Pasó, pues el presente delante de él; mas él se quedó aquella noche en el campamento.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Aquella noche se levantó Jacob, tomó a sus dos mujeres, a sus dos siervas y a sus once hijos, para pasar el vado del Yaboc.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Los tomó, y los hizo pasar el río, e hizo pasar también todo lo que tenía.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Así se quedó Jacob solo, y luchó con él un hombre hasta rayar el alba.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Pero viendo que no le podía, le tocó en la articulación del muslo de Jacob mientras luchaba con él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Por lo cual dijo: “Déjame que ya raya el alba.” Mas (Jacob) contestó: “No te dejaré ir si no me bendices.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Le preguntó él: “¿Cuál es tu nombre?”, y respondió: “Jacob.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Le dijo entonces: “En adelante no te llamarás más Jacob, sino Israel; porque has luchado con Dios y con hombres, y has prevalecido.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Preguntole Jacob, diciendo: “Dime, por favor, tu nombre.” Mas él contestó: “¿Por qué preguntas mi nombre?” Y le bendijo allí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Jacob dio a aquel lugar el nombre de Fanuel, porque (dijo): “He visto a Dios cara a cara, y ha quedado a salvo mi vida.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Apenas había pasado de Fanuel cuando salió el sol; e iba cojeando del muslo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Por tanto, los hijos de Israel no comen, hasta el día de hoy, el nervio ciático, que está en la articulación del muslo, por haber sido tocada la articulación del muslo de Jacob en el nervio ciático.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Cuando Jacob alzando los ojos vio que venía Esaú, y con él cuatrocientos hombres, repartió los niños entre Lía y Raquel y las dos siervas,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'poniendo delante a las siervas con sus hijos, detrás a Lía con sus hijos, y a Raquel con José los postreros.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Él mismo se les adelantó y se postró en tierra siete veces, hasta que se hubo acercado a su hermano.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Entonces Esaú corrió a su encuentro, le abrazó, se echó sobre su cuello y le besó; y lloraron.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Alzando los ojos, vio (Esaú) a las mujeres y a los niños, y preguntó: “¿Quiénes son estos que tienes contigo?” Respondió: “Son los hijos que Dios ha dado a tu siervo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Y se acercaron las siervas, ellas y sus hijos, y se postraron.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Acercose también Lía con sus hijos, y se postraron; y después se acercaron José y Raquel, y se postraron.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Preguntó entonces: “¿Qué significa toda esta caravana que acabo de encontrar?” A lo que respondió (Jacob): “Es para hallar gracia a los ojos de mi señor.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, '“Vivo en abundancia, hermano mío, contestó Esaú; sea para ti lo que es tuyo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Pero Jacob replicó: “De ninguna manera. Si he hallado gracia a tus ojos, acepta mi presente de mi mano, por cuanto he visto tu rostro como quien ve el rostro de Dios, y me has mostrado tu benevolencia.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Acepta, pues, mi bendición que te he traído; pues Dios me ha favorecido y tengo de todo.” Y le instó tanto que aceptó.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Luego dijo (Esaú): “Partamos y pongámonos en marcha, y yo iré delante de ti.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Mas él respondió: “Mi señor sabe que los niños son tiernos, y que tengo ovejas y vacas preñadas; y si las arrean apresuradamente un solo día, morirá todo el ganado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Adelántese, pues, mi señor a su siervo, y yo seguiré lentamente, al paso de los rebaños que llevo delante, y al paso de los niños, hasta que llegue a mi señor, a Seír.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Respondió Esaú: “Dejaré entonces para ti parte de la gente que tengo conmigo.” Mas (Jacob) dijo: “¿Para qué esto? ¡Con tal que halle yo gracia a los ojos de mi señor!”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Se volvió, pues, Esaú ese mismo día rumbo a Seír.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Jacob marchó a Sucot, donde hizo una casa para sí, y cabañas para su ganado. Por donde se llamó aquel lugar Sucot.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'De vuelta de Mesopotamia llegó Jacob sano y salvo a la ciudad de Siquem, que está en el país de Canaán, y acampó frente a la ciudad.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Y compró a los hijos de Hemor, padre de Siquem, por cien kesitas, la parte del campo donde había asentado su tienda.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Allí erigió un altar, y lo llamó El-Elohé- Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Diná, la hija que Lía había dado a luz a Jacob, salió para ver a las hijas del país.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'La vio Siquem, hijo de Hemor el heveo, príncipe del país, y la tomó y cohabitó con ella, haciéndole violencia.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Y se prendó de Dina, hija de Jacob, de tal manera que se enamoró de la joven y le habló al corazón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Habló, pues, Siquem a su padre Hemor, diciendo: “Tómame esta joven por mujer.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Supo Jacob que (Siquem) había violado a su hija Dina; mas estando sus hijos con el ganado en el campo, se calló Jacob hasta su regreso.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Entretanto, Hemor, padre de Siquem fue a ver a Jacob para hablar con él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Cuando los hijos de Jacob vinieron del campo y lo supieron, se entristecieron y se irritaron mucho, porque con la violación de la hija de Jacob se había cometido un crimen contra Israel, cosa que no se debía hacer.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Habló Hemor con ellos, y dijo: “Siquem, mi hijo, está enamorado de vuestra hija; os ruego, dádsela por mujer.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'Emparentad con nosotros, dadnos vuestras hijas, y tomad para vosotros nuestras hijas;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'y habitad con nosotros, pues la tierra estará a vuestra disposición. Permaneced en ella, recorredla y tomadla en posesión.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'También Siquem dijo al padre y a los hermanos de ella: “¡Halle yo gracia a vuestros ojos!, pues daré lo que me pidiereis.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Exigidme mucha dote y muchos dones; yo daré cuanto me digáis; pero dadme a la joven por mujer.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Los hijos de Jacob respondieron a Siquem y a Hemor, su padre, hablando con dolo, por cuanto había violado a Dina su hermana,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'y les dijeron: “No podemos hacer eso de dar nuestra hermana a un hombre incircunciso; porque sería para nosotros una deshonra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Solo con esta condición podremos acceder a vuestro deseo: si consentís en ser como nosotros, circuncidando a todo varón de entre vosotros.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Entonces os daremos nuestras hijas, y nos tomaremos vuestras hijas; y habitaremos con vosotros, formando un solo pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Pero, si no queréis escucharnos y no os circuncidáis, tomaremos a nuestra hija y nos iremos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Parecieron bien sus palabras a Hemor y a Siquem, hijo de Hemor;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'y no tardó el joven en hacer aquello, porque estaba prendado de la hija de Jacob; y era él el más distinguido de toda la casa de su padre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Luego fueron Hemor y Siquem, su hijo, a la puerta de su ciudad, y hablaron con los hombres de la ciudad, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, '“Estos hombres son pacíficos con nosotros; habiten, pues, en el país y lo recorran. He aquí que el país es suficientemente largo y ancho para ellos. Tomaremos a sus hijas por mujeres y les daremos nuestras hijas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Pero los hombres solo querrán consentir en habitar con nosotros y formar un mismo pueblo con tal que se circuncide todo varón de entre nosotros, así como ellos son circuncisos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Entonces sus ganados y sus riquezas y todas sus bestias, ¿no serán nuestros?, tan solo accedamos a sus deseos; y así habitarán con nosotros.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Asintieron a Hemor y a Siquem, su hijo, todos los que venían a la puerta de su ciudad; y se circuncidaron todos los varones que venían a la puerta de su ciudad.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Mas al tercer día, cuando sintieron los dolores, dos de los hijos de Jacob, Simeón y Leví, hermanos de Dina, tomaron cada uno su espada, y en plena paz entraron en la ciudad, y mataron a todos los varones.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Mataron también a Hemor y a Siquem, su hijo, al filo de espada; y tomando a Dina de la casa de Siquem se volvieron.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Después los hijos de Jacob se arrojaron sobre los muertos y saquearon la ciudad, por cuanto habían violado a su hermana.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Tomaron sus ovejas, sus vacadas y sus asnos; todo lo que había en la ciudad y lo que había en el campo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'Se llevaron como botín todos sus bienes, a todos sus niños y a sus mujeres, y todo cuanto había en las casas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Dijo entonces Jacob a Simeón y Leví: “Me habéis desconcertado, haciéndome odioso a los moradores de esta tierra, a los cananeos y los fereceos; y no tengo sino poca gente; se juntarán contra mí y me matarán; y seré destruido yo y mi casa.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Le respondieron: “¿Debió él tratar a nuestra hermana como a una prostituta?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Dijo Dios a Jacob: “Levántate, sube a Betel, donde habitarás, y construye allí un altar al Dios que se te apareció cuando ibas huyendo de Esaú, tu hermano.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Dijo, pues, Jacob a su familia, y a todos los que con él estaban: “Apartad los dioses extraños que hay en medio de vosotros; purificaos y mudad vuestros vestidos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'Nos levantaremos para subir a Betel, donde construiré un altar al Dios que me oyó en el día de mi angustia y me asistió en el camino por donde he andado.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Entonces entregaron a Jacob todos los dioses extraños que tenían, y los pendientes que traían en las orejas; y Jacob los escondió bajo la encina que está cerca de Siquem.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Luego se pusieron en marcha, y vino el terror de Dios sobre las ciudades circunvecinas, de manera que no persiguieron a los hijos de Jacob.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Llegó, pues, Jacob a Luz, en tierra de Canaán, que es Betel, él y todo su pueblo con él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'Allí erigió un altar, y llamó al lugar El-Betel; porque allí se le apareció Dios, cuando huía de su hermano.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Y murió Débora, nodriza de Rebeca, y fue enterrada al pie de Betel, bajo una encina, la cual fue llamada Encina del Llanto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Apareciose Dios otra vez a Jacob después de su vuelta de Mesopotamia, y le bendijo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'Dios le dijo: “Tu nombre es Jacob; pero ya no te llamarás Jacob; tu nombre será Israel.” Y le puso por nombre Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Y le dijo Dios: “Yo soy el Dios Omnipotente. Crece y multiplícate; de ti nacerá una nación y una multitud de naciones, y reyes saldrán de tus lomos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Y la tierra que di a Abrahán y a Isaac, te la daré a ti; a tu posteridad después de ti daré esta tierra.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Y desapareció Dios de su presencia, en el lugar donde había hablado con él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'En aquel lugar donde había hablado con él levantó Jacob un monumento, un monumento de piedra, sobre el cual ofreció una libación y derramó óleo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'Y Jacob dio al lugar donde Dios le había hablado, el nombre de Betel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Partieron de Betel, y faltaba aún algún trecho de camino para llegar a Efrata cuando Raquel dio a luz. Tuvo ella un duro parto,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'y cuando peligraba en el parto, le dijo la partera: “No temas, porque también esta vez tienes un hijo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Y al salir su alma —pues estaba ya moribunda— le llamó Benoní; mas su padre le llamó Benjamín.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Murió, pues, Raquel y fue sepultada en el camino de Efrata, que es Betlehem.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Erigió Jacob un monumento sobre su tumba, es el monumento de la tumba de Raquel hasta el día de hoy.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Partió Israel y asentó sus tiendas más allá de Migdal-Eder.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Y mientras moraba Israel en aquella región, fue Rubén y cohabitó con Bilhá, concubina de su padre, lo que supo Israel. Los hijos de Israel eran doce:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Hijos de Lía: Rubén, el primogénito de Jacob; Simeón, Leví, Judá, Isacar y Zabulón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Hijos de Raquel: José y Benjamín.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'Hijos de Bilhá, sierva de Raquel: Dan y Neftalí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'Hijos de Silfá, sierva de Lía: Gad y Aser. Estos son los hijos de Jacob que le nacieron en Mesopotamia.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Fue Jacob adonde vivía Isaac, su padre, a Mamré, a Quiriat Arbá, que es Hebrón, donde moraron como extranjeros Abrahán e Isaac.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Fueron los días de Isaac ciento ochenta años.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'Anciano y colmado de días expiró Isaac y murió, y fue reunido con su pueblo; le sepultaron sus hijos Esaú y Jacob.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Esta es la historia de Esaú, que es Edom:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Esaú tomó sus mujeres de entre las hijas de Canaán: a Adá, hija de Elón, heteo; a Oholibamá, hija de Aná, hijo de Sibeón, heveo;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'y a Basemat, hija de Ismael, hermana de Nebayot.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'De Adá nació a Esaú Elifaz, y de Basemat Reuel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Oholibamá dio a luz a Jeús, a Jalam y a Core. Estos son los hijos de Esaú, que le nacieron en tierra de Canaán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Esaú tomó a sus mujeres, sus hijos y sus hijas, y a todas las almas de su casa, su ganado y todas sus bestias, con todos los bienes que había adquirido en tierra de Canaán, y se dirigió a un país alejado de Jacob, su hermano.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Porque la hacienda de ellos era tan grande, que no podían habitar juntos; pues la tierra de sus peregrinaciones no era capaz de sostenerlos a causa de sus ganados.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Se estableció, pues, Esaú en la montaña de Seír. Esaú es lo mismo que Edom.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Estos son los descendientes de Esaú, padre de los idumeos, en la montaña de Seír,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'y estos son los nombres de sus hijos: Elifaz, hijo de Adá, mujer de Esaú.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Los hijos de Elifaz fueron: Temán, Omar, Sefó, Gatam y Quenaz.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Timná fue concubina de Elifaz, hijo de Esaú, y dio a luz a Amalec. Estos son los descendientes de Adá, mujer de Esaú.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Y estos son los hijos de Reuel: Náhat, Sera, Samá y Misá. Son estos los descendientes de Basemat, mujer de Esaú.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Los hijos de Oholibamá, hija de Aná, hijo de Sibeón, mujer de Esaú, que ella dio a luz a Esaú, fueron estos: Jeús, Jalam y Core.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'He aquí los príncipes de los hijos de Esaú. De los hijos de Elifaz, primogénito de Esaú: el príncipe Temán, el príncipe Omar, el príncipe Sefó, el príncipe Quenaz,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'el príncipe Core, el príncipe Gatam, el príncipe Amalec. Estos son los príncipes de Elifaz, en el país de Edom, y estos son los descendientes de Adá.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Los hijos de Reuel, hijo de Esaú, fueron el príncipe Náhat, el príncipe Sera, el príncipe Samá, el príncipe Misá. Estos son los príncipes de Reuel, en el país de Edom; y estos son los descendientes de Basemat, mujer de Esaú.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Los hijos de Oholibamá, mujer de Esaú, fueron: el príncipe Jeús, el príncipe Jalam, el príncipe Core. Estos son los príncipes de Oholibamá, hija de Aná, mujer de Esaú.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Estos son los hijos de Esaú, y estos sus príncipes. Este es Edom.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'He aquí los hijos de Seír, el horreo, que habitaba aquella tierra: Lotá, Sobal, Sibeón, Aná,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Disón, Eser y Disán. Estos son los príncipes de los horreos, hijos de Seír, en el país de Edom.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Los hijos de Lotán fueron: Horí y Hemán; y la hermana de Lotán fue Timná.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Los hijos de Sobal fueron: Alván, Manáhat, Efal, Sefó y Onam;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'y los hijos de Sibeón: Ayá y Aná. Este es el mismo Aná que halló las aguas calientes en el desierto, cuando apacentaba los asnos de su padre Sibeón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Los hijos de Aná: Disón y Oholibamá, hija de Aná.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Los hijos de Disón: Hemdán, Esbán, Itrán y Querán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Los hijos de Eser: Bilhán, Saaván y Acán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Los hijos de Disán: Us y Arán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Estos son los príncipes horreos: el príncipe Lotán, el príncipe Sobal, el príncipe Sibeón, el príncipe Aná,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'el príncipe Disón, el príncipe Eser, el príncipe Disán. Estos son los príncipes horreos, según sus principados en el país de Seír.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Estos son los reyes que reinaron en el país de Edom, antes que tuvieran rey los hijos de Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Reinó en Edom Bela, hijo de Beor; y el nombre de su ciudad era Dinabá.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Murió Bela, y reinó en su lugar Jobab, hijo de Sera, de Bosra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Murió Jobab, y reinó en su lugar Husam, de la tierra de los temanitas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Murió Husam, y reinó en su lugar Hadad, hijo de Badad, el que derrotó a Madián en el campo de Moab; y el nombre de su ciudad era Avit.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Murió Hadad, y reinó en su lugar Samlá, de Masrecá.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Murió Samlá, y reinó en su lugar Saúl, de Rehobot del Río.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Murió Saúl, y reinó en su lugar Baalhanán, hijo de Acbor.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Murió Baalhanán, hijo de Acbor, y reinó en su lugar Hadar; y el nombre de su ciudad era Pau, y el nombre de su mujer Mehetabel, hija de Matred, hija de Mesahab.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Estos son los nombres de los príncipes de Esaú, según sus familias, según sus territorios, y por sus nombres: el príncipe Timná, el príncipe Alvá, el príncipe Jetet,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'el príncipe Oholibamá, el príncipe Elá, el príncipe Pinón,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'el príncipe Quenaz, el príncipe Temán, el príncipe Mibsar,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'el príncipe Magdiel, el príncipe Iram. Estos son los príncipes de Edom, según sus moradas, en la tierra que ocupa. Este es Esaú, padre de Edom.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Habitó Jacob en la tierra de las peregrinaciones de su padre, en la tierra de Canaán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'He aquí la historia de Jacob. Cuando José tenía diez y siete años, apacentaba con sus hermanos los rebaños, y por ser todavía joven, estaba con los hijos de Bilhá y los hijos de Silfá, mujeres de su padre; y dio José noticia de la mala fama que ellos tenían.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Israel amaba a José más que a todos sus hermanos, por ser el hijo de su vejez; y le había hecho un traje talar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Viendo, pues, sus hermanos que su padre le amaba más que a todos sus hermanos, cobraron tal odio contra él que no podían hablarle en paz.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Tuvo José un sueño, que contó a sus hermanos, por lo cual le odiaron más todavía.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Les dijo: “Escuchad este sueño que he soñado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Estábamos atando gavillas en el campo, y vi cómo se levantaba mi gavilla y se mantenía derecha, mientras que vuestras gavillas la rodeaban, y se postraban ante mi gavilla.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Le dijeron sus hermanos: “¿Quieres acaso reinar sobre nosotros o dominarnos por completo?” De modo que le odiaron aún más a causa de sus sueños y sus palabras.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Tuvo, además otro sueño, y lo contó a sus hermanos diciendo: “Mirad, he tenido otro sueño más: el sol y la luna y once estrellas se postraban delante de mí.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Lo contó a su padre y a sus hermanos, por lo cual su padre le reprendió, diciendo: “¿Qué sueño es este que has soñado? ¿Debemos acaso venir, yo y tu madre y tus hermanos, y postrarnos en tierra delante de ti?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Y sus hermanos le tenían envidia, mas su padre reflexionaba sobre lo sucedido.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Los hermanos de José fueron a apacentar los rebaños de su padre en Siquem,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'y dijo Israel a José: “¿No están tus hermanos pastoreando en Siquem? Ven, que te enviaré a donde ellos están.” Le respondió: “Heme aquí.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Y dijo: “Anda, y ve cómo están tus hermanos y cómo se halla el ganado, y tráeme noticias.” Así le envió desde el valle de Hebrón, y (José) se fue a Siquem.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Y cuando andaba errante por el campo le encontró un hombre, el cual le preguntó: “¿Qué estás buscando?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Contestó: “Busco a mis hermanos; dime por favor, dónde están pastoreando.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Dijo el hombre; “Se han ido de aquí, pues les oí decir: ‘Vamos a Dotain’.” Con esto se marchó José en busca de sus hermanos, y los halló en Dotain.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Cuando ellos le vieron desde lejos, ya antes que llegase a ellos, buscaron cómo matarle dolosamente,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'diciéndose uno a otro: “Mirad, ahí viene ese soñador.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Vamos a matarle y arrojarle en una de estas cisternas; y diremos que una fiera lo ha devorado; entonces veremos qué será de sus sueños.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Rubén, que oyó esto, trató de librarlo de sus manos, diciendo: “No le quitemos la vida.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Y los exhortó Rubén: “No derraméis sangre; arrojadlo en esta cisterna que está en el desierto, mas no pongáis en él la mano”, (esto decía) para librarlo de su mano, a fin de devolverlo a su padre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Con todo, cuando José llegó a sus hermanos, le despojaron de su túnica, el traje talar que traía puesto;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'y tomándolo lo arrojaron en la cisterna. La cisterna estaba vacía, no había agua en ella.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Después se sentaron a comer, y levantando los ojos vieron una caravana de ismaelitas que venía de Galaad, y cuyos camellos llevaban especias y bálsamo y resina para transportarlos a Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Entonces dijo Judá a sus hermanos: “¿Qué ganaremos con matar a nuestro hermano y ocultar su sangre?');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Vamos, vendámoslo a los ismaelitas y no pongamos en él nuestra mano; pues es nuestro hermano, carne nuestra.” Sus hermanos estaban de acuerdo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'y cuando pasaron los mercaderes madianitas, sacaron a José, alzándole de la cisterna. Y vendieron a José por veinte piezas de plata a los ismaelitas, que le llevaron a Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Cuando Rubén volvió a la cisterna y vio que José no estaba en la cisterna, rasgó sus vestidos,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'y volviéndose a sus hermanos, les dijo: “El niño no aparece; ahora, ¿adónde voy yo?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Mas ellos tomaron la túnica de José, degollaron un macho cabrío, empaparon la túnica en la sangre,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'y enviaron el traje talar a su padre, diciendo: “Esto hemos hallado; comprueba, pues, si es o no la túnica de tu hijo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Y él la reconoció y dijo: “Es la túnica de mi hijo; una fiera lo ha devorado. Despedazado, despedazado ha sido José.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Y rasgó Jacob sus vestidos, puso un saco sobre sus lomos e hizo duelo por su hijo muchos días.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Todos sus hijos y todas sus hijas vinieron a consolarle; mas él no quiso ser consolado, sino que dijo: “Por tristeza bajaré adonde está mi hijo, al scheol.” Así lo lloró su padre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Los madianitas le vendieron en Egipto a Putifar, eunuco del Faraón, jefe de la guardia.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'En aquel tiempo se separó Judá de sus hermanos, y bajando llegó a un adullamita que se llamaba Hirá.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Allí vio Judá a la hija de un cananeo, llamado Súa; la tomó (por mujer) y se llegó a ella;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'la cual concibió y dio a luz un hijo, a quien llamó Er.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Concibió otra vez, y dio a luz un hijo, al que puso por nombre Onán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Volvió a dar a luz un hijo, a quien llamó Selá. Estaba en Quesib cuando dio a luz.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Ahora bien, tomó Judá para Er, su primogénito, una mujer que se llamaba Tamar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Pero Er, el primogénito de Judá, era malo a los ojos de Yahvé, y Yahvé le quitó la vida.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Entonces dijo Judá a Onán: “Llégate a la mujer de tu hermano, y cumple con ella tu deber de cuñado, suscitando descendencia a tu hermano.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Mas Onán, sabiendo que la descendencia no había de ser suya, siempre que se llegaba a la mujer de su hermano, derramaba en tierra, para no dar prole a su hermano.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Lo que hacía, era malo a los ojos de Yahvé, por lo cual lo mató a él también.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Dijo entonces Judá a Tamar, su nuera: “Quédate como viuda en casa de tu padre, hasta que sea mayor mi hijo Selá”, porque se decía: “No sea que muera también él, como sus hermanos.” Se fue, pues, Tamar, y habitó en casa de su padre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Pasados ya muchos días, murió la hija de Súa, mujer de Judá; y concluido el duelo, subió Judá con su amigo Hirá adullamita a Timná donde estaban los esquiladores de sus ovejas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Lo supo Tamar, pues le decían: “Mira, tu suegro sube a Timná, al esquileo de sus ovejas.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Entonces ella se quitó los vestidos de su viudez y se cubrió de un velo; y así envuelta se sentó a la entrada de Enaim, en el camino de Timná, porque veía que Selá era ya grande, y ella no le había sido dada por mujer.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Como la viese Judá, la tuvo por ramera, por tener ella cubierto el rostro;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'y dirigiéndose hacia ella, en el borde del camino dijo: “Déjame, por favor llegarme a ti”, pues no sabía que era su nuera. Ella preguntó: “¿Qué me darás por llegarte a mi?”,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Respondió: “Enviaré un cabrito del rebaño”, a lo cual ella dijo: “Sí, con tal que me des una prenda, hasta que lo mandes.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, '“¿Qué prenda te he de dar?”, preguntó él, y ella contestó: “Tu sello, tu cordón y el bastón que llevas en la mano.” Se lo dio, y llegose a ella, la cual concibió de él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Después se levantó y se fue, se quitó el velo y se vistió los vestidos de su viudez.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Envió Judá el cabrito por mano de su amigo, el adullamita, para retirar de la mujer los objetos dados en prenda, pero no la halló.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Por lo cual preguntó a los hombres de aquel lugar, diciendo “¿Dónde está la prostituta de Enaim, la de junto al camino?” Respondieron: “Aquí no ha habido prostituta alguna.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Se volvió, pues, a Judá y dijo: “No la he encontrado; y además los hombres de aquel lugar dicen: ‘No ha habido aquí prostituta alguna.’”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Dijo entonces Judá: “Tómeselo para sí, para que nadie pueda burlarse de nosotros. He aquí, yo he enviado este cabrito, mas tú no la has encontrado.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Pasados unos tres meses fue dada a Judá esta noticia: “Tu nuera Tamar se ha prostituido, y también está encinta a consecuencia de sus fornicaciones.” Y mandó Judá: “¡Sacadla, y sea quemada!”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Fue, pues, sacada, mas envió a decir a su suegro: “Del varón a quien pertenecen estas cosas estoy yo encinta.” Y añadió: “Averigua tú, te ruego, de quien son este sello, este cordón y este bastón.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Los reconoció Judá, y dijo: “Más justa es ella que yo, por cuanto no se la he dado a Selá, mi hijo.” Y no volvió más a conocerla.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Venido el tiempo de su parto, sucedió que había mellizos en su seno.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Y al dar a luz, uno sacó la mano; la tomó la partera y ató a ella un hijo de escarlata, diciendo: “Este salió primero.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Pero retiró él su mano y salió su hermano. Y ella dijo: “¡Cómo te abriste brecha!” Y fue llamado Fares.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Luego salió su hermano, el que tenía en la mano el hijo de escarlata, y fue llamado Zara.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'José fue llevado a Egipto; y Putifar, eunuco del Faraón, capitán de la guardia, egipcio, le compró a los ismaelitas que allá le habían llevado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Mas Yahvé estaba con José e hizo prosperar lo que hacía. Habitaba en casa de su señor, el egipcio;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'y su señor vio que Yahvé le asistía y que Yahvé favorecía en sus manos todas sus empresas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'Así José halló gracia a sus ojos, y le servía de tal manera que le encargó el gobierno de su casa y puso en sus manos todo lo que tenía.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Y sucedió que desde el tiempo en que le encargara el gobierno de su casa y de todo lo que tenía, Yahvé bendijo la casa del egipcio por amor a José; y la bendición de Yahvé se derramó sobre todo lo que tenía, tanto en la casa como en el campo;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'de manera que dejó todo lo suyo en manos de José, sin tener otra preocupación que la de comer. Era José de bella figura y de hermoso aspecto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Acaeció después de estas cosas que la mujer de su señor puso los ojos en José y dijo: “Acuéstate conmigo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Pero él rehusó, diciendo a la mujer de su señor: “Es verdad que mi señor no me pide cuentas acerca de lo que tiene en su casa, y todos sus bienes los ha puesto en mi mano;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'nadie hay en esta casa que sea más grande que yo, y él no se ha reservado nada, a excepción de ti, por cuanto eres su mujer. ¿Cómo, pues, voy a hacer esta gran maldad y pecar contra Dios?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Todos los días hablaba ella así, pero él no consintió en acostarse a su lado y estarse con ella.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Mas cuando cierto día entró en la casa para cumplir su tarea, y no había ninguno de los sirvientes de la casa allí dentro,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'le asió de su vestido y dijo: “Acuéstate conmigo.” Pero él, dejando su vestido en mano de ella, huyó y salió afuera.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Viendo ella que le había dejado su vestido en la mano y había huido afuera,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'llamó a los sirvientes de su casa y les dijo: “Mirad, nos ha traído un hebreo para que se burle de nosotros; vino a mí para acostarse conmigo, pero yo clamé a grandes voces;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'y él, como oyese que yo alzaba mi voz y clamaba, dejó su vestido junto a mí y escapó huyendo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Y puso ella junto a sí el vestido de él hasta que su señor volviera a la casa.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'A este le habló en los mismos términos, diciendo: “Vino a mí el siervo hebreo que nos trajiste, para burlarse de mí;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'pero cuando yo levanté mi voz y grité, dejó su vestido junto a mí y huyó afuera.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Al oír el señor las palabras que su mujer le hablaba, diciendo: “Esto me ha hecho su siervo”, montó en cólera,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'y tomando a José lo metió en la cárcel, en el lugar donde se guardaban los presos del rey; y allí quedó en la cárcel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Mas Yahvé estaba con José, y le mostró su misericordia, haciéndolo grato a los ojos del jefe de la cárcel,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'de tal manera que el jefe de la cárcel puso todos los presos que había en la cárcel en manos de José, y sin José no se hacía nada allí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'El jefe de la cárcel no se cuidaba de cosa alguna que estaba en manos (de José), porque Yahvé le asistía, y Yahvé favorecía todas sus acciones.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Después de esto sucedió que el copero del rey de Egipto y el panadero faltaron contra su señor, el rey de Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Y se encolerizó el Faraón contra sus dos ministros, el jefe de los coperos y el jefe de los panaderos;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'y los metió presos en la casa del capitán de la guardia, en la cárcel donde José estaba preso.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'El capitán de la guardia los puso bajo la custodia de José, y este les atendía. Estando ya algún tiempo en prisión,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'el copero y el panadero del rey de Egipto, que se hallaban presos en la cárcel, soñaron sueños, ambos en la misma noche, cada uno el suyo, cada uno según lo que había de significar su sueño.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Cuando por la mañana José vino a ellos, vio que estaban tistes;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'por lo cual preguntó a los ministros del Faraón que estaban con él en la cárcel, en la casa de su señor, diciendo: “¿Por qué están hoy vuestros semblantes tan tristes?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'Le respondieron: “Hemos soñado sueños, y no hay quien los interprete.” Les replicó José: “¿No es Dios el que da interpretación? Contadme (el sueño), os ruego.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Entonces el jefe de los coperos le contó su sueño, diciendo: “En mi sueño vi una vid delante de mí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'En la vid había tres sarmientos; estaba brotando, salía su flor, y sus racimos maduraban uvas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'Yo tenía en mi mano la copa del Faraón, y tomando las uvas las exprimí en la copa del Faraón, y entregué la copa en mano del Faraón.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'José le dijo: “Esta es su interpretación: Los tres racimos son tres días.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Al cabo de tres días el Faraón exaltará tu cabeza, y te restituirá en tu cargo, y darás la copa del Faraón en su mano, como tenías costumbre anteriormente, cuando eras su copero.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Solo te pido que te acuerdes de mí cuando te vaya bien; y que uses de misericordia conmigo, recordándome ante el Faraón, y que me saques de esta casa.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Pues he sido robado del país de los hebreos; y aun aquí no he hecho nada para que me metieran en el calabozo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Viendo el jefe de los panaderos que era buena la interpretación, dijo a José: “Yo, por mi parte, vi en mi sueño tres canastos de pasta fina sobre mi cabeza.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'En el canasto de encima había toda clase de pastelería para el Faraón, y las aves comían del canasto que llevaba sobre mi cabeza.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Respondió José diciendo: “Esta es su interpretación: Los tres canastos son tres días.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Al cabo de tres días el Faraón te quitará la cabeza, te colgará en un madero y las aves comerán tu carne.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Y, efectivamente, al día tercero, día del cumpleaños del Faraón, hizo este un banquete para todos sus siervos; y alzó en medio de sus siervos la cabeza del jefe de los coperos y la del jefe de los panaderos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'Restituyó al jefe de los coperos a su oficio de copero, el cual volvió a poner la copa en mano del Faraón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'Mas al jefe de los panaderos le colgó, como les había interpretado José.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Y no se acordó el jefe de los coperos de José, sino que se olvidó del mismo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Dos años después tuvo el Faraón un sueño: le parecía que estaba junto al río,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'y subían del río siete vacas hermosas de parecer y gordas de carne, y pacían en los lugares lagunosos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Y he aquí otras siete vacas que subían del río tras ella, feas de parecer y flacas de carne, que se pusieron junto a aquellas vacas a la orilla del río.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Y las vacas feas de parecer y flacas de carne devoraron a las siete vacas hermosas de parecer y gordas. Tras esto despertó el Faraón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Volvió a dormirse y tuvo un segundo sueño: vio siete espigas que brotaban de una misma caña, gruesas y lozanas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Pero detrás de ellas brotaban siete espigas delgadas y abrasadas por el solano;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'y las siete espigas delgadas devoraron a las siete espigas gruesas y llenas. Despertó el Faraón, y he aquí que era un sueño.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'A la mañana, sintiendo perturbado su espíritu, envió a llamar a todos los adivinos de Egipto y a todos sus sabios. Les contó el Faraón su sueño, mas no hubo quien se lo interpretase al Faraón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Entonces habló el jefe de los coperos al Faraón, diciendo: “Ahora recuerdo mis faltas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Cuando el Faraón estuvo enojado con sus siervos y me echó en la cárcel en la casa del capitán de la guardia, a mí y al jefe de los panaderos,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'soñamos sueños en una misma noche, yo y él, soñando cada uno según el significado que correspondía a su sueño.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Estaba allí con otros un joven hebreo, siervo del capitán de la guardia; le contamos nuestros sueños y él nos dio su interpretación, cada uno la interpretación correspondiente a su sueño.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'Y según nos había interpretado, así ocurrió: a mí me restituyó a mi cargo, y al otro lo hizo colgar.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'El Faraón envió a llamar a José, al cual sacaron a toda prisa del calabozo. Se afeitó, se mudó de ropa y vino al Faraón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Y dijo el Faraón a José: “He tenido un sueño, y no hay quien lo interprete; mas he oído decir de ti que apenas oído un sueño sabes interpretarlo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Contestó José al Faraón: “No depende de mí; Dios es quien dará al Faraón una respuesta favorable.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Dijo entonces el Faraón a José: “En mi sueño, me parecía que estaba de pie a la orilla del río,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'y he aquí que subían del río siete vacas gordas de carne y hermosas de aspecto, que pacían en los lugares lagunosos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Mas he aquí que otras siete vacas subían detrás de ellas, delgadas, y muy feas de parecer y flacas de carne; nunca las he visto tan feas como ellas, en todo el país de Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'Y las vacas flacas y feas devoraron a los primeras siete vacas gordas,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'las cuales entraron en su vientre sin que se notase que en él hubieran penetrado, siendo su aspecto tan feo como antes. Y desperté.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Vi también en mi sueño siete espigas que brotaban de una misma caña, gruesas y lozanas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Mas tras ellas brotaban siete espigas secas, delgadas y abrasadas por el solano;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'y las siete espigas delgadas se tragaron a las siete espigas buenas. Se lo he contado a los adivinos mas no hay quien me lo interprete.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Dijo entonces José al Faraón: “El sueño del Faraón es uno solo. Dios ha manifestado al Faraón lo que va a hacer.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Las siete vacas hermosas son siete años, y las siete espigas lozanas son siete años; el sueño es uno mismo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Las siete vacas flacas y feas, que subían después de ellas, son también siete años, y serán, (como) las siete espigas vacías que abrasó el solano, siete años de hambre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'Es lo que he dicho al Faraón: Dios ha manifestado al Faraón lo que va a hacer.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'He aquí que vendrán siete años de grande abundancia en todo el país.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'Después de ellos vendrán siete años de hambre, y se olvidará en la tierra de Egipto toda la abundancia, pues el hambre consumirá el país.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'Y no se conocerá más la abundancia en el país a causa del hambre que la seguirá y que será muy grande.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'La repetición del sueño al Faraón por dos veces significa que es cosa establecida por parte de Dios, y Dios se apresura a ejecutarla.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Ahora, pues, busque el Faraón un hombre entendido y sabio, y póngale el frente del país de Egipto,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'y procure el Faraón nombrar intendentes sobre el país, que durante los siete años de abundancia recojan la quinta parte (de la cosecha) en la tierra de Egipto,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'y junten así toda la producción (sobrante) de esos años buenos que vienen, y almacenen trigo a disposición del Faraón, para abastecimiento de las ciudades, y lo conserven,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'a fin de que esta producción sea una reserva para el país cuando vengan los siete años de hambre que habrá en la tierra de Egipto. De esta manera el país no será consumido por el hambre”.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Agradó este consejo al Faraón y a todos sus servidores.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Y dijo el Faraón a sus siervos: “¿Podríamos acaso hallar un varón como este, lleno del espíritu de Dios?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Dijo, pues, el Faraón a José: “Ya que Dios te ha dado a conocer todo esto, no hay nadie que sea tan inteligente y sabio como tú.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Tú gobernarás mi casa, y obedecerá a tu voz todo mi pueblo. Tan solo por el trono seré más grande que tú.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Y dijo el Faraón a José: “He aquí, te pongo sobre toda la tierra de Egipto.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Se quitó luego el Faraón su anillo de la mano y lo puso en la mano de José; lo vistió con vestiduras de lino finísimo, y colgó un collar de oro alrededor de su cuello.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'Lo hizo subir en la segunda carroza que tenía, gritando delante de él un heraldo: “Poneos de rodillas.” Así fue puesto sobre toda la tierra de Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'También dijo el Faraón a José: “Yo soy el Faraón; mas sin ti nadie levantará mano ni pie en toda la tierra de Egipto.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'El Faraón puso a José por nombre Safnat Panea, y le dio por mujer a Asenat, hija de Putifar, sacerdote de On. Y recorrió José la tierra de Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'José tenía treinta años cuando se presentó delante del Faraón, rey de Egipto. Recorrió, pues, José toda la tierra de Egipto, después de haberse retirado de la presencia del Faraón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'La tierra produjo a montones en los siete años de abundancia;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'y él recogió toda la producción de los siete años que hubo en la tierra de Egipto, y almacenó la producción en las ciudades, depositando en cada ciudad los productos del campo que estaba alrededor de ella.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Almacenó José tanto trigo como las arenas del mar; en tan gran cantidad que dejó de contarlo, porque no tenía número.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Antes que viniese el año del hambre, le nacieron a José dos hijos, que le dio a luz Asenat, hija de Putifar, sacerdote de On.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Llamó José al primogénito Manasés (diciendo): “Dios me ha hecho olvidar todas mis penas y toda la casa de mi padre.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Al segundo puso por nombre Efraím (diciendo): “Dios me ha dado prole en la tierra de mi aflicción.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Terminados los siete años de abundancia que hubo en el país de Egipto,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'comenzaron a venir los siete años de hambre, como José había anunciado; y hubo hambre en todos los países, pero en toda la tierra de Egipto hubo pan.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Al sentir el hambre toda la tierra de Egipto clamó el pueblo al Faraón por pan; y dijo el Faraón a todos los egipcios: “Id a José; haced lo que él os dijere.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'Y habiendo hambre sobre toda la faz de la tierra, abrió José todo lo que tenía en los graneros y vendió (trigo) a los egipcios, pues el hambre arreció en la tierra de Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Y de todos los países fueron a Egipto a comprar grano a José; porque era grande el hambre en toda la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Viendo Jacob que había grano en Egipto, dijo a sus hijos: “¿Por qué estáis mirándoos el uno al otro?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Y añadió: “He aquí, he oído que hay grano en Egipto. Bajad allá a comprárnoslo de allí, a fin de que vivamos y no muramos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Bajaron entonces diez de los hermanos de José a comprar trigo en Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Mas a Benjamín, hermano de José, no lo envió Jacob con sus hermanos, pues dijo: “No sea que le suceda alguna desgracia.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Así llegaron, entre otros, también los hijos de Israel a comprar trigo, porque había hambre en el país de Canaán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'José era entonces gobernador del país, el que vendía el trigo a todo el pueblo de la tierra. Por tanto, cuando llegaron los hermanos de José se postraron delante de él rostro a tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Al ver José a sus hermanos, los reconoció, mas fingiéndose extraño para ellos les habló con dureza, diciéndoles: “¿De dónde venís?” Contestaron: “De la tierra de Canaán, a comprar víveres.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Reconoció, pues, José a sus hermanos, pero ellos no le reconocieron a él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Se acordó entonces José de los sueños que había soñado acerca de ellos, y les dijo: “Espías sois; habéis venido a observar los lugares indefensos del país.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'Le contestaron “No, señor mío; tus siervos han venido a comprar víveres.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Todos somos hijos de un mismo padre; hombres honestos somos; tus siervos no son espías.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Pero él les dijo: “No, a observar los puntos indefensos del país habéis venido.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Respondieron: “Tus siervos somos doce hermanos, hijos de un mismo padre en la tierra de Canaán; el menor está todavía con nuestro padre, y el otro ya no existe.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Les replicó José: “Es como os he dicho: sois espías.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'En esto seréis probados. ¡Por la vida del Faraón! No saldréis de aquí, a menos que venga acá vuestro hermano menor.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Enviad a uno de vosotros que traiga a vuestro hermano; entretanto, vosotros quedaréis presos. Serán puestas a prueba vuestras palabras (para comprobar) si hay verdad en vosotros. Si no, ¡por la vida del Faraón! que sois espías.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Y los puso juntos en la cárcel por espacio de tres días.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Al tercer día les dijo José: “Haced esto y viviréis; pues yo soy temeroso de Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Si sois gente honesta, uno de vuestros hermanos quede preso en la casa de vuestras prisión; mas vosotros, id y llevad el grano para el hambre de vuestras casas,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'y traedme a vuestro hermano menor; entonces se verá si vuestras palabras son verdaderas, y no moriréis.” Ellos hicieron así,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'diciendo el uno al otro: “Verdaderamente hemos pecado contra nuestro hermano; porque vimos la angustia de su alma cuando nos pedía compasión y no le escuchamos; por eso nos ha sobrevenido esta tribulación.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Respondioles Rubén, diciendo: “¿No os decía yo que no pequéis contra el niño; y no me escuchasteis? Ahora se nos demanda su sangre.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'No se daban cuenta de que José escuchaba, pues les hablaba por medio de un intérprete.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Y se retiró de ellos para llorar. Después volvió donde estaban, y les habló; y tomando de entre ellos a Simeón, lo hizo atar ante sus ojos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Dio José orden que les llenasen los costales de trigo y devolvieran el dinero de cada uno poniéndolo en su saco, y les diesen provisiones para el viaje; y así hicieron con ellos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Cargaron, pues, ellos el trigo sobre sus asnos y se marcharon de allí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Mas al abrir uno en la posada su saco para dar pienso a su asno, vio que su dinero se hallaba en la boca de su costal.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Y dijo a sus hermanos: “Me ha sido devuelto mi dinero; vedlo en mi costal.” Llenos de temor y temblando se dijeron unos a otros: “¿Qué es esto que Dios ha hecho con nosotros?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Llegados a Jacob, su padre, a la tierra de Canaán, le contaron todo lo que les había sucedido, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, '“Ese hombre, señor de aquella tierra, nos habló con dureza, y nos tomó por espías del país.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Nosotros le dijimos: Somos hombres honestos, no somos espías.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Somos doce hermanos, hijos de nuestro padre; el uno ya no vive, y el menor está ahora con nuestro padre en la tierra de Canaán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Mas aquel hombre, señor del país, nos dijo: “En esto conoceré que sois gente honesta: Dejad conmigo a uno de vuestros hermanos, y tomad (lo necesario) para el hambre de vuestras casas y partid;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'y traedme a vuestro hermano menor; así sabré que no sois espías, sino gente honesta. Os daré entonces a vuestro hermano, y podréis recorrer el país.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Y sucedió que al vaciar ellos sus costales estaba en el costal de cada uno el bolsillo con su dinero, y cuando ellos y su padre vieron los bolsillos con su dinero tuvieron temor.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Y les dijo su padre Jacob: “Vosotros me vais a dejar sin hijos. ¡José ya no está, Simeón tampoco, y (ahora) queréis llevar a Benjamín! ¡Todo eso ha venido sobre mí!”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Entonces Rubén habló a su padre, diciendo: “Quita la vida de mis dos hijos si yo no te lo devuelvo. Entrégalo en mi mano, y yo te lo devolveré.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Mas él respondió: “No bajará mi hijo con vosotros, pues su hermano murió, y él es el único que me ha quedado. Si le sucediera alguna desgracia en el camino por donde vais, tendrías la culpa de que mis canas desciendan de puro dolor al sepulcro.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'El hambre pesaba sobre la tierra,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'por lo cual cuando acabaron de comer el grano que habían traído de Egipto, su padre les dijo: “Volved y compradnos algo que comer.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Le respondió Judá, diciendo: “Aquel hombre nos declaró terminantemente: ‘No veréis mi rostro, si vuestro hermano no viene con vosotros’.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Bajaremos, pues, con tal que dejes ir con nosotros a nuestro hermano, y te compraremos alimentos;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'pero si no quieres dejarlo ir, no bajaremos; porque aquel hombre nos dijo: “No veréis mi rostro si vuestro hermano no viene con vosotros.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'A lo cual respondió Israel: “¿Por qué me habéis hecho este mal, de decir a aquel hombre que aún teníais otro hermano?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Contestaron: “Aquel hombre nos preguntó detalladamente acerca de nosotros y de nuestra familia, diciendo: ‘Vive todavía vuestro padre? ¿Tenéis otro hermano?’ Y le contestamos conforme a estas preguntas. ¿Podíamos acaso saber que iba a decir: ‘Traed a vuestro hermano?’.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Entonces dijo Judá a Israel, su padre: “Envía al joven conmigo, de modo que nos pondremos en marcha e iremos, para que vivamos y no muramos, ni nosotros, ni tú, ni nuestros niños.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Yo respondo por él; reclámalo de mi mano. Si no te lo devuelvo y lo pongo delante de ti, seré culpable ante ti por siempre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Si no fuera por esta demora, estaríamos de vuelta ya por segunda vez.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Les dijo, pues, Israel, su padre: “Si así ha de ser, haced esto: tomad de lo mejor del país (y ponedlo) en vuestro equipaje, y haced a aquel hombre un presente: un poco de bálsamo, un poco de miel, especias, resina, pistachos y almendras.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Y llevad en vuestra mano doble cantidad de dinero para restituir el dinero que os fue devuelto en la boca de vuestros costales. Quizás fue por equivocación.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Tomad también a vuestro hermano y levantáos para volver hacia aquel hombre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'El Dios Todopoderoso os haga hallar gracia ante ese hombre, para que deje volver con vosotros al otro hermano vuestro y a Benjamín. En cuanto a mí, si he de ser privado de hijos, séalo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Tomaron, pues, los hombres aquel presente. Tomaron también en sus manos la doble cantidad de dinero y a Benjamín, Luego se pusieron en camino y bajaron a Egipto y se presentaron ante José.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Apenas vio José con ellos a Benjamín, dijo al mayordomo de su casa: “Lleva a estos hombres a mi casa, degüella animales y pon la mesa, porque estos hombres comerán conmigo a mediodía”.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'E hizo este como José había mandado y los llevó a casa de José.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Mientras los hombres eran conducidos a casa de José, sobrecogidos de temor, decían “Por el dinero que la vez pasada nos han devuelto en nuestros costales, somos traídos aquí; es para asaltarnos; van a caer sobre nosotros y prendernos como siervos, juntamente con nuestros asnos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Acercáronse, pues, al mayordomo de la casa de José, y hablando con él a la puerta de la casa,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'dijeron: “Disculpe, señor mío. Nosotros hemos bajado ya una vez a comprar provisiones.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'Mas cuando llegamos a la posada y abrimos nuestros costales, he aquí que el dinero de cada uno estaba en la boca de su costal, nuestro dinero en igual peso; por lo cual lo hemos vuelto a traer con nosotros.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'Hemos traído con nosotros también otro dinero para comprar provisiones. No sabemos quién puso nuestro dinero en nuestros costales.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'A lo que él respondió: “¡Estad tranquilos! No temáis. Vuestro Dios y el Dios de vuestro padre os puso un tesoro en vuestros costales. Vuestro dinero llegó a mí.” Y condujo a Simeón adonde estaban.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Después introdujo a los hombres en la casa de José, les dio agua para que se lavaran los pies, y también pienso a sus asnos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Prepararon entonces el presente para cuando viniese José al mediodía; pues habían oído que allí tendrían que comer.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Cuando José llegó a casa, transportaron a su palacio el presente que habían traído consigo; y se postraron en tierra delante de él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'El cual les preguntó cómo estaban y dijo: “¿Está bien vuestro anciano padre de quien me hablasteis? ¿Vive todavía?');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Contestaron: “Tu siervo nuestro padre está bien y vive todavía”; e inclinándose se postraron.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Alzando los ojos, vio a Benjamín, su hermano, hijo de su madre, y dijo: “¿Es este vuestro hermano menor, de quien me hablasteis?” Y agregó: “¡Dios te bendiga, hijo mío!”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Tras esto buscó José precipitadamente un lugar donde llorar, porque se le conmovieron las entrañas a causa de su hermano; entró, pues, en su aposento y allí lloró.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Después de haberse lavado el rostro, salió; y haciendo esfuerzo por contenerse, dijo: “Servid la comida.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Y sirvieron para él aparte, y para ellos aparte, y aparte para los egipcios que comían con él; pues los egipcios no pueden comer con los hebreos, porque esto es cosa abominable para los egipcios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, '(Los hermanos de José) ocupaban los asientos delante de él, el mayor según su primogenitura, y el menor según su menor edad, por lo cual se miraban con asombro unos a otros.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Les hizo servir de las porciones que tenía delante de sí; mas la porción de Benjamín era cinco veces mayor que la de todos ellos. Y bebieron y se alegraron con él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Después dio José al mayordomo de su casa esta orden: “Llena de provisiones los costales de estos hombres cuanto puedan llevar y pon el dinero de cada uno en la boca de su costal.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Pon también mi copa, la copa de plata, en la boca del costal del menor, juntamente con el dinero de su trigo.” Y él hizo según la orden que José había dado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Al rayar el alba se despidieron los hombres con sus asnos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Pero apenas habían salido de la ciudad, hallándose aún a poca distancia de ella, dijo José al mayordomo de su casa: “Levántate y corre tras esas gentes, y cuando los alcances, les dirás: “¿Por qué habéis devuelto mal por bien?');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, '¿No es esta (la copa) en que bebe mi señor, y por medio de la cual suele adivinar? Habéis obrado mal en lo que hicisteis.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Y él, habiéndolos alcanzado, les repitió estas mismas palabras.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Contestáronle: “¿Por qué dice mi señor tal cosa? Lejos de tus siervos hacer algo semejante.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'He aquí que hemos vuelto a traerte desde el país de Canaán el dinero que hallamos en la boca de nuestros costales; ¿cómo íbamos a robar de la casa de tu señor plata u oro?');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Aquel de tus siervos en cuyo poder fuere hallada, muera, y en cuanto a nosotros seremos siervos de mi señor.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Sea así como decís, respondió él. Aquel en cuyo poder fuere hallado será mi siervo; mas vosotros quedaréis sin culpa.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Con esto se apresuraron a bajar cada uno su costal a tierra; y abrió cada cual su costal.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Y él (los) registró, empezando por el mayor, y acabando por el menor, y fue hallada la copa en el costal de Benjamín.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Rasgaron entonces sus vestidos, y cargando cada uno su asno, volvieron a la ciudad.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Así llegó Judá con sus hermanos a la casa de José —este se hallaba todavía allí— y se echaron delante de él a tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Díjoles José: “¿Qué es lo que habéis hecho? ¿No sabíais que un hombre como yo sabe adivinar?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'A lo cual respondió Judá: “¿Qué podemos decir a mi señor? ¿Qué vamos a hablar, o cómo nos justificaremos? Dios ha descubierto la iniquidad de tus siervos. Henos aquí, siervos somos de mi señor, tanto nosotros como aquel en cuyo poder fue hallada la copa.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, '“Lejos de mí hacer tal cosa, contestó José. El hombre en cuyo poder fue hallada la copa, ese será siervo mío; vosotros, empero, subid en paz a casa de vuestro padre.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Entonces Judá se acercó a él, y dijo: “Por favor, señor mío, permite que tu siervo diga una palabra a oídos de mi señor, y no se encienda tu ira contra tu siervo; porque tú eres igual al Faraón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Mi señor preguntó a sus siervos, diciendo: ‘¿Tenéis padre o hermano?’');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Respondimos a mi señor: ‘Sí, tenemos un padre anciano, y un niño de su vejez, que es el menor y cuyo hermano murió, de modo que él solo le ha quedado de su madre, y su padre le ama’.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Tú dijiste entonces a tus siervos: ‘Traédmelo, para que ponga mis ojos sobre él’.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Mas nosotros respondimos a mi señor: ‘El joven no puede dejar a su padre; porque si lo dejare, su padre morirá’.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Pero tú dijiste a tus siervos: ‘Si no baja con vosotros vuestro hermano menor, no volveréis a ver mi rostro’.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Subimos, pues a casa de tu siervo, mi padre, y le contamos las palabras de mi señor.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Y cuando dijo nuestro padre: ‘Volved a comprarnos algo para comer’,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'contestamos nosotros: ‘No podemos bajar. Pero si nuestro hermano menor va con nosotros, bajaremos; pues no podremos ver el rostro de aquel hombre, a no ser que vaya con nosotros nuestro hermano menor’.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Entonces nos dijo tu siervo, mi padre: ‘Vosotros sabéis que mi esposa me dio dos hijos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'El uno desapareció de mi presencia, y yo dije: Sin duda ha sido devorado, y hasta ahora no le he visto más.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Si lleváis también a este de mi presencia, y le sucede alguna desgracia, haréis descender con dolor mis canas al sepulcro’.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Ahora, pues, si yo llego a tu siervo mi padre, y no está con nosotros el joven, de cuya vida depende la suya,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'sucederá que al ver que el joven no existe, morirá; y así tus siervos harán descender con dolor al sepulcro las canas de tu siervo, nuestro padre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Porque tu siervo se hizo responsable por el joven ante mi padre, diciendo: ‘Si no te lo vuelvo a traer, seré para siempre reo de pecado contra mi padre’.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Te ruego, pues, que tu siervo quede en lugar del joven por esclavo de mi señor, a fin de que el joven pueda volver con sus hermanos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Pues ¿cómo podré yo subir a casa de mi padre, sin que el joven esté conmigo? ¡No vea yo el mal que vendrá sobre mi padre!”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'José, no pudiendo ya contenerse delante de cuantos lo rodeaban, gritó: “¡Haced salir a todos de mi presencia!” De modo que no se quedó nadie con José cuando se dio a conocer a sus hermanos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Y se puso a llorar en alta voz, de suerte que lo oyeron los egipcios; lo oyó también la casa del Faraón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Entonces dijo José a sus hermanos: “Yo soy José. ¿Vive todavía mi padre?” Pero sus hermanos no pudieron responderle, porque su presencia los había llenado de espanto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Dijo, pues, José a sus hermanos: “Acercaos a mí.” Ellos se le acercaron; y les repitió: “Yo soy José, vuestro hermano, a quien vendisteis a Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Mas ahora no os aflijáis, y no os pese el haberme vendido aquí, que para salvar vidas me envió Dios delante de vosotros.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Porque hace dos años ya que hay hambre en la tierra, y aún restan cinco años en que no habrá ni siembra ni siega.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Dios me ha enviado delante de vosotros para dejaros un resto sobre la tierra, y a fin de conservaros la vida para una gran salvación.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Así, pues, ya no sois vosotros los que me habéis enviado aquí, sino Dios, quien me ha constituido padre del Faraón y señor de toda su casa y gobernador de todo el país de Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Apresuraos a subir donde mi padre, y decidle: Así dice tu hijo José: Dios me ha hecho señor de todo en Egipto; ven a mí sin tardar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Habitarás en el país de Gosen, y estarás cerca de mí, tú y tus hijos y los hijos de tus hijos, tus ovejas y tus vacadas y todo cuanto tienes.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Y yo te sustentaré allí —pues vendrán todavía cinco años de hambre— no sea que perezcas tú y tu casa y todo lo tuyo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'He aquí que vuestros ojos, y también los ojos de mi hermano Benjamín están ahora viendo que es mi propia boca la que os habla.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Contad a mi padre toda mi gloria en Egipto y todo lo que habéis visto, y apresuraos a traer a mi padre aquí.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Arrojándose sobre el cuello de Benjamín su hermano lloró, llorando también Benjamín sobre el cuello de José.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Besó también a todos sus hermanos, llorando sobre ellos. Después de esto sus hermanos conversaron con él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'La nueva fue oída también en el palacio del Faraón, al cual dijeron: “Han venido los hermanos de José”, y se holgaron el Faraón y sus servidores.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Y dijo el Faraón a José: “Di a tus hermanos: Haced esto: Cargad vuestras bestias y encaminaos al país de Canaán,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'y tomad a vuestro padre y vuestras familias, y venid a mí. Yo os daré lo mejor del país de Egipto, y comeréis de la grosura de la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Y tú ordénales: Llevaos del país de Egipto carros para vuestros niños y para vuestras mujeres; y tomad a vuestro padre y venid.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Vuestros ojos no miren por las cosas (que dejáis); pues lo mejor de toda la tierra de Egipto es vuestro.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Los hijos de Israel hicieron así; y José les dio carros por mandato del Faraón, entregándoles además provisiones para el viaje.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Dio también a todos ellos vestidos de fiesta; más a Benjamín le dio trescientas monedas de plata y cinco vestidos de fiesta.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Y a su padre envió igualmente diez asnos cargados con las cosas más preciosas de Egipto, y diez asnas cargadas de trigo, pan y víveres para el viaje de su padre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Luego despidió a sus hermanos, y cuando se fueron, les dijo: “No os peleéis en el camino.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Subieron, pues, de Egipto y llegaron al país de Canaán, a su padre Jacob,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'al cual dieron la nueva, diciendo: “Vive todavía José y es gobernador de todo el país de Egipto.” Mas no se conmovió su corazón, porque no les dio crédito.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Dijéronle entonces todas las palabras que José les había dicho y cuando vio los carros que José había enviado para transportarle revivió el espíritu de Jacob, su padre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'Y exclamó Israel: “¡Basta! ¡Vive todavía mi hijo José; iré y lo veré antes de morir!”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Israel se puso en marcha con todo lo que tenía, y llegó a Bersabee, donde ofreció sacrificios al Dios de su padre Isaac.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Y habló Dios a Israel en visión nocturna y le dijo: ¡Jacob, Jacob!” Él respondió: “Heme aquí.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Y dijo: “Yo soy Dios, el Dios de tu padre; no temas bajar a Egipto, porque allí te haré padre de una gran nación.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Yo bajaré contigo a Egipto; y Yo te subiré también; y José pondrá su mano sobre tus ojos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Luego partió Jacob de Bersabee, y los hijos de Israel pusieron a Jacob su padre, y a sus niños y a sus mujeres, en los carros que el Faraón había enviado para transportarlo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Lleváronse también sus ganados y la hacienda que habían adquirido en el país de Canaán, y fueron a Egipto: Jacob y con él toda sus descendencia.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'Llevó consigo a Egipto a sus hijos y a los hijos de sus hijos, a sus hijas y a las hijas de sus hijos y a toda su familia.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Estos son los nombres de los hijos de Israel que llegaron a Egipto: Jacob y sus hijos: el primogénito de Jacob: Rubén.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Y los hijos de Rubén: Enoc, Falú, Hesrón, Carmí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Los hijos de Simeón: Jemuel, Jamín, Ohad, Jaquín, Sóhar y Saúl, hijo de la cananea.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Los hijos de Leví: Gersón, Caat y Merarí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Los hijos de Judá: Er, Onán, Selá, Fares y Zara; pero habían muerto ya Er y Onán en el país de Canaán. Hijos de Fares: Hesrón y Hamul.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Los hijos de Isacar: Tolá, Fuá, Job y Simrón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Los hijos de Zabulón: Séred, Elón y Jahleel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Estos son los hijos que Lía dio a Jacob en Mesopotamia, con Diná, su hija. Todas las almas de sus hijos y de sus hijas fueron treinta y tres.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Los hijos de Gad: Sifión, Haguí, Suní, Esbón, Erí, Arodí y Arelí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Los hijos de Aser: Jimná, Isuá, Isuí, Beriá y Sera, hermana de ellos. Hijos de Beriá: Héber y Malquiel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Estos son los hijos de Silfá, la cual Labán dio a su hija Lía, y ella dio estos a Jacob: diez y seis almas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Los hijos de Raquel, mujer de Jacob: José y Benjamín.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Nacieron a José en tierra de Egipto Manasés y Efraím, de Asenat, hija de Putifar, sacerdote de On.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Los hijos de Benjamín: Bela, Béquer, Asbel, Gerá, Naamán, Ehí, Ros, Mupim, Hupim y Ard.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Estos son los hijos de Raquel, que nacieron de Jacob. En total catorce almas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Los hijos de Dan: Husim.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Los hijos de Neftalí: Jahzeel, Guní, Jéser y Silem.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Estos son los hijos de Bilhá, la cual Labán dio a su hija Raquel; y de ella nacieron estos a Jacob, en total siete almas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Toda la familia de Jacob, que vino a Egipto, descendientes suyos sin contar las mujeres de los hijos de Jacob, todas estas almas eran sesenta y seis.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Los hijos de José, que le habían nacido en Egipto, eran dos. Todas las almas de la casa de Jacob, que vinieron a Egipto, eran setenta.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Envió (Jacob) a Judá delante suyo adonde estaba José para que este preparara su llegada a Gosen; y así llegaron a la tierra de Gosen.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Entretanto, José había enganchado su carroza y subido a recibir a Israel, su padre, en Gosen; y cuando lo vio se arrojó a su cuello y lloró largo tiempo sobre su cuello.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Y dijo Israel a José: “Ahora puedo morir, ya que he visto tu rostro, pues tú vives todavía.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Y dijo José a sus hermanos y a la casa de su padre: “Iré a dar parte al Faraón, diciendo: Han venido a mí mis hermanos y la casa de mi padre, que estaban en el país de Canaán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Son pastores de ovejas, pues poseen rebaños, y han traído sus ovejas y sus ganados y todo lo que tienen.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Y cuando el Faraón os llamare y preguntare: ¿Cuál es vuestra ocupación?');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'responderéis: Criadores de ganado han sido tus siervos desde nuestra infancia hasta ahora, tanto nosotros como nuestros padres. Así podréis habitar en la tierra de Gosen; porque los egipcios detestan a todo pastor de ovejas.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Fue, pues, José a dar parte al Faraón, diciendo: “Mi padre y mis hermanos han venido del país de Canaán, con sus ovejas y sus vacadas y todo lo que poseen, y he aquí que están en la tierra de Gosen.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Después tomó a cinco de sus hermanos y se los presentó al Faraón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Y cuando el Faraón preguntó a sus hermanos: “¿Cuál es vuestra ocupación?”, respondieron al Faraón: “Nosotros, tus siervos, somos pastores de ganado menor, tanto nosotros como nuestros padres.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Y dijeron además al Faraón: “Hemos venido para morar en esta tierra; porque no hay pastos para los rebaños que tienen tus siervos, por ser grande el hambre en el país de Canaán. Permite, pues, que habiten tus siervos en la tierra de Gosen.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Dijo entonces el Faraón a José: “Tu padre y tus hermanos han venido a ti.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'La tierra de Egipto está a tu disposición. Da a tu padre y a tus hermanos morada en la mejor parte del país; habiten ellos en la tierra de Gosen; y si sabes que hay entre ellos hombres capaces, hazlos mayorales de mis ganados.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Luego José hizo venir a su padre Jacob y le presentó al Faraón; y Jacob bendijo al Faraón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Cuando preguntó el Faraón a Jacob: “¿Cuántos son los días de los años de tu vida”?,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'contestó Jacob al Faraón: “Los días de los años de mi peregrinación son ciento treinta años; pocos y malos han sido los días de los años de mi vida, y no llegaron a los días de los años de la vida de mis padres en los días de su peregrinación.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Después de haber bendecido Jacob al Faraón, salió de su presencia.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Según había mandado el Faraón, estableció José a su padre y a sus hermanos, asignándoles posesiones en la tierra de Egipto, en la mejor parte del país, en la comarca de Ramesés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Y José proveyó de pan a su padre y a sus hermanos y a toda la casa de su padre, según el número de los hijos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'No había pan en todo el país, porque el hambre era muy grande; la tierra de Egipto y también la tierra de Canaán estaban agotadas por el hambre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Entonces José recogió toda la plata que se hallaba en el país de Egipto y en el país de Canaán a cambio del trigo que ellos compraron, y llevó ese dinero al palacio del Faraón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Acabado el dinero del país de Egipto y del país de Canaán, vinieron todos los egipcios a José, diciendo: “Danos pan. ¿Por qué hemos de morir en tu presencia?, pues el dinero se ha agotado.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Contestó José: “Entregad vuestro ganado, y os lo daré por vuestro ganado, si es que se ha acabado el dinero.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Trajeron, pues, sus ganados a José, y José les dio pan a cambio de caballos y de rebaños de ovejas y de vacas y de asnos. Aquel año los proveyó de pan a trueque de todos sus ganados.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Pasado aquel año, vinieron a él el año siguiente y le dijeron: “No ocultaremos a nuestro señor que se ha agotado el dinero, y también los ganados pertenecen ya a nuestro señor; no nos queda nada delante de nuestro señor, salvo nuestros cuerpos y nuestras tierras.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, '¿Por qué hemos de perecer ante tus ojos, tanto nosotros como nuestras tierras? Cómpranos a nosotros y nuestras tierras por pan, y nosotros y nuestras tierras serviremos al Faraón, y danos para sembrar; así viviremos y no moriremos, y no quedarán desolados los campos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Adquirió, pues, José todo el suelo de Egipto para el Faraón; todos los egipcios vendieron cada uno su campo porque el hambre prevalecía sobre ellos. Así la tierra vino a ser propiedad del Faraón;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'el cual hizo pasar al pueblo a las ciudades, desde un extremo del territorio de Egipto hasta el otro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Mas no adquirió las tierras de los sacerdotes; porque los sacerdotes percibían del Faraón una ración determinada, y comían la ración determinada que les daba el Faraón; por eso no vendieron sus tierras.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Dijo entonces José al pueblo: “Mirad, hoy os he comprado para el Faraón, a vosotros y vuestras tierras. Ahí tenéis semilla, sembrad la tierra;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'y al tiempo de la siega, daréis la quinta parte al Faraón; las otras cuatro partes serán vuestras, para sembrar los campos, y para sustentar a vosotros y los que están en vuestras casa, y para alimento de vuestros niños.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'A lo cual ellos dijeron: “Nos ha dado la vida. Con tal que hallemos gracia a los ojos de mi señor, seremos siervos del Faraón.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'Y José puso esto por ley que vale para las tierras de Egipto hasta el día de hoy y en virtud de la cual la quinta parte es para el Faraón. Tan solo las tierras de los sacerdotes no vinieron a ser propiedad del Faraón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Habitó Israel en el país de Egipto, en la región de Gosen; allí adquirieron posesiones y crecieron y se multiplicaron mucho.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Vivió Jacob diez y siete años en la tierra de Egipto, y fueron los días de Jacob, los años de su vida, ciento cuarenta y siete años.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Cuando los días de Israel tocaron a su fin, llamó a José, y le dijo: “Si he hallado gracia a tus ojos, te ruego pongas tu mano debajo de mi muslo y uses conmigo de misericordia y de fidelidad: No me sepultes en Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'Cuando yo descansare con mis padres, me llevarás de Egipto y me sepultarás en el sepulcro de ellos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, '“Júramelo”, dijo Jacob. Y José se lo juró, e Israel se postró sobre la cabecera de su lecho.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Después de esto recibió José la noticia: “He aquí, tu padre está enfermo.” Tomó, pues, consigo a sus dos hijos, Manasés y Efraím;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'y se lo anunciaron a Jacob, diciendo: “Mira que viene a ti tu hijo José.” Entonces Israel esforzándose se sentó en su lecho.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Y dijo Jacob a José: “El Dios Todopoderoso se me apareció en Luz, en la tierra de Canaán, y me bendijo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'diciéndome: ‘He aquí que Yo te haré crecer y te multiplicaré, y haré de ti una muchedumbre de pueblos y daré esta tierra en posesión perpetua a tu descendencia después de ti’.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Ahora bien, tus dos hijos que te han nacido en tierra de Egipto antes de mi venida a ti a Egipto, serán míos. Como Rubén y Simeón, así serán míos Efraím y Manasés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Mas tus hijos que has engendrado después de ellos, son tuyos, y en cuanto a la herencia llevarán el nombre de sus hermanos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Al volver yo de Mesopotamia, se me murió Raquel en la tierra de Canaán, en el camino a poca distancia de Efrata; y la enterré allí en el camino de Efrata, que es Betlehem.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Viendo entonces Israel a los hijos de José, preguntó: “¿Quiénes son estos?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Respondió José a su padre: “Son mis hijos, los que Dios me ha dado aquí.” Y él dijo: “Acércamelos, te ruego, para que los bendiga.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Pues los ojos de Jacob se habían nublado por la vejez y no podía ya ver. Entonces José se los acercó, y él los besó y los abrazó.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Después dijo Israel a José: “Yo no pensaba ya ver más tu rostro, y he aquí que Dios me ha concedido ver también a tus hijos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Y sacándolos de entre las rodillas de Jacob se postró José delante de él en tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Luego tomó José a ambos, a Efraím a su derecha, o sea a la izquierda de Israel, y a Manasés a su izquierda, o sea a la derecha de Israel, y los acercó a este.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'E Israel extendió su mano derecha y la puso sobre la cabeza de Efraím, que era el menor, y su izquierda (la puso) sobre la cabeza de Manasés, cruzando las manos, aunque Manasés era el primogénito.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Y bendijo a José, diciendo: “El Dios en cuya presencia caminaron mis padre Abrahán e Isaac, el Dios que ha sido mi Pastor desde que existo hasta el día de hoy,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'el Ángel que me ha librado de todo mal, bendiga a estos niños; sean llamados con mi nombre y con el nombre de mis padres Abrahán e Isaac, y multiplíquense más y más sobre la tierra.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Cuando José vio que su padre tenía la mano derecha puesta sobre la cabeza de Efraím, no le pareció bien; tomando la mano de su padre para pasarla de la cabeza de Efraím a la cabeza de Manasés,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'dijo a su padre: “No así, padre mío, este es el primogénito; pon tu derecha sobre su cabeza.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Pero se negó su padre, diciendo: “Lo sé, hijo mío, lo sé; también él vendrá a ser un pueblo, también él será grande; pero su hermano menor será más grande que él, y su descendencia vendrá a ser una multitud de naciones.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Y los bendijo en aquel día, diciendo: “Por ti se bendecirá en Israel con las palabras: «¡Dios te haga como a Efraím y como a Manasés!»”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Después dijo Israel a José: “He aquí que yo me muero; mas Dios estará con vosotros y os hará volver al país de vuestros padres.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Y a ti te doy una porción más que a tus hermanos, la que tomé al amorreo con mi espada y con mi arco.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Llamó Jacob a sus hijos, y dijo “Reuníos, y os haré conocer las cosas que os han de suceder en los días postreros:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Reuníos y oíd, hijos de Jacob, escuchad a Israel, vuestro padre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Rubén, tú mi primogénito; mi vigor y el primer fruto de mi fuerza; el primero en dignidad, el primero en poder;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'tú que hierves como el agua, no tendrás más la primacía; porque subiste al lecho de tu padre. Lo manchaste, porque subiste a mi lecho.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Simeón y Leví, hermanos; instrumentos inicuos son sus espadas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, '¡En su consejo no entres, oh alma mía; honra mía, no te reúnas con su asamblea! porque en su saña mataron hombres, y por su capricho desjarretaron toros.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, '¡Maldita su ira, porque fue violenta, y su furor, porque fue cruel! Los dividiré en Jacob, y los esparciré en Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'A ti, Judá, te alabarán tus hermanos; tu mano pesará sobre la cerviz de tus enemigos; te adorarán los hijos de tu padre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Cachorro de león es Judá; —¡cómo te levantas, hijo mío, de la presa!— se encorva, echándose como un león, y cual leona, ¿quién le despertará?');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'No se apartará de Judá el cetro, ni el báculo de entre sus pies, hasta que venga Schiloh: a Él obedecerán las naciones.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Él ata a la vid su pollino, y a la cepa el pollino de su asna, lava en vino sus vestidos, y en sangre de uvas su manto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Sus ojos brillan por el vino, y sus dientes son blancos por la leche.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Zabulón habita en la ribera del mar, en la ribera donde (aportan) las naves; y su flanco se extiende hacia Sidón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Isacar es un asno huesudo, que descansa entre los apriscos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Viendo que el reposo es bueno, y la tierra amena; ofrece su hombro para cargas, y se somete a pagar tributos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dan juzgará a su pueblo como cualquier otra tribu de Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Será Dan una culebra junto al camino, una víbora en la senda, que muerde los talones del caballo, para que caiga hacia atrás su jinete.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Espero tu salvación, Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'A Gad lo atacan salteadores, mas él asalta su retaguardia.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Aser tiene pan con aceite, proporciona bocados dignos de reyes.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Neftalí es un ciervo suelto; profiere palabras hermosas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Retoño fecundo es José, retoño de árbol fértil, al borde de una fuente; sus vástagos pasan el muro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Le causan amarguras, le asaetean, le hostigan los flecheros,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'más su arco queda fuerte, y los brazos de sus manos son ágiles, por la ayuda del Fuerte de Jacob, por el Nombre del Pastor, la Roca de Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'El Dios de tu padre te ayudará, y el Todopoderoso te bendecirá con bendiciones celestiales de lo alto, bendiciones del abismo que yace abajo, bendiciones de los pechos y del seno.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Las bendiciones de tu padre superan a las bendiciones de los montes eternos, y los tesoros de los collados perennes. ¡Vengan ellas sobre la cabeza de José, sobre el vértice del príncipe entre sus hermanos!');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Benjamín es un lobo rapaz; por la mañana devora la presa, y a la tarde reparte los despojos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Todas estas son las doce tribus de Israel; y esto es lo que les dijo su padre cuando los bendijo: a cada una la bendijo con la bendición que le correspondía.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Y les dio orden, diciéndoles: “Yo voy a reunirme con mi pueblo; sepultadme con mis padres, en la cueva que está en el campo de Efrón el heteo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'en la cueva que está en el campo de Macpelá, frente a Mamré, en el país de Canaán; en el campo que compró Abrahán a Efrón, el heteo, para sepultura propia;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'donde sepultaron a Abrahán y a Sara, su mujer, donde sepultaron a Isaac y a Rebeca, su mujer, y donde sepulté yo a Lía;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'en el campo y la cueva que en él hay, que yo he comprado a los hijos de Het.” Y cuando acabó Jacob de dar estas órdenes a sus hijos, recogió sus pies en el lecho y expiró, y se reunió con su pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Se echó entonces José sobre el rostro de su padre y llorando sobre él lo besó.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Y mandó José a los médicos que tenía a su servicio, que embalsamaran a su padre; y embalsamaron los médicos a Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Emplearon en ello cuarenta días; porque este es el tiempo que se emplea para el embalsamamiento; y Egipto lo lloró por espacio de setenta días.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Pasado el tiempo de su llanto, habló José a los cortesanos del Faraón, diciendo: “Si he hallado gracia a vuestros ojos, hacedme el favor de hacer llegar a oídos del Faraón esta palabra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, '“Mi padre me ha tomado juramento diciendo: ‘He aquí que yo me muero; en la sepultura que abrí para mí, en la tierra de Canaán, allí me has de sepultar’. Ahora, pues permíteme que suba a sepultar a mi padre; y luego volveré.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Respondió el Faraón: “Sube y sepulta a tu padre, como él te hizo jurar.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Subió, pues, José a enterrar a su padre; y subieron con él todos los servidores del Faraón, los ancianos de su casa, y todos los ancianos del país de Egipto;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'y toda la casa de José, sus hermanos, y la casa de su padre. Solo a sus pequeñuelos, sus rebaños y sus vacadas dejaron en la tierra de Gosen.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Subieron también con él carros y gente de a caballo, de manera que el cortejo era muy grande.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Llegados a la era de Atad, que está al otro lado del Jordán, hicieron allí un duelo grande y muy solemne, y José hizo a su padre un duelo de siete días.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Cuando los cananeos, habitantes de la tierra, vieron el llanto en la era de Atad, decían: “Llanto muy grande es este de los egipcios.” Por eso se dio el nombre de Abel-Misraim a ese lugar que está allende el Jordán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Hicieron, pues, los hijos de Jacob con él según les había mandado:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'Lleváronle sus hijos a la tierra de Canaán, y le sepultaron en la cueva del campo de Macpelá, frente a Mamré; en el campo que Abrahán había comprado a Efrón, el heteo, para sepultura propia.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Después de haber sepultado a su padre, se volvió José a Egipto, él y sus hermanos, y todos los que habían subido con él a sepultar a su padre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Cuando vieron los hermanos de José que había muerto su padre, se dijeron: “A lo mejor José nos guarda rencor y nos devolverá todo el mal que le hemos hecho.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Enviaron, pues a decir a José: “Tu padre mandó, antes de su muerte, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'Así diréis a José: ‘Perdona, por favor, el crimen de tus hermanos y su pecado, porque ciertamente te han hecho mal. Pero ahora perdona, te rogamos, ese crimen de los siervos del Dios de tu padre’.” José lloró mientras así hablaban con él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Fueron entonces sus hermanos personalmente, y postrándose delante de él dijeron: “Henos aquí, somos siervos tuyos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Mas José le dijo: “No temáis. ¿Estoy yo acaso en lugar de Dios?');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Vosotros pensasteis hacerme mal, pero Dios lo dispuso para bien para cumplir lo de hoy, a fin de conservar la vida de mucha gente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Así, pues no temáis; yo os sustentaré a vosotros y a vuestros niños.” Y los consoló, hablándoles al corazón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Habitó José en Egipto, él y la casa de su padre. Y vivió José ciento diez años.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Vio José a los hijos de Efraím hasta la tercera generación. También los hijos de Maquir, hijo de Manasés, nacieron sobre las rodillas de José.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Y dijo José a sus hermanos: “Voy a morir; mas Dios seguramente os visitará, y os hará subir de este país a la tierra que juró dar a Abrahán, a Isaac y a Jacob.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Luego José hizo jurar a los hijos de Israel, diciendo: “De seguro os visitará Dios, y entonces llevaos de aquí mis huesos.” Murió José a la edad de ciento diez años. Lo embalsamaron, y lo pusieron en un féretro en Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Estos son los nombres de los hijos de Israel que entraron en Egipto con Jacob, cada uno con su familia:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Rubén, Simeón, Leví, Judá,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Isacar, Zabulón, Benjamín,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan, Neftalí, Gad y Aser.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Todos los descendientes nacidos de Jacob eran setenta almas. José estaba ya en Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Luego murió José, y todos sus hermanos, y toda aquella generación.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Mas los hijos de Israel crecieron y se multiplicaron, y llegaron a ser numerosos y fuertes, y se llenó de ellos el país.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Entretanto se alzó sobre Egipto un nuevo rey, que nada sabía de José;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'el cual dijo a su pueblo: “Mirad, el pueblo de los hijos de Israel es más numeroso y más fuerte que nosotros.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Tomemos, pues, precauciones contra él, no sea que siga multiplicándose, y en caso de venir sobre nosotros una guerra, se asocie también él a nuestros enemigos para combatirnos, y salga (después) del país.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Por lo cual pusieron sobre (Israel), sobrestantes de trabajos a fin de oprimirlos con sus cargas; y así edificaron para el Faraón ciudades almacenes: Pitom y Ramesés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Pero cuanto más los oprimían, tanto más crecían y tanto más se multiplicaban, de modo que (los egipcios) tomaron aversión a los hijos de Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Entonces los egipcios redujeron a cruel servidumbre a los hijos de Israel,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'y les amargaron la vida con duros trabajos de arcilla y ladrillos, toda suerte de labores del campo y toda clase de servidumbre con que los oprimían por fuerza.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'El rey de Egipto dio también orden a las parteras de las hebreas, de las cuales una se llamaba Sifrá, y la otra Puá,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'diciéndoles: “Cuando asistáis a las hebreas en sus partos, averiguad el sexo; si es niño, matadlo; mas si es niña, vivirá.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Pero las parteras temían a Dios, y no hicieron como les había mandado el rey de Egipto, sino que dejaban con vida a los niños.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Por lo cual llamó el rey de Egipto a las parteras y les dijo: “¿Por qué hacéis esto y dejáis con vida a los niños?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Respondieron las parteras al Faraón: “Porque las hebreas no son como las egipcias. Son robustas, y antes que a ellas llegue la partera, ya han dado a luz.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Recompensó Dios a las parteras; y se multiplicó el pueblo y se hizo muy poderoso.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Y por haber temido las parteras a Dios, Él les dio numerosa prole.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Entonces dio el Faraón a todo su pueblo esta orden: “Todo niño que naciere (a los hebreos) lo echaréis al río; mas a toda niña dejaréis con vida.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Un varón de la casa de Leví había ido y tomado por mujer a una hija de Leví.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Concibió la mujer y dio a luz un hijo; y viendo que era hermoso lo tuvo escondido durante tres meses.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Pero no pudiendo ocultarlo ya por más tiempo, tomó para él una cestilla de juncos, la calafateó con betún y pez, y metió en ella al niño, y la puso entre los juncos, a la ribera del río.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Entretanto, su hermana se apostó de lejos para saber lo que le ocurría.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Bajó la hija del Faraón para bañarse en el río, y mientras sus doncellas se paseaban por la ribera del río, divisó la cestilla en los juncos, y envió una criada suya para que se la trajese.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Al abrirla vio al niño que era una criatura que lloraba. Tuvo compasión de él, y exclamó: “Este es un niño de los hebreos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Entonces dijo su hermana a la hija del Faraón: “¿Quieres que yo vaya y te llame una nodriza de entre las hebreas que amamante para ti este niño?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, '“Anda”, le contestó la hija del Faraón. Fue pues la joven y llamó a la madre del niño.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Y le dijo la hija del Faraón: “Toma este niño, y amamántalo para mí, y yo te recompensaré.” Y tomó la mujer al niño y lo amamantó.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'El niño creció, y ella lo llevó entonces a la hija del Faraón. Así vino a ser hijo suyo, y le llamó Moisés, diciendo: “De las aguas lo he sacado.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'En aquellos días cuando Moisés ya era grande, visitó a sus hermanos, y vio sus trabajos penosos; vio también cómo un egipcio daba golpes a un hebreo, a uno de sus hermanos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Miró a un lado y a otro, y viendo que no había nadie, mató al egipcio y lo escondió en la arena.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Salió también al día siguiente y vio a dos hebreos que reñían. Dijo al culpable: “¿Por qué pegas a tu hermano?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Él respondió: “¿Quién te ha constituido jefe y juez sobre nosotros? ¿Piensas acaso matarme como mataste al egipcio?” Por esto Moisés tuvo miedo y dijo: Seguramente ha trascendido este asunto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Lo supo el Faraón y procuraba matar a Moisés; por lo cual Moisés huyó de la presencia del Faraón y se fue a morar en la tierra de Madián donde se sentó junto a un pozo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Tenía el sacerdote de Madián siete hijas, las cuales llegaron a sacar agua y llenar los abrevaderos, para abrevar las ovejas de su padre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Mas vinieron los pastores y las echaron. Entonces levantándose Moisés salió en su defensa y abrevó sus ovejas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Volvieron ellas a Ragüel, su padre, y este preguntó: “¿Cómo es que venís hoy tan temprano?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'Respondieron: “Un egipcio nos libró de las manos de los pastores, y a más de eso ha sacado agua para nosotras y abrevado las ovejas.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Preguntó entonces a sus hijas: “¿Dónde está? ¿Por qué habéis dejado a ese hombre? Llamadle para que coma pan.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Consintió Moisés en morar con aquel hombre, el cual dio a Moisés su hija Seforá.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Esta le dio un hijo, al cual él llamó Gersom; pues dijo: “Extranjero soy en tierra extraña.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Durante este largo período murió el rey de Egipto; y los hijos de Israel, gimiendo bajo la servidumbre, clamaron, y desde su dura servidumbre subió su clamor a Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Oyó Dios sus gemidos, y se acordó Dios de su pacto con Abrahán, con Isaac y con Jacob.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Y miró Dios a los hijos de Israel y (los) reconoció.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Un día, apacentando las ovejas de Jetró, su suegro, sacerdote de Madián, llevó Moisés las ovejas al interior del desierto y vino al Horeb (que es) el monte de Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Y se le apareció el Ángel de Yahvé en una llama de fuego, en medio de una zarza. Veía cómo la zarza ardía en el fuego, pero la zarza no se consumía.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Dijo, pues, Moisés: “Iré a contemplar este gran fenómeno (para saber) por qué no se consume la zarza.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Cuando Yahvé vio que se ponía en marcha para mirar, lo llamó de en medio de la zarza, diciendo: “¡Moisés, Moisés!” “Heme aquí”, respondió él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Y Dios le dijo: “No te acerques aquí; quita el calzado de tus pies, porque el lugar en que estás, es tierra santa.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Y añadió: “Yo soy el Dios de tu padre, el Dios de Abrahán, el Dios de Isaac y el Dios de Jacob.” Se cubrió entonces Moisés el rostro, porque temía mirar a Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Y dijo Yahvé: “He visto la aflicción de mi pueblo que está en Egipto, y he escuchado el clamor que levanta a causa de sus exactores; pues conozco sus sufrimientos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'He descendido para librarlo de la mano de los egipcios y para llevarlo de esta tierra a una buena y espaciosa; a una tierra que mana leche y miel, al país del cananeo, heteo, amorreo, fereceo, heveo y jebuseo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Ahora el clamor de los hijos de Israel ha llegado hasta Mí y también he visto la opresión con que los egipcios los oprimen.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Ve, por tanto, y te enviaré al Faraón, para que saques a mi pueblo, los hijos de Israel, de Egipto.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Moisés respondió a Dios: “¿Quién soy yo para ir al Faraón y sacar a los hijos de Israel de Egipto?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Respondió Él: “Yo estaré contigo y esto te servirá de señal de que Yo te he enviado: cuando hayas sacado al pueblo de Egipto, serviréis a Dios en este monte.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Contestó Moisés a Dios: “Iré, pues, a los hijos de Israel y les diré: El Dios de vuestros padres me ha enviado a vosotros; pero cuando me pregunten: ¿Cuál es su nombre? ¿Qué les responderé?');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Entonces dijo Dios a Moisés: “Yo soy el que soy.” Y agregó: “Así dirás a los hijos de Israel: «El que es me ha enviado a vosotros.»”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Prosiguió Dios diciendo a Moisés: “Así dirás a los hijos de Israel: Yahvé, el Dios de vuestros padres, el Dios de Abrahán, el Dios de Isaac y el Dios de Jacob, me ha enviado a vosotros. Este es mi nombre para siempre, y este mi memorial de generación en generación.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Ve, pues, y reúne a los ancianos de Israel, y diles: Yahvé, el Dios de vuestros padres, el Dios de Abrahán, de Isaac y de Jacob se me apareció y me dijo: Yo os he visitado (para ver) lo que os hacen en Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'Y queda dicho: Os sacaré de la tribulación de Egipto, al país del cananeo, heteo, amorreo, fereceo, heveo y jebuseo, a una tierra que mana leche y miel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Ellos escucharán tu voz, y tú irás con los ancianos de Israel al rey de Egipto; y le diréis: Yahvé, el Dios de los hebreos, se nos ha manifestado. Permite, pues, que vayamos camino de tres días al desierto, para ofrecer sacrificios a Yahvé, nuestro Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Ya sé que el rey de Egipto no os dejará ir, si no será por mano poderosa.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Por eso extenderé mi mano y heriré a Egipto con toda suerte de prodigios, que obraré allí; y después de esto os dejará salir.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Y haré que este pueblo halle gracia a los ojos de los egipcios, de modo que cuando partáis, no saldréis con las manos vacías,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'sino que cada mujer pedirá a su vecina y a la que mora en su casa, objetos de plata y objetos de oro, y vestidos, que pondréis a vuestros hijos y a vuestras hijas, despojando así a los egipcios.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Respondió Moisés y dijo: “Mira que no me creerán ni escucharán mi voz; pues dirán: No se te ha aparecido Yahvé.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Díjole Yahvé: “¿Qué es eso que tienes en tu mano?” “Una vara”, respondió él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Y le replicó: “Arrójala a tierra.” La tiró a tierra, y se convirtió en una serpiente; y huyó Moisés de ella.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Dijo entonces Yahvé a Moisés: “Extiende tu mano y agárrala por la cola —y él extendiendo la mano, la agarró, y volvió a ser vara en su mano—,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'para que crean que se te ha aparecido Yahvé, el Dios de sus padres, el Dios de Abrahán, el Dios de Isaac y el Dios de Jacob.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Le dijo además Yahvé: “Mete tu mano en tu seno.” Metió él la mano en su seno y la volvió a sacar; y he aquí que su mano estaba leprosa (blanca) como la nieve.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Y le dijo: “Vuelve a meter tu mano en tu seno.” Volvió a meter la mano en su seno, y cuando la sacó era como su carne.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, '“Así, pues, si no te creen ni escuchan la voz de la primera señal creerán a la voz de la segunda.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'Y si no creen tampoco a estas dos señales, y no escuchan tu voz, tomarás agua del río, y la derramarás en el suelo; y el agua que sacares del río, se convertirá en sangre sobre el suelo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Dijo entonces Moisés a Yahvé: “¡Ah, Señor! yo no soy hombre elocuente, y esto no desde ayer ni desde anteayer, ni desde que Tú hablas con tu siervo; sino que soy torpe de boca y torpe de lengua.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Le respondió Yahvé: “¿Quién ha dado al hombre la boca? ¿Y quién hace al mudo y al sordo, al que ve y al ciego? ¿No soy Yo, Yahvé?');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Ahora, vete, que Yo estaré con tu boca y te enseñaré lo que has de decir.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Mas él replicó: “¡Ah, Señor!, te ruego que mandes (tu mensaje) por mano de aquel que has de mandar.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Entonces se encendió la ira de Yahvé contra Moisés, y le dijo: “¿No tienes a tu hermano Aarón, el levita? Sé que él habla bien; he aquí que precisamente ahora sale a tu encuentro, y al verte se regocijará en su corazón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Hablarás, pues, con él y pondrás estas palabras en su boca, y Yo estaré con tu boca y con la suya, y os enseñaré lo que habéis de hacer.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'Él hablará por ti al pueblo y te servirá de boca, y tú serás para él (representante de) Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Toma también en tu mano esta vara, porque con ella has de hacer las señales.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Se fue Moisés para volver a casa de Jetró, su suegro, al cual dijo: “Iré con tu permiso, y volveré a ver a mis hermanos que están en Egipto, y veré si viven todavía.” Y dijo Jetró a Moisés: “Vete en paz.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Yahvé dijo (de nuevo) a Moisés en Madián: “Anda, vuelve a Egipto; pues han muerto todos los que buscaban tu vida.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Tomó, pues, Moisés a su mujer y a sus hijos, y montándolos sobre un asno, volvió a la tierra de Egipto. Tomó Moisés también la vara de Dios en su mano.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Y dijo Yahvé a Moisés: “Cuando vuelvas a Egipto, mira que hagas delante del Faraón todos los prodigios que he dado en tu mano; Yo, empero, endureceré su corazón, y no dejará ir al pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Y dirás al Faraón: “Así dice Yahvé: Israel es mi hijo, mi primogénito.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'Si Yo te digo: Deja ir a mi hijo para que me sirva, y si tú rehúsas dejarle ir, mira que Yo voy a matar a tu hijo, tu primogénito.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Y sucedió que en el camino, en la posada, Yahvé le salió al encuentro y quiso darle muerte.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Tomó entonces Seforá un pedernal y cortando el prepucio de su hijo, tocó las piernas de (Moisés), diciendo: “Tú eres para mí un esposo de sangre.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Y (Yahvé) le soltó por haber dicho ella: “esposo de sangre”, con motivo de la circuncisión.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'A Aarón le dijo Yahvé: “Vete al desierto al encuentro de Moisés.” Partió, pues, y le encontró en el monte de Dios y le besó.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Moisés contó a Aarón todas las cosas para las cuales Yahvé le había enviado y todas las señales que le había mandado hacer.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Fueron, pues, Moisés y Aarón y reunieron a todos los ancianos de los hijos de Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'Aarón refirió todas las palabras que Yahvé había dicho a Moisés, el cual hizo las señales delante del pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'El pueblo creyó, y al oír que Yahvé había visitado a los hijos de Israel y mirado su aflicción, inclinaron la cabeza y adoraron.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Después se presentaron Moisés y Aarón al Faraón y le dijeron: “Así dice Yahvé, el Dios de Israel: Deja marchar a mi pueblo, para que me celebre una fiesta en el desierto.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'A lo cual respondió el Faraón: “¿Quién es Yahvé para que yo escuche su voz y deje ir a Israel? No conozco a Yahvé, y no dejaré salir a Israel.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Ellos dijeron: “El Dios de los hebreos se nos ha manifestado; permite, pues, que vayamos camino de tres días al desierto para ofrecer sacrificios a Yahvé, nuestro Dios, no sea que nos castigue con peste y espada.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'EI rey de Egipto les replicó: “¿Por qué vosotros, Moisés y Aarón, distraéis al pueblo de sus trabajos? Idos a vuestras cargas.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Y agregó el Faraón: “He aquí que el pueblo de esa región es ahora numeroso y vosotros lo hacéis descansar de sus cargas.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Aquel mismo día el Faraón dio a los sobrestantes del pueblo y a los escribas esta orden:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, '“No deis ya, como antes, al pueblo paja, para hacer ladrillos; que vayan ellos mismos a recoger paja.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Pero exigidles la misma cantidad de ladrillos que hacían antes, sin rebajarla; pues son perezosos; por eso claman diciendo: Vamos a ofrecer sacrificios a nuestro Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Agrávense los trabajos sobre estos hombres, para que estén ocupados y no pierdan el tiempo con palabras mentirosas.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Fueron, pues, los sobrestantes del pueblo y los escribas, y hablaron al pueblo diciendo: “Esto dice el Faraón: No os daré más paja;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'id vosotros mismos a juntar la paja donde podáis hallarla; pero vuestro trabajo no se disminuirá en nada.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Se esparció el pueblo por todo el país de Egipto a buscar rastrojo para emplearlo en lugar de paja.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Y los sobrestantes los apremiaban, diciendo: “Terminad vuestro trabajo que os ha sido fijado para cada día, como cuando había paja.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Y los escribas de los hijos de Israel, a quienes los sobrestantes del Faraón habían puesto sobre ellos, fueron castigados, diciéndoseles: “¿Por qué no habéis hecho, ni ayer ni hoy, la misma cantidad de ladrillos que antes?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Fueron entonces los escribas de los hijos de Israel y clamaron al Faraón, diciendo: “¿Por qué tratas así a tus siervos?');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'No se da paja a tus siervos y se nos dice: Haced ladrillos. Y he aquí que tus siervos son castigados, siendo tu propio pueblo el que tiene la culpa.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Él respondió: “Haraganes sois, grandes haraganes; por eso decís: Vamos a ofrecer sacrificios a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Id, pues, y trabajad; no se os dará paja, y habéis de entregar la cantidad fijada de ladrillos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Los escribas de los hijos de Israel se vieron en grandes angustias, puesto que les fue dicho: “No disminuiréis (la cantidad) de vuestros ladrillos; ¡la obra de cada día en su día!”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Se encontraron con Moisés y Aarón, que les estaban esperando cuando salieron de la presencia del Faraón,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'y les dijeron: “Que Yahvé os vea y que Él juzgue por qué nos habéis hecho odiosos al Faraón y a sus siervos y puesto la espada en sus manos para matarnos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Se volvió entonces Moisés a Yahvé y dijo: “Señor, ¿por qué has hecho mal a este pueblo? ¿Con qué fin me has enviado?');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Pues desde que fui al Faraón para hablarle en tu nombre, está maltratando a este pueblo, y Tú de ninguna manera has librado a tu pueblo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Respondió Yahvé a Moisés: “Ahora verás lo que voy a hacer al Faraón; porque por mano poderosa los dejará salir, y debido a una mano fuerte los arrojará él mismo de su país.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Y habló Dios a Moisés y le dijo: “Yo soy Yahvé;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Me aparecí a Abrahán, a Isaac y a Jacob como Dios Todopoderoso; mas con mi nombre de Yahvé no me di a conocer a ellos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Establecí también mi pacto con ellos, para darles la tierra de Canaán, la tierra de sus peregrinaciones, donde moraban como extranjeros.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'He oído el gemido de los hijos de Israel, a quienes los egipcios han reducido a servidumbre, y tengo presente mi pacto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Por tanto, di a los hijos de Israel: Yo soy Yahvé; Yo os sacaré de debajo de las cargas de los egipcios, os libertaré de su esclavitud y os salvaré con brazo extendido y con grandes juicios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'Yo os adoptaré por pueblo mío, y seré vuestro Dios; y conoceréis que Yo soy Yahvé, vuestro Dios, que os sacaré de la esclavitud de Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Yo os llevaré a la tierra que he jurado dar a Abrahán, a Isaac y a Jacob, y os la daré en heredad. Yo Yahvé.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Habló, pues, Moisés de esta manera a los hijos de Israel; pero ellos no escucharon a Moisés, por cortedad de espíritu, y a causa de la dura servidumbre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Habló entonces Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, '“Ve a hablar con el Faraón, rey de Egipto, para que deje salir a los hijos de Israel fuera de su territorio.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Respondió Moisés en la presencia de Yahvé, y dijo: “Mira, los hijos de Israel no me escuchan; ¿cómo me va a escuchar el Faraón, a mí que soy incircunciso de labios?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Entonces habló Yahvé a Moisés y a Aarón, y les dio órdenes para los hijos de Israel y para el Faraón, rey de Egipto, a fin de sacar del país de Egipto a los hijos de Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Estos son los jefes de sus casas paternas: Hijos de Rubén, primogénito de Israel: Henoc, Falú, Hesrón y Carmí. Estas son las familias de Rubén.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Hijos de Simeón: Jemuel, Jamín, Ohad, Jaquín, Sóhar y Saúl, hijo de la cananea. Estas son las familias de Simeón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Y estos son los nombres de los hijos de Leví por sus linajes: Gersón, Caat y Merarí. Y los años de la vida de Leví fueron ciento treinta y siete años.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Hijos de Gersón: Lobní y Semeí, según sus familias.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Hijos de Caat: Amram, Ishar, Hebrón y Uciel. Los años de la vida de Caat fueron ciento treinta y tres años.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Hijos de Merarí: Mahelí y Musí. Estas son las familias de los levitas, por sus linajes.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Amram tomó por mujer a Jocábed, su tía, de la cual le nacieron Aarón y Moisés. Y los años de la vida de Amram fueron ciento treinta y siete.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Hijos de Ishar: Coré, Néfeg y Sicrí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Hijos de Uciel: Misael, Elsafán y Sitrí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Aarón tomó por mujer a Elisabet, hija de Aminadab, hermana de Naasón; de la cual le nacieron Nadab, Abiú, Eleazar e Itamar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Hijos de Coré: Asir, Elcaná y Abiasaf. Estas son las familias de los coreítas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Eleazar, hijo de Aarón tomó por mujer a una de las hijas de Futiel, y de ella nació Fineés. Estos son los jefes de las casas de los levitas, según sus familias.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Estos, pues, son aquel Aarón y aquel Moisés a quienes dijo Yahvé: “Sacad a los hijos de Israel de la tierra de Egipto, según sus escuadras.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Estos son los que hablaron al Faraón, rey de Egipto, para sacar de Egipto a los hijos de Israel. Estos son Moisés y Aarón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'Y sucedió que en el día en que Yahvé habló a Moisés en el país de Egipto,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'le habló en estos términos: “Yo soy Yahvé; di al Faraón, rey de Egipto, todo lo que Yo te digo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Y Moisés respondió ante Yahvé: “Mira, yo soy incircunciso de labios. ¿Cómo me va a escuchar el Faraón?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Dijo Yahvé a Moisés: “He aquí que te he constituido dios para el Faraón, y Aarón, tu hermano, será tu profeta,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'al cual dirás todo lo que Yo te mandare; y Aarón, tu hermano, se lo dirá al Faraón, a fin de que deje salir de su país a los hijos de Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Yo, entretanto, endureceré el corazón del Faraón, y multiplicaré mis señales y mis prodigios en el país de Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'El Faraón no os escuchará, pero Yo pondré mi mano sobre Egipto, y sacaré de la tierra de Egipto a mi ejército, mi pueblo, los hijos de Israel a fuerza de severos juicios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Y conocerán los egipcios que Yo soy Yahvé, cuando extienda mi mano sobre Egipto y saque de en medio de ellos a los hijos de Israel.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Lo hicieron Moisés y Aarón. Como les había mandado Yahvé, así hicieron.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Tenía Moisés ochenta años, y Aarón ochenta y tres, cuando hablaron al Faraón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Después habló Yahvé a Moisés y a Aarón, y dijo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, '“Cuando el Faraón os dijere: Haced algún milagro en favor vuestro, dirás a Aarón: Toma tu vara y échala delante del Faraón, y se convertirá en serpiente.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Se presentaron Moisés y Aarón al Faraón, e hicieron según la orden de Yahvé: Aarón echó su vara delante del Faraón y delante de sus servidores, la cual se convirtió en serpiente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Mas el Faraón llamó igualmente a los sabios y a los hechiceros, y también ellos, los magos egipcios, hicieron con sus encantamientos las mismas cosas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'Echaron ellos cada cual su vara, y se convirtieron en serpientes; pero la vara de Aarón se tragó las varas de ellos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Sin embargo, se endureció el corazón del Faraón, de manera que no los escuchó, como había dicho Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Entonces dijo Yahvé a Moisés: “El corazón del Faraón es duro; se niega a dejar salir al pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Preséntate, pues, al Faraón por la mañana, cuando salga a las aguas. Tú lo esperarás a la orilla del río, y tomarás en tu mano la vara que se convirtió en serpiente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'Le dirás: ‘Yahvé, el Dios de los hebreos, me ha enviado a ti con esta orden: Deja ir a mi pueblo, a fin de que me den culto en el desierto; y he aquí que no has escuchado hasta ahora.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Por lo tanto, así dice Yahvé: En esto conocerás que Yo soy Yahvé: Mira que voy a golpear con la vara que tengo en la mano las aguas del río, y se convertirán en sangre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'Los peces que hay en el río morirán, el río hederá, y los egipcios tendrán asco de beber las aguas del río’.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Yahvé dijo también a Moisés: “Di a Aarón: Toma tu vara, y extiende tu mano sobre las aguas de Egipto, sobre sus canales, sobre sus ríos, sobre sus lagunas y sobre todos sus depósitos de agua. Y se convertirán en sangre. Habrá sangre en toda la tierra de Egipto, lo mismo en las vasijas de madera que en las de piedra.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Hicieron Moisés y Aarón como les había mandado Yahvé: Levantó (Aarón) la vara y golpeó las aguas en presencia del Faraón y de sus servidores, y se convirtieron todas las aguas del río en sangre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Los peces que había en el río murieron, quedó apestado el río y los egipcios no podían beber las aguas del río; y hubo sangre en todo el país de Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Pero lo mismo hicieron los magos de Egipto con sus encantamientos; por lo cual se endureció el corazón del Faraón y no los escuchó, como había dicho Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Luego se volvió el Faraón y se retiró a su palacio sin hacer caso de estas cosas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Y todos los egipcios cavaron en los alrededores del río para hallar agua potable, porque no podían beber las aguas del río.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'Pasaron siete días después que Yahvé había herido el río, y dijo Yahvé a Moisés: “Preséntate al Faraón y dile: Así dice Yahvé: Deja ir a mi pueblo para que me sirva. Y si rehúsas dejarlo ir, he aquí que voy a castigar todo tu país con ranas. El río bullirá de ranas, que subirán y entrarán en tu casa, en tu alcoba y en tu lecho, en las casas de tus servidores y entre tu pueblo, en tus hornos y en tus artesas. Subirán las ranas sobre ti, y sobre tu pueblo, y sobre tus siervos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Dijo, pues, Yahvé a Moisés: “Di a Aarón: Extiende tu mano con tu vara sobre los canales, sobre los ríos y sobre las lagunas, y haz subir ranas sobre la tierra de Egipto.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Aarón extendió la mano sobre las aguas de Egipto; y subieron las ranas y cubrieron la tierra de Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'Pero los magos hicieron lo mismo con sus encantamientos, haciendo subir las ranas sobre el país egipcio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'El Faraón llamó a Moisés y a Aarón y dijo: “Pedid a Yahvé que aparte las ranas de mí y de mi pueblo, y yo dejaré salir al pueblo para que ofrezca sacrificios a Yahvé.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Respondió Moisés al Faraón: “Dígnate decirme para cuándo he de rogar por ti, por tus siervos y por tu pueblo, a fin de que (Dios) quite las ranas de ti y de tus casas, y queden solamente en el río.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, '“Para mañana”, contestó él. Replicó Moisés: “Será conforme a tu palabra, para que sepas que no hay como Yahvé, nuestro Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Las ranas se apartarán de ti, de tus casas, de tus siervos y de tu pueblo, y quedarán solamente en el río.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Después salieron Moisés y Aarón de la presencia del Faraón; e invocó Moisés a Yahvé a causa de las ranas que afligían al Faraón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'E hizo Yahvé conforme a la súplica de Moisés, de manera que murieron las ranas en las casas, en los patios y en los campos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Las juntaron en montones y el país estaba lleno de hediondez.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Pero el Faraón viendo que se le daba respiro, endureció su corazón, y no los escuchó, como había dicho Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Después dijo Yahvé a Moisés: “Di a Aarón: Extiende tu vara y golpea el polvo de la tierra, y se convertirá en mosquitos en todo el país de Egipto.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'Así lo hicieron: Aarón extendió su mano en que tenía la vara, y golpeó el polvo de la tierra; y hubo mosquitos sobre los hombres y sobre las bestias. Todo el polvo de la tierra se convirtió en mosquitos en todo el país de Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Los magos tentaron de hacer lo mismo con sus encantamientos, a fin de suscitar mosquitos, mas no pudieron. Hubo, pues, mosquitos sobre hombres y bestias.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Dijeron entonces los magos al Faraón: “¡Este es el dedo de Dios!” Pero se endureció el corazón del Faraón, y no los escuchó, como había dicho Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Yahvé dijo a Moisés: “Levántate muy de mañana, y preséntate al Faraón cuando salga hacia las aguas, y le dirás: Así dice Yahvé: Deja ir a mi pueblo, para que me sirva.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Si no dejas ir a mi pueblo, he aquí que voy a enviar tábanos contra ti, contra tus siervos, tu pueblo y tus casas, de manera que se llenarán de tábanos las casas de los egipcios y también el suelo sobre el cual están.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Mas distinguiré en ese día la región de Gosen, donde habita mi pueblo, para que no haya allí tábanos, a fin de que sepas que Yo soy Yahvé en medio de la tierra,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'que hago distinción entre mi pueblo y el tuyo. Mañana será esta señal.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Hizo Yahvé así, y un enjambre de tábanos molestísimos vino sobre la casa del Faraón y las casas de sus siervos; y toda la tierra de Egipto fue devastada por los tábanos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Entonces llamó el Faraón a Moisés y a Aarón y les dijo: “Id, ofreced sacrificios a vuestro Dios en este país.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Moisés respondió: “No conviene hacerlo así, porque lo que hemos de sacrificar a Yahvé, nuestro Dios, es abominación para los egipcios. ¿No nos apedrearían los egipcios si sacrificáramos ante sus ojos lo que para ellos es abominable?');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Iremos tres jornadas de camino por el desierto, y allí ofreceremos sacrificios a Yahvé, nuestro Dios, según Él nos mandare.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Contestó el Faraón: “Os dejaré ir, para que ofrezcáis en el desierto sacrificios a Yahvé vuestro Dios, con tal que no vayáis demasiado lejos. Rogad por mí.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Moisés respondió: “He aquí que voy a salir de tu presencia y rogaré a Yahvé, y mañana los tábanos se alejarán del Faraón, de sus siervos y de su pueblo; pero que no vuelva el Faraón a obrar con engaño, impidiendo al pueblo que vaya a ofrecer sacrificios a Yahvé.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Salió, pues, Moisés de la presencia del Faraón, y rogó a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'E hizo Yahvé conforme a la súplica de Moisés, y quitó los tábanos del Faraón, de sus siervos y de su pueblo, sin que quedase uno solo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Pero el Faraón endureció también esta vez su corazón y no dejó partir al pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, '');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, '');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, '');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, '');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Entonces dijo Yahvé a Moisés: “Preséntate al Faraón y dile: Así dice Yahvé, el Dios de los hebreos: Deja salir a mi pueblo para que me den culto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Si te niegas a dejarlos ir y todavía los retienes,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'he aquí que la mano de Yahvé enviará una peste gravísima sobre tu ganado que está en el campo, sobre los caballos, sobre los asnos, sobre los camellos, sobre las vacadas y sobre las ovejas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Mas Yahvé hará distinción entre el ganado de Israel y el ganado de los egipcios, de modo que no morirá nada de lo perteneciente a Israel.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Y Yahvé fijó el plazo, diciendo: “Mañana hará esto Yahvé en el país.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Y lo hizo Yahvé al día siguiente, de modo que murió todo el ganado de los egipcios; mas del ganado de los hijos de Israel no murió ni una sola cabeza.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'El Faraón envió (a averiguarlo); y he aquí que del ganado de Israel no había muerto ni un solo animal. Sin embargo, se endureció el corazón del Faraón y no dejó ir al pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Dijo entonces Yahvé a Moisés y a Aarón: “Tomad unos puñados de hollín de horno, y espárzalo Moisés hacia el cielo, a los ojos del Faraón;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'y se convertirá en polvo fino en todo el territorio de Egipto, y formará tumores que producirán úlceras, tanto en los hombres como en las bestias, por toda la tierra de Egipto.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Tomaron, pues, hollín de horno, y poniéndose delante del Faraón, lo esparció hacia el cielo; y hubo tumores que producían úlceras, tanto en los hombres como en las bestias.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Ni los magos pudieron mantenerse delante de Moisés a causa de los tumores; pues los magos tenían los mismos tumores que todos los egipcios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Mas Yahvé endureció el corazón del Faraón, de modo que no les escuchó, según Yahvé lo había dicho a Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Luego dijo Yahvé a Moisés: “Levántate muy de mañana, preséntate al Faraón, y dile: ‘Así dice Yahvé, el Dios de los hebreos: Deja ir a mi pueblo, para que me den culto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Porque esta vez voy a enviar todas mis plagas sobre tu corazón, sobre tus siervos y sobre tu pueblo, para que sepas que no hay como Yo en toda la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Si yo hubiera extendido mi mano para herirte a ti y a tu pueblo con peste, ya habrías desaparecido de la tierra;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'pero para esto te he conservado, para mostrarte mi poder, y para que sea celebrado mi nombre en toda la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Tú, empero, te ensalzas todavía contra mi pueblo, para no dejarlo salir.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'He aquí que mañana, a esta hora, haré llover una granizada tan fuerte, que nunca ha habido semejante en Egipto, desde el día que fue fundado hasta el presente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Ahora, pues, envía y pon a salvo tu ganado y cuanto tienes en el campo; porque sobre todos los hombres y animales que se hallan en el campo sin recogerse bajo techumbre, caerá el granizo y perecerán’.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Aquellos de entre los siervos del Faraón que temieron la palabra de Yahvé, recogieron en las casas a sus siervos y a su ganado;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'mas aquellos que no hicieron caso de la palabra de Yahvé, dejaron a sus siervos y a su ganado en el campo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Dijo entonces Yahvé a Moisés: “Extiende tu mano hacia el cielo, y caiga granizo en todo el país de Egipto, sobre los hombres, sobre los animales y sobre todas las plantas que hay en la tierra de Egipto.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Extendió, pues, Moisés su vara hacia el cielo, y Yahvé envió truenos y granizo; el relámpago discurría sobre la tierra, y Yahvé hizo llover granizo sobre el país de Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'El granizo, y el fuego mezclado con el granizo cayeron con fuerza tan extraordinaria, que nunca hubo semejante en toda la tierra de Egipto desde que comenzó a ser pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'El granizo hirió en todo el país de Egipto cuanto había en el campo, desde los hombres hasta las bestias. El granizo destrozó también todas las hierbas del campo, y quebró todos los árboles campestres.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Solamente en la región de Gosen, donde habitaban los hijos de Israel, no hubo granizo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Entonces el Faraón envió a llamar a Moisés y a Aarón y les dijo: “Esta vez he pecado; Yahvé es el justo, y yo y mi pueblo somos los inicuos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Rogad a Yahvé, para que no haya más truenos de Dios y granizo; y os dejaré salir y no os quedaréis más aquí.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Le respondió Moisés: “Cuando salga de la ciudad extenderé mis manos hacia Yahvé, y cesarán los truenos, y no habrá más granizo, para que sepas que la tierra es de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Mas ya sé que ni tu ni tus siervos teméis todavía a Yahvé, Dios.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Habían sido destrozados ya el lino y la cebada, pues la cebada estaba ya en espiga, y el lino en caña.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'Mas el trigo y la espiga no fueron destrozados, por ser tardíos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Dejó, pues, Moisés al Faraón y saliendo de la ciudad extendió las manos hacia Yahvé, con lo cual cesaron los truenos y el granizo, y no cayó más lluvia sobre la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Pero en cuanto el Faraón vio que había cesado la lluvia y el granizo y los truenos, volvió a pecar, endureciendo su corazón, tanto él como sus siervos,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'se endureció, pues, el corazón del Faraón, y no dejó ir a los hijos de Israel como Yahvé había dicho por boca de Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Después dijo Yahvé a Moisés: “Ve al Faraón, porque Yo he endurecido su corazón y el corazón de sus siervos, para obrar estos mis prodigios en medio de ellos;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'y para que puedas contar a tu hijo, y al hijo de tu hijo, las grandes cosas que Yo hice en Egipto, y los prodigios que obré en él, a fin de que sepáis que Yo soy Yahvé.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Fueron, pues, Moisés y Aarón al Faraón y le dijeron: “Así dice Yahvé, el Dios de los hebreos: ¿Hasta cuándo te negarás a humillarte ante Mí? Deja salir a mi pueblo, para que me sirva.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Si sigues resistiendo y no dejas salir a mi pueblo, he aquí que mañana traeré sobre tu país langostas;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'las cuales cubrirán la superficie del país, de manera que no podrá verse el suelo. Comerán el resto que se salvó, lo que os dejó el granizo; y comerán también todos los árboles que os crecen en el campo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'Llenarán tus casas, y las casas de todos tus siervos, y las casas de todos los egipcios, lo que nunca vieron tus padres, ni los padres de tus padres, desde el día en que viven sobre la tierra hasta el día de hoy.” Con esto se retiró, y salió de la presencia del Faraón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Dijeron entonces al Faraón sus siervos: “¿Hasta cuándo ha de sernos este hombre un lazo? Deja salir a esa gente a fin de que sirvan a Yahvé, su Dios. ¿No sabes aún que Egipto está al borde de la ruina?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Llamaron, pues, de nuevo a Moisés y a Aarón a la presencia del Faraón; el cual les dijo: “Id, servid a Yahvé, vuestro Dios. ¿Quiénes son los que han de ir?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Respondió Moisés: “Saldremos con nuestros jóvenes y nuestros ancianos, con nuestros hijos y nuestras hijas, con nuestras ovejas y nuestras vacadas; porque hemos de celebrar una fiesta en honor de Yahvé.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Les contestó: “¡Así sea Yahvé con vosotros, como yo os dejo salir a vosotros y a vuestros hijos! Pero tened cuidado, pues seguramente procedéis con mala intención.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Por eso, no será así; salid los varones solos y servid a Yahvé, ya que esta fue vuestra petición.” Con esto fueron echados de la presencia del Faraón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Entonces dijo Yahvé a Moisés: “Extiende tu mano sobre la tierra de Egipto para que venga la langosta; suba ella sobre el país de Egipto, y coma toda la hierba del país, todo lo que dejó el granizo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Extendió, pues, Moisés su vara sobre la tierra de Egipto; y Yahvé hizo soplar el viento solano sobre el país, todo aquel día y toda la noche. Y cuando vino la mañana, el viento de oriente había traído las langostas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Y subieron las langostas sobre todo el país de Egipto, y se posaron en todo el territorio egipcio, en cantidad tan grande, como nunca hubo anteriormente ni habrá después.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Cubrieron toda la superficie del país, de modo que se oscureció la tierra; comieron toda la hierba del país, y todos los frutos de los árboles que el granizo había dejado, y no quedó nada verde ni en los árboles ni en las hierbas del campo en todo el territorio de Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Entonces el Faraón llamó a toda prisa a Moisés y a Aarón, y dijo: “He pecado contra Yahvé, vuestro Dios, y contra vosotros.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Perdonad, por favor, mi pecado todavía esta única vez; rogad a Yahvé, vuestro Dios, que aparte de mí al menos esta muerte.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Salió (Moisés) de la presencia del Faraón y rogó a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'Y Yahvé hizo soplar un viento de occidente muy recio que se llevó las langostas y las echó al Mar Rojo. No quedó ni una langosta en todo el territorio de Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Pero Yahvé endureció el corazón del Faraón, el cual no dejó ir a los hijos de Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Después dijo Yahvé a Moisés: “Extiende tu mano hacia el cielo, para que haya sobre la tierra de Egipto tinieblas que puedan palparse.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Extendió, pues, Moisés su mano hacia el cielo, y hubo densas tinieblas en toda la tierra de Egipto durante tres días.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'No se veían unos a otros, ni se levantaba nadie de su sitio por espacio de tres días, en tanto que los hijos de Israel tenían luz en sus moradas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Entonces llamó el Faraón a Moisés, y dijo: “Id y servid a Yahvé; queden solamente vuestras ovejas y vuestras vacadas. Aun vuestros niños podrán ir con vosotros.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Respondió Moisés: “Nos has de conceder también sacrificios y holocaustos, para que los ofrezcamos a Yahvé, nuestro Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'Por lo cual también nuestro ganado ha de ir con nosotros. No quedará ni una pezuña; porque de ellos hemos de tomar para dar culto a Yahvé, nuestro Dios; y no sabemos todavía qué hemos de ofrecer a Yahvé, hasta que lleguemos allá.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Mas Yahvé endureció el corazón del Faraón, el cual no quiso dejarles salir.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Dijo, pues, el Faraón: “¡Retírate de mí! ¡Guárdate de volver a ver mi rostro!, pues el día en que vieres mi rostro, morirás.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'A lo cual respondió Moisés: “Tú lo has dicho: no volveré a ver tu rostro.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Dijo Yahvé a Moisés: “Solo una plaga más haré venir sobre el Faraón y sobre los egipcios; después de la cual os dejará marchar de aquí; y cuando, por fin, os deje salir, lo hará expulsándoos por completo de aquí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Di, pues, al pueblo que cada hombre pida a su vecino, y cada mujer a su vecina, objetos de plata y objetos de oro.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Pues Yahvé había hecho que el pueblo hallase gracia a los ojos de los egipcios. Además, Moisés era una persona muy grande en la tierra de Egipto, tanto a los ojos de los siervos del Faraón como a los ojos del pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Dijo entonces Moisés: “Así dice Yahvé: A medianoche pasaré Yo a través de Egipto;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'y morirá en el país de Egipto todo primogénito, desde el primogénito del Faraón que se sienta en su trono, hasta el primogénito de la esclava que está detrás de la muela, y todo primogénito del ganado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Y se alzará en todo el país de Egipto un alarido grande cual nunca ha habido, y nunca lo habrá.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Pero contra ninguno de los hijos de Israel, contra ningún hombre y ninguna bestia, ni siquiera ladrará un perro; para que sepáis qué distinción hace Yahvé entre los egipcios e Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Entonces vendrán a mí todos estos tus siervos, y se postrarán delante de mí, diciendo: Sal tú y todo el pueblo que te sigue. Y después de esto saldré.” Y encendido en cólera se retiró de la presencia del Faraón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Y dijo Yahvé a Moisés: “No os escuchará el Faraón, para que se multipliquen mis prodigios en la tierra de Egipto.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Moisés y Aarón obraron todos estos prodigios delante del Faraón; pero Yahvé endureció el corazón del Faraón, el cual no dejó salir de su país a los hijos de Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Dijo Yahvé a Moisés y a Aarón en el país de Egipto:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, '“Este mes será para vosotros el comienzo de los meses; os será el primero de los meses del año.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Hablad a toda la asamblea de Israel y decid: El día diez de este mes tome cada uno para sí un cordero por familia, un cordero por casa.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Y si la casa no alcanzare para un cordero, lo tomará junto con el vecino más cercano a su casa, según el número de las personas. Calculad la porción que cada uno puede comer del cordero.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'El cordero será sin defecto, macho y primal. De las ovejas o de las cabras lo tomaréis.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Lo guardaréis hasta el día catorce de este mes; y toda la multitud de los hijos de Israel lo inmolará entre las dos tardes.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Luego tomarán de la sangre y rociarán los dos postes (de la puerta) y el dintel de las casas en que han de comer.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Comerán la carne en aquella misma noche. La comerán asada al fuego, con panes ácimos y con hierbas amargas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'No comeréis nada de él crudo, ni cocido en agua, sino asado al fuego, con su cabeza, sus piernas y sus entrañas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Y no dejaréis nada de él para el día siguiente; lo que sobrare de él hasta la mañana, lo quemaréis al fuego.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Lo habéis de comer de la siguiente manera: Ceñidos vuestros lomos, calzados vuestros pies, y el bastón en vuestra mano; y lo comeréis de prisa, pues es la Pascua de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Porque Yo pasaré esta noche por la tierra de Egipto y quitaré la vida a todos los primogénitos en el territorio de Egipto, desde los hombres hasta las bestias, y ejecutaré mis juicios en todos los dioses de Egipto, Yo, Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Será, pues, vuestro distintivo la sangre en las casas de vuestra morada. Viendo la sangre pasaré de largo por vosotros, y no habrá entre vosotros plaga exterminadora cuando Yo hiera el país de Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Os será memorable este día, y lo celebraréis como fiesta en honor de Yahvé durante vuestras generaciones. La celebraréis como institución perpetua.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Por siete días comeréis panes ácimos, por lo cual desde el primer día apartaréis de vuestras casas la levadura. Todo el que desde el día primero hasta el día séptimo comiere pan fermentado será exterminado de en medio de Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'El primer día tendréis asamblea santa; asimismo el día séptimo os reuniréis en asamblea santa. Ninguna obra se haga en esos días, exceptuando la comida para cada uno. Esto es lo único que podréis hacer.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Guardad (la fiesta de) los Ácimos, porque en ese mismo día habré sacado Yo vuestros ejércitos de la tierra de Egipto. Observad este día durante vuestras generaciones como institución perpetua.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'Comeréis, pues, panes ácimos en el mes primero desde el día catorce del mes por la tarde, hasta la tarde del día veintiuno del mes.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'No se halle levadura en vuestras casas por espacio de siete días, pues todo aquel que comiere cosa fermentada, sea extranjero o natural del país, será exterminado de en medio del pueblo de Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'No comeréis cosa fermentada alguna; en todas vuestras habitaciones comed panes ácimos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Entonces llamó Moisés a todos los ancianos de Israel y les dijo: “Buscad y tomaos corderos para vuestras familias, e inmolad la pascua.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Luego tomad un manojo de hisopo, mojadlo en la sangre que está en el tazón, y rociad el dintel y los dos postes con la sangre del tazón; y nadie de vosotros salga de la puerta de su casa hasta la mañana.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Pues pasará Yahvé y herirá a los egipcios, mas al ver la sangre en el dintel y en los dos postes, Yahvé pasará de largo por aquella puerta, y no permitirá que el exterminador entre en vuestras casas para herir.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Guardad este mandato como ley perpetua para vosotros y vuestros hijos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Observad este rito también después de vuestra llegada a la tierra que os dará Yahvé según su promesa.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Y cuando os preguntaren vuestros hijos: ¿Qué significado tiene para vosotros este rito?,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'responderéis: Este es el sacrificio de la Pascua de Yahvé, quien pasó de largo por las casas de los hijos de Israel en Egipto cuando hirió a los egipcios y salvó nuestras casas. Entonces el pueblo se prosternó para adorar,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'fueron, pues, los hijos de Israel e hicieron así como había mandado Yahvé a Moisés y a Aarón; así lo hicieron.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Y sucedió que a media noche Yahvé hirió en el país de Egipto a todos los primogénitos, desde el primogénito del Faraón que se sienta sobre su trono, hasta el primogénito del preso en la cárcel, y a todos los primogénitos de las bestias.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Con lo que se levantó el Faraón de noche, él y todos sus siervos y todos los egipcios; y hubo grande alarido en Egipto, porque no había casa donde no hubiese un muerto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Y llamó a Moisés y a Aarón de noche y dijo: “¡Adelante!, salid de en medio de mi pueblo, vosotros y los hijos de Israel. Id y ofreced sacrificios a Yahvé como habéis dicho.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Tomad también vuestras ovejas y vuestras vacadas, como dijisteis. Marchaos y bendecidme también a mí.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Los egipcios por su parte instaban al pueblo para acelerar su salida del país; pues decían: “Pereceremos todos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Tomó, pues, el pueblo la harina amasada, antes que fermentara y envueltas sus artesas en la ropa se las echaron a cuestas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Y los hijos de Israel hicieron según la palabra de Moisés, pidiendo a los egipcios objetos de plata y objetos de oro y vestidos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Pues Yahvé había hecho que el pueblo hallara gracia a los ojos de los egipcios, los cuales accedieron a sus pedidos. Así despojaron a los egipcios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Partieron, pues, los hijos de Israel de Ramesés para Sucot, unos seiscientos mil hombres de a pie, sin contar los niños.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Salió con ellos también mucha gente de toda clase, y ganado menor y mayor, muchísimos animales.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'De la masa que habían sacado de Egipto, cocieron tortas ácimas; porque (la masa) no había aún fermentado; pues habían sido echados de Egipto a toda prisa y sin que pudieran prepararse provisiones.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'El tiempo que los hijos de Israel habían habitado en Egipto, fue de cuatrocientos treinta años.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Al fin de los cuatrocientos treinta años, en ese mismo día, salieron de la tierra de Egipto todas las escuadras de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Noche de vela fue esta para Yahvé cuando los sacó de la tierra de Egipto. Esa misma noche será noche de vela en honor de Yahvé para todos los hijos de Israel de generación en generación.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Dijo Yahvé a Moisés y a Aarón: “Esta es la ley de la Pascua: No coma de ella ningún extranjero.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Todo siervo, comprado por dinero, después de haber sido circuncidado, comerá de ella.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Mas el advenedizo y el jornalero no comerán de ella,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'En una misma casa se ha de comer; no sacaréis fuera de la casa nada de la carne, ni le quebraréis ningún hueso.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'La celebrará todo el pueblo de Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Si un extranjero habita contigo y quiere celebrar la Pascua en honor de Yahvé, sean circuncidados todos sus varones, y entonces podrá acercarse para celebrarla; y será como el indígena, porque ningún incircunciso comerá de ella.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Una misma ley habrá para el indígena y para el extranjero que habita en medio de vosotros.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Así lo hicieron todos los hijos de Israel. Según había mandado Yahvé a Moisés y a Aarón, así lo hicieron.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'Y en aquel mismo día Yahvé sacó del país de Egipto a los hijos de Israel (repartidos) en sus escuadras.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, '“Conságrame todo primogénito. Mío es todo primer nacido entre los hijos de Israel, tanto de hombres como de animales.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Dijo pues Moisés al pueblo: “Acordaos de este día en que salisteis de Egipto, de la casa de la servidumbre; pues Yahvé os ha sacado de aquí con mano poderosa; y no comáis pan fermentado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Salís hoy, en el mes de Abib.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Así, pues, cuando Yahvé te haya introducido en la tierra del cananeo, del heteo, del amorreo, del heveo y del jebuseo, que juró a tus padres darte, tierra que mana leche y miel, celebrarás ese rito en este mes.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Siete días comerás panes ácimos y el día séptimo será fiesta en honor de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Se comerán panes ácimos durante siete días, y no se verá pan fermentado en tu casa, ni levadura en todo tu territorio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'En aquel día dirás a tu hijo: “Esto es a causa de lo que hizo conmigo Yahvé cuando salí de Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Y esto te será como una señal en tu mano, y como un recuerdo entre tus ojos, para que la ley de Yahvé se halle en tu boca; porque con mano poderosa te sacó Yahvé de Egipto.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Guardarás este precepto, año por año, en el tiempo señalado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'Cuando Yahvé te haya introducido en la tierra del cananeo, como lo tiene jurado a ti y a tus padres, y te la haya dado,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'apartarás para Yahvé a todos los primogénitos. También todos los primerizos de tus animales, si son machos, pertenecen a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Todo primerizo del asno lo rescatarás con un cordero; y si no lo rescatas, has de quebrarle la cerviz. Rescatarás también todo primogénito humano de entre tus hijos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Y cuando el día de mañana te preguntare tu hijo, diciendo: “¿Qué significa esto?”, le dirás: “Con mano poderosa nos sacó Yahvé de Egipto, de la casa de la servidumbre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Al obstinarse el Faraón en no dejarnos salir, Yahvé mató a todos los primogénitos en el país de Egipto, desde el primogénito del hombre hasta el primogénito de la bestia. Por eso sacrifico a Yahvé todo primer nacido macho, y rescato todo primogénito de mis hijos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Esto será como una señal en tu mano, y como frontal entre tus ojos; porque con mano poderosa Yahvé nos ha sacado de Egipto.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Cuando el Faraón dejó salir al pueblo, Dios no los condujo por el camino de la tierra de los filisteos, aunque estaba cerca; pues dijo Dios: “No sea que al verse atacado se arrepienta el pueblo y se vuelva a Egipto.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Dios hizo, pues, rodear al pueblo por el camino del desierto hacia el Mar Rojo. Y los hijos de Israel salieron en buen orden del país de Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Moisés llevó también consigo los huesos de José, pues este había hecho jurar a los hijos de Israel, diciendo: “Cuando os visitare Dios, llevad de aquí con vosotros mis huesos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Partieron de Sucot y acamparon en Etam, al borde del desierto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'E iba Yahvé al frente de ellos, de día en una columna de nube para guiarlos en el camino, y de noche en una columna de fuego para alumbrarlos, a fin de que pudiesen marchar de día y de noche.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'La columna de nube no se retiraba del pueblo de día, ni la columna de fuego de noche.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, '“Di a los hijos de Israel que se vuelvan y acampen frente a Fihahirot, entre Migdol y el mar, enfrente de Baalsefón. Delante de ese lugar acamparéis, junto al mar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Porque el Faraón dirá respecto de los hijos de Israel: ‘Andan errantes en el país, y el desierto los tiene encerrados.’');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Y Yo endureceré el corazón del Faraón, y os perseguirá; pero Yo manifestaré mi gloria en el Faraón y en todo su ejército, y sabrán los egipcios que Yo soy Yahvé.” Así lo hicieron.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Efectivamente, cuando fue dado aviso al rey de Egipto que había huido el pueblo, se mudó el corazón del Faraón y de sus siervos respecto del pueblo, y dijeron: “¿Qué es lo que hemos hecho dejando ir a Israel, privándonos así de su servicio?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Hizo, entonces, enganchar sus carros y llevó consigo a su pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Tomó seiscientos carros escogidos y todos los carros de Egipto, con capitanes para todos ellos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Así endureció Yahvé el corazón del Faraón, rey de Egipto, el cual persiguió a los hijos de Israel; pero los hijos de Israel salieron (guiados) por una mano elevada.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Los persiguieron, pues, los egipcios, todos los caballos de los carros del Faraón, y su gente de a caballo y su ejército; y les dieron alcance mientras acampaban junto al mar, cerca de Fihahirot, frente a Baalsefón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Cuando el Faraón se iba acercando, los hijos de Israel alzaron sus ojos, y he aquí que los egipcios marcharon en pos de ellos. Con lo que se amedrentaron mucho los hijos de Israel y clamaron a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'Y dijeron a Moisés: “¿Acaso no había sepulturas en Egipto para que nos hayas traído a morir en el desierto? ¿Qué has hecho con nosotros sacándonos de Egipto?');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, '¿No te decíamos en Egipto: Déjanos que sirvamos a los egipcios? Porque mejor nos sería servir a los egipcios que morir en el desierto.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Contestó Moisés al pueblo: “No temáis; estad firmes, y veréis el auxilio que Yahvé os otorgará en este día, pues los egipcios que hoy veis, no los volveréis a ver nunca jamás.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Yahvé peleará por vosotros, y vosotros quedaos tranquilos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Y dijo Yahvé a Moisés “¿Por qué sigues clamando a mí? Manda a los hijos de Israel que se pongan en marcha.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Y tú alza tu vara, y extiende tu mano sobre el mar y divídelo, para que los hijos de Israel entren en medio del mar a pie enjuto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Yo, entretanto, endureceré el corazón de los egipcios para que entren tras ellos, y se manifestará mi gloria en el Faraón y en todo su ejército, en sus carros y en su caballería.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'Y conocerán los egipcios que Yo soy Yahvé, cuando haya manifestado mi gloria en el Faraón, en sus carros y en su caballería.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Se levantó entonces el Ángel de Yahvé que marchaba al frente del ejército de Israel, y se puso detrás de ellos. Se levantó también la columna de nube de delante de ellos, y se colocó a la espalda,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'intercalándose así entre el campamento de los egipcios y el campamento de los israelitas. Era nube y tinieblas (por una parte), y (por la otra) iluminaba la noche, de modo que no pudieron acercarse aquellos a estos en toda la noche.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Extendió Moisés su mano sobre el mar, y Yahvé hizo soplar un viento del Oriente muy fuerte durante toda la noche, el cual hizo retroceder el mar y lo dejó seco, y se dividieron las aguas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Entonces los hijos de Israel entraron en medio del mar a pie enjuto, formando para ellos las aguas una muralla a su derecha y a su izquierda.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Los egipcios los persiguieron y entraron en pos de ellos, todos los caballos del Faraón, sus carros y su caballería, hasta el medio del mar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Llegada la vigilia de la mañana, echó Yahvé una mirada desde la columna de fuego y de humo hacia el ejército de los egipcios, y puso en consternación al ejército egipcio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'Quitó las ruedas de sus carros, de suerte que no podían avanzar sino con gran dificultad. Dijeron por tanto los egipcios: “Huyamos delante de Israel, porque Yahvé pelea por ellos contra los egipcios.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Entonces dijo Yahvé a Moisés: “Extiende tu mano sobre el mar, para que las aguas vuelvan sobre los egipcios, sobre sus carros y sobre su caballería.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Extendió Moisés su mano sobre el mar, y al rayar el alba el mar volvió a su sitio; de modo que los egipcios queriendo huir se vieron frente a las (aguas). Así arrojó Yahvé a los egipcios en medio del mar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Pues reuniéndose las aguas cubrieron los carros y la gente de a caballo y todo el ejército del Faraón, que había entrado en el mar para seguirlos, y no escapó ni siquiera uno de ellos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Mas los hijos de Israel pasaron a pie enjuto por en medio del mar, teniendo las aguas por muralla a su derecha y a su izquierda.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'Aquel día salvó Yahvé a Israel de mano de los egipcios; y vio Israel a los egipcios muertos a orillas del mar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Y cuando Israel vio la mano poderosa que Yahvé había extendido contra los egipcios, temió el pueblo a Yahvé, y creyeron en Yahvé y en Moisés, su siervo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Entonces Moisés y los hijos de Israel cantaron este cántico a Yahvé. Dijeron así: “Cantaré a Yahvé por su altísima gloria; arrojó al mar al caballo y a su jinete.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Yahvé es mi fortaleza y (el objeto) de mi canción. Él me ha salvado; Él es mi Dios, a quien celebraré, el Dios de mi padre, a quien he de ensalzar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'El Señor es un guerrero poderoso; Yahvé es su nombre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Ha precipitado en el mar los carros del Faraón y su ejército; la flor de sus capitanes se hundió en el Mar Rojo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Los cubrió el abismo; como una piedra cayeron al fondo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Tu diestra, Yahvé, es admirable por su poder; tu diestra, Yahvé, aplasta al enemigo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'En tu grandeza sin medida derribas a los que contra Ti se levantan, desencadenas tu ira que los consume como hojarasca.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Soplaron tus narices y se apiñaron las aguas; se pararon las olas como un dique, los abismos se cuajaron en medio del mar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Perseguiré, alcanzaré, había dicho el enemigo; repartiré despojos, se saciará mi alma; desenvainaré mi espada, los destruirá mi mano.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Pero con tu viento soplaste y los cubrió el mar; se hundieron como plomo en las temibles aguas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, '¿Quién como Tú, Yahvé, entre los dioses? ¿Quién, como Tú, glorioso en santidad, terrible en prodigios, hacedor de maravillas?');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Extendiste tu diestra, y los engulló la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Guiaste en tu misericordia al pueblo por Ti redimido; con tu poder lo condujiste a la morada de tu santidad.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Lo oyeron los pueblos temblando; se amedrentó la gente de Filistea;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'los príncipes de Edom se estremecieron; temblaron los valientes de Moab y trepidaron todos los moradores de Canaán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Cayó sobre ellos pavor y espanto; por la grandeza de tu brazo enmudecieron como una piedra, hasta que pasó tu pueblo, Yahvé, hasta que pasó el pueblo que Tú adquiriste.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Tú los condujiste y los plantaste en el monte de tu herencia; en el lugar que Tú, oh Yahvé, preparaste para tu sede; en el Santuario, Señor, que fundaron tus manos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Yahvé reinará por siempre jamás.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Porque cuando los caballos del Faraón y sus carros y su caballería entraron en el mar, Yahvé hizo volver sobre ellos las aguas marinas, en tanto que los hijos de Israel pasaron a pie enjuto por medio del mar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'También María, la profetisa, hermana de Aarón, tomó en su mano un tamboril, y todas las mujeres salieron en pos de ella, con tamboriles y danzando.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Y María les repetía: “Cantad a Yahvé por su altísima gloria; arrojó al mar al caballo y a su jinete.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Moisés hizo partir a los hijos de Israel del Mar Rojo, y se dirigieron hacia el desierto de Sur, donde caminaron tres días en el desierto sin encontrar agua.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Luego llegaron a Mará, mas no pudieron beber el agua, por ser amarga. Por eso llamaron (a ese lugar) Mará.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Y murmuró el pueblo contra Moisés, diciendo: “¿Qué vamos a beber?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Entonces clamó Moisés a Yahvé, y Yahvé le mostró un madero que Moisés echó en el agua, y el agua se volvió dulce. Allí Yahvé le dio (a Israel) leyes y estatutos, y allí lo probó,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'y dijo: “Si de veras escuchas la voz de Yahvé, tu Dios, y haces lo que es recto a sus ojos, dando oídos a sus mandamientos y guardando todos sus preceptos, no traeré sobre ti ninguna de las plagas que envié sobre los egipcios; porque Yo soy Yahvé, el que te sana.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Después llegaron a Elim, donde había doce fuentes de agua y setenta palmeras, y acamparon allí junto a las aguas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Habiendo partido de Elim llegó todo el pueblo de los hijos de Israel al desierto de Sin, que está entre Elim y el Sinaí, el día quince del segundo mes después de su salida del país de Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Y murmuró todo el pueblo de los hijos de Israel contra Moisés y Aarón en el desierto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'Les decían los hijos de Israel: “¡Ojalá hubiéramos muerto a manos de Yahvé en la tierra de Egipto, cuando nos sentábamos junto a las ollas de carne, cuando comíamos pan en abundancia! Vosotros nos habéis sacado a este desierto para matar de hambre a todo este pueblo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Dijo entonces Yahvé a Moisés: “Mira, Yo haré llover sobre vosotros pan del cielo; y saldrá el pueblo a recoger cada día la porción diaria; de esta manera lo pongo a prueba si quiere andar o no según mi ley.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Mas al día sexto han de conservar lo que hayan traído, porque será el doble de lo que acostumbran recoger cada día.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Dijeron, pues, Moisés y Aarón a todos los hijos de Israel: “Esta tarde conoceréis que Yahvé es quien os ha sacado del país de Egipto;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'y a la mañana veréis la gloria de Yahvé, ya que ha oído vuestras murmuraciones que se dirigen contra Él; porque nosotros ¿qué somos para que murmuréis contra nosotros?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Y añadió Moisés: “Esto será al daros Yahvé esta tarde carne para comer, y a la mañana pan en abundancia; pues Yahvé ha oído vuestras murmuraciones con que murmuráis contra Él; pues ¿qué somos nosotros? No van contra nosotros vuestras murmuraciones, sino contra Yahvé.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Dijo entonces Moisés a Aarón: “Di a todo el pueblo de los hijos de Israel: Acercaos a Yahvé, porque Él ha oído vuestras murmuraciones.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Aún estaba hablando Aarón a todo pueblo de los hijos de Israel, cuando ellos volvieron la cara hacia el desierto, y he aquí que la gloria de Yahvé se apareció en la nube.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Y habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, '“He oído las murmuraciones de los hijos de Israel. Diles: Entre las dos tardes comeréis carne y por la mañana os hartaréis de pan; y conoceréis que Yo soy Yahvé, vuestro Dios.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Y sucedió que a la tarde vinieron codornices que cubrieron el campamento; y a la mañana había una capa de rocío alrededor del campamento.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Y al evaporarse la capa de rocío se vio en la superficie del desierto una cosa menuda y granosa, tan menuda como la escarcha sobre la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Cuando la vieron los hijos de Israel, se decían unos a otros: “¿Qué es esto?” Pues no sabían lo que era. Les dijo Moisés: “Este es el pan que Yahvé os da por alimento.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Esta es la orden prescrita por Yahvé: “Recoged de ello cada uno cuanto necesite para comer, un gomor por cabeza, conforme al número de vuestras personas; cada uno recogerá para la gente que tenga en su tienda.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Lo hicieron así los hijos de Israel, y recogieron unos más, otros menos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Mas cuando lo midieron con el gomor (encontraron que) quien había recogido mucho, nada tenía de mas, y quien había recogido poco, nada tenía de menos. Cada uno había recogido según lo que podía comer.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Les dijo también Moisés: “Nadie deje nada de ello hasta el día siguiente.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Pero no obedecieron a Moisés, sino que algunos dejaron sobras para el día siguiente, y se produjeron gusanos y hediondez, por lo cual Moisés se airó contra ellos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Lo recogían pues todas las mañanas, cada uno según lo que necesitaba para comer; mas cuando se dejaba sentir el calor del sol se derretía.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'El día sexto recogieron doble porción de alimento, dos gomor para cada persona. Y fueron todos los príncipes del pueblo a decírselo a Moisés;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'el cual les respondió: “Esto es lo que ha mandado Yahvé: Mañana es sábado, día de reposo, consagrado a Yahvé. Coced lo que hayáis de cocer, y lo que hayáis de hervir, hervidlo; y todo lo que sobre guardadlo como reserva para el día siguiente.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Y ellos lo guardaron para el día siguiente, según la orden de Moisés; y no hedió, ni se halló en él gusano alguno.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Dijo entonces Moisés: “Comedlo hoy, porque hoy es sábado en honor de Yahvé; hoy no lo hallaréis en el campo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Seis días lo recogeréis, mas al séptimo día que es sábado, no habrá nada”.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'A pesar de todo al séptimo día salieron algunos del pueblo a recogerlo pero no encontraron nada.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Dijo entonces Yahvé a Moisés: “¿Hasta cuándo rehusaréis guardar mis mandamientos y mis leyes?');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'He aquí que Yahvé os ha dado el sábado; por eso en el día sexto os da pan para dos días. Quédese cada hombre en su sitio; no salga nadie el día séptimo de su lugar”.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Y descansó el pueblo el día séptimo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'La casa de Israel dio a ese alimento el nombre de maná. Era como granos de cilantro, blanco, y su sabor como de torta de miel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Y dijo Moisés: “Esto es lo que manda Yahvé: Llenad de maná un gomor, a fin de que se guarde para vuestros descendientes y vean ellos el pan con que os he alimentado en el desierto cuando os saqué del país de Egipto.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Dijo, pues, Moisés a Aarón: “Toma una vasija y pon en ella un gomor completo de maná, y colócalo delante de Yahvé, a fin de guardarlo para vuestros descendientes”.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Y de acuerdo con lo que Yahvé había mandado a Moisés, puso Aarón el (maná) ante el Testimonio para guardarlo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Los hijos de Israel comieron el maná cuarenta años, hasta que llegaron a tierra habitada. Comieron el maná hasta llegar a los confines del país de Canaán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'El gomor es la décima parte del efa.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Partió todo el pueblo de los hijos de Israel del desierto de Sin, haciendo sus jornadas según ordenaba Yahvé; y acamparon en Rafidim, donde el pueblo no tenía agua que beber.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Por lo cual el pueblo se querelló contra Moisés, diciendo: “Danos agua de beber.” Les respondió Moisés: “¿Por qué altercáis conmigo? ¿Por qué tentáis a Yahvé?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Pero el pueblo sufriendo allí sed de agua, siguió murmurando contra Moisés, y dijo: “¿Por qué nos has hecho salir de Egipto, para matarnos de sed, a nosotros, a nuestros hijos y a nuestro ganado?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Clamó entonces Moisés, a Yahvé y dijo: “¿Qué hago yo con este pueblo? Falta poco que me apedreen.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Respondió Yahvé a Moisés: “Pasa delante del pueblo, y lleva contigo algunos de los ancianos de Israel; y toma en tu mano la vara con que heriste el río y anda.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'He aquí que Yo estaré enfrente de ti, allá sobre la peña, en Horeb; golpearás la peña, y saldrá de ella agua para que beba el pueblo.” Moisés lo hizo así a los ojos de los ancianos de Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Y dio a aquel lugar el nombre de Masá y Meribá, a causa de la querella de los hijos de Israel, y por haber ellos tentado a Yahvé, diciendo: “¿Está Yahvé en medio de nosotros, o no?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Vino después Amalec e hizo guerra contra Israel en Rafidim.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Y dijo Moisés a Josué: “Escógenos hombres, y sal a combatir contra Amalec. Mañana yo me colocaré sobre la cima del monte, con la vara de Dios en mi mano.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Hizo Josué como le había dicho Moisés, y peleó contra Amalec. Moisés, empero, y Aarón y Hur subieron a la cima del monte.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Y sucedió que mientras Moisés tenía alzada su mano, prevalecía Israel; y cuando bajaba su mano, prevalecía Amalec.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Mas como las manos de Moisés se cansasen, tomaron ellos una piedra, se la pusieron debajo, y se sentó sobre ella, en tanto que Aarón y Hur le sostenían las manos, uno por un lado, y otro por el otro. Así quedaron firmes sus manos hasta ponerse el sol.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Y Josué derrotó a Amalec y a su pueblo al filo de la espada.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Entonces dijo Yahvé a Moisés: “Escribe esto para recuerdo en un libro, y notifica a Josué que Yo borraré por completo la memoria de Amalec de debajo del cielo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Después erigió Moisés un altar, al cual puso por nombre Yahvé Nisí,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'diciendo: “Por haber levantado la mano contra el trono de Yahvé, peleará Yahvé con Amalec de generación en generación.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Jetró, sacerdote de Madián, suegro de Moisés, supo todo lo que había hecho Dios en favor de Moisés e Israel, su pueblo: que Yahvé había sacado a Israel de Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'Y tomó Jetró, suegro de Moisés, a Seforá, mujer de Moisés, después de haberla (Moisés) despedido;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'y a los dos hijos de este, de los cuales uno se llamaba Gersom, pues había dicho (Moisés): “Soy un extranjero en tierra extraña.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'El otro se llamaba Eliéser, porque (Moisés) había dicho: “El Dios de mi padre fue mi protector y me ha librado de la espada del Faraón.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Vino, pues, Jetró, suegro de Moisés, con los hijos y la mujer de este, al desierto, donde acampaba junto al monte de Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'Y envió a decir a Moisés: “Yo, Jetró, tu suegro, vengo a ti con tu mujer, y con ella están sus dos hijos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Moisés salió al encuentro de su suegro, se prosternó y le besó. Y después de preguntarse mutuamente por su salud entraron en la tienda.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Luego contó Moisés a su suegro todo lo que Yahvé había hecho al Faraón y a los egipcios, en favor de Israel; y todos los trabajos sufridos en el camino y cómo Yahvé los había librado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Jetró se alegró de todo el bien que Yahvé había hecho a Israel, librándolo de la mano de los egipcios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Y dijo Jetró: “¡Bendito sea Yahvé que os ha librado de la mano de los egipcios y de la mano del Faraón y ha salvado al pueblo del poder de los egipcios!');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Ahora acabo de conocer que Yahvé es más grande que todos los dioses; pues en aquello mismo en que ellos se ensoberbecieron los ha castigado.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Después tomó Jetró, suegro de Moisés, un holocausto y sacrificios para (ofrecerlos) a Dios; y Aarón y todos los ancianos de Israel fueron a comer con el suegro de Moisés en presencia de Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Al día siguiente se sentó Moisés para juzgar al pueblo; y el pueblo estaba delante de Moisés desde la mañana hasta la tarde.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Vio el suegro de Moisés todo lo que hacía para con el pueblo, y dijo: “¿Qué es esto que haces con el pueblo? ¿Por qué te sientas tú solo, y todo el pueblo permanece parado alrededor tuyo desde la mañana hasta la tarde?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Contestó Moisés a su suegro: “Porque el pueblo viene a mí para consultar a Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Cuando tienen un pleito, vienen a mí; y yo juzgo entre unos y otros, dándoles a conocer los preceptos de Dios y sus leyes.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Entonces el suegro de Moisés le dijo: “No está bien lo que haces.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Te cansarás demasiado, tú y este pueblo que contigo está; porque este trabajo es superior a tus fuerzas; no podrás hacerlo tú solo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Oye, pues, ahora mi voz; yo te doy un consejo, y Dios sea contigo. Sé tú solamente el representante del pueblo delante de Dios, al cual presentarás los asuntos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'Enséñales los preceptos y las leyes, y dales a conocer el camino que deben seguir, y las obras que han de practicar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Y escoge de entre el pueblo hombres capaces, temerosos de Dios, hombres fieles y enemigos de la avaricia, y constitúyelos sobre ellos como jefes de mil, jefes de cien, jefes de cincuenta y jefes de diez.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'Ellos sean jueces del pueblo en todo tiempo; todo caso importante llévenlo a ti, mas en todos los asuntos de menor importancia decidan ellos. Así se aliviará tu carga, llevándola ellos contigo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Si haces esto, y Dios te lo manda, podrás sostenerte, y por su parte todo este pueblo podrá volver en paz a su lugar.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Moisés escuchó la voz de su suegro, e hizo todo lo que había dicho.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Escogió, pues, Moisés hombres capaces de entre todo Israel, y los constituyó jefes del pueblo, jefes de mil, jefes de cien, jefes de cincuenta y jefes de diez.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Estos juzgaban al pueblo en todo tiempo; los asuntos graves los llevaban a Moisés; mas en todos los asuntos menores decidían ellos mismos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Después despidió Moisés a su suegro, el cual se volvió a su tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Al tercer mes después de la salida de la tierra de Egipto, ese mismo día, llegaron los hijos de Israel al desierto de Sinaí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Habiendo partido de Rafidim, llegaron al desierto de Sinaí y acamparon en el desierto. Allí acampó Israel frente a la montaña.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Moisés subió hacia Dios, y le llamó Yahvé desde el monte, diciendo: “Así dirás a la casa de Jacob y anunciarás a los hijos de Israel:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'Vosotros habéis visto lo que he hecho a los egipcios, y cómo os he llevado sobre alas de águila y os he traído a Mí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Ahora, pues, si de veras escuchareis mi voz y guardareis mi pacto, seréis entre todos los pueblos mi propiedad particular, pues mía es toda la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'y seréis para Mí un reino de sacerdotes y una nación santa. Estas son las palabras que has de decir a los hijos de Israel.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Fue Moisés y convocó a los ancianos del pueblo, a los cuales expuso todas estas palabras según Yahvé le había mandado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Y todo el pueblo respondió a una voz, diciendo: “Haremos todo cuanto ha dicho Yahvé.” Y Moisés llevó a Yahvé la respuesta del pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Entonces dijo Yahvé a Moisés: “He aquí que Yo vendré a ti en una densa nube para que el pueblo oiga que hablo contigo, y también te dé crédito para siempre.” Y refirió Moisés a Yahvé las palabras del pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Luego dijo Yahvé a Moisés: “Vuélvete al pueblo y santifícalos hoy y mañana. Que se laven sus vestidos,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'y estén preparados para el día tercero; porque al tercer día descenderá Yahvé a la vista de todo el pueblo sobre el monte Sinaí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Le señalarás al pueblo un límite en torno (al monte), diciendo: Guardaos de subir al monte y aun de tocar su falda. Todo el que tocare el monte morirá irremisiblemente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Nadie lo toque con la mano, pues será apedreado o asaeteado; sea animal, sea hombre, perderá la vida. Cuando suene la trompeta, entonces subirán al monte.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Bajó, pues, Moisés del monte, adonde estaba el pueblo, y santificó al pueblo, y ellos lavaron sus vestidos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'Y dijo al pueblo: “Preparaos para el tercer día, y no toquéis mujer.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Al tercer día, al rayar el alba, hubo truenos y relámpagos y una densa nube sobre el monte, y también un toque penetrante de trompeta; por lo cual todo el pueblo que estaba en el campamento comenzó a temblar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Entonces Moisés hizo salir al pueblo del campamento para ir al encuentro de Dios, y se apostaron al pie del monte.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Todo el monte Sinaí humeaba, porque Yahvé descendía sobre él en medio de fuego. Este humo subía como el humo de un horno, y todo el monte temblaba fuertemente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'El sonido de la trompeta se sentía cada vez más fuerte; mientras Moisés hablaba y Dios le respondía con voz (de trueno).');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Después, cuando Yahvé había descendido sobre el monte Sinaí, sobre la cumbre del monte, llamó a Moisés a la cumbre del monte y Moisés subió,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'y dijo Yahvé a Moisés: “Desciende y prohíbe terminantemente al pueblo que traspase los límites por ver a Yahvé, no sea que mueran muchos de ellos;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'y que también los sacerdotes que se acercan a Yahvé se santifiquen para que Yahvé no haga estragos entre ellos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Moisés respondió a Yahvé: “El pueblo no podrá subir al monte Sinaí; porque Tú nos lo has prohibido, diciendo: Señala límites alrededor del monte y santifícalo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Yahvé le dijo: “Anda y baja, y después subirás tú y Aarón contigo; pero los sacerdotes y el pueblo no traspasen los límites para subir hacia Yahvé, no sea que haga estragos entre ellos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Bajó, pues, Moisés adonde estaba el pueblo y se lo dijo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Entonces habló Dios todas estas palabras, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, '“Yo soy. Yahvé, tu Dios, que te he sacado del país de Egipto, de la casa de la servidumbre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'No tendrás otros dioses delante de Mí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'No te harás escultura ni imagen alguna de lo que hay arriba en el cielo, ni de lo que hay abajo en la tierra, ni de lo que hay en las aguas debajo de la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'No te postrarás ante ellas ni les darás culto, porque Yo soy Yahvé, tu Dios, un Dios celoso, que castigo la iniquidad de los padres en los hijos hasta la tercera y cuarta generación de los que me odian,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'y que uso de misericordia hasta mil generaciones con los que me aman y guardan mis mandamientos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'No tomarás en vano el nombre de Yahvé, tu Dios; porque Yahvé no dejará sin castigo a quien tomare en vano su nombre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Acuérdate del día de sábado para santificarlo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Seis días trabajarás y harás todo tu trabajo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'pero el día séptimo es día de descanso, consagrado a Yahvé, tu Dios. No hagas ningún trabajo, ni tú, ni tu hijo, ni tu hija, ni tu siervo, ni tu sierva, ni tu ganado, ni el extranjero que habita dentro de tus puertas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Pues en seis días hizo Yahvé el cielo y la tierra, el mar y todo cuanto ellos contienen, y el séptimo descansó; por eso bendijo Yahvé el día de sábado y lo santificó.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Honra a tu padre y a tu madre, para que se prolongue tu vida sobre la tierra que Yahvé, tu Dios, te va a dar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'No matarás.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'No cometerás adulterio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'No hurtarás.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'No levantarás falso testimonio contra tu prójimo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'No codiciarás la casa de tu prójimo, tampoco codiciarás la mujer de tu prójimo, ni su siervo, ni su sierva, ni su buey, ni su asno, ni cosa alguna de las que pertenecen a tu prójimo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Todo el pueblo percibía los truenos, los relámpagos y el sonido de la trompeta, y (veía como) el monte humeaba; y viéndolo el pueblo temblaba y permanecía a distancia.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'Y dijeron a Moisés: “Habla tú con nosotros, y escucharemos, pero no hable Dios con nosotros, no sea que muramos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Respondió Moisés al pueblo: “No temáis, pues para probaros ha venido Dios, y para que su temor esté ante vuestros ojos, a fin de que no pequéis.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Así el pueblo se mantuvo a distancia; pero Moisés se acercó a la densa nube en que estaba Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Y dijo Yahvé a Moisés: “Así dirás a los hijos de Israel: Vosotros habéis visto que os he hablado desde el cielo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'No hagáis junto a Mí dioses de plata, ni os hagáis dioses de oro,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'antes bien me erigirás un altar de tierra para ofrecer sobre él tus holocaustos y tus ofrendas pacíficas, tus ovejas y tus bueyes. En todo lugar donde Yo veo que se hace memoria de mi nombre vendré a ti y te bendeciré.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Y si me fabricas un altar de piedra no lo edificarás de piedras labradas; porque al levantar tu hierro contra la piedra la habrás profanado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Tampoco subirás por gradas a mi altar, para que no se descubra allí tu desnudez.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'Estas son las leyes que les has de dar:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Cuando comprares un esclavo hebreo, te servirá seis años, más al séptimo saldrá libre sin pagar nada.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Si entró solo, solo saldrá; si tenía mujer, saldrá con él su mujer.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Si su amo le dio mujer, y ella le dio (a su marido) hijos o hijas, la mujer y sus hijos serán de su amo, y él saldrá solo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Mas si el esclavo dijere: “Amo a mi señor, y a mi mujer y a mis hijos, no quiero salir libre”,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'su amo lo llevará ante Dios, y arrimándolo a la puerta o al poste de ella, su amo le horadará la oreja con una lezna; y así quedará esclavo suyo para siempre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Cuando un hombre vendiere a su hija por esclava, ella no saldrá como salen los esclavos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Si no agrada a su señor que la había destinado para sí, permita él su rescate; mas no podrá venderla a gente extraña, por haberla engañado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Si la destina para su hijo, la ha de tratar según el derecho de las hijas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Si toma para sí otra mujer, no le disminuirá la comida, ni el vestido, ni el deber conyugal.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Y si él no quiere darle estas tres cosas, puede ella salirse, sin pagar nada, sin rescate.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'El que hiera mortalmente a otro, muera irremisiblemente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Mas si no le hizo asechanzas, sino que Dios le dejó caer en su mano, para este tal Yo te señalaré lugar donde podrá refugiarse.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Pero al que obrare con malicia contra su prójimo, matándole con alevosía, a ese lo arrancarás hasta de mi altar para matarlo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'El que pegare a su padre o a su madre, muera irremisiblemente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Quien robare un hombre y le vendiere, o si fuere hallado todavía en su poder, muera irremisiblemente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'El que maldijere a su padre o a su madre, muera sin remedio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Cuando riñeren unos hombres y el uno hiriere al otro con piedra o con el puño, sin causarle la muerte, y si este después de hacer cama');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'se levantare y anduviere fuera, apoyándose en su bastón, quedará libre aquel que lo hirió. Le pagará solamente el tiempo perdido y los gastos de su curación completa.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Quien hiriere con un palo a su siervo o a su sierva, de modo que muera bajo su mano, caerá irremisiblemente bajo la ley de venganza.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Pero si sobreviviere un día o dos, no será castigado, por cuanto es hacienda suya.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Cuando hombres trabados en riña dieren un golpe a una mujer encinta, de modo que aborte, sin más daño, (el culpable) será multado conforme a lo que imponga el marido de la mujer y según determinen los jueces.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Pero si resultare daño, darás vida por vida,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'ojo por ojo, diente por diente, mano por mano, pie por pie,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'quemadura por quemadura, herida por herida, contusión por contusión.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Si uno, hiriendo el ojo de su siervo o el ojo de su sierva lo destruyere, le dará libertad en compensación de su ojo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Asimismo, si hiciere saltar un diente a su siervo o un diente a su sierva, lo pondrá en libertad en compensación de su diente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Si un buey acornea a un hombre o a una mujer, con subsiguiente muerte, aquel buey será apedreado y no se comerá su carne, mas el dueño del buey quedará sin culpa.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Pero si el buey acorneaba ya desde tiempo atrás, y su dueño, a pesar de ser avisado, no lo tuvo encerrado, de modo que pudo matar a hombre o a mujer, el buey será apedreado, y también su dueño será muerto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Si le imponen un precio de rescate, dará en rescate de su vida cuanto se le imponga.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Si acornea a un hijo o a una hija, hágase con él según esta ley.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Pero si el buey acorneare a un siervo o a una sierva, el dueño pagará treinta siclos de plata al dueño de ellos, y el buey será apedreado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Si uno deja abierto un pozo, o si uno cava un pozo y no lo tapa, y cayere en él un buey o asno,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'el propietario del pozo pagará indemnización en dinero al dueño de ellos, y el animal muerto será suyo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Si el buey de uno hiere al buey de otro, y este muere, venderán el buey vivo partiéndose su precio, y también el buey muerto será dividido entre ellos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Mas si era notorio que el buey acorneaba desde tiempo atrás y su dueño faltó en custodiarlo, este resarcirá el daño: buey por buey; mas el (buey) muerto será suyo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Si uno roba un buey o una oveja, y los mata o vende, restituirá cinco reses mayores por el buey, y cuatro ovejas por la oveja,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Si el ladrón sorprendido al forzar (una casa) es herido de modo que muera, no hay delito de sangre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Mas si esto sucede salido ya el sol, es delito de sangre. Debe restituir. Si no tiene con qué hacerlo, sea vendido por su robo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Si lo robado fuere hallado vivo en su poder, sea buey o asno u oveja, restituirá el doble.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Si uno causa daño en un campo o en una viña, dejando suelto su ganado de modo que pazca en campo ajeno, tiene que dar en compensación lo mejor de su propio campo y lo mejor de su propia viña,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Si se declara un fuego, y encuentra espinos, y se abrasan las cosechas recogidas o en pie, o el campo, debe restituir el daño el que haya encendido el fuego.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Si uno da a otro dinero o utensilios en custodia, y fueren estos robados de la casa de tal hombre, si fuere hallado el ladrón, restituirá el doble.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Si el ladrón no es hallado, el dueño de la casa se presentará ante Dios para declarar si no ha puesto su mano sobre los bienes de su prójimo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'En todo caso de fraude, trátese de buey, o asno, u oveja, o ropa, o cualquier otra cosa desaparecida, si uno dice: Esto es (mío), ante Dios vendrá la causa de ambos; y aquel a quien Dios condenare, restituirá el doble a su prójimo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Si uno entrega un asno, o buey, u oveja, o cualquier otro animal en custodia de otro, y estos mueren o sufren daño o llevados por los enemigos sin que nadie los haya visto,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'se interponga entre los dos el juramento de Yahvé (para averiguar) si (el depositario) no ha puesto su mano sobre la hacienda de su prójimo; lo cual el dueño ha de aceptar, y no habrá restitución.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Pero si la (bestia) le ha sido robada hará restitución al dueño de ella.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Si ha sido destrozada, traiga lo destrozado en testimonio, y no ha de restituir el daño.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Si uno pide a otro prestada (una bestia) y esta sufre daño o muere, en ausencia de su dueño, deberá restituirla sin falta.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Si estaba presente su dueño, no se hará restitución. Si era alquilada, la compensación consistirá en el precio del alquiler.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Si uno seduce a una doncella no desposada, acostándose con ella, le pagará sin falta la dote, y sea ella su mujer.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Si el padre de ella de ningún modo quiere dársela, (el seductor) pagará la suma correspondiente a la dote de las vírgenes.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'A la hechicera no la dejarás con vida.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Todo aquel que pecare con bestia, será muerto irremisiblemente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Quien ofreciere sacrificios a dioses, y no a Yahvé solo, será exterminado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'No maltratarás al extranjero, ni lo oprimirás, pues extranjeros fuisteis vosotros en el país de Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'No afligiréis a la viuda ni al huérfano.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Si los afligiereis, clamarán a Mí, y Yo no dejaré de oír su clamor;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'y se encenderá mi ira, y os mataré a espada; y vuestras mujeres quedarán viudas, y vuestros hijos, huérfanos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Si prestas dinero a uno de mi pueblo, al pobre que habita contigo, no serás con él como usurero; no le exigirás interés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Si tomas en prenda el manto de tu prójimo, se lo devolverás antes de ponerse el sol;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'porque es su único abrigo; es el vestido de su cuerpo. ¿Sobre qué dormirá? Si clamare a Mí, le prestaré oído, porque soy misericordioso.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'No blasfemarás contra Dios, ni maldecirás al príncipe de tu pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'No tardarás (en darme) las primicias de tu cosecha y de tu lagar. Me darás el primogénito de tus hijos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Lo mismo has de hacer con el de tus vacas y ovejas. Siete días estará con su madre, y al octavo me lo darás.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'Gente santa seréis para Mí. No comáis la carne destrozada (por una fiera) en el campo; echádsela a los perros.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'No siembres falsos rumores ni te conciertes con el malvado para dar falso testimonio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'No sigas a la muchedumbre para hacer el mal; ni depongas en una causa inclinándote hacia la mayoría para torcer (la justicia).');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Tampoco favorecerás al pobre en su pleito.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Cuando encuentres extraviado el buey de tu enemigo, o su asno, devuélveselos sin falta.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Si ves caído debajo de su carga el asno del que te aborrece, no te niegues a ayudarlo. Ayúdalo juntamente con el (dueño).');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'No dobles el derecho de tu pobre en su pleito.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Aléjate de causas mentirosas, y no quites la vida al inocente y justo; porque Yo no absolveré al malvado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'No recibas regalos; porque el regalo ciega a los prudentes, y pervierte las causas justas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'No oprimas al extranjero; porque vosotros sabéis lo que es ser extranjero; pues extranjeros fuisteis en la tierra de Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Seis años sembrarás tu tierra y recogerás su producto;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'al séptimo la abandonarás y la dejarás sin cultivo para que coman los pobres de tu pueblo; y lo que quede, lo comerán las bestias del campo; lo mismo harás con tu viña y tu olivar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Seis días trabajarás, y al séptimo dejarás de trabajar, para que descansen tu buey y tu asno, y se recree el hijo de tu sierva y el extranjero.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Atended a todo lo que os he dicho. No mencionaréis el nombre de otros dioses, ni se oiga este de tu boca.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Tres veces al año me celebraréis fiestas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Guardarás la fiesta de los Ácimos. Durante siete días comerás panes sin levadura, como te he mandado, al tiempo señalado, en el mes de Abib; pues en él saliste de Egipto. Nadie se presentará delante de Mí con las manos vacías.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'También la fiesta de la siega, de las primicias de tus labores, de cuanto hayas sembrado en el campo; y la fiesta de la Recolección al final del año al recoger del campo los frutos de tu trabajo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Tres veces al año se presentarán todos tus varones delante de Yahvé, el Señor.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'No ofrecerás la sangre de mi sacrificio juntamente con pan fermentado; ni has de guardar la grasa de mi sacrificio hasta el día siguiente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Los primeros productos de tu tierra los llevarás a la Casa de Yahvé, tu Dios. No cocerás el cabrito en la leche de su madre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'He aquí que Yo envío un Ángel delante de ti, para guardarte en el camino, y para conducirte al lugar que te tengo dispuesto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Muéstrale reverencia y escucha su voz; no le irrites; porque no perdonará vuestras transgresiones, pues en él está mi Nombre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Si escuchas atentamente su voz haciendo todo lo que Yo diga, seré enemigo de tus enemigos y oprimiré a tus opresores.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Porque mi Ángel caminará delante de ti y te introducirá en el país del amorreo, del heteo, del fereceo, del cananeo, del heveo y del jebuseo; y Yo los destruiré.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'No te postrarás ante sus dioses, ni les darás culto, ni imitarás sus obras; al contrario, los destruirás por completo y quebrarás sus piedras de culto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Vosotros serviréis a Yahvé, Vuestro Dios, y Él bendecirá tu pan y tu agua. También las enfermedades las desterraré de ti.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'En tu tierra no habrá mujer que aborte ni que sea estéril; y colmaré el número de tus días.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Enviaré delante de ti mi terror y llenaré de consternación a todos los pueblos a los que llegues; y haré que todos tus enemigos vuelvan ante ti las espaldas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'También enviaré tábanos delante de ti que ahuyentarán ante tu presencia al heveo, al cananeo y al heteo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'No los expulsaré de tu presencia en un solo año, no sea que la tierra quede desierta y se multipliquen contra ti las fieras del campo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Poco a poco los haré desaparecer de tu vista, hasta que tú crezcas y te apoderes del país.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Y fijaré tus confines desde el Mar Rojo hasta el Mar de los filisteos, y desde el desierto hasta el río. Pues entregaré en tus manos a los habitantes del país para que los arrojes de tu presencia.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'No hagas pacto con ellos, ni con sus dioses.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'No habiten ellos en tu país, no sea que te hagan pecar contra Mí. Porque sirviendo a sus dioses caerías en un lazo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Dijo (Dios) a Moisés: “Sube a donde está Yahvé, tú, Aarón, Nadab y Abiú, con setenta de los ancianos de Israel, y adoraréis desde lejos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Mas solo Moisés se acercará a Yahvé; ellos, en cambio, no se acercarán; tampoco subirá con él el pueblo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Vino, pues, Moisés y refirió al pueblo todas las palabras de Yahvé y todas sus leyes. Y todo el pueblo respondió a una voz: “Haremos todo cuanto ha dicho Yahvé.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Entonces escribió Moisés todas las palabras de Yahvé; y levantándose muy de mañana, erigió al pie del monte un altar y doce piedras según el número de las doce tribus de Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Y mandó a algunos jóvenes, hijos de Israel, que ofreciesen holocaustos e inmolaran becerros como sacrificios pacíficos para Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Tomó Moisés la mitad de la sangre y la echó en vasijas, y la otra mitad la derramó sobre el altar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Después tomó el libro de la Alianza y lo leyó ante el pueblo, el cual respondió: “Obedeceremos y haremos todo cuanto ha dicho Yahvé.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Y tomando Moisés la sangre roció con ella al pueblo y dijo: “He aquí la sangre de la Alianza que Yahvé ha hecho con vosotros, a tenor de todas estas palabras.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Luego subió Moisés con Aarón, Nadab y Abiú y setenta de los ancianos de Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'Y vieron al Dios de Israel. Bajo sus pies había algo como un pavimento de zafiro tan puro como el mismo cielo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Mas no extendió su mano contra los príncipes de Israel; los cuales vieron a Dios, y comieron y bebieron.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Después dijo Yahvé a Moisés: “Sube al monte, hacia Mí, y permanece allí, y te daré las tablas de piedra, con la ley y los mandamientos que tengo escritos para instrucción de ellos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Se levantó, pues, Moisés, con Josué, su ministro; y cuando subió al monte de Dios,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'dijo a los ancianos: “Esperadnos aquí hasta que volvamos a dónde estáis vosotros. Tenéis aquí a Aarón y a Hur. Quien tenga alguna cuestión recurra a ellos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Subió, pues, Moisés al monte, y la nube cubrió el monte.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'La gloria de Yahvé reposó sobre el monte Sinaí y la nube lo cubrió por seis días. Al séptimo día llamó Él a Moisés de en medio de la nube.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Y parecía la gloria de Yahvé ante los ojos de los hijos de Israel como un fuego devorador sobre la cumbre del monte.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Moisés entró en la nube y subió al monte. Y permaneció Moisés en el monte cuarenta días y cuarenta noches.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, '“Di a los hijos de Israel que me traigan una ofrenda. De todo aquel a quien mueva su corazón aceptarás para Mí ofrendas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Estas son las ofrendas que tomaréis de ellos: Oro, plata y bronce;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'jacinto, púrpura escarlata y carmesí, lino fino y pelo de cabra;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'pieles de carnero teñidas de rojo y pieles de tejón, madera de acacia;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'aceite para el candelabro, especias aromáticas para el óleo de la unción y para el incienso de perfumes;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'piedras de ónice y piedras de engaste para el efod y el pectoral.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Pues me han de hacer un Santuario, y Yo habitaré en medio de ellos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Conforme a todo lo que te voy a mostrar, conforme al modelo del Tabernáculo y según el modelo de todos sus utensilios, lo haréis.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, '“Se fabricará un Arca de madera de acacia, de dos codos y medio de largo, codo y medio de ancho, y codo y medio de alto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'La cubrirás de oro puro; por dentro y por fuera la cubrirás; una guirnalda de oro la rodeará por el borde superior.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Fundirás para ella cuatro anillos de oro, que pondrás en sus cuatro ángulos, dos anillos a un costado, y dos anillos al otro costado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Harás también varas de madera de acacia, las cuales cubrirás de oro;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'y pasarás las varas por los anillos de los costados del Arca, para llevar el Arca con ellas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'Las varas deben permanecer en los anillos del Arca, y no se sacarán de allí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'Y dentro del Arca pondrás el Testimonio que Yo te voy a dar.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, '“Harás asimismo un propiciatorio de oro puro, de dos codos y medio de largo y codo y medio de ancho.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Harás, además, dos querubines de oro; los harás de oro labrado a martillo, en los dos extremos del propiciatorio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Haz un querubín en un extremo y el otro querubín en el otro extremo. Haréis los querubines de tal manera que formen una sola pieza con el propiciatorio, a sus dos extremos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Los querubines estarán con sus alas extendidas hacia arriba, cubriendo con ellas el propiciatorio, uno frente al otro y con las caras vueltas hacia el propiciatorio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Pondrás el propiciatorio sobre el Arca, y dentro del Arca el Testimonio que Yo te daré.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Allí me encontraré contigo, y desde encima del propiciatorio, de en medio de los dos querubines colocados sobre el Arca del Testimonio, te intimaré todas mis órdenes para los hijos, de Israel.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, '“Harás también una mesa de madera de acacia, de dos codos de largo, un codo de ancho, y codo y medio de alto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'La cubrirás de oro puro y le pondrás una guirnalda de oro alrededor.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Le harás también en torno un listón de un palmo y una guirnalda de oro alrededor del listón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Y le harás cuatro anillos de oro, y pondrás los anillos en los cuatro ángulos correspondientes a sus cuatro pies.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Los anillos estarán cerca del listón, para meter por ellos las varas, a fin de llevar la mesa.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Fabricarás las varas de madera de acacia, y las cubrirás de oro. Con ellas se llevará la mesa.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Harás también sus platos, sus cucharones, sus copas y sus tazas con que se han de hacer las libaciones. De oro puro los harás.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Y sobre la mesa pondrás perpetuamente delante de Mí el pan de la proposición.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, '“Harás también un candelabro de oro puro. El candelabro se haga de oro labrado a martillo. Su pie, su tallo, sus cálices, sus botones y sus flores serán de una sola pieza.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Seis brazos saldrán de sus lados: de un lado tres brazos del candelabro, y del otro lado otros tres brazos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'El primer brazo tendrá tres cálices en forma de flor de almendro (cada una), con un botón y una flor; también el segundo brazo tendrá tres cálices en forma de flor de almendro, con un botón y una flor; y así los seis brazos que salen del candelabro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'En el tallo del candelabro habrá cuatro cálices en forma de flor de almendro, con sus botones y sus flores.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'Habrá en el tallo un botón debajo de los dos brazos (inferiores) que salen de él, y un botón debajo de (otros) dos de los brazos que salen de él, y un botón debajo de los dos brazos (superiores) que salen de él, según el número de los seis brazos que salen del candelabro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Sus botones y sus brazos serán de una sola pieza. Todo ello será una sola masa labrada a martillo, de oro puro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Harás para él siete lámparas, y colocarás esas lámparas de tal manera que alumbren la parte delante (del candelabro).');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Sus despabiladeras y sus cazoletas serán de oro puro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Un talento de oro puro se empleará para hacer el candelabro con todos estos utensilios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Y mira que lo hagas según modelo que te ha sido mostrado en el monte.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, '“Al hacer la Morada emplearás diez cortinas de tienda, de lino fino torcido, de color de jacinto, púrpura escarlata y carmesí, con querubines; harás de ella una obra maestra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'La longitud de cada cortina será de veinte y ocho codos, y el ancho de cada cortina será de cuatro codos. Una misma medida tendrán todas las cortinas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Cinco cortinas estarán unidas entre sí, y las otras cinco estarán también unidas la una con la otra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Pondrás lazos de jacinto en el borde de la primera cortina, en el extremo donde se une con la otra; lo mismo harás en el borde de la cortina que termina el segundo conjunto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Cincuenta lazos pondrás en la primera cortina, y otros cincuenta harás en el extremo de la segunda cortina donde termina el segundo conjunto, correspondiéndose los lazos unos a otros.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Y harás cincuenta broches de oro, y por medio de los broches enlazarás las cortinas entre sí, a fin de que la Morada forme un todo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Fabricarás también cortinas de pelo de cabra para un techo encima de la Morada. De estas cortinas harás once.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'La longitud de cada cortina será de treinta codos, y el ancho de cada cortina, de cuatro codos. Una misma medida tendrán las once cortinas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Juntarás cinco cortinas aparte y seis cortinas aparte; y doblarás la sexta cortina sobre el frente del Tabernáculo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Pondrás cincuenta lazos en el borde de la última cortina del primer conjunto, y cincuenta lazos en el borde del segundo conjunto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Y harás cincuenta broches de bronce e introducirás los broches en los lazos, uniendo así el Tabernáculo a fin de que forme un conjunto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'En cuanto a la parte sobresaliente de las cortinas del Tabernáculo, (tomarás) la mitad de la cortina sobrante para colgarla en la parte posterior de la Morada.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'Lo que sobra del largo de las cortinas del Tabernáculo —un codo por este lado, y uno por el otro— colgará de ambos lados de la Morada, a un lado y a otro, para cubrirla.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Harás también para el Tabernáculo una cubierta de pieles de carnero teñidas de rojo: y sobre esta, una cubierta de pieles de tejón.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, '“Harás asimismo para la Morada unos tablones de madera de acacia que sirvan de postes.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'La longitud de cada tablón será de diez codos, y la anchura de cada tablón será de codo y medio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Cada tablón tendrá dos espigas, para ensamblar el uno con el otro. De la misma manera harás todos los tablones de la Morada.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'De los tablones de la Morada harás veinte para el lado del Négueb, hacia el sur.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'Iguahnente fabricarás cuarenta basas de plata para colocar debajo de los veinte tablones: dos basas bajo cada uno de los tablones, para sus dos espigas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Para el segundo lado de la Morada, la parte del norte, harás también veinte tablones,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'con sus cuarenta basas de plata: dos basas bajo cada uno de los tablones.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Para la parte posterior de la Morada, hacia el occidente, harás seis tablones;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'y dos más para los ángulos de la parte posterior de la Morada;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'los cuales estarán unidos por la parte inferior, formando un conjunto hasta arriba, hasta el primer anillo. Así se harán los dos tablones destinados para los dos ángulos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Serán, pues, ocho tablones, con sus basas de plata, (en total) diez y seis basas; dos basas bajo cada uno de los tablones.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Harás, además, cinco travesaños de madera de acacia para los tablones de un lado de la Morada,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'y cinco travesaños para los tablones del otro lado de la Morada, y cinco travesaños para los tablones de la parte posterior de la Morada, hacia el occidente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'Y el travesaño intermedio pasará a través de los tablones de un extremo al otro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Los tablones los revestirás de oro, y harás anillos de oro, por donde han de pasar los travesaños. Revestirás de oro también los travesaños.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Erigirás la Morada según el plan que te ha sido mostrado en el monte.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, '“Y harás un velo de jacinto, púrpura escarlata, carmesí y lino fino torcido, con querubines. Ha de ser una obra maestra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Y lo colgarás de cuatro columnas de acacia, revestidas de oro, provistas de clavos de oro y (asentadas) sobre cuatro basas de plata.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Y colgarás el velo de los corchetes; y allí, detrás del velo, pondrás el Arca del Testimonio, y el velo os servirá para separar el Santo del Santísimo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'El propiciatorio lo pondrás sobre el Arca del Testimonio en el Santísimo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Fuera del velo colocarás la mesa, y frente a la mesa, en el lado meridional de la Morada, el candelabro; de manera que pondrás la mesa en el lado norte.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, '“Harás también para la puerta del Tabernáculo una cortina de jacinto, púrpura escarlata, carmesí y lino fino torcido, obra de recamador.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Para la cortina fabricarás cinco columnas de acacia, las que cubrirás de oro; sus corchetes serán también de oro, y fundirás para ellas cinco basas de bronce.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, '“Harás de madera de acacia también el altar, de cinco codos de largo y de cinco codos de ancho. El altar será, pues, de forma cuadrada y tendrá tres codos de altura,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'En sus cuatro ángulos le pondrás cuernos, procedentes de él mismo, y lo revestirás de bronce.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Y harás para él recipientes donde recoger sus cenizas, y paletas y tazones y tenedores y braseros. Todos sus utensilios los harás de bronce.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Fabricarás para él también una rejilla de bronce, en forma de red; y en la red, en sus cuatro extremos, harás cuatro anillos de bronce;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'y la colocarás abajo, en el circuito inferior del altar, de modo que la red llegue hasta la mitad del altar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Y harás varas para el altar, varas de madera de acacia, que revestirás de bronce.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Estas varas se introducirán por los anillos de modo que corran a lo largo de ambos lados del altar para transportarlo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Lo harás de tablas y hueco. Conforme a lo que te he mostrado en el monte, así sea hecho.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'También harás el atrio de la Morada. Del lado del Négueb, hacia el sur, habrá para el atrio cortinas de lino fino torcido, en una extensión de cien codos a lo largo de este lado, con sus veinte columnas y sus veinte basas de bronce.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'Los corchetes de las columnas y sus anillos serán de plata.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'A lo largo del lado septentrional habrá igualmente cortinas en una extensión de cien codos de largo, con sus veinte columnas, y veinte basas de bronce para ellas; y los corchetes de las columnas y sus anillos serán de plata.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'A lo ancho del atrio, por el lado occidental, habrá cortinas en una extensión de cincuenta codos; sus columnas serán diez, y las basas para ellas, diez.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'El ancho del atrio por el lado oriental, donde sale el sol, será de cincuenta codos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'Las cortinas puestas por un lado (de la puerta) tendrán quince codos; sus columnas serán tres, y las basas para ellas, tres');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'Y por el otro lado, quince (codos) de cortinas; sus columnas serán tres, y las basas para ellas, tres.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'La puerta del atrio tendrá una cortina de veinte codos, de Jacinto, de púrpura escarlata, carmesí y lino fino torzal, obra de recamador. Sus columnas serán cuatro, y las basas para ellas, cuatro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Todas las columnas en torno al atrio tendrán anillos de plata; sus corchetes serán de plata, y sus basas de bronce.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'El atrio tendrá cien codos de largo, cincuenta de ancho por ambos lados y cinco codos de alto; (sus cortinas) serán de lino torzal y sus basas de bronce.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Todos los utensilios de la Morada para toda clase de servicio, con todas sus estacas y todas las estacas del atrio, serán de bronce.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, '“Mandarás a los hijos de Israel que te traigan aceite puro de olivas majadas para el candelabro, a fin de alimentar las lámparas continuamente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'En el Tabernáculo de la Reunión, fuera del velo que pende delante del Testimonio, lo han de preparar Aarón y sus hijos, (para que arda) delante de Yahvé desde la tarde hasta la mañana. Estatuto perpetuo es este para todas las generaciones de los hijos de Israel.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, '“Has llegar a ti de en medio de los hijos de Israel a tu hermano Aarón, con sus hijos, para que él sea sacerdote mío: Aarón, con Nadab, Abiú, Eleazar e Itamar, hijos de Aarón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Y harás a Aarón, tu hermano, vestiduras sagradas, para gloria y adorno.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Hablarás con todos los hombres ingeniosos, que Yo he dotado de espíritu de sabiduría, y ellos harán las vestiduras de Aarón, para santificarle, a fin de que sea sacerdote mío.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Estas son las vestiduras que han de hacer: un pectoral, un efod, una sobretúnica, una túnica bordada, una mitra y un cinturón. Harán, pues, vestiduras sagradas para Aarón, tu hermano, y para sus hijos, a fin de que sean sacerdotes delante de Mí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Tomarán para ello oro, jacinto, púrpura escarlata y carmesí y tejido de lino fino.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, '“El efod lo harán artísticamente de oro, de jacinto, púrpura escarlata, carmesí y lino fino torzal.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Tendrá dos hombreras unidas entre sí y atadas a sus dos extremos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'La cinta que está sobre él para ceñirlo, formará una misma pieza con él arrancando del mismo, y será de oro, de jacinto, púrpura escarlata, carmesí y lino fino torzal.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Y tomarás dos piedras de ónice, sobre las cuales grabarás los nombres de los hijos de Israel:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'seis de sus nombres en una piedra, y los seis nombres restantes en la otra piedra, por orden de su nacimiento.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Como se tallan las piedras y como se graban los sellos, así harás grabar en esas dos piedras los nombres de los hijos de Israel, engarzándolas en engastes de oro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Después pondrás las dos piedras sobre las hombreras del efod, como piedras de recuerdo de los hijos de Israel, y así llevará Aarón sus nombres sobre sus dos hombros para memoria delante de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Harás, pues, engastes de oro;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'y también dos cadenillas de oro puro, trenzadas a manera de cordones, y fijaras las cadenillas trenzadas en los engastes.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, '“Harás también artísticamente el pectoral del juicio, al estilo de la obra del efod. De oro, púrpura escarlata, carmesí y lino fino torzal lo harás.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Será cuadrado y doblado, de un palmo de largo y de un palmo de ancho.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Lo guarnecerás de engastes de pedrería, poniendo las piedras en cuatro filas; en la primera fila un sardio, un topacio y una esmeralda;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'en la segunda fila un rubí, un zafiro y un diamante;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'en la tercera fila un jacinto, un ágata y una amatista;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'en la cuarta fila un crisólito, un ónice y un jaspe; todos engastados en oro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Las piedras corresponderán a los nombres de los hijos de Israel: doce, como los nombres de ellos, entalladas como sellos cada una con su nombre, conformé a las doce tribus.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, '“Sobre el pectoral harás cadenillas de oro puro, trenzadas a manera de cordones;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'y sobre el pectoral dos anillos de oro, que fijarás en los dos extremos del pectoral.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'Introducirás los dos cordones de oro por los dos anillos, en los extremos del pectoral;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'y unirás los dos extremos de los dos cordones a los dos engastes, y los fijarás en la parte delantera de las hombreras del efod.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Harás (otros) dos anillos de oro, que pondrás en los dos extremos (inferiores) del pectoral, en el borde interior que mira hacia el efod.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Además harás dos anillos de oro y los fijarás en la parte inferior de las dos hombreras del efod, por delante, cerca de su enlace, por encima de la cinta del efod.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'El pectoral se unirá por sus anillos a los anillos del efod, con un cordón de jacinto, para que quede sobre la cinta del efod y no se desprenda el pectoral del efod.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Así llevará Aarón sobre su corazón los nombres de los hijos de Israel, en el pectoral del juicio, siempre que entre en el Santuario, en memoria perpetua delante de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'En el pectoral del juicio pondrás los Urim y Tummim, para que estén sobre el corazón de Aarón cuando se presente ante Yahvé. Así llevará Aarón constantemente sobre su corazón delante de Yahvé el juicio de los hijos de Israel.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, '“La sobretúnica del efod la harás toda de jacinto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'En su centro habrá una abertura para la cabeza; esta abertura tendrá todo en torno una orla, tejida como el cuello de una cota, para que no se rompa.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Alrededor de todo su borde inferior pondrás granadas de jacinto, púrpura escarlata y carmesí, y en medio de ellas todo en torno campanillas de oro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'A una campanilla de oro y una granada siga otra campanilla de oro y otra granada, todo alrededor del borde inferior de la sobretúnica.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Aarón la llevará en el ejercicio de su ministerio, para que se oiga su sonido cuando entre en el Santuario ante Yahvé y cuando salga; y así no morirá.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, '“Harás, además, una lámina de oro puro, y en ella grabarás, como se graban los sellos: Santidad a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'La sujetarás con un cordón de jacinto de tal modo que esté fija sobre la mitra, por delante.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'Estará sobre la frente de Aarón; pues Aarón llevará las faltas cometidas por los hijos de Israel en las cosas sagradas al ofrecer toda suerte de santas ofrendas. Estará constantemente sobre su frente, para que hallen gracia delante de Yahvé.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, '“La túnica la tejerás de lino fino. Harás también la mitra de lino fino. El cinturón lo harás de labor de recamado.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, '“Para los hijos de Aarón harás túnicas. Les harás también cinturones y turbantes para distinción y adorno.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Vestirás así a Aarón, tu hermano, y a sus hijos. Y los ungirás, los consagrarás y los santificarás, para que sean sacerdotes míos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Hazles también calzoncillos de lino, para cubrir su desnudez desde la cintura hasta los muslos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'Aarón y sus hijos los llevarán al entrar en el Tabernáculo de Reunión, o al acercarse al altar para servir en el Santuario, a fin de que no se atraigan culpa y así mueran. Estatuto perpetuo será este para él y su descendencia después de él.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, '“Para consagrar a los sacerdotes míos, has de proceder con ellos de esta manera: Toma un novillo y dos carneros sin tacha,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'y panes ácimos y tortas sin levadura amasadas con aceite, como también galletas sin levadura, untadas con aceite. De flor de harina de trigo los harás.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Y los pondrás en un canasto, y los presentarás en el canasto junto con el novillo y los dos carneros.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Luego harás que Aarón y sus hijos se acerquen a la entrada del Tabernáculo de la Reunión, donde los lavarás con agua.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Tomarás después las vestiduras y vestirás a Aarón con la túnica, el manto del efod, el efod y el pectoral, que ceñirás con la cinta del efod.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'Pondrás la mitra sobre su cabeza, y sobre la mitra colocarás la diadema de santidad.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Entonces tomarás el óleo de la unción, se lo derramarás sobre la cabeza y así lo ungirás.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Harás igualmente que se lleguen sus hijos y los vestirás con túnicas;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'y ceñirás a Aarón y a sus hijos los cinturones y les sujetarás las tiaras. A ellos les corresponderá el sacerdocio por ley perpetua. Así consagrarás a Aarón y a sus hijos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'El novillo lo llevarás ante el Tabernáculo de la Reunión, y Aarón y sus hijos pondrán las manos sobre la cabeza del novillo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Luego degollarás el novillo delante de Yahvé, a la entrada del Tabernáculo de la Reunión.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'Y tomando de la sangre del novillo la pondrás con tu dedo sobre los cuernos del altar, y derramarás toda la sangre al pie del altar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Saca todo el sebo que cubre las entrañas, la redecilla del hígado, y los dos riñones con el sebo que los envuelve, para quemarlo en el altar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Mas la carne del novillo, con su piel y sus excrementos, la quemarás fuera del campamento. Es sacrificio por el pecado.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, '“Después tomarás uno de los carneros, y Aarón y sus hijos pondrán las manos sobre la cabeza del carnero.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Degollado el carnero tomarás de su sangre y rociarás con ella el altar todo en derredor.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Luego descuartizarás el carnero, lavarás sus entrañas y sus piernas, las pondrás sobre sus trozos y sobre su cabeza,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'y quemarás todo el carnero en el altar. Es holocausto a Yahvé, olor grato, sacrificio consumido por el fuego en honor de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Tomarás también el segundo carnero, y Aarón y sus hijos pondrán las manos sobre la cabeza del carnero.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'Y degollado este carnero, tomarás de su sangre y untarás con ella el lóbulo de la oreja derecha de Aarón y el lóbulo de la oreja derecha de sus hijos, el pulgar de su mano derecha y el pulgar de su pie derecho, y derramarás la sangre (restante) alrededor del altar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Toma luego de la sangre que habrá sobre el altar, y del óleo de la unción, para rociar a Aarón y sus vestiduras, sus hijos y las vestiduras de sus hijos juntamente con él. Así quedarán consagrados él y sus vestiduras, y con él sus hijos y las vestiduras de sus hijos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Toma después de este carnero el sebo: la cola, el sebo que cubre las entrañas, la redecilla del hígado, los dos riñones con el sebo que los envuelve, y la pierna derecha, porque es carnero de consagración.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'Toma también un pan, una torta de pan de aceite y una galleta del canasto de los ácimos que está delante de Yahvé.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, '“Todo eso pondrás sobre las palmas de las manos de Aarón y de sus hijos; y lo mecerás como ofrenda mecida delante de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Después lo tomarás de sus manos y lo quemarás en el altar encima del holocausto como olor grato a Yahvé. Es un sacrificio a fuego en honor de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Tomarás también el pecho del carnero degollado en la consagración de Aarón, y lo mecerás como ofrenda mecida delante de Yahvé; esa será tu porción.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Así santificarás el pecho de la ofrenda mecida y la pierna de la elevación, es decir, aquellas partes del carnero de la consagración que han sido mecidas y elevadas y pertenecen a Aarón y a sus hijos;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'y serán de Aarón y de sus hijos, como porción legal perpetua, de parte de los hijos de Israel; porque es ofrenda de elevación; y esa ofrenda de elevación han de dársela los hijos de Israel en sus sacrificios pacíficos como ofrenda alzada en honor de Yahvé.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, '“Las vestiduras sagradas de Aarón serán después de él para sus hijos. Con ellas serán ungidos y con ellas serán consagrados.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Por siete días las vestirá aquel de sus hijos que sea sacerdote en su lugar y entre en el Tabernáculo de la Reunión para servir en el Santuario.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Después tomaras el carnero de la consagración y cocerás su carne en lugar sagrado;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'y Aarón y sus hijos comerán a la entrada del Tabernáculo de la Reunión la carne del carnero y el pan que estará en el canasto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'Comerán aquello que ha servido para su expiación, al consagrarlos y santificarlos; pero ningún extraño coma de ellas, porque son cosas santas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Si sobrare algo de la carne de la consagración o del pan hasta el día siguiente, quemaras el resto; no ha de comerse, porque es cosa santa.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, '“Harás, pues, con Aarón y con sus hijos de esta manera, según todo lo que te he mandado. Durante siete días los consagrarás.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'Cada día ofrecerás un novillo como sacrificio por el pecado, para expiación; y purificarás el altar mediante esta expiación, y lo ungirás para santificarlo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Por siete días harás la expiación del altar, y lo santificarás, y será el altar cosa sacratísima; todo cuanto toque el altar quedará santificado.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, '“He aquí lo que has de ofrecer sobre el altar: dos corderos primales cada día perpetuamente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Un cordero ofrecerás por la mañana, y el otro cordero lo ofrecerás entre las dos tardes;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'y con el primer cordero la décima parte (de un efa) de flor de harina amasada con un cuarto de hin de aceite de oliva majada, y para libación un cuarto de hin de vino.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'El otro cordero lo ofrecerás entre las dos tardes, con la misma ofrenda como a la mañana y con la misma libación, como olor grato, sacrificio a fuego en honor de Yahvé;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'en holocausto perpetuo, durante vuestras generaciones, ante Yahvé, a la entrada del Tabernáculo de la Reunión, donde me encontraré con vosotros, para hablar allí contigo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Allí me reuniré con los hijos de Israel y (el lugar) será consagrado por mi gloria.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Consagraré el Tabernáculo de la Reunión y el altar, y consagraré también a Aarón y a sus hijos para que sean mis sacerdotes.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Y habitaré en medio de los hijos de Israel, y seré su Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'Y reconocerán que Yo soy Yahvé, su Dios, que los saqué de la tierra de Egipto para habitar entre ellos, Yo, Yahvé, su Dios.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, '“Harás también un Altar para quemar el incienso. De madera de acacia lo harás.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'Será cuadrado: de un codo de largo y de un codo de ancho, y su altura será de dos codos. Sus cuernos formarán un mismo cuerpo con él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Lo revestirás de oro puro, tanto su parte superior como sus cuatro lados, y sus cuernos. Le harás en torno una guirnalda de oro,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'y debajo de la guirnalda, a los costados, dos anillos. Hazlos a ambos lados, para pasar por ellas las varas con que transportarlo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Fabricarás las varas tomando madera de acacia y las recubrirás de oro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Lo colocarás delante del velo que está ante el Arca del Testimonio y ante el propiciatorio que se halla encima del Testimonio, donde Yo me entrevistaré contigo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Aarón quemará en él incienso aromático; lo quemará todas las mañanas, al preparar las lámparas,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'y lo quemará Aarón también cuando entre las dos tardes preparare las luces. Será incienso continuo ante Yahvé de generación en generación.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'No ofrezcáis sobre él incienso extraño, ni holocausto ni ofrendas, ni derraméis sobre él libación alguna.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Una vez al año hará Aarón expiación sobre los cuernos de este altar con la sangre del sacrificio por el pecado. Una vez cada año hará sobre él expiación para vuestros descendientes. Cosa santísima es esta para Yahvé.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, '“Cuando contares el número de los hijos de Israel, para hacer su censo, cada uno de ellos pagará a Yahvé un rescate por su vida al ser empadronados, para que no haya plaga entre ellos con motivo del empadronamiento.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Esto es lo que ha de dar cada uno de los empadronados: medio siclo, según el peso del Santuario. Un siclo son veinte gueras. Medio siclo es, pues, el tributo que se ha de dar a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Todos los empadronados, de veinte años para arriba, pagarán el tributo a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'El rico no dará más, ni el pobre menos del medio siclo, al pagar el tributo a Yahvé como rescate de vuestras vidas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Tomarás el dinero del rescate de parte de los hijos de Israel, para emplearlo en el servicio del Tabernáculo de la Reunión; y será para los hijos de Israel un recuerdo ante Yahvé para el rescate de sus vidas.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Habló Yahvé a Moisés diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, '“Haz una pila de bronce con su base de bronce para las abluciones. Colócala entre el Tabernáculo de la Reunión y el altar y echa agua en ella,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'para que Aarón y sus hijos se laven en ella las manos y los pies.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Antes de entrar en el Tabernáculo de la Reunión se han de lavar con agua para que no mueran, y también antes de acercarse al altar para el ministerio, para quemar un sacrificio en honor de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'Se lavarán las manos y los pies, para que no mueran. Esta será ley perpetua para ellos, para Aarón y sus descendientes de generación en generación.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, '“Y tú, toma de los mejores aromas de mirra pura quinientos (siclos); de canela aromática la mitad de esto, o sea doscientos cincuenta, de caña aromática doscientos cincuenta,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'de casia quinientos, según el siclo del Santuario, y un hin de aceite de olivas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'Con ello formarás el óleo para la unción sagrada, perfume oloroso compuesto según el arte de perfumería. Este será el óleo para la unción sagrada.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Con él ungirás el Tabernáculo de la Reunión y el Arca del Testimonio,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'la mesa con todos sus utensilios, el candelabro con todos sus utensilios, el altar del incienso,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'el altar del holocausto con todos sus utensilios y la pila con su base.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Así los santificarás y serán cosa santísima. Todo el que los toque quedará santificado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Ungirás también a Aarón y a sus hijos y los consagrarás, para que me sirvan de sacerdotes.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Y hablarás a los hijos de Israel, diciendo: “Este será para Mí el óleo de la unción sagrada de generación en generación.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'No debe derramarse sobre ningún hombre, y en cuanto a su composición no haréis ninguno parecido a él. Santo es y lo tendréis por cosa sagrada.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Cualquiera que elabore algo semejante o derrame de él sobre persona extraña será exterminado de en medio de su pueblo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Dijo Yahvé a Moisés: “Toma por cantidades iguales los siguientes aromas: resina, uña odorífera y gálbano, especias aromáticas e incienso puro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'Con ello harás, según el arte de perfumería, un incienso perfumado, sazonado con sal, puro y santo;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'del cual pulverizarás una parte que pondrás delante del Testimonio en el Tabernáculo de la Reunión, donde Yo me entrevistaré contigo. Será para vosotros cosa santísima.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Y en cuanto a la composición de este incienso que vas a hacer, no la imitéis para vuestro uso. Lo tendrás por consagrado a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Cualquiera que prepare otro semejante para aspirar su fragancia, será exterminado de en medio de su pueblo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, '“Mira que he llamado por su nombre a Besalel, hijo de Urí, hijo de Hur, de la tribu de Judá;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'y le he llenado de espíritu divino, de sabiduría, inteligencia y maestría en toda clase de trabajos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'Para inventar diseños y labrar el oro, la plata y el bronce;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'para grabar piedras de engaste, para tallar la madera y ejecutar cualquier otra obra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Y mira que le he dado por compañero a Oholiab, hijo de Ahisamac, de la tribu de Dan; y además he infundido sabiduría en el corazón de todos los hombres hábiles, para que hagan todo lo que te he mandado:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'el Tabernáculo de la Reunión, el Arca del Testimonio, el propiciatorio que la cubre, con todos los utensilios del Tabernáculo;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'la mesa con sus utensilios, el candelabro de oro puro, con todos sus utensilios, el altar del incienso,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'el altar del holocausto, con todos sus utensilios, la pila con su base;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'las vestiduras litúrgicas y las vestiduras sagradas de Aarón el sacerdote y las vestiduras de sus hijos para las funciones sacerdotales;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'el óleo de la unción y el incienso aromático para el Santuario. Ellos lo han de hacer conforme a todo lo que te he ordenado.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Habló Yahvé a Moisés y dijo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, '“Di a los hijos de Israel: Mirad que guardéis mis sábados; porque el sábado es una señal entre Mí y vosotros, de generación en generación, para que sepáis que Yo, Yahvé soy quien os santifico.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Guardad el sábado, porque es santo para vosotros. El que lo profane morirá irremisiblemente. Todo el que trabajare en él, será exterminado de en medio de su pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Seis días se trabajará; mas el día séptimo será día de descanso completo, consagrado a Yahvé. Todo aquel que trabaje en sábado, morirá irremisiblemente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Los hijos de Israel observarán el sábado como pacto perpetuo celebrándolo de generación en generación.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Será entre Mí y los hijos de Israel una señal perpetua; pues en seis días hizo Yahvé el cielo y la tierra, y el día séptimo descansó y reposó.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Después de hablar Dios con Moisés en el monte Sinaí, le dio las dos tablas del Testimonio; tablas de piedra, escritas por el dedo de Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Cuando el pueblo vio que Moisés tardaba en bajar del monte, se reunió alrededor de Aarón y le dijeron: “Anda, haznos un dios que vaya delante de nosotros, ya que no sabemos que ha sido de ese Moisés, ese hombre que nos ha sacado de la tierra de Egipto.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Les respondió Aarón: “Quitad los pendientes de oro de las orejas de vuestras mujeres y de vuestros hijos y de vuestras hijas, y traédmelos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Y todos se quitaron los pendientes de oro que llevaban en las orejas, y los entregaron a Aarón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Y él, tomándolos de sus manos le dio forma con el buril e hizo así un becerro de fundición. Entonces ellos dijeron: “Este es tu Dios, oh Israel, el que te ha sacado de la tierra de Egipto.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Viendo esto Aarón, erigió un altar ante el becerro e hizo esta proclamación: “Mañana habrá fiesta en honor de Yahvé.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Y levantándose al día siguiente muy temprano, ofrecieron holocaustos y presentaron sacrificios pacíficos. Luego se sentó el pueblo a comer y beber, y después se levantaron a divertirse.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Entonces habló Yahvé a Moisés, y dijo: “¡Ve, baja! porque ha pecado tu pueblo que sacaste de la tierra de Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Muy pronto se han apartado del camino que Yo les había prescrito. Se han hecho un becerro de fundición y se han postrado ante él; le han ofrecido sacrificios y han dicho: “Este es tu Dios, oh Israel, el que te ha sacado de la tierra de Egipto.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Y dijo Yahvé a Moisés: “Veo que este pueblo es un pueblo de dura cerviz.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Déjame ahora para que se encienda mi ira contra ellos y los consuma; de ti, en cambio, haré un gran pueblo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Pero Moisés imploró a Yahvé, su Dios, diciendo: “¿Por qué, oh Yahvé, ha de encenderse tu ira contra tu pueblo, que Tú sacaste de la tierra de Egipto con gran poder y mano fuerte?');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, '¿Por qué han de decir los egipcios: Para hacerles mal los ha sacado a fin de matarlos en las montañas, y extirparlos de sobre la faz de la tierra? Deja el ardor de tu ira y arrepiéntete del mal contra tu pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Acuérdate de Abrahán, de Isaac y de Israel, siervos tuyos, a los cuales por Ti mismo juraste, diciéndoles: Multiplicaré vuestra descendencia como las estrellas del cielo; y toda esta tierra que os tengo prometida, la daré a vuestros descendientes, y ellos la poseerán para siempre.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Y se arrepintió Yahvé del mal con que había amenazado a su pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Se volvió Moisés y bajó del monte, con las dos tablas del Testimonio en su mano; tablas escritas por ambos lados; por una y otra cara estaban escritas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Las tablas eran obra de Dios, y la escritura era escritura de Dios, grabada sobre las tablas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Cuando Josué oyó la voz del pueblo que gritaba, dijo a Moisés: “Gritos de guerra hay en el campamento.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Respondió él: “No son gritos de victoria, ni alaridos de derrota. Voz de canto es lo que oigo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Mas cuando Moisés estuvo cerca del campamento y vio el becerro y las danzas, se encendió su ira de tal manera que arrojó de su mano las tablas y las hizo pedazos al pie del monte.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Luego tomó el becerro que habían hecho, lo quemó y lo molió hasta reducirlo a polvo, el cual esparció en el agua y se lo dio de beber a los hijos de Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Y dijo Moisés a Aarón: “¿Qué te hizo este pueblo para que le hayas acarreado pecado tan grave?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Aarón respondió: “No se encienda la ira de mi señor. Tú mismo sabes que este pueblo es propenso al mal.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Me dijeron: ‘Haznos un dios que vaya delante de nosotros; ya que no sabemos qué ha sucedido a ese Moisés, ese hombre que nos ha sacado de la tierra de Egipto.’');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Yo les contesté: ‘Quien tenga oro, quíteselo.’ Me lo dieron y yo lo eché al fuego y salió este becerro.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Entonces Moisés viendo al pueblo desenfrenado —pues Aarón les había dado rienda suelta, para que se alegrasen sus enemigos—,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'se puso a la puerta del campamento, y exclamo: “¡A mí los de Yahvé!” Y se reunieron con él todos los hijos de Leví.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Y les dijo: “Así dice Yahvé, el Dios de Israel: Cíñase cada uno su espada sobre su muslo, y pasad y repasad por el campamento de puerta en puerta, y matad, cada uno a su hermano, a su amigo y a su pariente.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Hicieron los hijos de Leví según la orden de Moisés; y perecieron en aquel día unos tres mil hombres del pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Y dijo Moisés: “Hoy os habéis consagrado a Yahvé, cada uno contra su hijo y su hermano; para que hoy recibáis bendición.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Al día siguiente dijo Moisés al pueblo: “Habéis cometido un gran pecado. Subiré ahora a Yahvé; quizás podré obtener la remisión de vuestro pecado.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Y se volvió Moisés a Yahvé y dijo: “¡Ay! este pueblo ha cometido un pecado grande, fabricándose un dios de oro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Pero ahora, perdona su pecado; y si no, bórrame de tu libro que has escrito.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Yahvé respondió a Moisés: “Al que haya pecado contra Mí, a este le borraré de mi libro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Por ahora ve y conduce al pueblo adonde te he dicho. He aquí que mi Ángel irá delante de ti, mas en el día de mi visitación los castigaré por su pecado.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Así hirió Yahvé al pueblo por haber hecho el becerro por manos de Aarón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Dijo Yahvé a Moisés: “Anda, sube de aquí, tú y el pueblo que sacaste de Egipto, al país que Yo con juramento prometí a Abrahán, a Isaac y a Jacob, diciendo: A tu posteridad lo daré.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'Enviaré delante de ti un Ángel, y echaré al cananeo, al amorreo, al heteo, al fereceo, al heveo y al jebuseo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, '(para que entres) en la tierra que mana leche y miel; pues Yo no iré en medio de ti, porque eres un pueblo de dura cerviz; no sea que te destruya en el camino.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Al oír estas duras palabras el pueblo se puso de luto y nadie se atavió con sus galas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Dijo entonces Yahvé a Moisés: “Di a los hijos de Israel: Vosotros sois un pueblo de dura cerviz. Si Yo un solo momento subiera contigo, te consumiría. Ahora, pues, quítate tus atavíos, para que Yo sepa qué he de hacer contigo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Por lo cual los hijos de Israel se despojaron de sus atavíos desde el monte Horeb.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Y tomó Moisés el Tabernáculo y lo plantó a cierta distancia fuera del campamento, y lo llamó Tabernáculo de la Reunión. De modo que todo el que buscaba a Yahvé salía hacia el Tabernáculo de la Reunión fuera del campamento.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Cuando salía Moisés hacia el Tabernáculo se ponía en pie todo el pueblo, y cada cual se estaba a la puerta de su tienda, siguiendo con sus ojos a Moisés hasta entrar este en el Tabernáculo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Y cuando Moisés entraba en el Tabernáculo, bajaba la columna de nube y se detenía a la puerta del Tabernáculo, mientras (Yahvé) hablaba con Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Todo el pueblo que veía la columna de nube erguida a la puerta del Tabernáculo, se levantaba, y cada cual se postraba junto a la puerta de su tienda.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Así hablaba Yahvé con Moisés cara a cara, como suele hablar un hombre con su amigo. Luego volvía este al campamento, pero su ministro, el joven Josué, hijo de Nun, no se apartaba del Tabernáculo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Y dijo Moisés a Yahvé: “Mira, Tú me dices: Saca este pueblo; mas no me has dado a conocer a quien enviarás conmigo; y sin embargo me has dicho: Te conozco por tu nombre, y también: Has hallado gracia a mis ojos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Ahora, pues, si realmente he hallado gracia a tus ojos, te ruego me muestres tu camino, para que yo te conozca y halle gracia a tus ojos, y considera que este pueblo es pueblo tuyo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Respondió Él: “Mi Rostro irá (delante de ti) y te daré descanso.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Le contestó: “Si tu Rostro no va (delante nuestro), no nos hagas partir de aquí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Pues ¿en qué podrá conocerse que he hallado gracia a tus ojos, yo y tu pueblo, sino en eso en que Tú marches con nosotros, para que nos distingamos, yo y tu pueblo, de todos los pueblos que hay sobre la tierra?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Respondió Yahvé a Moisés: “Cumpliré también esto que me acabas de pedir, pues has hallado gracia a mis ojos, y Yo te conozco por tu nombre.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Entonces dijo (Moisés): “Muéstrame, te ruego tu gloria.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Él le contestó: “Yo haré pasar ante tu vista toda mi bondad y pronunciaré delante de ti el nombre de Yahvé; y haré merced a quien Yo haga merced y usaré de misericordia con quien Yo use de misericordia.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Y añadió: “Pero mi Rostro no podrás verlo; porque no puede verme el hombre y vivir.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Luego dijo Yahvé: “He aquí un lugar junto a Mí; tú te pondrás sobre la peña;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'y al pasar mi gloria, te pondré en una hendidura de la peña, y te cubriré con mi mano hasta que Yo haya pasado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Luego apartaré mi mano, para que veas mis espaldas; pero mi Rostro no se puede ver.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Dijo Yahvé a Moisés: “Tállate dos tablas de piedras como las primeras, y Yo escribiré sobre estas tablas las palabras que había en las primeras tablas que quebraste.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Y prepárate para mañana para subir temprano al monte Sinaí; allí en la cumbre del monte te presentarás delante de Mí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'No suba nadie contigo, ni aparezca nadie en todo el monte; ni tampoco oveja ni buey pazca frente a este monte.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Talló, pues, Moisés dos tablas de piedra como las primeras, y levantándose muy de mañana subió al monte Sinaí, como le había mandado Yahvé, llevando en su mano las dos tablas de piedra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Y descendió Yahvé en la nube y poniéndose allí junto a él pronunció el nombre de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Y mientras Yahvé pasaba por delante de él, exclamó: “Yahvé, Yahvé, Dios misericordioso y clemente, longánimo y rico en bondad y fidelidad;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'que conserva la misericordia hasta mil (generaciones), que perdona la iniquidad, la transgresión y el pecado, pero que de ningún modo los deja impune; que castiga la iniquidad de los padres en los hijos, y en los hijos de los hijos hasta la tercera y cuarta generación.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Al instante Moisés se prosternó en tierra y adoró,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'diciendo: “Si en verdad he hallado gracia a tus ojos, oh Señor, dígnese mi Señor andar en medio de nosotros, aunque es un pueblo de dura cerviz; y perdona nuestra iniquidad y nuestro pecado, y tómanos por herencia tuya.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Respondió Él: “Mira, Yo hago un pacto: haré maravillas delante de todo tu pueblo, como nunca se han hecho en toda la tierra ni en nación alguna; y todo el pueblo en medio del cual estás verá la obra de Yahvé, porque tremendas son las cosas que he de hacer por medio de ti.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, '“Observa bien lo que te mando hoy. He aquí que voy a echar delante de ti al amorreo, al cananeo, al heteo, al fereceo, al heveo y al jebuseo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Guárdate de hacer alianza con los habitantes del país en que vas a entrar, para que no sean un lazo en medio de ti;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'antes bien, destruid sus altares, quebrad sus piedras idolátricas y romped sus ascheras.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'No te postrarás ante ningún otro Dios, pues Yahvé, cuyo nombre es Celoso, es un Dios celoso.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'No hagas pacto con los moradores de aquella tierra, porque ellos fornican con sus dioses y les ofrecen sacrificios. Te invitarán y tú comerás de sus sacrificios;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'y tomarás de sus hijas para tus hijos; y fornicando sus hijas con sus dioses harán también fornicar a tus hijos con los dioses de ellas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'No te harás dioses de fundición.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Guardarás la fiesta de los Ácimos; siete días comerás panes ácimos como te he mandado, al tiempo fijado, esto es, en el mes de Abib; pues en el mes de Abib saliste de Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Todo primogénito es mío, asimismo todo primerizo de tu ganado, que fuere del sexo masculino, sea de vaca o de oveja.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Mas el primerizo del asno rescatarás con una oveja; y si no lo rescatas le quebrarás la cerviz. A todos los primogénitos de tus hijos los rescatarás, y nadie se presentará ante Mí con las manos vacías.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Seis días trabajarás, mas en el séptimo descansarás. Descansarás también en el tiempo de la siembra y de la siega.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Celebrarás la fiesta de las Semanas: la de los primeros frutos de la cosecha del trigo, y también la fiesta de la recolección al fin del año.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Tres veces al año, comparezcan todos tus varones ante Yahvé, el Señor, el Dios de Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Porque Yo arrojaré los pueblos delante de ti, y ensancharé tus límites, y nadie codiciará tu tierra mientras subas tres veces al año a presentarte delante de Yahvé, tu Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'No ofrecerás con pan fermentado la sangre de mi sacrificio ni quede hasta el día siguiente la víctima de la fiesta de Pascua.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Llevarás a la Casa de Yahvé, tu Dios, las primicias de los primeros frutos de tu tierra. No cocerás el cabrito en la leche de su madre.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Y dijo Yahvé a Moisés: “Escríbete estas palabras; porque a tenor de ellas hago alianza contigo y con Israel.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Moisés estuvo allí con Yahvé cuarenta días y cuarenta noches, sin comer pan ni beber agua. Y Yahvé escribió en las tablas las palabras de la alianza, los diez mandamientos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Luego bajó Moisés del monte Sinaí, y al bajar del monte tenía en su mano las dos tablas del Testimonio; mas no sabía Moisés que la piel de su rostro se había hecho radiante por haber hablado con Él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Aarón y todos los hijos de Israel miraron a Moisés, y he aquí que la piel de su rostro brillaba, por lo cual tuvieron miedo de acercársele.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Pero Moisés los llamó y se volvieron a él Aarón y todos los príncipes del pueblo, y Moisés habló con ellos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Después se acercaron también todos los hijos de Israel, y él les dio todas las órdenes que Yahvé le había dado en el monte Sinaí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Y cuando Moisés acabó de hablar con ellos, se puso un velo sobre el rostro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Y siempre cuando Moisés iba a presentarse delante de Yahvé para hablar con Él se quitaba el velo hasta que salía, y cuando salía, refería a los hijos de Israel lo que se le había ordenado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Los hijos de Israel veían entonces el rostro de Moisés y la radiante piel de su rostro. Y Moisés cubría de nuevo su rostro hasta que entraba a hablar con Él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Moisés convocó a toda la congregación de los hijos de Israel y les dijo: “Estas son las cosas que Yahvé ha mandado hacer.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Seis días trabajarás, mas el día séptimo os será santo, sábado de descanso completo en honor de Yahvé. Cualquiera que en él hiciere obra alguna será muerto,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'En ninguna de vuestras moradas encenderéis fuego en el día de sábado.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Moisés habló a toda la congregación de los hijos de Israel y dijo: “Esta es la orden de Yahvé:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Tomad de lo que poseéis una ofrenda para Yahvé. Todos den generosamente un tributo para Yahvé: oro, plata y bronce,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'jacinto, purpura escarlata y carmesí, lino fino, pelo de cabra,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'pieles de carnero teñidas de rojo, pieles de tejón, madera de acacia,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'aceite para el candelabro, aromas para el óleo de unción y para el incienso aromático,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'piedras de ónice, y piedras de engaste para el efod y el pectoral.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Y vengan los artífices hábiles de entre vosotros a fabricar todo cuanto Yahvé ha ordenado:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'la Morada, su Tabernáculo y su cubierta, sus broches, sus tablas, sus travesaños, sus columnas y sus basas;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'el Arca y sus varas, el propiciatorio y la cortina del velo;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'la mesa con sus varas y todos sus utensilios, el pan de la proposición,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'el candelabro para el alumbrado con sus utensilios y sus lámparas y el aceite del alumbrado;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'el altar del incienso con sus varas; el óleo de la unción, el incienso aromático, la cortina de la puerta de entrada a la Morada,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'el altar de los holocaustos con su rejilla de bronce, sus varas y todos sus utensilios; la pila con su base;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'las cortinas del atrio con sus columnas y sus basas; la cortina de la entrada del atrio;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'las estacas de la Morada y las estacas del atrio y sus cuerdas;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'los ornamentos litúrgicos para el servicio en el Santuario; las vestiduras sagradas para Aarón, el sacerdote, y las vestiduras de sus hijos para sus funciones sacerdotales.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Entonces toda la congregación de los hijos de Israel salió de la presencia de Moisés;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'y cuantos se sentían impulsados por su corazón y cuyo espíritu era generoso, vinieron a ofrecer tributo a Yahvé, para la obra del Tabernáculo de la Reunión, para todo su culto y para las vestiduras sagradas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Vinieron, pues, hombres y mujeres, todos los de corazón generoso, trayendo zarcillos, pendientes, anillos, brazaletes y toda clase de objetos de oro, y, además, todos los que presentaban una ofrenda de oro para Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Y cuantos tenían jacinto, púrpura escarlata y carmesí, lino fino, pelo de cabra, pieles de carnero teñidas de rojo y pieles de tejón, lo trajeron.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Todos los que podían presentar una ofrenda de plata y de bronce, la trajeron como tributo a Yahvé. También los que tenían madera de acacia para cualquier obra del servicio, la trajeron.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Y todas las mujeres diestras hilaron con sus manos y trajeron lo que habían hilado: jacinto, púrpura escarlata y carmesí y lino fino.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Y todas las mujeres que se sentían a ello impulsadas y que eran hábiles hilaron pelo de cabra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Los príncipes trajeron piedras de ónice y piedras de engaste para el efod y el pectoral;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'aromas y aceite para el alumbrado, para el óleo de la unción y para el incienso aromático.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Todos los hijos de Israel, hombres y mujeres, cuyo corazón los impulsaba a que trajesen algo para toda la obra que Yahvé por medio de Moisés, había mandado hacer; dieron así sus ofrendas voluntarias a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Dijo entonces Moisés a los hijos de Israel: “Mirad que Yahvé ha llamado por su nombre a Besalel, hijo de Urí, hijo de Hur, de la tribu de Judá,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'y le ha llenado de espíritu divino, de sabiduría, inteligencia y maestría en toda clase de trabajos,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'para idear diseños, labrar el oro, la plata y el bronce,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'grabar piedras de engaste, tallar madera y ejecutar toda obra de arte;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'y le ha puesto en el corazón el don de enseñar, lo mismo que a Oholiab, hijo de Ahisamac, de la tribu de Dan.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Él les ha llenado de sabiduría el corazón para hacer toda obra de escultor y artista, de recamador en jacinto y púrpura, carmesí y lino fino, y de tejedor, para ejecutar toda suerte de obra y para proyectar obras de arte.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Así, pues, Besalel y Oholiab y todos los hombres hábiles en cuyo corazón Yahvé ha infundido sabiduría e inteligencia para saber realizar todas las obras para el servicio del Santuario, las ejecutarán conforme al mandato de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'LIamó, pues, Moisés a Besalel y a Oholiab y a todos los hombres de talento en cuyo corazón Yahvé había infundido sabiduría, a todos los que voluntariamente estaban dispuestos a ponerse a la obra para realizarla.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Y recibieron de Moisés todas las ofrendas que los hijos de Israel habían traído para la ejecución de las obras del Santuario. Entretanto el pueblo siguió entregando a Moisés ofrendas voluntarias de mañana en mañana.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Por eso todos los artífices que hacían todas las obras del Santuario dejaron cada cual la obra que estaban haciendo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'y fueron a hablar con Moisés, diciendo: “El pueblo trae más de lo que se precisa para la realización de las obras que Yahvé ha mandado hacer.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Entonces Moisés hizo promulgar por el campamento: “Ni hombre ni mujer traiga ya más ofrendas para el Santuario.” Y se impidió al pueblo traer más;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'pues ya había material suficiente para ejecutar todas las obras y aun sobraba.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'Entonces todos los sabios de corazón de entre los que hacían la obra, fabricaron la Morada de diez cortinas de fino lino torzal, de color jacinto, púrpura escarlata y carmesí, con querubines. Resultó una obra maestra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'El largo de cada cortina era de veinte y ocho codos y la anchura de cada cortina de cuatro codos. Todas las cortinas tenían la misma medida.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, '(Besalel) unió cinco de las cortinas una con otra, y las otras cinco cortinas también las unió una con otra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'E hizo lazos de jacinto en el borde de la última cortina del primer conjunto; las hizo también en el borde extremo de las cortinas del segundo conjunto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Cincuenta lazos hizo en el primer conjunto, y cincuenta en el extremo del segundo conjunto allá donde se unen, correspondiéndose los lazos unos a otros.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Hizo también cincuenta broches de oro, y enlazó los conjuntos el uno con el otro, por medio de los broches, de modo que la Morada vino a ser una sola pieza.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Hizo también cortinas de pelo de cabra para que sirvan de tienda sobre la Morada. Once cortinas hizo para esto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'La longitud de cada cortina era de treinta codos, y de cuatro codos era la anchura de cada cortina. Una misma medida tenían las once cortinas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Enlazó cinco de las cortinas entre sí, y seis de las cortinas entre sí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Y puso cincuenta lazos en el borde del (primer) conjunto en el extremo donde se enlazan, y cincuenta lazos en el borde del segundo conjunto, donde se enlazan.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Hizo asimismo cincuenta broches de bronce a fin de unir el Tabernáculo; para que fuese un solo todo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Hizo además para el Tabernáculo una cubierta de pieles de carnero teñidas de rojo, y por encima una cubierta de pieles de tejón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Para la Morada hizo tablones de madera de acacia para colocarlos verticalmente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'Diez codos de largo tenía un tablón, y de codo y medio era el ancho de cada tablón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'Cada tablón tenía dos espigas unidas una con otra. Así hizo todos los tablones de la Morada.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Hizo, pues, los tablones para la Morada (de esta manera): veinte tablones para el lado del Négueb, hacia el sur,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'colocando debajo de los veinte tablones cuarenta basas de plata, dos basas debajo de un tablón para sus dos espigas; y dos basas debajo de los otros tablones para sus dos espigas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Para el otro flanco de la Morada, para el lado del norte, hizo también veinte tablones,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'con sus cuarenta basas de plata; dos basas debajo de un tablón, y dos asas debajo de los otros tablones.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Para la parte posterior de la Morada, hacia el occidente, hizo seis tablones;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'y dos tablones hizo para los ángulos de la Morada, en el fondo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'los cuales eran dobles desde abajo y formaban un conjunto hasta arriba, hasta el primer anillo. Así lo hizo con entrambos, en los dos ángulos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Eran, pues, ocho tablones, con sus basas de plata: diez y seis basas, dos basas bajo cada tablón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Después hizo travesaños de madera de acacia, cinco para los tablones de un costado de la Morada;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'y cinco travesaños para los tablones del otro costado de la Morada; y cinco travesaños para los tablones de la parte posterior de la Morada hacia el occidente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'E hizo el travesaño central de tal suerte que pasase en medio de los tablones, de un extremo al otro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Los tablones los revistió de oro, y de oro hizo también los anillos correspondientes, por los cuales habían de pasar los travesaños, revestidos igualmente de oro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Hizo también el velo de jacinto, púrpura escarlata, carmesí y lino fino torzal. Era una obra artística con motivos de querubines.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'Fabricó para el mismo cuatro columnas de acacia, que revistió de oro; también sus clavos eran de oro, y fundió para ellas cuatro basas de plata.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Hizo para la entrada del Tabernáculo una cortina de jacinto, púrpura escarlata, carmesí y lino fino torzal, obra de recamador,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'con sus cinco columnas y sus clavos, revistiendo de oro sus capiteles y sus anillos de oro y haciendo de bronce sus cinco basas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Besalel hizo el Arca de madera de acacia, de dos codos y medio de largo, de codo y medio de ancho, y de codo y medio de alto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'La Revistió de oro puro, por dentro y por fuera, e hizo para ella una guirnalda de oro alrededor.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Fundió para ella cuatro anillos de oro para sus cuatro pies, dos anillos a un lado y dos anillos al otro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Hizo también varas de madera de acacia, que revistió de oro;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'y pasó las varas por los anillos a los costados del Arca, para transportarla.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Después hizo un propiciatorio de oro puro, de dos codos y medio de largo y de codo y medio de ancho.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Hizo igualmente dos querubines de oro labrados a martillo para los dos extremos del propiciatorio;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'un querubín por un lado, y el otro querubín por el otro, de tal manera que (salieran) del propiciatorio en sus dos extremos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Estaban los querubines con las alas extendidas hacia arriba, cubriendo con ellas el propiciatorio. Tenían sus caras vueltas la una a la otra, pues las caras de los querubines se dirigían hacia el propiciatorio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Hizo, además, la mesa de madera de acacia, de dos codos de largo, de un codo de ancho y de codo y medio de alto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'La recubrió de oro puro, y puso alrededor de ella una guirnalda de oro,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'haciéndole, además, un borde a la redonda, del ancho de un palmo, y ornándole con una moldura alrededor.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Fundió para ella cuatro anillos de oro, y colocó los anillos en los cuatro ángulos, o sea en sus cuatro pies.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Junto al borde se hallaban los anillos por los cuales habían de pasar las varas para el transporte de la mesa.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Hizo también las varas para llevar la mesa de madera de acacia y las recubrió de oro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Asimismo fabricó de oro puro los utensilios que habían de estar sobre la mesa; sus platos, sus cucharas, sus copas y sus tazas, con que se hacían las libaciones.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Hizo el candelabro de oro puro; labrado a martillo hizo el candelabro. Su pie, su tallo, sus cálices, sus botones y sus flores eran de una sola pieza.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'De sus lados salían seis brazos: tres brazos de un lado del candelabro, y tres brazos del otro lado del candelabro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'En el primer brazo había tres cálices en forma de flor de almendro, con botón y flor; también en el segundo brazo había tres cálices, en forma de flor de almendro, con botón y flor, y así en los seis brazos que salían del candelabro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'En el (tallo del) candelabro había cuatro cálices, en forma de flor de almendro, con sus botones y sus flores:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'un botón debajo de los dos (primeros) brazos que salían de él, un botón debajo de los dos brazos (siguientes) que salían de él, y un botón debajo de los dos brazos (restantes) que salían de él, conforme a los seis brazos que salían del mismo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Sus botones y sus brazos formaban con él un solo cuerpo; todo ello era una pieza labrada a martillo, de oro puro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Hizo también sus siete lámparas, sus despabiladeras y sus platillos, de oro puro,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'empleando un talento de oro puro para el candelabro y todos sus utensilios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Hizo también de madera de acacia el altar del incienso, de un codo de largo y de un codo de ancho, cuadrado, y de dos codos de alto. Sus cuernos formaban con él una sola pieza.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Lo revistió de oro puro, por encima y por sus lados alrededor, y también sus cuernos. Le hizo también todo en torno una guirnalda de oro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Por debajo de la guirnalda, a sus dos lados, en ambos costados, hizo dos anillos de oro, por los cuales habían de pasar las varas, a fin de transportarlo con ellas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Hizo las varas de madera de acacia y las revistió de oro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Confeccionó también el óleo santo de la unción, y el incienso puro de especies aromáticas, con arte de perfumería.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Hizo el altar de los holocaustos de madera de acacia, de cinco codos de largo y de cinco codos de ancho, cuadrado; y de tres codos de alto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'En sus cuatro ángulos le puso cuernos que salían de él, y lo recubrió de bronce.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Hizo, además, todos los utensilios del altar: los recipientes, las palas, los tazones, los tenedores y los braseros. Todos sus utensilios los hizo de bronce.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Hizo para el altar una rejilla de bronce, a manera de red, en torno a su base, que llegaba hasta la mitad del mismo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'Y fundió cuatro anillos para los cuatro extremos de la rejilla de bronce, por donde habían de pasar las varas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Hizo las varas de madera de acacia, las recubrió de bronce,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'y pasó las varas por los anillos a los costados del altar, para transportarlo mediante ella. Lo hizo hueco y de tablas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Hizo la fuente de bronce, y también su base de bronce, de los espejos de las mujeres que servían a la entrada del tabernáculo de la Reunión.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Hizo también el atrio: por el lado meridional, a la derecha, las cortinas del atrio, de lino fino torzal, de cien codos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'Sus columnas eran veinte, y veinte sus basas de bronce; los corchetes de las columnas y sus anillos eran de plata.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Por el lado del norte había también (cortinas de) cien codos. Sus columnas eran veinte, y veinte sus basas de bronce; los corchetes de las columnas y sus anillos eran de plata.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'En el lado occidental había (cortinas de) cincuenta codos. Sus columnas eran diez, y diez sus basas; los corchetes de las columnas y sus anillos eran de plata.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'En el lado oriental, donde nace el sol, colgaban también cincuenta codos (de cortinas):');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'cortinas de quince codos, con tres columnas y tres basas, por un lado (de la entrada),');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'y de igual manera por el otro lado. A ambos lados de la entrada del atrio había cortinas de quince codos. Sus columnas eran tres, y tres sus basas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Todas las cortinas en torno al atrio eran de lino fino torzal.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'Las basas de las columnas eran de bronce, los corchetes de las columnas y sus anillos de plata. También sus capiteles estaban revestidos de plata, y todas las columnas del atrio llevaban anillos de plata.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'La cortina de la entrada del atrio era obra de recamador y estaba hecha de jacinto, púrpura escarlata, carmesí y lino fino torzal. Tenía veinte codos de largo; su altura correspondía a su anchura y era de cinco codos, lo mismo que las cortinas del atrio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'Sus cuatro columnas y sus cuatro basas eran de bronce; sus corchetes de plata, como también el revestimiento de sus capiteles y sus anillos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Todas las estacas de la Morada y del atrio que la rodeaba, eran de bronce.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Este es el inventario de la Morada, de la Morada del Testimonio, hecho por orden de Moisés por los levitas bajo la dirección de Itamar, hijo de Aarón, el sacerdote.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Besalel, hijo de Urí, hijo de Hur, de la tribu de Judá, hizo todo cuanto Yahvé había mandado a Moisés;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'juntamente con Oholiab, hijo de Ahisamac, de la tribu de Dan, que era artífice, diseñador y recamador en jacinto, púrpura escarlata y carmesí y lino fino.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'El total del oro empleado en la obra, en toda la construcción del Santuario, o sea, el oro de la ofrenda, fue veintinueve talentos y setecientos treinta siclos, según el peso del Santuario.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Y la plata de los empadronados de entre el pueblo, fue cien talentos y mil setecientos setenta y cinco siclos, según el peso del Santuario:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'un beka por cabeza, o sea medio siclo, según el peso del Santuario, para cada hombre comprendido en el censo, de los seiscientos tres mil quinientos cincuenta hombres de veinte años para arriba.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Los cien talentos de plata se emplearon para fundir las basas del Santuario y las basas del velo: cien basas correspondientes a los cien talentos, un talento por basa.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'De los mil setecientos setenta y cinco siclos hizo corchetes para las columnas, revistió sus capiteles y las unió mediante aros.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'El bronce de la ofrenda fue setenta talentos y dos mil cuatrocientos siclos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'De él hizo las basas para la entrada del Tabernáculo de la Reunión, el altar de bronce con su rejilla de bronce y todos los utensilios del altar,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'las basas del atrio alrededor del mismo y las basas de la entrada del atrio, todas las estacas de la Morada y todas las estacas del atrio que la rodeaba.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Hicieron para el servicio del Santuario vestiduras litúrgicas de jacinto, púrpura escarlata y carmesí. Hicieron también las vestiduras sagradas de Aarón, como Yahvé había mandado a Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Se hizo, pues, el efod, de oro, de jacinto, púrpura escarlata, carmesí y lino torzal.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Fabricaron láminas delgadas de oro y las cortaron en hilos, para entretejerlos con jacinto, púrpura escarlata y carmesí y con el lino fino, obra de recamador.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Le pusieron hombreras que se juntaban y se unían en sus dos extremos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'La faja del cinturón que pasaba sobre él y que servía para ceñir (el efod), formaba con él una sola pieza y era de la misma labor: oro, jacinto, púrpura escarlata, carmesí y lino fino torzal, como Yahvé lo había mandado a Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Labraban igualmente las piedras de ónice, engastadas en oro y grabadas como se graban los sellos, (doce) conforme a los nombres de los hijos de Israel;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'y las colocaron sobre las hombreras del efod, como piedras de recuerdo de los hijos de Israel, según Yahvé había ordenado a Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Hizo también el pectoral, obra primorosa, al estilo de la obra del efod, de oro, jacinto, púrpura escarlata, carmesí y lino fino torzal.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'El pectoral era cuadrado y doble; tenía un palmo de largo y un palmo de ancho y era doble.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Lo guarnecieron de cuatro filas de piedras. En la primera fila había un sardio, un topacio y una esmeralda;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'en la segunda fila: un rubí, un zafiro y un diamante;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'en la tercera fila: un jacinto, un ágata y una amatista;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'y en la cuarta: un crisólito, un ónice y un jaspe. Cada una de ellas tenía su engaste y estaba engarzada y guarnecida de oro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Las piedras eran doce, correspondientes a los nombres de los hijos de Israel, según sus nombres propios, grabados como se graban los sellos, cada una con su nombre, conforme a las doce tribus.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Fijaron sobre el pectoral cadenillas de oro puro, trenzadas a manera de cordones.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'E hicieron dos engastes de oro y dos anillos de oro, y pusieron los dos anillos a los dos extremos (superiores) del pectoral.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'Pasaron después las dos cadenillas de oro por los dos anillos a los extremos del pectoral.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Y los otros dos extremos de las dos cadenillas los ataron a los dos engastes, que colocaron en la parte delantera de las hombreras del efod.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Hicieron otros dos anillos de oro y los pusieron en los dos extremos (inferiores) del pectoral, en el borde interior vuelto hacia el efod.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'E hicieron dos anillos de oro, que fijaron a las dos hombreras del efod, por debajo y en su parte delantera, cerca de su juntura, por encima de la cinta del efod.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'Y por medio de sus anillos ataron el pectoral a los anillos del efod, con un cordón de jacinto, para que quedase fijo sobre la cinta del efod y no se desprendiese el pectoral del efod, como Yahvé había mandado a Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Hizo también la sobretúnica del efod, obra de tejedor, todo de jacinto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'Había una abertura en medio de la sobretúnica, semejante al cuello de una cota, con una orla alrededor de la abertura para que no se rompiese.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'En el borde inferior de la sobretúnica aplicaron granadas de jacinto, púrpura escarlata, carmesí y lino fino torzal.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Hicieron, además, campanillas de oro puro, colocándolas entre las granadas en el borde inferior de la sobretúnica, en medio de las granadas, todo alrededor suyo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'Una campanilla y una granada alternaba con otra campanilla y otra granada en el borde inferior de la sobretúnica, todo en derredor. (Así se usaba) para el ministerio, como Yahvé ordenara a Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Hicieron también las túnicas de lino fino, obra de tejedor, para Aarón y sus hijos;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'y la mitra de lino fino, las cintas de los turbantes de lino fino, y también los calzoncillos de lino fino torcido,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'lo mismo que el cinturón de lino fino torcido, de jacinto, púrpura escarlata y carmesí, obra de recamador, como Yahvé había ordenado a Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'E hicieron de oro puro la lámina, la diadema sagrada, en la cual grabaron, como se graban los sellos: Santidad a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Y fijaron en ella una cinta de jacinto para ponerla sobre la mitra, por la parte de arriba, como Yahvé había mandado a Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'Así fue acabada toda la obra de la Morada y del Tabernáculo de la Reunión, y los hijos de Israel hicieron todo conforme a lo que había mandado Yahvé a Moisés. Así lo hicieron.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'Luego presentaron a Moisés la Morada, el Tabernáculo y todos sus utensilios; sus ganchos, sus tablones, sus travesaños, sus columnas y sus basas;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'la cubierta de pieles de carnero teñidas de rojo, la cubierta de pieles de tejón y la cortina del velo;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'el Arca del Testimonio con sus varas y el propiciatorio;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'la mesa con todos sus utensilios, y el pan de la proposición;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'el candelabro (de oro) puro con sus lámparas —las lámparas que habían de colocarse en él—, todos sus utensilios y el aceite del alumbrado;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'el altar de oro, el óleo de la unción, el incienso aromático y la cortina para la entrada del Tabernáculo;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'el altar de bronce con su rejilla de bronce, sus varas y todos sus utensilios; la pila con su base;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'las cortinas del atrio, sus columnas con sus basas, la cortina para la entrada del atrio, sus cuerdas, sus estacas y todos los utensilios del servicio de la Morada para el Tabernáculo de la Reunión;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'las vestiduras litúrgicas para el servicio en el Santuario, los ornamentos sagrados para el sacerdote Aarón, y las vestiduras de sus hijos para ejercer el sacerdocio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Conforme a cuanto Yahvé había ordenado a Moisés, así hicieron los hijos de Israel toda la obra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Moisés vio toda la obra y reconoció que la habían llevado a cabo; tal como había mandado Moisés, así la habían hecho; y Moisés los bendijo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Habló Yahvé a Moisés y dijo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, '“El día primero del primer mes erigirás la Morada del Tabernáculo de la Reunión.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'Pondrás allí el Arca del Testimonio y cubrirás el Arca con el velo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Introducirás la mesa y dispondrás lo que hay que poner sobre ella; colocarás también el candelabro y ubicarás en él las lámparas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Erigirás el altar de oro para el incienso delante del Arca del Testimonio y pondrás la cortina a la entrada del Tabernáculo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Colocarás el altar de los holocaustos delante de la entrada de la Morada del Tabernáculo de la Reunión.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Pondrás la pila entre el Tabernáculo de la Reunión y el altar, y echarás agua en ella,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'levantarás el atrio en derredor y tenderás la cortina a la entrada del atrio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Y tomarás el óleo de la unción y ungirás la Morada y todo lo que hay en ella. La consagrarás con todos sus utensilios para que sea santa.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Ungirás también el altar de los holocaustos con todos sus utensilios. Consagrarás el altar, y el altar será cosa santísima.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Asimismo ungirás la pila y su base, y la consagrarás.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Después dispondrás que Aarón y sus hijos se presenten a la entrada del Tabernáculo de la Reunión y los lavarás con agua.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'Y vestirás a Aarón con las vestiduras sagradas, le ungirás y le consagrarás para que me sirva de sacerdote.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Harás también que se presenten sus hijos; los vestirás con túnicas');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'y los ungirás, como ungiste a su padre, para que me sirvan de sacerdotes. Su unción les conferirá el sacerdocio sempiterno entre sus descendientes.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Hizo Moisés conforme a todo lo que Yahvé le había mandado. Así lo hizo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'En el primer mes del año segundo, el día primero del mes, fue erigida la Morada.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Moisés alzó la Morada, asentó sus basas, colocó sus tablones, metió sus travesaños y erigió sus columnas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Después extendió el Tabernáculo por encima de la Morada y puso sobre ella, por la parte de arriba, la cubierta del Tabernáculo, como Yahvé había mandado a Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Luego tomó el Testimonio y lo depositó dentro del Arca; acomodó las varas al Arca y asentó sobre ella el propiciatorio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'Metió el Arca en la Morada, colgó la cortina del velo y ocultó el Arca del Testimonio, como Yahvé había mandado a Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Colocó también la mesa en el Tabernáculo de la Reunión, al lado septentrional de la Morada, fuera del velo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'Y dispuso sobre ella los panes delante de Yahvé, así como Yahvé ordenara a Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Luego instaló el candelabro en el Tabernáculo de la Reunión, frente a la mesa, en el lado meridional de la Morada,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'y colocó las lámparas delante de Yahvé, como Yahvé había mandado a Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Asimismo erigió el altar de oro en el Tabernáculo de la Reunión, delante del velo;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'y quemó sobre él incienso aromático, como Yahvé había mandado a Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Tendió la cortina a la entrada de la Morada,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'y colocó también el altar de los holocaustos a la entrada de la Morada del Tabernáculo de la Reunión; y ofreció sobre él el holocausto y la ofrenda, como Yahvé había mandado a Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'La pila la colocó entre el Tabernáculo de la Reunión y el altar, y echó en ella agua para las abluciones;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'y Moisés y Aarón y los hijos de este se lavaron en ella sus manos y sus pies.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'Siempre que entraban en el Tabernáculo de la Reunión, y siempre que se acercaban al altar, se lavaban, como Yahvé había mandado a Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Por fin erigió el atrio alrededor de la Morada y del altar, y puso la cortina a la puerta del atrio. Así acabó Moisés la obra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Entonces la nube cubrió el Tabernáculo de la Reunión y la gloria de Yahvé llenó la Morada,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'de modo que Moisés no pudo entrar en el Tabernáculo de la Reunión, pues la nube descansaba sobre este, y la gloria de Yahvé llenaba la Morada.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'En todas sus marchas los hijos de Israel levantaban el campamento cuando la nube se alzaba de encima de la Morada. Y si la nube no se levantaba, no marchaban, hasta el día en que se levantaba. Porque durante el día estaba sobre la Morada la nube de Yahvé, en la cual durante la noche había fuego, viéndolo toda la casa de Israel en todas sus marchas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Llamó Yahvé a Moisés y le habló desde el Tabernáculo de la Reunión, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, '“Habla a los hijos de Israel y diles: Cuando alguno de vosotros quisiere presentar a Yahvé una ofrenda de animales, ofreceréis una res del ganado mayor o del ganado menor.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Si su ofrenda es holocausto de ganado mayor, presentará un macho sin tacha. A la entrada del Tabernáculo de la Reunión lo presentará para que sea grato delante de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'Pondrá su mano sobre la cabeza del holocausto, y será acepto para expiación suya.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Luego degollará el becerro delante de Yahvé; y los hijos de Aarón, los sacerdotes, ofrecerán la sangre, derramándola sobre todos los costados del altar que está a la entrada del Tabernáculo de la Reunión.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Después será desollado el holocausto y cortado en trozos,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'y los hijos de Aarón, los sacerdotes, pondrán fuego en el altar y dispondrán la leña sobre el fuego.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Luego los hijos de Aarón, los sacerdotes, dispondrán los trozos, juntamente con la cabeza y el sebo, sobre la leña que hay sobre el fuego encima del altar;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'y después de lavar con agua las entrañas y las patas, el sacerdote lo quemará todo sobre el altar. Es holocausto, sacrificio de combustión, de olor grato a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Si su ofrenda es de ganado menor, tomada de las ovejas o de las cabras, ofrecerá como holocausto un macho sin tacha.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'Lo degollará al lado septentrional del altar, delante de Yahvé; y los hijos de Aarón, los sacerdotes, derramarán su sangre sobre todos los costados del altar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'Lo cortarán en trozos, y junto con la cabeza y el sebo lo ordenará el sacerdote sobre la leña dispuesta sobre el fuego encima del altar;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'y luego de lavar con agua las entrañas y las patas, el sacerdote lo ofrecerá todo, y lo quemará sobre el altar. Es holocausto, sacrificio de combustión, de olor grato a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Cuando ofrezca a Yahvé un holocausto de aves, será su ofrenda de tórtolas o de palominos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'El sacerdote la llevará al altar y después de retorcerle con las uñas la cabeza la quemará sobre el altar y se hará gotear su sangre sobre el borde del altar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Le quitará el buche con sus suciedades y lo tirará junto al altar, al lado oriental, en el lugar de las cenizas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'Después le quebrantará las alas, pero sin separarlas, y el sacerdote la quemará sobre el altar, encima de la leña dispuesta sobre el fuego. Es un holocausto, sacrificio de combustión, de olor grato a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Cuando alguno presentare una ofrenda en homenaje a Yahvé, su oblación será de flor de harina, sobre la cual derramará aceite y pondrá incienso.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'La llevará a los sacerdotes, hijos de Aarón, y (el sacerdote) tomará de allí un puñado de la flor de harina con el aceite, y todo el incienso, y lo quemará sobre el altar para recuerdo. Es un sacrificio de combustión, de olor grato a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Lo restante de la ofrenda será para Aarón y sus hijos. Es cosa santísima entre las ofrendas quemadas en honor de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Si ofrecieres como oblación una cosa cocida al horno, será de tortas ácimas de flor de harina amasadas con aceite o de galletas ácimas untadas con aceite.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Y si tu oblación fuere ofrenda hecha en sartén, será de flor de harina, sin levadura, amasada con aceite;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'la desmenuzarás, y derramarás sobre ella aceite; pues es ofrenda.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Y si tu oblación fuere ofrenda cocida en olla, será de flor de harina con aceite,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'elevarás la ofrenda así preparada a Yahvé y la entregarás al sacerdote, el cual la llevará al altar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'El sacerdote tomará de la ofrenda la parte destinada para recuerdo y la quemará sobre el altar. Es un sacrificio de combustión, de olor grato a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Lo restante de la ofrenda será para Aarón y sus hijos; es cosa santísima entre los sacrificios quemados en honor de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Ninguna ofrenda que presentareis a Yahvé sea hecha con levadura, pues ninguna cosa hecha con levadura, ni que contenga miel, sea quemada como sacrificio ígneo en honor de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Podréis presentarlas como oblación de primicias a Yahvé; pero no han de ponerse sobre el altar como (sacrificio de) olor grato.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Sazonarás con sal toda oblación de tus ofrendas. Nunca dejarás que falte en tus ofrendas la sal de la alianza de tu Dios. Con todas tus oblaciones ofrecerás sal.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, '“Si presentares a Yahvé ofrenda de primicias, ofrecerás espigas tostadas al fuego, o granos machacados, como oblación de tus primicias.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'Sobre ellas derramarás aceite y pondrás incienso, porque es ofrenda.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'El sacerdote quemará del grano machacado y del aceite la porción destinada para recuerdo con todo el incienso. Es sacrificio de combustión en honor de Yahvé.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, '“Quien presentare como oblación un sacrificio pacífico, si la ofrece del ganado mayor, sea macho o hembra la presentará sin tacha delante de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Pondrá su mano sobre la cabeza de la víctima, que degollará a la entrada del Tabernáculo de la Reunión y cuya sangre derramarán los hijos de Aarón, los sacerdotes, sobre todos los costados del altar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Del sacrificio pacífico ofrecerá a Yahvé, quemándolo en el fuego, el sebo que cubre las entrañas, todo el sebo que está adherido a las entrañas,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'los dos riñones, con el sebo que los cubre, el que hay sobre los ijares, y la telilla del hígado, que cortará de junto a los riñones.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Los hijos de Aarón lo quemarán en el altar, encima del holocausto puesto sobre la leña, debajo de la cual arde el fuego. Es sacrificio consumido por el fuego, olor grato a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Quien ofreciere a Yahvé un sacrificio pacífico del ganado menor, sea macho o hembra, lo presentará sin tacha.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Si ofrece como sacrificio suyo un cordero lo presentará ante Yahvé,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'pondrá su mano sobre la cabeza de la víctima la degollará delante del Tabernáculo de la reunión, y los hijos de Aarón derramarán la sangre sobre todos los costados del altar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'De este sacrificio pacífico ofrecerá (el oferente) a Yahvé, como sacrificio de combustión, el sebo y la cola entera, cortándola desde el espinazo, el sebo que cubre las entrañas, todo el sebo que está adherido a las entrañas,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'los dos riñones con el sebo que los cubre, el que hay sobre los ijares, y la telilla del hígado, que cortará de junto a los riñones.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'El sacerdote quemará esto sobre el altar; es alimento del sacrificio de combustión ofrecido a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Si ofreciere en sacrificio una cabra, la presentará ante Yahvé,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'pondrá su mano sobre la cabeza de la misma y la degollará delante del Tabernáculo de la Reunión; y los hijos de Aarón derramarán la sangre sobre todos los costados del altar:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'De ella ofrecerá a Yahvé, como sacrificio de combustión, el sebo que cubre las entrañas, todo el sebo adherido a las entrañas,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'los dos riñones con el sebo que los cubre, el que hay sobre los ijares, y la telilla del hígado, que cortará de junto a los riñones.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'El sacerdote quemará esto sobre el altar; es alimento del sacrificio de combustión, de olor grato. Toda la grasa pertenece a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Ley perpetua es esta para vuestros descendientes. En todas vuestras moradas no comeréis ni grasa ni sangre.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, '“Habla a los hijos de Israel y diles: Si alguno pecare por ignorancia haciendo algo prohibido por las leyes de Yahvé, y cometiendo alguna de aquellas cosas;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'si el que peca es el sacerdote ungido, que de este modo hace culpable al pueblo, ofrecerá a Yahvé por el pecado cometido un becerro sin tacha, como sacrificio por el pecado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Conducirá el becerro a la entrada del Tabernáculo de la Reunión, ante Yahvé, pondrá su mano sobre la cabeza del becerro y lo inmolará delante de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'El sacerdote ungido tomará de la sangre del becerro, y la llevará al Tabernáculo de la Reunión;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'y mojará el sacerdote su dedo en la sangre y hará con ella siete aspersiones ante Yahvé, hacia el velo del Santuario.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'El sacerdote untará también con la sangre los cuernos del altar del incienso aromático, que está delante de Yahvé en el Tabernáculo de la Reunión; y derramará toda la sangre del becerro al pie del altar de los holocaustos, que está a la entrada del Tabernáculo de la Reunión.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Después tomará todo el sebo del becerro inmolado por el pecado, el sebo que cubre las entrañas, todo el sebo que está adherido a las entrañas,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'los dos riñones, el sebo que los cubre, el que hay sobre los ijares, y la telilla del hígado, que cortará de junto a los riñones;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'es decir, lo mismo que se toma en el becerro del sacrificio pacífico; y el sacerdote lo quemará sobre el altar de los holocaustos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Mas el cuero del becerro y toda su carne, junto con su cabeza y sus piernas, con sus entrañas y sus excrementos,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'el becerro entero, lo sacará fuera del campamento a un lugar limpio, donde se echan las cenizas, y lo quemará sobre la leña. Será quemado allí donde se echan las cenizas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Si todo el pueblo de Israel pecare por ignorancia, sin que la asamblea se dé cuenta de ello, de modo que hiciera una cosa prohibida por las leyes de Yahvé, haciéndose así culpable,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'cuando se conozca el pecado cometido, ofrecerá la asamblea un becerro en sacrificio por el pecado, que presentarán delante del Tabernáculo de la Reunión.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'Y los ancianos del pueblo pondrán sus manos sobre la cabeza del becerro, ante Yahvé; y será inmolado el becerro delante de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Después el sacerdote ungido llevará parte de la sangre del becerro al Tabernáculo de la Reunión;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'y mojará el sacerdote su dedo en la sangre y hará siete aspersiones ante Yahvé hacia el velo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Untará también con la sangre los cuernos del altar que está delante de Yahvé y que se halla en el Tabernáculo de la Reunión; y después verterá toda la sangre al pie del altar de los holocaustos, que está a la entrada del Tabernáculo de la Reunión.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Le quitará todo su sebo y lo quemará sobre el altar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'Hará, pues, con este becerro lo mismo que hizo con el becerro inmolado por el pecado. Así hará con él. De este modo el sacerdote hará expiación por ellos y serán reconciliados.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Luego sacará el becerro fuera del campamento y lo quemará como quemó el becerro primero. Este es el sacrificio por el pecado de toda la asamblea.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Cuando un príncipe pecare por ignorancia, cometiendo algo prohibido por las leyes de Yahvé, haciéndose así culpable,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'tan pronto como se diere cuenta del pecado que cometió, dará como ofrenda suya un macho cabrío sin tacha,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'pondrá su mano sobre la cabeza del macho cabrío y lo degollará en el lugar donde se degüella el holocausto, delante de Yahvé. Es sacrificio por el pecado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Después el sacerdote con su dedo tomará de la sangre del sacrificio por el pecado, y la pondrá sobre los cuernos del altar de los holocaustos; la sangre (restante) la derramará al pie del altar de los holocaustos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Quemará todo el sebo en el altar, del mismo modo que quemó el sebo de los sacrificios pacíficos. Así el sacerdote hará expiación por el pecado del (príncipe) y le será perdonado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Si alguno del pueblo pecare por ignorancia, transgrediendo alguna de las prohibiciones de Yahvé, haciéndose así culpable,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'al darse cuenta del pecado cometido, dará como ofrenda por el pecado cometido una cabra, hembra, sin tacha,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'pondrá su mano sobre la cabeza del sacrificio por el pecado y la degollará en el lugar donde se degüellan los holocaustos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Después tomará el sacerdote con su dedo de esta sangre, la pondrá sobre los cuernos del altar de los holocaustos y derramará todo (el resto de) la sangre al pie del altar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Luego tomará todo el sebo de la víctima, como se hace en los sacrificios pacíficos; y el sacerdote lo quemará en el altar, como olor grato a Yahvé. Así le expiará el sacerdote y le será perdonado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Si trajere como ofrenda suya por el pecado un cordero, ha de ser hembra sin tacha;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'pondrá su mano sobre la cabeza de la víctima por el pecado y la degollará, como sacrificio por el pecado en el lugar donde se degüellan los holocaustos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Después tomará el sacerdote con su dedo de la sangre de la víctima por el pecado y la pondrá sobre los cuernos del altar de los holocaustos; toda la (demás) sangre la derramará al pie del altar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Luego tomará todo el sebo de la víctima, como se hace con el cordero en los sacrificios pacíficos, y el sacerdote lo quemará en el altar, junto con los sacrificios que se queman en honor de Yahvé. Así el sacerdote hará expiación por él, por el pecado cometido, y este le será perdonado.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, '“Si alguno pecare porque habiendo oído una imprecación y sido testigo de una cosa, sea porque la vio, o sea porque la supo, y no la denunció, llevará su iniquidad.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'O si alguno sin darse cuenta tocare cosa inmunda, sea el cadáver de una fiera inmunda, o el cadáver de un animal doméstico, o el cadáver de un reptil inmundo, se hace inmundo y culpable él mismo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'O si tocare, por inadvertencia, cualquier inmundicia de hombre, con la que uno se puede contaminar, tan pronto como llegue a saberlo, será reo de culpa.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'O si alguno con sus labios jurare inconsideradamente hacer mal o hacer bien, en una de esas cosas en que los hombres suelen jurar inconsideradamente, y no se da cuenta, tan pronto como llegue a saberlo, se hará culpable de la cosa respectiva.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'Quienquiera que fuere culpable de una de estas cosas, confesará aquello en que ha pecado;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'y para expiación del pecado cometido ofrecerá a Yahvé una hembra del ganado menor, oveja o cabra, como sacrificio por el pecado; y el sacerdote hará por él expiación de su pecado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Cuando sus recursos no alcancen para una oveja, presentará a Yahvé, como sacrificio por su pecado, dos tórtolas o dos palominos, uno como sacrificio por el pecado y otro en holocausto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Los llevará al sacerdote, quien ofrecerá primero el que se ofrece por el pecado. Con las uñas le retorcerá la cabeza cerca del cuello sin arrancarla.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'Y derramará parte de la sangre del sacrificio expiatorio contra la pared del altar; y lo restante de la sangre la hará gotear al pie del altar, pues es sacrificio por el pecado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Luego ofrecerá el segundo en holocausto, conforme al rito. Así el sacerdote le expiará por el pecado cometido y este le será perdonado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Si no tuviere lo suficiente para dos tórtolas o dos palominos, presentará, como ofrenda suya por el pecado, la décima parte de una efa de flor de harina en sacrificio expiatorio. No añadirá aceite, ni echará sobre ella incienso, porque es sacrificio por el pecado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'La llevará al sacerdote; y el sacerdote tomando de ella un puñado, para recuerdo, la quemará en el altar, encima de los sacrificios consumidos por el fuego en honor de Yahvé. Es sacrificio por el pecado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'Y el sacerdote hará expiación por él, por el pecado que cometió en alguna de aquellas cosas, y se le perdonará. Y (el resto) pertenecerá al sacerdote, como en oblación.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Y habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, '“Si uno comete infidelidad y peca por inadvertencia contra las cosas santas que pertenecen a Yahvé, ofrecerá a Yahvé, como sacrificio por su delito, un carnero del rebaño, sin tacha, estimado según tu valuación en dos siclos, conforme al peso del Santuario.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'Y restituirá lo que defraudó de la cosa santa, añadiéndole una quinta parte, y lo dará al sacerdote, el cual hará por él la expiación con el carnero del sacrificio por el delito y se le perdonará.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Quien pecare sin darse cuenta, haciendo algo prohibido por los mandamientos de Yahvé; será culpable y llevará su iniquidad.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'Llevará al sacerdote, como sacrificio por el delito, un carnero del rebaño, sin tacha, según tu valuación; y el sacerdote hará expiación por el error que cometió sin saberlo, y se le perdonará.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Es sacrificio expiatorio, pues pecó indudablemente contra Yahvé.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Y habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, '“Quien pecare y cometiere infidelidad contra Yahvé, negando a su compañero (la devolución de) un depósito, o de una prenda puesta en sus manos, o de una cosa robada, o haciendo violencia a uno de su pueblo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'o hallare una cosa perdida y mintiere respecto de ella, jurando en falso, en una de las cosas en que los hombres suelen pecar;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'cuando así pecare, haciéndose culpable, devolverá lo robado, o lo apropiado con violencia, o el depósito que se le confió, o la cosa perdida que halló,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'o todo aquello sobre lo cual juró en falso. Lo restituirá íntegramente, con el recargo de una quinta parte, y lo devolverá a su dueño en el día de su sacrificio expiatorio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Y entregará al sacerdote para Yahvé, como sacrificio por su culpa, un carnero del rebaño, sin tacha, según tu valuación.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'El sacerdote hará por él la expiación delante de Yahvé; y le será perdonada cualquier culpa en que haya incurrido.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, '“Manda a Aarón y a sus hijos y diles: Esta es la ley del holocausto: El holocausto estará en el altar sobre el fuego encendido toda la noche hasta la mañana, sin que el fuego del altar se apague.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'El sacerdote se vestirá su túnica de lino y puestos sobre su carne los calzoncillos de lino, sacará las cenizas a que el fuego habrá reducido el holocausto sobre el altar, y las depositará al lado del altar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Después se quitará los vestidos y se pondrá otros para llevar las cenizas fuera del campamento a un lugar puro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'El fuego arderá siempre en el altar sin apagarse; el sacerdote lo cebará con leña todas las mañanas, dispondrá encima el holocausto y quemará sobre él el sebo de los sacrificios pacíficos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'Es un fuego que ha de arder perpetuamente sobre el altar, sin apagarse jamás.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, '“Esta es la ley de la oblación. Los hijos de Aarón la presentarán delante de Yahvé, frente al altar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'El (sacerdote) tomará de la oblación un puñado de flor de harina con su aceite, y todo el incienso puesto sobre la oblación, y lo quemará en el altar, para recuerdo, como olor grato a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'El resto de ella lo comerán Aarón y sus hijos; debe comerse sin levadura en lugar santo. En el atrio del Tabernáculo de la Reunión han de comerlo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'No se la cocerá con levadura. Es la porción que Yo les doy de lo que se me ofrece para ser consumido por el fuego. Es cosa sacratísima, como el sacrificio por el pecado y como el sacrificio por el delito.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Todos los varones de los hijos de Aarón comerán de ello. Es ley perpetua de generación en generación con respecto a las ofrendas hechas a Yahvé por el fuego. Todo el que las tocare quedará santificado.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Y habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, '“Esta es la oblación que Aarón y sus hijos presentarán a Yahvé el día de su unción: la décima parte de un efa de flor de harina. Es oblación perpetua, la mitad por la mañana, y la mitad por la tarde.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'Será preparada con aceite en la sartén; bien frita la ofrecerás; como oblación partida en trozos la presentarás como olor grato a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'También el Sumo Sacerdote que le suceda de entre sus hijos, la ofrecerá. Y es precepto perpetuo de Yahvé que sea totalmente quemada.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Toda oblación de sacerdote será totalmente quemada; no se comerá.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, 'Habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, '“Habla a Aarón y a sus hijos y diles: Esta es la ley del sacrificio por el pecado: En el lugar donde se degüella el holocausto, delante de Yahvé, será degollada también la víctima por el pecado. Es cosa santísima.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, 'El sacerdote que ofrece la víctima por el pecado la comerá. La comerá en lugar santo, en el atrio del Tabernáculo de la Reunión.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, 'Todo el que tocare esta carne será santificado, y si una gota de su sangre cayere sobre un vestido, lavarás en lugar santo la parte manchada por la sangre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'La vasija de barro en que haya sido cocida será quebrada; y si fuere cocida en vasija de cobre, se la fregará y lavará con agua.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, 'Todos los varones de entre los sacerdotes podrán comer de ella. Es cosa santísima.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, 'Mas no se comerá ninguna víctima ofrecida por el pecado, cuando parte de su sangre haya de llevarse al Tabernáculo de la Reunión para hacer la expiación en el Santuario. Será quemada en el fuego.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Esta es la ley del sacrificio por el delito. Es cosa santísima.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'En el lugar donde se inmola el holocausto, será inmolada la víctima por el delito, y su sangre será derramada sobre el altar todo en derredor.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Se ofrecerá de ella todo el sebo, la cola, el sebo que cubre las entrañas,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'los dos riñones, el sebo que los cubre, el que está sobre los ijares, y la telilla del hígado, que se cortará de junto a los riñones.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'El sacerdote lo quemará sobre el altar, como sacrificio que se ofrece a Yahvé por el fuego. Este es el sacrificio por el delito.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Todos los varones de entre los sacerdotes podrán comerlo; en lugar sagrado se lo comerá. Es cosa santísima.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'El sacrificio por el pecado y el sacrificio por el delito se rigen por la misma ley. La víctima pertenece al sacerdote que hace la expiación con ella.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'El sacerdote que ofrece el holocausto de una persona, se quedará con la piel de la víctima que haya ofrecido.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'También toda oblación cocida al horno, y toda preparada en cazuela o en sartén, es del sacerdote que la ofrece.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Mas toda oblación amasada con aceite, o seca, será de todos los hijos de Aarón, en porciones iguales.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, '“Esta es la ley del sacrificio pacífico que se ofrece a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Si se ofrece en acción de gracias, se ofrecerán, juntamente con el sacrificio de acción de gracias, tortas sin levadura amasadas con aceite, galletas ácimas untadas de aceite y tortas de flor de harina amasadas con aceite.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Además de las tortas podrán ofrecerse como oblación, pan fermentado, juntamente con su sacrificio pacífico de acción de gracias.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'Se presentará a Yahvé una porción de cada una de estas oblaciones, como ofrenda alzada, que corresponderá al sacerdote que derramare la sangre del sacrificio pacífico.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'La carne del sacrificio pacífico en acción de gracias será comida en el día de su oblación, sin dejar nada de ella para el día siguiente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Si el sacrificio se ofrece en cumplimiento de un voto, o como oblación voluntaria, se comerá el día mismo en que fuere ofrecido, y lo que de él sobrare podrá comerse al día siguiente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Mas lo que de la carne del sacrificio quedare hasta el tercer día, será quemada.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Si alguno comiere de la carne de su sacrificio pacífico el día tercero; su sacrificio no será acepto; no se le computará al oferente del mismo; antes será abominación; y el que comiere de ella llevará su iniquidad.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'La carne que tocare cualquier cosa inmunda no podrá comerse; será entregada al fuego. Mas la carne (incontaminada) cualquier persona pura podrá comerla.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Quien, siendo impuro, coma carne del sacrificio pacífico presentado a Yahvé, será exterminado de entre su pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Y el que tocare cualquier cosa inmunda, por ejemplo, inmundicia de hombre, o bestia inmunda, o inmundicia de cualquier otra abominación impura, y luego comiere de la carne del sacrificio pacífico ofrecido a Yahvé, será extirpado de entre su pueblo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, '“Habla a los hijos de Israel y diles: No comeréis sebo de buey, ni de oveja, ni de cabra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'El sebo de animal muerto o destrozado (por fieras) podrá servir para cualquier uso, pero en modo alguno lo comeréis.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Porque todo aquel que coma sebo de animal que suele quemarse en honor de Yahvé, será extirpado de entre su pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Tampoco comeréis sangre, ni de ave, ni de cuadrúpedo, en ninguno de los lugares en que habitareis.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Todo el que comiere cualquier clase de sangre, será extirpado de entre su pueblo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, '“Habla a los hijos de Israel y diles: Quien ofreciere a Yahvé su sacrificio pacífico, entregue a Yahvé una porción de su sacrificio pacífico.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Con sus mismas manos ofrecerá lo que se ha de quemar en honor de Yahvé: presentará él mismo el sebo y el pecho; el pecho para mecerlo como ofrenda mecida ante Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'El sacerdote quemará el sebo del sacrificio en el altar, el pecho, empero, será para Aarón y sus hijos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'También daréis al sacerdote, como ofrenda alzada, la pierna derecha de vuestros sacrificios pacíficos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Aquel de los hijos de Aarón que ofrezca la sangre de los sacrificios pacíficos y el sebo, tendrá la pierna derecha como porción.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Pues Yo tomo de los sacrificios pacíficos de los hijos de Israel el pecho mecido y la espaldilla alzada, y se los doy al sacerdote Aarón y a sus hijos como derecho perpetuo de parte de los hijos de Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Esta es la porción de Aarón y la de sus hijos, que les corresponde de los sacrificios que se queman en honor de Yahvé, desde el día en que los constituyó sacerdotes de Yahvé.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'Por lo cual mandó Yahvé que los hijos de Israel les dieran esto desde el día en que los ungió, como derecho perpetuo de generación en generación.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Tal es la ley del holocausto, de la oblación, del sacrificio por el pecado, del sacrificio por el delito, de la consagración y del sacrificio pacífico,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'que Yahvé prescribió a Moisés en el monte Sinaí, el día en que mandó a los hijos de Israel que ofrecieran sus oblaciones a Yahvé en el desierto de Sinaí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, '“Toma a Aarón, y con él a sus hijos, y también las vestiduras, el óleo de la unción, el becerro para el sacrificio por el pecado, los dos carneros, y el canasto de los ácimos;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'y reúne a toda la comunidad a la entrada del Tabernáculo de la Reunión.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Moisés hizo como Yahvé le había mandado, y se reunió la comunidad a la entrada del Tabernáculo de la Reunión.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Y dijo Moisés a la asamblea: “Esto es lo que Yahvé ha ordenado que se haga.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Entonces mandó Moisés que se acercaran Aarón y sus hijos y los lavó con agua.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'Puso (sobre Aarón) la túnica, le ciñó con el cinturón y le vistió con el manto, poniéndole encima el efod, que le ciñó con el cinturón del efod para atárselo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Luego le puso el pectoral, en el cual depositó los Urim y Tummim.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Colocó también la mitra sobre su cabeza y puso al frente de ella la lámina de oro, la diadema santa, como Yahvé había mandado a Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Después tomó Moisés el óleo de la unción y ungió la Morada, con todas las cosas que había en ella, para consagrarlas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'Con parte de él roció siete veces el altar y lo ungió con todos sus utensilios, como también la pila con su base, para consagrarlos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Y derramando parte del óleo de la unción sobre la cabeza de Aarón, lo ungió para consagrarlo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Luego mandó Moisés que se acercaran los hijos de Aarón, a los cuales vistió con las túnicas, les ciñó el cinturón y les ató los turbantes, como Yahvé había mandado a Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Después hizo traer el becerro para el sacrificio por el pecado, y Aarón y sus hijos pusieron sus manos sobre la cabeza del becerro del sacrificio por el pecado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Moisés lo degolló; y tomando de la sangre la puso con su dedo sobre los cuernos del altar, todo en torno, para purificarlo del pecado. Después derramó la sangre al pie del altar; de esta manera lo consagró haciendo sobre él la expiación.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Tomó luego todo el sebo que cubre las entrañas, la telilla del hígado y los dos riñones con su sebo; y lo quemó Moisés sobre el altar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Mas el becerro con su piel, su carne y sus excrementos, lo quemó fuera del campamento, como Yahvé había ordenado a Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Después hizo traer el carnero del holocausto, sobre cuya cabeza Aarón y sus hijos pusieron las manos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Moisés lo degolló y roció con la sangre el altar por todos lados.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'El carnero fue descuartizado, y Moisés quemó la cabeza, los trozos y el sebo;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'y después de lavarlas en agua también las entrañas y las patas, de manera que Moisés quemó todo el carnero sobre el altar, como holocausto de olor grato, un sacrificio de combustión en honor de Yahvé, como Yahvé había mandado a Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Hizo luego traer el segundo carnero, el carnero de la consagración, y Aarón y sus hijos pusieron sus manos sobre la cabeza del carnero.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Moisés lo degolló, y tomando de su sangre la puso sobre el lóbulo de la oreja derecha de Aarón, sobre el pulgar de su mano derecha y sobre el dedo gordo de su pie derecho.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Después hizo Moisés acercar a los hijos de Aarón, les untó con la sangre el lóbulo de la oreja derecha, el pulgar de la mano derecha y el dedo gordo del pie derecho y derramó la sangre sobre el altar todo en derredor.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Tomó luego el sebo, la cola, todo el sebo que cubre las entrañas, la telilla del hígado, los dos riñones con su sebo y la espaldilla derecha,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'sacó del canasto de los ácimos que estaba ante Yahvé, una torta de pan ácimo, una torta de pan de aceite y una galleta y las puso sobre el sebo y sobre la espaldilla derecha.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'Entregó todo esto en las manos de Aarón y en las manos de sus hijos, haciéndolo mecer como ofrenda ante Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Recibiéndolo otra vez de manos de ellos Moisés lo quemó en el altar, encima del holocausto, como sacrificio de consagración, de olor grato, como sacrificio de combustión en honor de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Moisés tomó entonces el pecho y lo meció como ofrenda ante Yahvé; era esta la porción del carnero de la consagración que tocaba a Moisés, como Yahvé había mandado a Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Después tomó Moisés del óleo de la unción y de la sangre que había encima del altar y roció a Aarón y sus vestiduras, y a la vez a sus hijos y las vestiduras de sus hijos. Así consagró a Aarón y sus vestiduras, y con él a sus hijos y las vestiduras de sus hijos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Y dijo Moisés a Aarón y a sus hijos: “Coced la carne a la entrada del Tabernáculo de la Reunión. Comedla allí mismo como también el pan que está en el canasto de la consagración, respecto del cual yo he mandado diciendo: Aarón y sus hijos la comerán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'Lo restante de la carne y del pan lo quemaréis en el fuego.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Y no saldréis de la entrada del Tabernáculo de la Reunión por siete días, hasta el día en que se cumplan los días de vuestra consagración; porque siete días durará vuestra consagración.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Como se ha hecho hoy, así ha mandado Yahvé que se haga (los siete días) a fin de expiaros.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Durante siete días os quedaréis día y noche a la entrada del Tabernáculo de la Reunión, guardando el mandato de Yahvé para que no muráis, porque así me fue ordenado.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Hicieron Aarón y sus hijos todo cuanto Yahvé había mandado a Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'El día octavo llamó Moisés a Aarón y sus hijos, y a los ancianos de Israel,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'y dijo a Aarón: “Tómate un becerro de la vacada para el sacrificio por el pecado y un carnero para holocausto, ambos sin tacha, para ofrecerlos ante Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Y hablarás a los hijos de Israel, diciendo: ‘Tomad un macho cabrío para el sacrificio por el pecado, y un becerro y un cordero, ambos primales y sin tacha, para el holocausto,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'y un toro y un carnero para el sacrificio pacífico, que se inmolen ante Yahvé, y una oblación amasada con aceite; porque hoy se os mostrará Yahvé’.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Trajeron, pues, ante el Tabernáculo de la Reunión lo que Moisés había mandado, y se acercó todo el pueblo y se mantuvo en pie delante de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Dijo entonces Moisés: “He aquí lo que ha mandado Yahvé; hacedlo y se os aparecerá la gloria de Yahvé.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Después dijo Moisés a Aarón: “Acércate al altar y ofrece tu sacrificio por el pecado y tu holocausto, y haz la expiación por ti mismo y por el pueblo; ofrece también la oblación del pueblo y haz la expiación por ellos; como Yahvé lo ha prescrito.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Se acercó, pues, Aarón al altar y degolló el becerro del sacrificio por su propio pecado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Los hijos de Aarón le presentaron la sangre; y él, mojando su dedo en la sangre roció con ella los cuernos del altar y derramó la sangre al pie del altar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Luego quemó sobre el altar el sebo, los riñones y la telilla del hígado, del sacrificio por el pecado, como Yahvé había mandado a Moisés;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'pero la carne y la piel las quemó fuera del campamento.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Después degolló el holocausto, y los hijos de Aarón le presentaron la sangre, la cual derramó todo en torno sobre el altar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Le presentaron igualmente el holocausto, trozo por trozo, juntamente con la cabeza, y lo quemó sobre el altar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Y habiendo lavado las entrañas y las patas las quemó encima del holocausto sobre el altar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Después ofreció la oblación del pueblo. Tomó el macho cabrío correspondiente al pueblo para el sacrificio por el pecado, lo inmoló y lo presentó por el pecado del mismo modo que el primero.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Ofreció así el holocausto, haciéndolo según, el rito.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Además presentó la oblación. Tomando un puñado de ella lo quemó en el altar, juntamente con el holocausto de la mañana.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Degolló asimismo el toro y el carnero como sacrificio pacífico por el pueblo. Los hijos de Aarón le entregaron la sangre, la cual él derramó sobre el altar, todo alrededor,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'y las partes grasas del toro y del carnero con la cola, el sebo que cubre las entrañas, los riñones y la telilla del hígado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'Las partes grasas las pusieron sobre los pechos (de las víctimas) y él las quemó sobre el altar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Mas los pechos y la pierna derecha los meció Aarón como ofrenda ante Yahvé, conforme Moisés había mandado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Entonces Aarón alzando las manos hacia el pueblo lo bendijo, y se retiró después de haber ofrecido el sacrificio por el pecado, el holocausto y la hostia pacífica.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Luego Moisés y Aarón entraron en el Tabernáculo de la Reunión y cuando salieron bendijeron al pueblo. Entonces la gloria de Yahvé se apareció a todo el pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'Salió fuego de la presencia de Yahvé que consumió el holocausto puesto en el altar y las partes grasas. Todo el pueblo lo vio, y prorrumpiendo en gritos de júbilo cayeron sobre sus rostros.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Nadab y Abiú, hijos de Aarón, tomaron cada uno su incensario, pusieron fuego en ellos, y después de echar incienso encima, ofrecieron ante Yahvé un fuego extraño que Él no les había mandado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Entonces salió fuego de la presencia de Yahvé que los devoró; y murieron delante de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Por lo cual dijo Moisés a Aarón: “Esto es lo que Yahvé ha declarado diciendo: He de ser santificado por los que se me acercan, y glorificado delante de todo el pueblo.” Aarón enmudeció.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Entonces llamó Moisés a Misael y a Elsafán, hijos de Usiel, tío de Aarón, y les dijo: “Aproximaos y sacad a vuestros hermanos de delante del Santuario, llevándolos fuera del campamento.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Se aproximaron, pues, y los llevaron con sus túnicas fuera del campamento, como Moisés había mandado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Y dijo Moisés a Aarón y a sus hijos Eleazar e Itamar: “No descubráis vuestras cabezas ni rasguéis vuestras vestiduras, no sea que muráis y se irrite Yahvé contra todo el pueblo; mas vuestros hermanos y toda la casa de Israel lloren el incendio que Yahvé ha encendido.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Tampoco salgáis de la entrada del Tabernáculo de la Reunión, no sea que muráis, pues el óleo de la unción de Yahvé está sobre vosotros.” Ellos hicieron conforme a la palabra de Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Habló Yahvé a Aarón, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, '“Cuando entréis en el Tabernáculo de la Reunión, no beberéis vino ni bebida que pueda embriagar, ni tú, ni tus hijos contigo, no sea que muráis. Ley perpetua es esta para vuestros descendientes;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'a fin de que podáis distinguir entre lo sagrado y lo profano, y entre lo impuro y lo puro,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'y enseñar a los hijos de Israel todos los preceptos que Yahvé les ha dado por medio de Moisés.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Moisés dijo a Aarón y a Eleazar e Itamar, los hijos que le quedaban (a Aarón): “Tomad la ofrenda que sobra de los sacrificios quemados en honor de Yahvé y comedla sin levadura junto al altar, pues es cosa santísima.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'La comeréis en lugar sagrado, por ser porción tuya, y porción de tus hijos, de los sacrificios quemados en honor de Yahvé, pues así se me ha ordenado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Comeréis también en lugar puro, tú y tus hijos y tus hijas contigo, el pecho mecido y la pierna alzada, porque de los sacrificios pacíficos de los hijos de Israel os han sido dados como porción tuya y porción de tus hijos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Ellos presentarán la pierna alzada y el pecho mecido, además del sebo destinados para el fuego, a fin de mecerlos como ofrenda delante de Yahvé; y serán porción perpetua para ti y para tus hijos contigo, según ha mandado Yahvé.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'También acerca del macho cabrío del sacrificio por el pecado hizo Moisés diligente investigación y he aquí que había sido quemado. Entonces irritado contra Eleazar e Itamar, los hijos de Aarón que a este le habían quedado, dijo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, '“¿Por qué no comisteis en lugar sagrado la víctima del sacrificio por el pecado? Pues es cosa santísima, y (Dios) os la ha dado para llevar la iniquidad del pueblo, para hacer expiación por ellos ante Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'No habiendo sido llevada su sangre al interior del Santuario, debíais comerla sin falta en lugar sagrado, según os he ordenado.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Respondió Aarón a Moisés: “Mira que ellos han presentado hoy su sacrificio por el pecado y su holocausto delante de Yahvé; mas si yo hoy, después de lo que me ha sucedido, hubiera comido la víctima expiatoria, ¿habría esto acaso sido grato a Yahvé?”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Cuando Moisés oyó esto, se dio por satisfecho.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Habló Yahvé a Moisés y a Aarón y les dijo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, '“Hablad a los hijos de Israel y decidles: Estos son los animales que podréis comer, de entre todos los animales que hay sobre la tierra,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Todo animal biungulado de pezuña hendida que rumia, ese podréis comer.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Pero no comeréis, a pesar de que rumian y tienen pezuña hendida: el camello, pues aunque rumia, no tiene partida la pezuña; será impuro para vosotros;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'ni el conejo, porque rumia, pero no tiene la pezuña partida; será impuro para vosotros;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'ni liebre, porque rumia, pero no tiene la pezuña partida; será impura para vosotros;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'ni cerdo, pues aunque tiene la pezuña hendida y biungulada, no rumia; será inmundo para vosotros.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'De la carne de estos no comeréis ni tocaréis sus cadáveres; serán impuros para vosotros.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'De entre todos los animales que viven en las aguas, podréis comer a cuantos teniendo aletas y escamas se encuentran en los mares y en los ríos; a estos podréis comer.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Pero serán cosa abominable para vosotros todos los que carecen de aletas y escamas, de entre todos los que pululan en las aguas, sea en los mares o en los ríos, y de entre todos los demás animales que viven en el agua.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'Serán detestables para vosotros: no comeréis de su carne y tened sus cadáveres por abominación.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Todo cuanto en las aguas no tiene aletas y escamas os sea abominable.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'De entre las aves os sean abominables las siguientes, que no se comerán y os serán detestables: el águila, el quebrantahuesos, el águila marina,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'el buitre, el halcón en todas sus especies,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'toda clase de cuervos,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'el avestruz, la lechuza, la gaviota, el gavilán en todas sus especies,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'el búho, el somormujo, el ibis,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'el cisne, el pelícano, el calamón,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'la cigüeña, la garza en sus especies todas, la abubilla y el murciélago.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Todo insecto alado que anda sobre cuatro patas os será abominable.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Pero de todos los insectos alados que andan sobre cuatro pies, podréis comer aquellos que por encima de sus pies tienen dos patas para brincar con ellas sobre la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'De ellos podréis comer estos: la langosta en sus diversas especies y toda clase de solam, de hargol y de hagab.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Todo otro insecto alado de cuatro patas os será abominable.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'Estos animales os hacen inmundos. Quien tocare su cadáver quedará impuro hasta la tarde.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'Quien alzare alguno de sus cadáveres, lavará sus vestidos y quedará impuro hasta la tarde.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Asimismo todos los animales que tienen pezuña pero no partida en dos uñas y que no rumian, serán inmundos para vosotros. Todo aquel que los tocare quedará impuro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'De entre los cuadrúpedos os serán abominables todos los que andan sobre sus plantas. Quien tocare sus cadáveres quedará impuro hasta la tarde.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'El que sacare el cadáver de uno de ellos lavará sus vestidos, y quedará impuro hasta la tarde; son inmundos para vosotros.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'De entre los animales pequeños que andan arrastrándose sobre la tierra, os serán inmundos: la comadreja, el ratón, el lagarto en sus diversas especies,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'el erizo, el cocodrilo, el camaleón, la salamandra y el topo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'De entre todos los reptiles estos serán inmundos para vosotros. Cualquiera que tocare su cadáver quedará impuro hasta la tarde.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Y todo objeto sobre el cual cayere uno de estos cadáveres, quedará inmundo, ya sea un instrumento de madera, o un vestido, una piel, un saco, en fin, cualquier objeto que se usa para algo. Será metido en agua y quedará inmundo hasta la tarde; después será puro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Si cayera algo de esto en una vasija de barro, todo lo que hubiere dentro de ella quedará inmundo y tendréis que romperla.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Toda cosa comestible, si fuere preparada con tal agua, quedará inmunda, y toda bebida que se beba en una de esas vasijas quedará inmunda.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Y todo objeto sobre el cual caiga algo de esos cuerpos muertos, quedará inmundo; el horno y el fogón serán derribados; son impuros para vosotros y los tendréis por inmundos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Solamente las fuentes y cisternas, donde se recogen las aguas, permanecerán limpias, mas el que tocare sus cadáveres quedará inmundo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'De igual manera cuando cayere algo de esos cadáveres sobre una semilla que ha de sembrarse, quedará pura.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'Mas si cayere algo de esos cuerpos muertos sobre semilla mojada, la tendréis por inmunda.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Si muere uno de aquellos animales que os es lícito comer, quien tocare su cadáver quedará inmundo hasta la tarde.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'Y quien transportare ese cuerpo muerto lavará sus vestidos y quedará inmundo hasta la tarde.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Todo reptil que anda arrastrándose sobre la tierra, es cosa abominable; no servirá de comida.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'De entre todos los reptiles que se arrastran sobre la tierra, no comeréis ninguno de los que andan sobre su vientre o sobre cuatro patas o sobre muchos pies, porque son detestables.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'No os hagáis abominables con ninguna clase de reptil que anda arrastrándose, ni os hagáis inmundos con ellos, para que no os contaminéis por medio de ellos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Porque Yo soy Yahvé, vuestro Dios; por eso habéis de santificaros y ser santos, porque Yo soy santo; y no os contaminaréis con ninguno de esos reptiles que se arrastran sobre la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Pues Yo soy Yahvé que os ha sacado de la tierra de Egipto, a fin de ser vuestro Dios. Sed, pues, santos, porque Yo soy santo.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Esta es la ley acerca de las bestias, y de las aves, y de todos los seres vivientes que se mueven en el agua, y de todos los que andan arrastrándose sobre la tierra;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'para que hagáis distinción entre lo impuro y lo puro, entre el animal que puede comerse y el que no puede ser comido.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Habló Yahvé a Moisés y dijo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, '“Habla a los hijos de Israel y diles: Cuando una mujer dé a luz y tenga un hijo varón, quedará impura siete días; quedará impura conforme a los días de la impureza de su menstruación.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Al octavo día será circuncidado el niño en la carne de su prepucio;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'ella, empero, permanecerá todavía treinta y tres días en la sangre de su purificación. No tocará ninguna cosa santa ni irá al Santuario hasta cumplirse los días de su purificación.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Mas si da a luz una hija, quedará inmunda dos semanas, como en su menstruación, y permanecerá sesenta y seis días más en la sangre de su purificación.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Al cumplirse los días de su purificación, por hijo o por hija, presentará al sacerdote, a la entrada del Tabernáculo de la Reunión, un cordero primal para holocausto, y un palomino o una tórtola para sacrificio por el pecado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'El (sacerdote) los ofrecerá ante Yahvé, haciendo expiación por ella, y quedará purificada del flujo de su sangre. Esta es la ley referente a la mujer que da a luz hijo o hija.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Mas si ella no tiene lo suficiente como para presentar un cordero, tome dos tórtolas o dos palominos, uno para holocausto y otro para sacrificio por el pecado; y el sacerdote hará expiación por ella, y quedará pura.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Yahvé habló a Moisés y a Aarón, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, '“Cuando uno tuviere en la piel de su carne tumor, pústula o mancha reluciente que podría resultar ser llaga de lepra en la piel de su carne, será llevado al sacerdote Aarón o a uno de sus hijos, los sacerdotes.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'El sacerdote examinará la llaga en la piel de la carne; y si el pelo de la llaga se ha vuelto blanco, y la llaga parece más hundida que la piel de su carne, es llaga de lepra, y el sacerdote que le haya examinado le declarará impuro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Mas si hay en la piel de su carne una mancha blanca sin que parezca más hundida que la piel, y sin que el pelo se haya vuelto blanco, el sacerdote recluirá al hombre afectado durante siete días.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Al día séptimo lo revisará el sacerdote, y si a su parecer la llaga no ha cundido y no ha hecho progreso en la piel, lo recluirá otros siete días.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Pasados estos siete días el sacerdote lo revisará nuevamente, y si la llaga ha palidecido y no se ha extendido en la piel, lo declarará puro; es una erupción. Lavará sus vestidos y quedará puro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Mas si la mancha en la piel siguiere cundiendo después de mostrarse el hombre al sacerdote para ser declarado limpio, será revisado otra vez por el sacerdote.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'El sacerdote le revisará y si la mancha se ha extendido por la piel, el sacerdote lo declarará inmundo: es lepra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Cuando se mostrare en un hombre la plaga de la lepra, será llevado al sacerdote.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'El sacerdote lo revisará y si observa un tumor blanco en la piel, y mudado en blanco el color del pelo, y carne viva en la hinchazón,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'es lepra inveterada en la piel de su carne; el sacerdote lo declarará impuro y no lo recluirá, pues es impuro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Pero si la lepra ha cundido mucho en la piel, hasta cubrir toda la piel del enfermo desde la cabeza a los pies, en cuanto alcanza a verlo el sacerdote,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'este lo examinará, y si la lepra ha cubierto toda su carne, declarará puro al afectado por la plaga: se ha vuelto todo blanco; es puro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Mas cuando se ve en él carne viva quedará impuro;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'y cuando el sacerdote observe la carne viva, lo declarará impuro; la carne viva es impura; es lepra;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Pero si la carne viva cambia volviéndose blanca, ha de presentarse al sacerdote.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'El sacerdote lo examinará, y al ver que la plaga se ha vuelto blanca, declarará puro al afectado por la enfermedad, y este quedará puro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Cuando en la piel de la carne de alguno hubiere una úlcera que se ha curado,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'y apareciere en el lugar de la úlcera un tumor blanco, o una mancha de color blanco rojizo, este tal ha de presentarse al sacerdote.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'El sacerdote lo examinará, y si la mancha parece más hundida que la piel, y su pelo se ha vuelto blanco, lo declarará impuro. Es llaga de lepra que se ha producido en la úlcera.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Mas si el sacerdote ve que no hay en ella pelo blanco, ni está más hundida que la piel, y que ha tomado color pálido, lo recluirá por siete días.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Si entonces se extendiere por la piel, el sacerdote lo declarará impuro; es lepra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Pero si la mancha sigue estacionaria en su lugar, sin extenderse, es cicatriz de la úlcera; y el sacerdote lo declarará puro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Cuando uno tiene en la piel de su carne quemadura de fuego, y aparece sobre la quemadura una mancha, de color blanco rojizo o solo blanco,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'la examinará el sacerdote; y si el pelo se ha vuelto blanco en la mancha blanca y ella aparece más hundida que la piel, es lepra que se ha producido en la quemadura. El sacerdote lo declarará impuro. Es llaga de lepra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Si, en cambio, el sacerdote observa que en la mancha no aparece pelo blanco y que no está más hundida que la piel y que ha palidecido, lo recluirá siete días.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Al séptimo día lo examinará, y si (la mancha) se ha extendido por la piel, el sacerdote le declarará impuro; es llaga de lepra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Pero si la mancha sigue estacionaria en su lugar, sin cundir en la piel, y ha cobrado color pálido, es hinchazón de quemadura, y el sacerdote lo declarará puro; pues es cicatriz de la quemadura.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Cuando un hombre o una mujer tuvieren una llaga en la cabeza o en la barba,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'el sacerdote examinará la llaga, y si esta aparece más hundida que la piel, y si hay en ella pelo amarillento y más delgado, el sacerdote lo declarará impuro, es tina, o sea lepra de la cabeza o de la barba.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Mas si el sacerdote ve que la llaga de la tina no aparece más hundida que la piel, aunque no hay en ella pelo negro, recluirá al enfermo de la tina por siete días.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Al séptimo lo examinará el sacerdote, y si no ha cundido la tiña, ni hay en ella pelo amarillento, ni aparece la tina más hundida que la piel,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'se afeitará aquella persona, excepto el lugar de la tiña; y el sacerdote recluirá al tiñoso durante otros siete días.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Al séptimo día lo examinará el sacerdote, y si no ha cundido la tiña por la piel, ni aparece más hundida que la piel, lo declarará puro. Lavará sus vestidos y quedará puro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Pero si la tiña, después de la purificación, se extendiere mucho por la piel,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'lo examinará el sacerdote, y si la tiña se ha extendido por la piel, el sacerdote ya no tendrá que buscar el pelo amarillento; aquella persona es impura.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Mas si según su opinión la tiña no se ha extendido, y ha brotado en ella pelo negro, se ha curado la tifia. Esa persona es pura, y el sacerdote la declarará pura.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Cuando un hombre o una mujer tuviere en la piel de su carne manchas blancas,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'el sacerdote los examinará y si las manchas lustrosas en la piel de su carne son de color pálido blanco, es una eczema que ha brotado en la piel; esa persona es pura.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Si a alguno se le caen los pelos, es un calvo, pero queda puro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'Y si los pelos se le caen de la parte delantera de la cabeza, es calvo de frente, pero queda puro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Mas si en la calva, por detrás o por delante, aparece una llaga de color blanco rojizo, es lepra que ha nacido en la calva, sea por detrás o por delante.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'El sacerdote lo examinará, y si la hinchazón de la llaga en la parte calva, sea por detrás o por delante, es de color blanco rojizo teniendo el aspecto de la lepra en la piel de la carne,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'es leproso; es impuro; el sacerdote lo declarará impuro; su lepra está en la cabeza.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'El afectado por la lepra, llevará sus vestidos rasgados, dejará descubierta su cabeza, se tapará la boca y caminará gritando: ¡Impuro, impuro!');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Todo el tiempo que durare la plaga, quedará impuro; impuro es; habitará solo; fuera del campamento será su morada.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Cuando aparezca plaga de lepra en un vestido de lana o en un vestido de lino,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'sea en la urdimbre del lino o de la lana, o sea en la trama, o en una piel, o en cualquier objeto hecho de cuero,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'si la mancha en el vestido o en la piel, o en la urdimbre, o en la trama, o en cualquier objeto hecho de cuero, tiene color verdoso o rojizo, es plaga de lepra y debe ser mostrada al sacerdote.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'El sacerdote examinará la mancha y encerrará el objeto manchado durante siete días.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Al séptimo el sacerdote examinará la plaga, y si la plaga se ha extendido en el vestido, sea en la urdimbre o en la trama, o en la piel, o en cualquier objeto hecho de cuero, lepra maligna es la tal plaga, y (el objeto) queda impuro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Por lo cual se quemará el vestido, esté (la mancha) en la urdimbre o en la trama de lana o de lino, y asimismo cualquier objeto de piel en que se encuentre la mancha; pues es lepra maligna; será entregado al fuego.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Pero si el sacerdote ve que no ha cundido la mancha por el vestido, ni en la urdimbre, ni en la trama, ni en cualquier objeto de piel,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'el sacerdote hará lavar el objeto manchado y lo encerrará otros siete días.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Si el sacerdote ve que la mancha después de haber sido lavada no ha mudado de aspecto, aunque la mancha no se haya extendido, (el objeto) es impuro; lo entregará al fuego; es una corrosión en su reverso o en su anverso.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Mas si el sacerdote ve que la parte manchada, después de lavada, ha tomado color, la rasgará del vestido, de la piel, de la urdimbre o de la trama respectiva.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Pero si volviere a aparecer en el vestido, sea en la urdimbre o en la trama o en cualquier objeto de cuero, es una erupción (de lepra); entregarás al fuego aquello en que estuviese la lepra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Mas si el vestido, la urdimbre o la trama, o cualquier objeto de cuero que después de ser lavados pierden la mancha, serán lavados por segunda vez y quedarán limpios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Esta es la ley de la plaga de la lepra que se halla en los vestidos de lana o de lino, sea en la urdimbre o en la trama, o en cualquier objeto hecho de cuero, para declararlos puros o impuros.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, '“Esta es la ley del leproso en el día de su purificación: Se lo conducirá al sacerdote,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'y el sacerdote saldrá fuera del campamento; y si ve que el leproso ya está curado de la llaga de la lepra,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'mandará tomar para aquel que ha de ser purificado dos pájaros vivos y puros, madera de cedro, púrpura escarlata e hisopo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'Después el sacerdote mandará degollar uno de los pájaros sobre una vasija de barro con agua viva.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Luego tomará el pájaro vivo, la madera de cedro, la púrpura escarlata y el hisopo, los mojará, juntamente con el pájaro vivo, en la sangre del pájaro degollado sobre el agua viva,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'y rociará siete veces al que ha de ser purificado de la lepra. Así lo purificará; luego soltará en el campo al pájaro vivo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Aquel que ha de purificarse lavará sus vestidos, se raerá todo su pelo, y se bañará en agua, y quedará limpio. Después podrá entrar en el campamento; pero durante siete días ha de habitar fuera de su tienda.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'El día séptimo se raerá todo su pelo, sus cabellos, su barba, sus cejas; en fin, raerá todo su pelo; lavara también sus vestidos, bañará su cuerpo en agua, y quedará limpio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'El día octavo tomará dos corderos sin tacha y una oveja primal sin tacha, y como oblación tres décimas de flor de harina amasada con aceite, y un log de aceite.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'El sacerdote que hace la purificación, presentará al hombre que ha de purificarse, juntamente con aquellas cosas, ante Yahvé, a la entrada del Tabernáculo de la Reunión;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'y tomará el sacerdote uno de los corderos para ofrecerlo como sacrificio por la culpa, además del log de aceite, y lo mecerá por ofrenda ante Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Luego inmolará el cordero en el lugar donde se inmola el sacrificio por el pecado y el holocausto, en lugar sagrado; porque así como en el sacrificio por el pecado, así también en el sacrificio por la culpa la víctima es para el sacerdote; es cosa santísima.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Después tomará el sacerdote de la sangre de la víctima por el delito, y la pondrá sobre el lóbulo de la oreja derecha del que se está purificando, sobre el pulgar de su mano derecha y sobre el dedo gordo de su pie derecho.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Y tomando el log de aceite echará el sacerdote parte de él sobre la palma de su mano izquierda.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'Después mojará el sacerdote el dedo de su mano derecha en el aceite que tiene en la palma de su mano izquierda, y con su dedo hará siete aspersiones de aceite delante de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Con el resto del aceite que tiene en la palma de su mano untará el sacerdote el lóbulo de la oreja derecha del que se purifica, el pulgar de su mano derecha y el dedo gordo de su pie derecho, por encima de la sangre de la victima expiatoria.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'El resto del aceite que queda en la mano del sacerdote, se echara sobre la cabeza del que se purifica, y el sacerdote hará expiación por él ante Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Entonces el sacerdote ofrecerá el sacrificio por el pecado, y hará expiación por quien se purifica de su inmundicia, finalmente degollará el holocausto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Ese holocausto y la oblación los ofrecerá el sacerdote sobre el altar. De esta manera el sacerdote hará expiación por él; y quedará limpio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Si es pobre y no tiene suficientes recursos, tomará un cordero que será ofrecido en sacrificio por la culpa, como ofrenda mecida, para hacer expiación por él, y además, como oblación una décima de flor de harina amasada con aceite, y un log de aceite,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'y dos tórtolas o dos palominos, según sus recursos, el uno como sacrificio por el pecado y el otro para holocausto:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'Al octavo día, los llevará al sacerdote, a la entrada del Tabernáculo de la Reunión, para su purificación delante de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'El sacerdote tomará el cordero del sacrificio por la culpa y el log de aceite, y los mecerá por ofrenda ante Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Y después de haber inmolado el cordero del sacrificio por la culpa, tomará el sacerdote de la sangre de la victima expiatoria y la pondrá sobre el lóbulo de la oreja derecha del que se purifica, sobre el pulgar de su mano derecha, y sobre el dedo gordo de su pie derecho.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Luego derramará el sacerdote parte del aceite sobre la palma de su mano izquierda;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'y con el dedo de su mano derecha hará ante Yahvé siete aspersiones, con el aceite que tiene en la palma de su mano izquierda,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'y pondrá parte del aceite que tiene en su mano, sobre el lóbulo de la oreja derecha del que se purifica, sobre el pulgar de su mano derecha, y sobre el dedo gordo de su pie derecho, en el lugar donde puso la sangre de la víctima por la culpa.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'El resto del aceite que le queda en la mano lo pondrá el sacerdote sobre la cabeza del que se purifica, haciendo expiación por él ante Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Luego ofrecerá según sus posibilidades una de las tórtolas o de los palominos,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'es decir, en la medida de sus recursos, el uno como sacrificio por el pecado, y el otro para holocausto, además de la oblación. De este modo el sacerdote hará expiación ante Yahvé por aquel que se purifica.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Esta es la ley de purificación para aquel que tiene plaga de lepra y cuyos recursos son limitados.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Yahvé habló a Moisés y Aarón y dijo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, '“Cuando hayáis entrado en la tierra de Canaán que Yo os daré en posesión, y ponga la plaga de la lepra en alguna casa de la tierra de vuestra posesión,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'el propietario de la casa irá a avisar al sacerdote, diciendo: Me parece que hay algo como lepra en mi casa.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'El sacerdote antes de entrar en la casa para examinar la lepra, dispondrá su evacuación, para que no quede contaminado todo lo que hay en ella. Después entrará a registrar la casa.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Si al examinar la plaga observa que las manchas en las paredes de la casa forman cavidades verdosas y rojizas, que parecen hundidas en la pared,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'el sacerdote se retirará del interior hasta la puerta de la casa y cerrará la casa por siete días.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Volverá el sacerdote al día séptimo y si viere que la lepra se ha extendido en las paredes de la casa,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'mandará arrancar las piedras manchadas y arrojarlas fuera de la ciudad en un lugar inmundo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Hará raspar todo el interior de la casa; y el polvo que quiten raspando, lo echarán fuera de la ciudad en un lugar inmundo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'Luego tomarán otras piedras y las volverán a poner en lugar de aquellas y también otra argamasa para revocar la casa.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Si con todo la plaga volviere a difundirse en la casa después de arrancar las piedras, y después de raspar y revocar la casa,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'entrará de nuevo el sacerdote, y si viere que la plaga se ha extendido en la casa, es lepra maligna de la casa y esta es inmunda.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Se derribará aquella casa; y sus piedras y su maderamen y todo el material de la casa, todo será sacado fuera de la ciudad, a un lugar inmundo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Quien entrare en esa casa durante todo el tiempo que estuviere cerrada, quedará inmundo hasta la tarde.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'El que durmiere en aquella casa lavará sus vestidos; y también el que comiere en esa casa lavara sus vestidos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Mas si el sacerdote al entrar nota que la plaga, después de revocada la casa, no ha cundido en ella, la declarará limpia, pues se ha curado de la plaga.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Entonces para purificar la casa, tomará dos pájaros, madera de cedro, lana escarlata e hisopo;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'degollará uno de los pájaros sobre una vasija de barro con agua viva:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'y tomando la madera de cedro, el hisopo y la lana escarlata, con el pájaro vivo, los mojará en la sangre del pájaro degollado y en el agua viva y rociará la casa siete veces.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'Así purificará la casa con la sangre del pájaro, con el agua viva, el pájaro vivo, la madera de cedro, el hisopo y la lana escarlata.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Luego soltará el pájaro vivo fuera de la ciudad, en el campo. De este modo hará expiación por la casa, la cual quedará limpia.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Esta es la ley para toda clase de lepra y de tina,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'para la lepra del vestido y de la casa,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'y para los tumores y erupciones y manchas blancas,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'para discernir cuándo una cosa es impura y cuándo es pura. Tal es la ley de la lepra.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Habló Yahvé a Moisés y a Aarón, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, '“Hablad a los hijos de Israel y decidles: Cualquier hombre que tuviere flujo proveniente de su carne es inmundo por su flujo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'Y esta impureza causada por su flujo, que él se contrae, tanto al destilar su carne el flujo, cuanto al retenerlo, es impureza para él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Toda cama en que durmiere el que padece flujo, quedará inmunda; y todo mueble encima del cual se sentare, será impuro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Quien tocare su cama lavará sus vestidos, se bañará en agua y quedará impuro hasta la tarde.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Quien se sentare sobre un mueble donde se haya sentado el que padece flujo, lavará sus vestidos, se bañará en agua y será impuro hasta la tarde.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Quien tocare la carne del que padece flujo, lavará sus vestidos, se bañará en agua y será impuro hasta la tarde.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Si el que tiene el flujo escupiere sobre un hombre puro, este lavará sus vestidos, se bañará en agua y quedará impuro hasta la tarde.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Toda silla de montar sobre la cual haya cabalgado el que padece flujo, será inmunda.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Quien tocare un objeto que haya estado debajo del (que padece flujo), quedará impuro hasta la tarde. Y el que lo transportare, lavará sus vestidos, se bañará en agua y será impuro hasta la tarde.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Todo aquel a quien el que padece flujo tocare sin haberse lavado las manos con agua, lavará sus vestidos, se bañará en agua y quedará impuro hasta la tarde.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Toda vasija de barro tocada por el que padece flujo, será quebrada, y todo utensilio de madera será lavado con agua.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Si el que padece flujo sanare de su flujo, contará siete días para su purificación; después lavará sus vestidos, se bañará en agua viva y quedará puro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Al día octavo tomará dos tórtolas o dos palominos y se presentará ante Yahvé a la entrada del Tabernáculo de la Reunión, para entregarlos al sacerdote.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'El sacerdote los ofrecerá uno como sacrificio por el pecado, el otro en holocausto, y de esta manera el sacerdote hará expiación por él ante Yahvé, por su flujo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'El hombre que tuviere derrame de semen, lavará con agua todo su cuerpo y quedará impuro hasta la tarde.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Toda ropa y toda piel sobre la cual se hubiere derramado el semen, será lavada con agua y quedará impura hasta la tarde.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Cuando el hombre se acostare con la mujer, produciéndose efusión de semen, se lavarán ambos con agua y quedarán impuros hasta la tarde.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'La mujer que tiene flujo, su flujo de sangre en su cuerpo, permanecerá en su impureza por espacio de siete días y quien la tocare será impuro hasta la tarde.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Aquello sobre que durmiere durante su impureza, quedará impuro, lo mismo que todo aquello en que se sentare.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Quien tocare el lecho de ella, lavará sus vestidos, se bañará en agua y permanecerá impuro hasta la tarde.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Quien tocare un objeto cualquiera sobre el cual ella se haya sentado, lavará sus vestidos, se bañará en agua y será impuro hasta la tarde.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Quien tocare una cosa puesta sobre el lecho o sobre el mueble donde ella se sienta, quedará impuro hasta la tarde.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Si uno se acuesta con ella, se acarrea la impureza de ella y queda impuro siete días, y toda cama en que él se acueste será inmunda.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Cuando una mujer tuviere flujo de su sangre durante algunos días, fuera del tiempo de su impureza o cuando el flujo se prolongare más allá del tiempo de su impureza, quedará impura todo el tiempo del flujo de su inmundicia como en los días de su impureza.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Toda cama en que se acostare durante todo el tiempo de su flujo, le será como la cama de su impureza, y cualquier objeto sobre el que se sentare quedará inmundo, le será como la inmundicia de su impureza.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Quien los tocare, quedará impuro y lavará sus vestidos, se bañará en agua y quedará impuro hasta la tarde.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Cuando ella sanare de su flujo, contará siete días, después quedará pura.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Al octavo día tomará dos tórtolas o dos palominos y los entregará al sacerdote a la entrada del Tabernáculo de la Reunión.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'El sacerdote los ofrecerá, uno como sacrificio por el pecado, el otro en holocausto; y el sacerdote hará expiación por ella ante Yahvé por el flujo de su impureza.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Así enseñaréis a los hijos de Israel a purificarse de sus impurezas para que no mueran a causa de su impureza por haber contaminado mi Morada, que está en medio de ellos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Esta es la ley respecto del hombre que padece flujo o se mancha con efusión de semen,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'y respecto de la mujer que se mancha con la impureza mensual, y de aquel que padece flujo, ya varón ya mujer, y de aquel que se acuesta con una mujer impura.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Habló Yahvé a Moisés después de la muerte de los dos hijos de Aarón, los cuales murieron al acercarse a Yahvé;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'y dijo Yahvé a Moisés: “Di a tu hermano Aarón, que no en todo tiempo entre en el Santuario que está tras el velo, delante del propiciatorio que cubre el Arca, no sea que muera: pues Yo me hago ver en la nube encima del propiciatorio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'He aquí cómo Aarón ha de entrar en el Santuario: tomará un becerro para sacrificio por el pecado y un carnero para holocausto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Se vestirá de la túnica santa de lino, se pondrá sobre su carne los calzoncillos de lino, se ceñirá el cinturón de lino y se cubrirá con la mitra de lino. Estas son las vestiduras sagradas que vestirá después de haberse lavado con agua.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Luego tomará de la Congregación de los hijos de Israel dos machos cabríos para sacrificio por el pecado y un carnero para holocausto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Y después de ofrecer su becerro por el pecado para expiación de sí mismo y de su casa,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'tomará Aarón los dos machos cabríos y los presentará ante Yahvé, a la entrada del Tabernáculo de la Reunión.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Luego Aarón echará suertes sobre los dos machos cabríos, una suerte para Yahvé, y la otra para Asasel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Y presentará Aarón el macho cabrío que haya tocado en suerte a Yahvé, ofreciéndolo como sacrificio por el pecado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'El macho cabrío que por suerte tocare a Asasel, lo colocará vivo delante de Yahvé, para hacer sobre él la expiación y echarlo al desierto, para Asasel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Entonces ofrecerá Aarón su becerro por el pecado, para hacer expiación por sí mismo y por su casa, e inmolará su becerro por el pecado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Tomará después un incensario lleno de brasas sacadas de sobre el altar que está ante Yahvé, y dos puñados de incienso aromático pulverizado, y llevándolo detrás del velo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'pondrá el incienso sobre el fuego, delante de Yahvé, para que la nube del incienso envuelva el propiciatorio que está encima del Testimonio y él no muera.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Tomando luego de la sangre del becerro la derramará con su dedo sobre el frente oriental del propiciatorio, y con su dedo hará siete aspersiones de sangre delante del propiciatorio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Después degollará el macho cabrío por el pecado del pueblo, y llevará su sangre detrás del velo, haciendo con su sangre lo que hizo con la sangre del becerro: la derramará sobre el propiciatorio y delante del mismo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'Así purificará el Santuario de las impurezas de los hijos de Israel y de sus transgresiones y de todos sus pecados. Lo mismo hará con el Tabernáculo de la Reunión, que está entre ellos en medio de sus impurezas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Nadie debe estar en el Tabernáculo de la Reunión cuando él entre para hacer la expiación dentro del Santuario, hasta que salga después de haber hecho la expiación por sí mismo, por su casa y por toda la asamblea de Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Luego saldrá hacia el altar que está ante Yahvé, y lo expiará, tomando de la sangre del becerro y de la sangre del macho cabrío y poniéndola sobre los cuernos del altar todo en torno.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'Hará sobre él con su dedo siete aspersiones de la sangre, y así lo purificará y lo santificará de las impurezas de los hijos de Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Acabada la expiación del Santuario, del Tabernáculo de la Reunión y del altar, presentará Aarón el macho cabrío vivo;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'y poniendo ambas manos sobre la cabeza del macho cabrío vivo, confesará sobre él todas las iniquidades de los hijos de Israel, y todas las transgresiones y todos los pecados de ellos, y depositándolos sobre la cabeza del macho cabrío, lo enviará al desierto por mano de un hombre designado para ello.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'Así el macho cabrío llevará sobre sí todas las iniquidades de ellos hacia tierra inhabitada, y el hombre soltará al macho cabrío en el desierto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Luego entrará Aarón en el Tabernáculo de la Reunión, y quitándose las vestiduras de lino que se había vestido al entrar en el Santuario, las dejará allí,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'lavará su cuerpo con agua en lugar sagrado y se pondrá sus vestiduras. Después saldrá y ofrecerá su holocausto y el holocausto del pueblo, haciendo la expiación por sí mismo y por el pueblo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'y quemando sobre el altar el sebo de la víctima por el pecado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'El hombre encargado de soltar al macho cabrío para Asasel, lavará sus vestidos y bañará su cuerpo en agua; después de esto podrá entrar en el campamento.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'El becerro del sacrificio por el pecado y el macho cabrío inmolado por el pecado, cuya sangre fue introducida en el Santuario para hacer expiación, serán sacados fuera del campamento y quemados sus pieles, su carne y sus excrementos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'El que los queme lavará sus vestidos y se bañará en agua; después de esto podrá entrar en el campamento.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Será esta para vosotros una ley perpetua: En el mes séptimo, el día décimo del mes, os mortificaréis y no haréis trabajo alguno, ni el indígena, ni el extranjero que mora en medio de vosotros.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Porque en ese día se hará expiación por vosotros para purificaros y de todos vuestros pecados quedaréis limpios delante de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Será para vosotros un sábado solemne, en el cual os habéis de mortificar. Ley perpetua será esta.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'La expiación será hecha por el sacerdote ungido y consagrado como sacerdote en lugar de su padre: se vestirá las vestiduras de lino, las vestiduras sagradas,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'y hará la expiación del Santuario de la santidad; expiará el Tabernáculo de la Reunión y el altar, como asimismo hará la expiación por los sacerdotes y por todo el pueblo de la Congregación.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Esto lo tendréis por precepto perpetuo, para hacer la expiación por los hijos de Israel, por todos sus pecados, una vez al año.” Y se hizo como Yahvé mandara a Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Yahvé habló a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, '“Habla a Aarón y a sus hijos y a todos los hijos de Israel, y diles: Esta es la orden que ha dado Yahvé:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Cualquier hombre de la casa de Israel que degüelle res vacuna u oveja o cabra dentro del campamento, o fuera del mismo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'sin llevarlos a la entrada del Tabernáculo de la Reunión, para presentarlo como sacrificio a Yahvé ante la Morada de Yahvé, será considerado reo de sangre. Tal hombre ha derramado sangre y será extirpado de en medio de su pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'Por lo cual presentarán los hijos de Israel sus víctimas que (hasta ahora) sacrificaban en el campo; los presentarán al sacerdote, para Yahvé, a la entrada del Tabernáculo de la Reunión, y los ofrecerán como sacrificios pacíficos a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'El sacerdote derramará la sangre sobre el altar de Yahvé, a la entrada del Tabernáculo de la Reunión, y quemará el sebo en olor agradable a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'De este modo ellos no ofrecerán más sus sacrificios a los demonios, con los cuales están fornicando. Ley perpetua será esta para ellos, de generación en generación.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Diles, pues: Cualquier hombre de la casa de Israel, o de los extranjeros que moran en medio de vosotros, que ofrezca holocausto o sacrificio,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'y no lo traiga a la entrada del Tabernáculo de la Reunión para sacrificarlo en honor de Yahvé, será extirpado de entre su pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'Si algún hombre de la casa de Israel, o de los extranjeros que moran en medio de vosotros, comiere cualquier clase de sangre, Yo volveré mi rostro contra el que comiere sangre y lo extirparé de en medio de su pueblo;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'porque la vida de la carne está en la sangre, y Yo os la doy para hacer expiación en el altar por vuestras almas; pues mediante la sangre se hace la expiación de las almas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Por eso mando a los hijos de Israel: Ninguno de vosotros comerá sangre; tampoco coma sangre el extranjero que mora en medio de vosotros.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Todo hombre de la casa de Israel, o de los extranjeros que habitan en medio de ellos, que cazare un animal o un ave que es lícito comer, derramará su sangre y la cubrirá con tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Porque la vida de toda carne es su sangre, en esta consiste su vida. Por eso mando a los hijos de Israel: No comeréis la sangre de carne alguna, pues la vida de toda carne es su sangre. Quienquiera la comiere, será exterminado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Quien de vuestra gente o de los extranjeros comiere carne mortecina, o presa (de fieras), lavará sus vestidos, se bañará en agua, y quedará impuro hasta la tarde; después será puro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Si no los lava ni baña su cuerpo, pagará su iniquidad.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, '“Habla a los hijos de Israel y diles: Yo soy Yahvé vuestro Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'No hagáis lo que se hace en la tierra de Egipto, donde habéis morado; ni hagáis lo que se hace en el país de Canaán adonde Yo os llevo; no sigáis sus costumbres.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Cumplid mis mandamientos y guardad mis preceptos, caminando por ellos. Yo soy Yahvé, vuestro Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Guardad mis mandamientos y mis preceptos. El hombre que los cumpliere vivirá por ellos. Yo soy Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Ninguno de vosotros se acerque a una consanguínea suya para descubrir su desnudez. Yo soy Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'No descubrirás la desnudez de tu padre, ni la desnudez de tu madre. Es tu madre; no descubrirás la desnudez de ella.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'No descubrirás la desnudez de la mujer de tu padre; es la desnudez de tu padre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'No descubrirás la desnudez de tu hermana, hija de tu padre o hija de tu madre, nacida en casa o fuera de ella.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'No descubrirás la desnudez de la hija de tu hijo o de la hija de tu hija, pues es tu propia desnudez.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'No descubrirás la desnudez de la hija de la mujer de tu padre, engendrada de tu padre, que es tu hermana.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'No descubrirás la desnudez de la hermana de tu padre; es carne de tu padre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'No descubrirás la desnudez de la hermana de tu madre, es carne de tu madre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'No descubrirás la desnudez del hermano de tu padre; no te acercarás a su mujer; es tu tía.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'No descubrirás la desnudez de tu nuera; es la mujer de tu hijo; no descubrirás su desnudez.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'No descubrirás la desnudez de la mujer de tu hermano; es la desnudez de tu hermano.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'No descubrirás la desnudez de una mujer y la de su hija, ni tomarás la hija de su hijo ni la hija de su hija para descubrir su desnudez; son parientas cercanas, sería un crimen.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'No tomarás a una mujer juntamente con su hermana, haciéndola rival de ella y descubriendo su desnudez mientras viva la primera.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Tampoco te acercarás a una mujer en la impureza de su inmundicia para descubrir su desnudez.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'No te juntes carnalmente con la mujer de tu prójimo, contaminándote con ella.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'No darás ningún hijo tuyo para consagrarlo a Moloc; no profanarás así el nombre de tu Dios. Yo soy Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'No te acostarás con varón como con mujer; es abominación.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'No te copularás con bestia, contaminándote con ella. La mujer no se pondrá delante de una bestia para unirse con ella; es cosa perversa.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'No os manchéis con ninguna de estas (abominaciones), pues con ellas se han contaminado las naciones que Yo voy a arrojar de vuestra vista.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'Se ha manchado el país, por lo cual castigaré su maldad, y el país vomitará a sus habitantes.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Vosotros, pues, guardad mis preceptos y mis leyes, y no cometáis ninguna de estas abominaciones, tanto los de vuestro pueblo, como los extranjeros que moran entre vosotros.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'Porque todas estas abominaciones han cometido los hombres de aquella tierra, anteriores a vosotros, y por eso se ha contaminado el país.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'Mirad, no sea que os vomite la tierra, cuando la contaminéis, como vomitó a las naciones anteriores a vosotros;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'porque todos los que cometan una de estas abominaciones, todos ellos serán exterminados de en medio de su pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Guardad, pues, mis preceptos; no practiquéis ninguna de estas costumbres abominables que se practicaban antes de vosotros, ni os contaminéis con ellas. Yo soy Yahvé, vuestro Dios.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, '“Habla a toda la Congregación de los hijos de Israel y diles: Sed santos; porque Yo, Yahvé vuestro Dios, soy santo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Respete cada cual a su madre y a su padre, y guardad mis sábados. Yo soy Yahvé, vuestro Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'No os volváis hacia los ídolos, ni os hagáis dioses fundidos. Yo soy Yahvé, vuestro Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Cuando presentéis un sacrificio pacífico a Yahvé, ofrecedlo voluntariamente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'La víctima se ha de comer el mismo día en que la inmolareis, y al día siguiente; y lo que sobrare hasta el día tercero, será entregado al fuego.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Si se comiere algo al tercer día, estando ya en putrefacción, no será acepto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'El que lo coma pagará su iniquidad; porque está profanando lo consagrado a Yahvé. Tal persona será extirpada de entre su pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'En la recolección de la mies de vuestra tierra no segarás hasta el límite de tu campo, ni respigaras los restos de tu mies.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Tampoco harás rebusca en tu viña, ni recogerás en tu viña las uvas caídas; las dejarás para el pobre y para el extranjero. Yo soy Yahvé, vuestro Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'No hurtaréis; no usaréis de engaño o mentira entre vosotros.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'No juraréis en falso por mi nombre, ni profanarás el nombre de Dios. Yo soy Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'No oprimirás a tu prójimo, ni le despojarás. No quede el salario del jornalero en tu mano hasta el día siguiente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'No maldecirás al sordo, ni pondrás tropiezo ante el ciego, sino que temerás a tu Dios. Yo soy Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Siendo juez no hagas injusticia, ni en favor del pobre, ni por respeto al grande. Juzgarás a tu prójimo según justicia.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'No andes sembrando calumnias por entre tu pueblo; no te cruces de brazos cuando esté en peligro la vida de tu prójimo. Yo soy Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'No odies en tu corazón a tu hermano, pero reprende a tu prójimo, para que no lleves pecado por él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'No tomarás venganza, ni guardarás rencor contra los hijos de tu pueblo. Amarás a tu prójimo como a ti mismo. Yo soy Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Guardad mis mandamientos. No hagas que tus bestias se mezclen con las de otra especie. No siembres tu campo con dos clases distintas de semillas. No lleves vestido tejido de dos clases de hilo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Si un hombre duerme con una mujer, teniendo con ella comercio carnal, y ella es sierva y desposada a otro, sin que haya sido rescatada, ni puesta en libertad, serán castigados (ambos), mas no con la muerte, porque ella no era libre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'El hombre ofrecerá por su culpa a Yahvé un carnero, como sacrificio por el delito, a la entrada del Tabernáculo de la Reunión.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'Con el carnero ofrecido por el delito el sacerdote hará expiación por él ante Yahvé por el pecado cometido, y se le perdonará este pecado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Cuando después de entrar en la tierra plantéis todo género de árboles frutales, consideraréis su fruto como incircunciso; por tres años lo consideraréis como incircunciso; no se comerá.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Al cuarto año todos sus frutos serán consagrados en loor de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'Y desde el quinto año comeréis de su fruto; rendirán entonces mayor fruto. Yo soy Yahvé, vuestro Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'No comáis nada con sangre. No practiquéis adivinación, ni magia.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'No raeréis en forma redonda las extremidades de vuestra cabellera, ni cortarás los bordes de tu barba.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'No haréis sajaduras en vuestra carne, a causa de un muerto; ni os imprimiréis tatuaje. Yo soy Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'No profanarás a tu hija, prostituyéndola; no sea que la tierra se entregue a la fornicación y se llene de maldad.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Guardad mis sábados y respetad mi Santuario. Yo soy Yahvé,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'No consultéis a los que evocan a los muertos, ni a los adivinos. No andéis en busca de ellos para no contaminaros con ellos. Yo soy Yahvé, vuestro Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Levántate ante las canas y honra el rostro del anciano. Teme a tu Dios. Yo soy Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Cuando un extranjero morare entre vosotros, en vuestra tierra, no le oprimáis.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'El extranjero que morare entre vosotros, os sea como uno de vuestro pueblo. Le amarás como a ti mismo; pues extranjeros habéis sido vosotros en la tierra de Egipto. Yo soy Yahvé, vuestro Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'No hagáis injusticia en los juicios, ni en las medidas de longitud, ni en el peso, ni en las medidas de capacidad.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Tened balanza justa, peso justo, efa justo e hin justo. Yo soy Yahvé, vuestro Dios, que os saqué del país de Egipto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Guardad todos mis preceptos y todos mis mandamientos, y ponedlos en práctica. Yo soy Yahvé.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Yahvé habló a Moisés y dijo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, '“Di a los hijos de Israel: Cualquier hombre de entre los hijos de Israel o de los extranjeros que habitan en Israel, si entregare uno de sus hijos a Moloc, será muerto irremisiblemente; el pueblo del país lo apedreará.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Yo mismo volveré mi rostro contra el tal hombre y lo extirparé de en medio de su pueblo, por haber dado un hijo suyo a Moloc, contaminando mi Santuario y profanando mi santo nombre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Si el pueblo del país apartare sus ojos de ese hombre que dio uno de sus hijos a Moloc, y no le diere muerte,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'yo mismo volveré mi rostro contra aquel hombre y contra su familia, y le extirparé de entre su pueblo, a él y a todos los que como él se prostituyan a Moloc.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Si una persona consultare a los que evocan a los muertos, y a los que adivinan, fornicando en pos de ellos, Yo volveré mi rostro contra ella y la extirparé de en medio de su pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Santificaos y sed santos; porque Yo soy Yahvé, vuestro Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Guardad mis leyes y cumplidlas. Yo soy Yahvé quien os santifico.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Quien maldiga a su padre o a su madre será muerto sin remedio; ha maldecido a su padre o a su madre; recaiga sobre él su sangre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'El hombre que cometa adulterio con la mujer de otro, con la mujer de su prójimo, ambos serán muertos irremisiblemente, tanto el adúltero como la adúltera.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'El que se acueste con la mujer de su padre, descubre la desnudez de su padre; ambos serán muertos irremisiblemente; recaiga sobre ellos su sangre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'El hombre que se acueste con su nuera, mueran ambos; han hecho cosa abominable; su sangre recaiga sobre ellos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'El que se acueste con varón, como se hace con mujer; ambos han cometido abominación: mueran irremisiblemente; su sangre recaiga sobre ellos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Si uno toma por mujeres a la hija y a la madre, es un crimen. Serán entregados a las llamas tanto él como ellas, para que no haya tal crimen en medio de vosotros.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'El que se ayuntare con bestia, muera irremisiblemente. Mataréis también la bestia.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Si una mujer se acerca a una bestia para ayuntarse con ella, matarás a la mujer y a la bestia. Morirán irremisiblemente; recaiga sobre ellos su sangre.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'El que tomare a su hermana, hija de su padre o hija de su madre, viendo así la desnudez de ella, y ella viendo la desnudez de él, es cosa vergonzosa. Se les dará muerte en presencia de los hijos de su pueblo; ha descubierto la desnudez de su hermana; llevará su iniquidad.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'El que se acostare con mujer que padece la indisposición mensual, descubriendo la desnudez de ella, ha descubierto su flujo y ella también ha descubierto el flujo de su sangre. Ambos serán extirpados de entre su pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'No descubras la desnudez de la hermana de tu madre, ni de la hermana de tu padre, porque es desnudar su propia carne; por eso llevarán su iniquidad.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'El que se acostare con su tía, descubre la desnudez de su tía. Llevarán su pecado; morirán sin prole.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Si uno se casa con la mujer de su hermano, hace cosa impura, pues descubre la desnudez de su hermano; quedarán sin hijos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Guardad, pues, todas mis leyes y todos mis preceptos y cumplidlos, no sea que os vomite el país adonde os llevo para habitarlo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'No caminéis según las costumbres de los pueblos que Yo voy a expulsar de vuestra vista; pues por haber hecho ellos todas esas cosas les tengo asco.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Mas a vosotros os he dicho: Poseeréis su tierra, la que Yo os daré en herencia, tierra que mana leche y miel. Yo soy Yahvé, vuestro Dios, que os he separado de los demás pueblos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Habéis de hacer distinción entre animales puros e impuros, y entre aves impuras y puras; y no os contaminéis, ni con animales, ni con aves, ni con lo que anda arrastrándose por el suelo. Todas esas cosas os he señalado como impuras.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Sed, pues, santos para Mí, porque Yo, Yahvé, soy santo; y os he elegido de entre los pueblos, para que seáis míos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'El hombre o la mujer que evoque a los muertos o que se dedique a la adivinación muera irremisiblemente; serán apedreados; recaiga sobre ellos su sangre.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Dijo Yahvé a Moisés: “Habla a los sacerdotes, hijos de Aarón, y diles: Nadie se haga impuro si muere uno de su pueblo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'a no ser un consanguíneo cercano suyo, como su madre, su padre, su hijo, su hija, su hermano,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'o una hermana suya, virgen, que viva con él y no haya sido desposada aún. Por esa puede contaminarse.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Pues siendo él un jefe en medio de su pueblo no debe contaminarse, haciéndose profano.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, '(Los sacerdotes) no se raparán la cabeza, ni se cortarán los bordes de su barba, ni se harán sajaduras en su carne.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Santos han de ser para su Dios y no profanarán el nombre de su Dios; pues son ellos los que presentan los sacrificios que se queman en honor de Yahvé, el pan de su Dios; han de ser santos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'No tomarán mujer prostituta ni deshonrada, ni tampoco tomarán mujer repudiada de su marido; porque (el sacerdote) está consagrado a su Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Lo tendrás por santo, porque él es quien presenta el pan de tu Dios; por tanto será santo para ti; pues santo soy Yo, Yahvé, que os santifico.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Si la hija de un sacerdote se deshonra, prostituyéndose, a su padre deshonra; será entregada al fuego.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'El Sumo Sacerdote entre sus hermanos, sobre cuya cabeza fue derramado el óleo de la unción y que ha sido consagrado para vestir las vestiduras, no desgreñará sus cabellos ni rasgará sus vestidos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'Tampoco se acercará a ningún muerto; ni siquiera por su padre o por su madre ha de contaminarse.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'No saldrá del Santuario ni profanará el Santuario de su Dios; pues la consagración del óleo de la unción de su Dios está sobre él. Yo soy Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Tomará por esposa una virgen.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'No se casará con viuda, ni repudiada, ni deshonrada, ni prostituida, sino que tomará por esposa una virgen de entre su pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'Así no deshonrará su descendencia en medio de su pueblo, pues soy Yo Yahvé quien le santifico.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Y habló Yahvé a Moisés y dijo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, '“Habla a Aarón y dile: Ninguno de tu descendencia, durante (todas) sus generaciones, que tenga un defecto corporal, se acercará a presentar el pan de su Dios;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'porque ningún hombre que tenga defecto corporal, ha de acercarse; ni ciego, ni cojo, ni mutilado, ni desproporcionado,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'ni hombre que tenga quebrado el pie o la mano;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'ni jorobado, ni débil, ni enfermo de los ojos, ni sarnoso, ni tiñoso, ni eunuco.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Ninguno de la estirpe de Aarón que tenga un defecto corporal puede acercarse para ofrecer los sacrificios que se queman en honor de Yahvé. Tiene un defecto corporal, y por eso no puede acercarse para ofrecer el pan de su Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Sin embargo podrá comer del pan de su Dios, de las cosas santísimas y de las santas,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'mas no penetrará hasta el velo ni se llegará al altar, porque tiene defecto, no sea que profane mis cosas santas; pues Yo soy Yahvé, que los santifico.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Moisés dijo esto a Aarón y a sus hijos, y a todos los hijos de Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Habló Yahvé a Moisés y dijo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, '“Di a Aarón y a sus hijos que respeten las ofrendas santas que los hijos de Israel me consagran y que no profanen mi santo nombre. Yo soy Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Diles: Cualquiera de todo vuestro linaje de vuestras generaciones que siendo, impuro se acercare a las cosas santas que los hijos de Israel consagran a Yahvé, será extirpado delante de Mí. Yo soy Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Ninguno de la estirpe de Aarón que sea leproso o tenga flujo, comerá de las cosas santas, hasta que se purifique. El que tocare a una persona contaminada por contacto con un cadáver, o el que haya tenido un derrame de semen,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'o haya tocado algún reptil que lo contaminó, o a una persona que le contaminó con cualquier clase de impureza:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'quien tocare estas cosas, quedará impuro hasta la tarde, y no comerá de las cosas santas, sino que lavará su cuerpo con agua;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'y después de la puesta del sol quedará limpio y podrá comer de las cosas santas, pues son su alimento.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'No comerá de bestia muerta o desgarrada (por fieras), para no contaminarse con ella. Yo soy Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Que guarden mis preceptos, no sea que cargados de pecados mueran por ellos, por haber profanado (lo santo). Yo soy Yahvé, que los santifico.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Ningún extraño comerá de las cosas santas; tampoco ningún huésped del sacerdote ni jornalero suyo coma de las cosas santas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Pero el esclavo comprado por el sacerdote con su dinero, este podrá comer de ellas, también los siervos nacidos en su casa podrán comer de su pan.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'La hija de un sacerdote casada con hombre extraño, no podrá comer de lo que ha sido alzado de las cosas santas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Mas si la hija del sacerdote quedare viuda o repudiada, sin tener hijo, y volviere a la casa de su padre, podrá comer del pan de su padre, como en su juventud; pero ningún extraño comerá de él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Quien por ignorancia comiere de cosa santa, la restituirá al sacerdote, añadiendo una quinta parte.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'No profanen, pues, (los sacerdotes) las cosas santas ofrecidas por los hijos de Israel a Yahvé;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'pues los cargarían con la iniquidad del delito que cometen al comer de sus cosas santas. Yo soy Yahvé, que los santifico.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, '“Habla a Aarón y a sus hijos y a todos los hijos de Israel y diles: Si alguno de la casa de Israel, o de los extranjeros residentes en Israel, presenta su oblación, sea en cumplimiento de su voto, o como ofrenda voluntaria suya, si la presenta a Yahvé como holocausto,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'la víctima, a fin de alcanzaros gracia, ha de ser macho sin tacha: buey, oveja o cabra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'No ofrezcáis nada que tenga defecto, pues no será aceptado de vuestras manos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Si alguno ofrece a Yahvé ganado mayor o ganado menor como sacrificio pacífico, sea en cumplimiento de un voto, sea como ofrenda voluntaria, ha de ser sin defecto para que sea acepto. No debe tener defecto alguno.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Animal ciego, o cojo, o mutilado, o ulcerado, o sarnoso, o roñoso no presentaréis ante Yahvé, ni quemaréis nada de ellos en el altar para Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Buey u oveja que tenga un miembro demasiado largo o demasiado corto, los podrás presentar como ofrenda voluntaria, mas para voto no serán aceptos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Animal que tenga los testículos aplastados, majados, arrancados o cortados, no lo habéis de ofrecer a Yahvé. No hagáis esto en vuestra tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Nada recibiréis de la mano del extranjero como pan de vuestro Dios, porque sus ofrendas son corrompidas; hay defecto en ellos; no serán aceptadas de vuestras manos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Y habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, '“Cuando nace un ternero, o cordero, o cabrito, quedará siete días con su madre; y desde el día octavo en adelante, será agradable para ser ofrecido a Yahvé en sacrificio por el fuego.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'No inmoléis en el mismo día, vaca u oveja juntamente con su cría.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Al ofrecer a Yahvé un sacrificio en acción de gracias, lo habéis de ofrecer de tal modo que sea aceptado de vuestras manos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'Será comido ese mismo día; no dejaréis nada de él hasta la mañana. Yo soy Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Guardad mis mandamientos y cumplidlos. Yo soy Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Y no profanéis mi santo nombre, pues Yo he de ser santificado en medio de los hijos de Israel. Yo soy Yahvé que os santifico,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'y que os he sacado de la tierra de Egipto, para ser vuestro Dios. Yo soy Yahvé.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, '“Habla a los hijos de Israel y diles: Las fiestas solemnes de Yahvé, que celebraréis como asambleas santas, son estas:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Seis días se trabajará, mas el séptimo día será día de descanso solemne, asamblea santa, en que no haréis trabajo alguno. Será sábado consagrado a Yahvé dondequiera que habitéis.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Estas son las fiestas solemnes de Yahvé, las asambleas santas que habréis de celebrar en las fechas señaladas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'El mes primero, el día catorce del mes, entre las dos luces, será la Pascua de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'El quince de ese mes se celebrará la fiesta de los Ácimos en honor de Yahvé. Durante siete días comeréis panes ácimos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'El día primero tendréis asamblea santa; ningún trabajo servil haréis (en él).');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Ofreceréis a Yahvé por siete días sacrificios de combustión. El séptimo día celebraréis asamblea santa; no haréis ningún trabajo servil.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, '“Habla a los hijos de Israel y diles: Cuando, después de entrar en el país que Yo os daré, segareis allí la mies llevareis una gavilla, como primicias de vuestra siega, al sacerdote,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'el cual mecerá la gavilla; delante de Yahvé, para que os sea favorable. El día siguiente al sábado la mecerá el sacerdote.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Ese mismo día en que meciereis la gavilla, sacrificaréis un cordero primal, sin tacha, en holocausto a Yahvé,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'juntamente con su oblación consistente en dos décimas de flor de harina amasada con aceite, como ofrenda quemada en olor grato para Yahvé. Su libación será de vino, un cuarto de hin.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'No comeréis pan, ni grano tostado, ni espigas nuevas, antes de este mismo día, antes de traer la ofrenda de vuestro Dios. Ley perpetua será esta de generación en generación dondequiera que habitéis.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Contaréis siete semanas enteras desde el día siguiente al sábado, (o sea) desde el día en que habréis ofrecido la gavilla de la ofrenda mecida,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'hasta el día siguiente al séptimo sábado —serán cincuenta días— y entonces ofreceréis a Yahvé una nueva oblación.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Traeréis de vuestras casas para ofrenda mecida dos panes, hechos con dos décimas de flor de harina, y cocidos con levadura, como primicias a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Juntamente con el pan ofreceréis en holocausto a Yahvé siete corderos primales sin tacha, un becerro y dos carneros, con su ofrenda y sus libaciones, en sacrificio de combustión, de olor grato a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Ofreceréis también un macho cabrío como sacrificio por el pecado, y dos corderos primales como sacrificio pacífico.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'El sacerdote los mecerá, como ofrenda mecida ante Yahvé, juntamente con el pan de las primicias y con los dos corderos; serán santos a Yahvé y pertenecerán al sacerdote.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Ese mismo día celebraréis una asamblea santa, y no haréis ningún trabajo servil. Ley perpetua será esta de generación en generación dondequiera que habitéis.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Cuando segareis la mies de vuestra tierra, no segarás los límites extremos de tu campo, ni recogerás las espigas de tu mies; las dejarás para el pobre y para el extranjero. Yo soy Yahvé, vuestro Dios.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, '“Habla a los hijos de Israel y diles: En el mes séptimo, el primero del mes, tendréis un descanso solemne, una fiesta memorable con toque de trompetas, una asamblea santa.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Ningún trabajo servil haréis, y ofreceréis a Yahvé un sacrificio de combustión.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, '“El día décimo de este séptimo mes será el día de la Expiación, en el cual tendréis asamblea santa; os mortificaréis y ofreceréis a Yahvé un sacrificio de combustión.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'No haréis en ese día ningún trabajo, pues es día de expiación, en el cual se ha de hacer la expiación por vosotros delante de Yahvé, vuestro Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Toda persona que en ese día no se mortifique será extirpada de entre su pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Y toda persona que en tal día hiciere un trabajo cualquiera, Yo la extirparé de entre su pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'No haréis, pues, trabajo alguno. Es ley perpetua durante vuestras generaciones dondequiera que habitéis.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Os será sábado de descanso absoluto, en el cual mortificaréis vuestras almas. El día nueve del mes, comenzando por la tarde, de una tarde a la otra, guardaréis vuestro descanso.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, '“Habla a los hijos de Israel y diles: El día quince de ese séptimo mes (celebraréis) durante siete días la fiesta de los Tabernáculos en honor de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'El día primero habrá asamblea santa y no haréis ningún trabajo servil.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Durante siete días ofreceréis a Yahvé sacrificios de combustión. El día octavo tendréis asamblea santa y ofreceréis a Yahvé un sacrificio de combustión. Es asamblea solemne. No haréis ningún trabajo servil.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Estas son las fiestas de Yahvé en que habéis de convocar para asamblea santa y ofrecer a Yahvé sacrificios de combustión, holocaustos, oblaciones, víctimas y libaciones; cada cosa en el día señalado,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'sin contar los sábados de Yahvé, vuestros dones, todos vuestros votos y todas vuestras oblaciones voluntarias que ofrezcáis a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Celebraréis, pues, el día quince de este séptimo mes, después de haber recolectado los frutos de la tierra, la fiesta en honor de Yahvé durante siete días. El primer día será sábado solemne e igualmente el octavo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'El primer día tomaréis frutos de árboles hermosos, gajos de palmeras, ramos de árboles frondosos y sauces del arroyo; y os regocijaréis en la presencia de Yahvé, vuestro Dios, por espacio de siete días.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Celebraréis esta fiesta en honor de Yahvé siete días cada año. Será ley perpetua de generación en generación. En el séptimo mes la celebraréis.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'Durante siete días habitaréis en tabernáculos. Todos los nativos de Israel habitarán bajo tabernáculos,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'para que sepan vuestros hijos que Yo hice habitar bajo tabernáculos a los hijos de Israel cuando los saqué de la tierra de Egipto. Yo soy Yahvé, vuestro Dios.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Moisés promulgó estas fiestas de Yahvé a los hijos de Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, '“Manda a los hijos de Israel que te traigan aceite puro de olivas majadas para el candelabro para alimentar continuamente las lámparas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Aarón las aderezará fuera del velo del Testimonio, en el Tabernáculo de la Reunión, (para que ardan) de continuo ante Yahvé desde la tarde hasta la mañana. Es ley perpetua para vuestras generaciones.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'El aderezará siempre las lámparas del candelabro (de oro) puro que está delante de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Tomarás flor de harina, y cocerás de ella doce tortas. Dos décimas tomarás para cada torta.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Las colocarás en dos pilas, seis en cada pila, sobre la mesa pura delante de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Pondrás sobre cada pila incienso puro, que haga del pan un memorial que se ofrece a Yahvé mediante el fuego.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Cada sábado se aderezará delante de Yahvé continuamente el pan de parte de los hijos de Israel. Será una alianza perpetua.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Pertenecerá a Aarón y a sus hijos, que lo comerán en lugar sagrado; porque es para él cosa santísima como las ofrendas hechas a Yahvé mediante el fuego. Es ley perpetua.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Se metió entre los hijos de Israel el hijo de una mujer israelita, pero de padre egipcio; y riñeron en el campamento el hijo de la israelita y un hombre de Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'Y blasfemó el hijo de la israelita el nombre (de Dios) y le maldijo, por lo cual le condujeron a Moisés. El nombre de su madre era Selomit, hija de Dibrí, de la tribu de Dan.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Le guardaron en prisión esperando el juicio por boca de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Y Yahvé habló a Moisés, y dijo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, '“Saca al blasfemo fuera del campamento, y todos los que le oyeron pongan las manos sobre su cabeza, y apedréele todo el pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Y dirás a los hijos de Israel estas palabras: “Cualquier hombre que maldijere a su Dios llevara sobre sí su pecado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'Quien blasfemare el Nombre de Yahvé muera irremisiblemente; toda la Congregación le apedreará. El extranjero y el indígena cuando blasfemare el Nombre morirá.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Quien hiriere a otro mortalmente, muera irremisiblemente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Quien hiriere mortalmente a una bestia restituirá otra por ella. Bestia por bestia.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Si alguno causare una herida a otro, según hizo él, así se le hará;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'fractura por fractura, ojo por ojo, diente por diente; se le hará la misma lesión que él haya causado a otro.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Quien matare una bestia hará restitución por ella, mas quien matare a un hombre, morirá.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Una misma ley tendréis para el extranjero y para los de vuestro pueblo; porque Yo soy Yahvé, vuestro Dios.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Habló entonces Moisés a los hijos de Israel, y sacaron al blasfemo fuera del campamento y le apedrearon. Así hicieron los hijos de Israel como Yahvé había mandado a Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Habló Yahvé a Moisés en el monte Sinaí y dijo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, '“Habla a los hijos de Israel y diles: Después de vuestra entrada en el país que Yo os daré, descansará también la tierra su sábado en honor de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Seis años sembrarás tu campo, y seis años podarás tu viña y recogerás sus frutos;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'pero el séptimo año será para la tierra un sábado de absoluto descanso, un sábado en honor de Yahvé: No sembrarás tu campo, ni podarás tu viña.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'No segarás lo que de suyo naciere de tu siega (anterior), ni recogerás las uvas de tu viña sin podar. Año de descanso absoluto será para la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Lo que la tierra diere durante el descanso os servirá de alimento a ti, a tu siervo, a tu sierva, a tu jornalero y al extranjero que mora contigo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'También a tus ganados y a los animales de tu tierra, servirán de alimento todos sus frutos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Contarás siete semanas de años, siete veces siete años; de modo que el tiempo de las siete semanas de años vendrá a sumar cuarenta y nueve años.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Entonces, en el mes séptimo, el diez del mes, harás resonar la trompeta sonora; en el día de la Expiación haréis resonar la trompeta por toda vuestra tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Santificaréis el año quincuagésimo, y proclamaréis en el país libertad para todos sus habitantes. Será para vosotros un jubileo; cada uno recobrará su propiedad, y cada cual regresará a su familia.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Un jubileo os será el año quincuagésimo; no sembraréis, ni segaréis lo que de suyo naciere de ella, ni vendimiaréis la viña, que ha quedado sin podar;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'porque es el jubileo, que os será santo. Comeréis el producto espontáneo del campo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'En este año jubilar volveréis cada cual a vuestra propiedad.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Si vendiereis algo a vuestro conciudadano o le comprareis alguna cosa, mirad que nadie perjudique a su hermano.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Conforme al número de los años transcurridos después del jubileo lo comprarás a tu conciudadano, y conforme al número de los años de cosecha él te lo ha de vender.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Cuanto más numerosos sean los años, tanto más cobrarás; y cuanto menos años queden, tanto más lo bajarás, porque el número de cosechas es lo que él te vende.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Nadie oprima a su prójimo, antes bien teme a tu Dios; pues Yo soy Yahvé, vuestro Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Guardad mis mandamientos y observad mis preceptos y cumplidlos; así viviréis seguros en la tierra;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'y la tierra dará su fruto, y comeréis hasta saciaros; y habitaréis tranquilamente en ella.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Y si preguntáis: ¿Qué comeremos el año séptimo, puesto que no sembraremos ni recogeremos nuestros productos?');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, '(Sabed que) Yo os mandaré mi bendición en el año sexto, de modo que (la tierra) producirá frutos para tres años;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'sembraréis el año octavo, y seguiréis comiendo de la cosecha añeja hasta el año noveno. Hasta que venga su cosecha seguiréis comiendo de lo añejo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'El suelo no puede venderse a perpetuidad, pues mía es la tierra, puesto que vosotros sois para mí como extranjeros y peregrinos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'En todo el país de vuestra posesión concederéis derecho de rescatar la tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Si se empobreceré tu hermano y vendiere algo de su posesión, vendrá su rescatador, el pariente suyo más cercano, y rescatará lo vendido por su hermano.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Si uno no teniendo rescatador adquiriere él mismo medios y hallare lo suficiente para rescatarlo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'haga el cómputo de los años transcurridos después de la venta y pague al comprador la suma restante; así recobrará su posesión.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Pero si no hallare lo suficiente para recobrarla, lo vendido quedará en poder del comprador hasta el año jubilar; y en el jubileo será libre, y (el vendedor) la recobrará de nuevo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Si uno vendiere una casa de habitación en ciudad amurallada, durará su derecho de rescatarla hasta cumplirse el año de su venta. Un año entero durará su derecho de rescate.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'En caso de no ser rescatada dentro de un año entero, la casa situada en ciudad amurallada quedará para siempre al comprador y a sus descendientes. No saldrá de su poder en el jubileo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Mas las casas de las aldeas no amuralladas serán tratadas como los campos del país: pueden rescatarse, y en el año jubilar quedan libres.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'En cuanto a las ciudades de los levitas, podrán siempre rescatar las casas de las ciudades de su posesión.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Si uno compra una casa de los levitas, la casa vendida, en la ciudad de su posesión, saldrá libre en el jubileo: porque las casas de las ciudades de los levitas son su posesión en medio de los hijos de Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Tampoco pueden venderse los campos en torno a las ciudades de ellos, pues son posesión de ellos a perpetuidad.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Si tu hermano empobreciere y se apoya sobre ti, lo sostendrás, sea extranjero o advenedizo, para que pueda vivir junto a ti.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'No tomarás de él interés ni usura, antes bien teme a tu Dios y deja vivir a tu hermano junto a ti.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'No le cobrarás interés por tu dinero ni le darás tus víveres a usura.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Yo Soy Yahvé, vuestro Dios, que os saqué de la tierra de Egipto para daros la tierra de Canaán, a fin de ser vuestro Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Si empobreciere tu hermano a tu lado y se te vendiere, no le impondrás trabajos de esclavo;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'estará contigo como jornalero y como advenedizo, te servirá hasta el año del jubileo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Entonces saldrá libre de tu casa, él y sus hijos juntamente con él, y volverá a su familia y a la posesión de sus padres.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Porque son mis siervos, a quienes Yo saqué de la tierra de Egipto; no han de ser vendidos como esclavos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'No le dominarás con dureza, sino que tendrás temor a tu Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Los siervos y las siervas que necesites serán de las naciones que os rodean; de ellos podréis adquirir siervos y siervas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'También de los hijos de los advenedizos que moran en medio de vosotros podréis comprarlos, y de sus familias residentes entre vosotros, es decir, de los nacidos en vuestra tierra. Esos serán vuestra propiedad.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'Los dejaréis en herencia a vuestros hijos después de vosotros como posesión hereditaria. A los tales podréis tener por siervos a perpetuidad. Pero si se trata de vuestros hermanos, los hijos de Israel, ninguno de vosotros domine a su hermano con dureza.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Si el extranjero o advenedizo que mora contigo, adquiriere riquezas, y si junto a él tu hermano empobreciere y se vendiere al extranjero que mora contigo, o a algún descendiente de la familia del extranjero;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'después de haberse vendido le quedará el derecho al rescate: uno de sus hermanos podrá rescatarlo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'Lo rescatará su tío, o el hijo de su tío; o algún pariente cercano suyo dentro de su parentela podrá rescatarlo, o si alcanzare los medios, él mismo podrá rescatarse.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Hará el cómputo con aquel que le compró, desde el año de su venta hasta el año del jubileo; el precio de su venta será según el número de años, los días (de su trabajo) le serán computados como los de un jornalero.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Si faltan todavía muchos años, pagará en proporción de ellos el precio de su rescate, descontándolo del precio con que fue comprado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'Y si faltan pocos años hasta el año del jubileo, hará el mismo cómputo; en proporción de los años pagará el precio de su rescate.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Como quien trabaja a jornal año por año, así estará con él; no permitas que le trate con dureza ante tus ojos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Si no fuere rescatado por otros, quedará libre el año del jubileo, él y sus hijos juntamente con él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Porque siervos míos son los hijos de Israel; siervos míos son, a quienes Yo he sacado del país de Egipto. Yo soy Yahvé, vuestro Dios.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, '“No os hagáis ídolos, ni erijáis imágenes ni estelas de culto; no coloquéis en vuestra tierra piedras esculpidas para postraros ante ellas, porque Yo soy Yahvé, vuestro Dios.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Observad mis sábados, y respetad mi Santuario. Yo soy Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Si siguiereis mis leyes y guardareis mis mandamientos, poniéndolos en práctica,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'os enviaré las lluvias a su tiempo, para que la tierra de sus productos y el árbol del campo su fruto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'El tiempo de trillar la mies se prolongará entre vosotros hasta la vendimia, y la vendimia se prolongará hasta la siembra, y comeréis vuestro pan en abundancia, y habitaréis en seguridad en vuestra tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Yo daré paz al país, y dormiréis sin que nadie os espante; haré desaparecer del país las bestias feroces, y la espada no pasara por vuestra tierra.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Perseguiréis a vuestros enemigos, que caerán ante vosotros al filo de la espada.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Cinco de vosotros perseguirán a cien, y cien de vosotros pondrán en fuga a diez mil; y vuestros enemigos caerán ante vosotros al filo de la espada.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Yo volveré hacia vosotros mi rostro. Yo os haré fecundos y os multiplicaré y mantendré mi alianza con vosotros.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Comeréis frutos añejos, muy añejos, hasta echar fuera los añejos para dar cabida a los nuevos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Estableceré mi morada en medio de vosotros, y no os detestará mi alma.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'En medio de vosotros marcharé, y seré vuestro Dios, y vosotros seréis mi pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Yo soy Yahvé, vuestro Dios, que os saqué de la tierra de Egipto, para que no fueseis sus esclavos; rompí las coyundas de vuestro yugo y os hice andar erguida la cabeza.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Pero si no me escucháis ni cumplís todos estos mandamientos;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'si despreciáis mis leyes y rechazáis mis preceptos, no haciendo caso de todos mis mandamientos y rompiendo mí pacto,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'mirad lo que Yo entonces haré con vosotros: Traeré sobre vosotros el espanto, la consumación y la fiebre, que os abrasen los ojos y os consuman el alma. Sembraréis en vano vuestra semilla, pues se la comerán vuestros enemigos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Me volveré contra vosotros, de modo que seréis derrotados ante vuestros enemigos; os tiranizarán los que os aborrecen, y huiréis sin que nadie os persiga.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Si ni aun con esto me obedeciereis, volveré a castigaros siete veces más por vuestros pecados.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'Quebrantaré vuestra orgullosa fuerza y haré vuestro cielo como hierro y vuestra tierra como bronce.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'Os esforzaréis inútilmente, pues vuestra tierra no dará sus productos, ni el árbol del campo sus frutos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Y si siguiereis oponiéndoos a Mí y no quisiereis oírme, volveré a castigaros siete veces más a causa de vuestros pecados.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Soltaré contra vosotros las fieras del campo, que os privarán de vuestros hijos, destrozarán vuestro ganado y os reducirán a pocos, de modo que vuestros caminos queden desiertos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Si aun con esto no os dejareis corregir por Mí sino que siguiereis en oposición conmigo,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'Yo también me opondré a vosotros, y os castigaré también por mi parte siete veces más por vuestros pecados.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'Traeré sobre vosotros la espada de la venganza que vengue mi pacto; y si os refugiareis en vuestras ciudades, enviaré la peste en medio de vosotros y seréis entregados en mano de vuestros enemigos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Cuando Yo os quebrantare el sostén del pan, diez mujeres cocerán (todo) vuestro pan en un solo horno, y os lo darán por peso; comeréis y no os saciaréis.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Si después de esto todavía no obedeciereis y siguiereis oponiéndoos a Mí,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'Yo me opondré a vosotros con saña, y os castigaré Yo también siete veces más por vuestros pecados.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'Comeréis la carne de vuestros hijos, y también la carne de vuestras hijas devoraréis.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Destruiré vuestros lugares altos, abatiré vuestras estatuas, echaré vuestros cadáveres sobre los cadáveres de vuestros ídolos, y mi alma os detestará.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Convertiré vuestras ciudades en desiertos y devastaré vuestros santuarios, no aceptaré ya más el olor grato de vuestros sacrificios;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'y asolaré el país a tal extremo, que queden atónitos vuestros mismos enemigos al ocuparlo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'A vosotros, empero, os esparciré entre las naciones, y desenvainaré la espada en pos de vosotros. Vuestro país será un yermo, y vuestras ciudades un desierto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Entonces disfrutará la tierra de sus sábados, todos los días que dure la desolación y vosotros estéis en la tierra de vuestros enemigos; entonces sí que descansará la tierra y gozará de sus sábados.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Durante todo el tiempo de la desolación descansará, lo que no pudo hacer en vuestros sábados cuando habitabais en ella.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'A los que quedaren de vosotros, les infundiré abatimiento en sus corazones en la tierra de sus enemigos; el ruido de una hoja que se vuela, los pondrá en fuga, huirán como quien huye de la espada, y caerán sin que nadie los persiga.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'Se atropellarán unos a otros, como delante de la espada, aunque nadie los persiga; y no podréis levantaros en presencia de vuestros enemigos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'Pereceréis entre las naciones, y os devorará la tierra de vuestros enemigos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'Y quienes de vosotros sobrevivan, serán consumidos por su propia iniquidad en los países de vuestros enemigos; y también por las iniquidades de sus padres serán consumidos como ellos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Entonces cuando confesaren sus iniquidades y las iniquidades de sus padres, las que cometieron contra Mí por sus infidelidades; y cuando confesaren cómo me resistieron,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'y cómo Yo por eso mismo resistí a ellos y los llevé al país de sus enemigos; cuando se doblegare su corazón incircunciso, y ellos aceptaren el castigo de su iniquidad,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'Yo entonces me acordaré de mi alianza con Jacob, y también de mi alianza con Isaac, y asimismo de mi alianza con Abrahán; y me acordaré del país.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Pero antes la tierra será abandonada por ellos y disfrutará de sus sábados, mientras quede desolada en su ausencia. Entretanto aceptarán el castigo de su iniquidad, por cuanto desecharon mis leyes y su alma detestó mis mandamientos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Pero aun con todo esto, estando ellos en tierra enemiga, no los desecharé ni los detestaré hasta destruirlos, anulando mi alianza con ellos, porque Yo soy Yahvé, su Dios,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'sino que me acordaré en favor de ellos, de la alianza hecha con sus padres, a quienes saqué de la tierra de Egipto, a vista de las naciones, para ser su Dios. Yo soy Yahvé.” Estos son los mandamientos, estatutos y leyes que Yahvé estableció entre Él y los hijos de Israel en el monte Sinaí, por boca de Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, '“Habla a los hijos de Israel y diles: Si uno hiciere un voto a Yahvé tocante a personas, estas (serán valoradas) según tu tasación.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'Si el objeto de tu tasación es un varón de veinte a sesenta años, tu valuación será de cincuenta siclos de plata, según el siclo del santuario.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'Mas si se trata de una mujer, tu valuación será de treinta siclos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'De los cinco a los veinte años, tu valuación será, para varón, veinte siclos; para mujer, diez siclos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'De un mes hasta la edad de cinco años, será tu valuación para niño cinco siclos de plata; para niña será tu valuación tres siclos de plata.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'De sesenta años para arriba, será tu valuación, para varón, quince siclos; para mujer, diez siclos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Si uno es tan pobre que no puede pagar tu valuación, será presentado al sacerdote, el cual le tasará a razón de los recursos que tenga el oferente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Si se trata de un animal que se puede ofrecer a Yahvé en oblación, todo lo que de él se diere a Yahvé será santo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'No se mudará ni se trocará bueno por malo, ni malo por bueno; y si de alguna manera se permutare un animal por otro, tanto el trocado como su sustituto serán cosa santa.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Mas si es uno de los animales impuros, de los que no se puede ofrecer como oblación a Yahvé, será presentado el animal al sacerdote,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'el cual lo tasará según sea bueno a malo; y se hará conforme a la estimación del sacerdote.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Si uno quisiere redimirlo, añada un quinto a tu valuación.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Si alguno consagra su casa, para que sea santa a Yahvé, la tasará el sacerdote, según sea buena o mala. Conforme a la valuación del sacerdote, así será.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Si el que consagró la casa desea rescatarla, añada la quinta parte al precio de tu valuación, y será suya.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Si uno consagra parte del campo de su posesión a Yahvé, será tu valuación según la cantidad de semilla necesaria para sembrarlo: a razón de cincuenta siclos por cada hómer de cebada.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Si él consagró su campo desde el año del jubileo, se atendrá a tu valuación.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Mas si consagra su campo después del jubileo, el sacerdote hará la valuación del precio a razón de los años que queden hasta el año del jubileo; y según eso será el descuento de tu valuación.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Si el que consagró el campo desea rescatarlo, añada la quinta parte al precio de tu valuación, y quedará suyo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Pero si no rescata el campo, y este se vendiere a otro, el campo no podrá ser rescatado en adelante.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'Ese campo, cuando salga libre en el jubileo, será consagrado a Yahvé como campo de anatema, y pertenecerá al sacerdote.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Si alguno consagra a Yahvé un campo que compró y que no forma parte de su patrimonio,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'el sacerdote le calculará el importe de la valuación hasta el año del jubileo; y él pagará ese mismo día la suma de la valuación como cosa consagrada a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'El año del jubileo volverá el campo al vendedor, al que pertenece como propietario del campo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Todas tus valuaciones se harán según el siclo del Santuario; veinte güeras son un siclo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Nadie, empero, podrá consagrar los primogénitos de los animales, que por ser primogénitos son de Yahvé. Sean del ganado mayor o del menor, pertenecen a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Si se trata de un animal impuro, y uno desea rescatarlo según tu estimación, añada la quinta parte al precio; mas si no fuere rescatado, sea vendido conforme a tu valuación.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Nada de lo que uno de toda su propiedad dedique a Yahvé con anatema, sea hombre o bestia o campo de su posesión, podrá venderse ni rescatarse. Toda cosa dedicada con anatema es sacratísima para Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Ninguna persona consagrada con anatema podrá ser rescatada; muera irremisiblemente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'El diezmo entero de la tierra, tanto de las semillas de la tierra como de los frutos de los árboles, es de Yahvé; es cosa consagrada a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Si alguno quiere rescatar parte de su diezmo, añada la quinta parte a su precio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Cada décimo animal del ganado mayor y del ganado menor, de todo lo que pasa bajo el cayado, cada décima cabeza será consagrada a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'No se escogerá entre animal bueno o malo, ni se ha de trocar; y si hiciere trueque, tanto el animal trocado como su sustituto serán cosas santas; no podrán ser rescatados.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Estos son los mandamientos que Yahvé dio a Moisés para los hijos de Israel en el monte Sinaí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'El segundo año después de la salida del país de Egipto, el primer día del mes segundo, habló Yahvé a Moisés en el desierto del Sinaí, en el Tabernáculo de la Reunión, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, '“Haced el censo de toda la Congregación de los hijos de Israel, según sus familias y casas paternas, contando por cabezas los nombres de todos los varones');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'de veinte años para arriba de todos los israelitas aptos para la guerra. Tú y Aarón los contaréis según sus escuadrones.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Os acompañará un hombre de cada tribu, que sea cabeza de su casa paterna.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Estos son los nombres de los varones que os ayudarán: De Rubén, Elisur, hijo de Sedeur,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'de Simeón, Selumiel, hijo de Surisadai;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'de Judá, Naasón, hijo de Aminadab;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'de Isacar, Natanael, hijo de Suar;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'de Zabulón, Eliab, hijo de Helón;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'de los hijos de José: de Efraím, Elisamá, hijo de Amiud; de Manasés, Gamaliel, hijo de Pedasur:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'de Benjamín, Abidán, hijo de Gedeoní;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'de Dan, Ahiéser, hijo de Amisadai;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'de Aser, Pagiel, hijo de Ocrán;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'de Gad, Eliasaf, hijo de Deuel;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'de Neftalí, Ahirá, hijo de Enan.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Estos fueron los designados de entre la Congregación. Eran los príncipes de las tribus de sus padres y cabezas de los millares de Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Moisés y Aarón tomaron a estos hombres designados nominalmente');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'y reunieron a toda la Congregación el día primero del segundo mes. Entonces fueron registrados, cabeza por cabeza, los varones de veinte años para arriba, según sus familias y casas paternas, conforme al número de los nombres.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'Como Yahvé había mandado a Moisés, así los contó este en el desierto del Sinaí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Hijos de Rubén, primogénito de Israel. Fueron alistados sus descendientes según sus familias y casas paternas, nominalmente y cabeza por cabeza, todos los varones de veinte años para arriba, todos los aptos para la guerra,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'y fueron contados de la tribu de Rubén cuarenta y seis mil quinientos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Hijos de Simeón. Fueron alistados sus descendientes, según sus familias y casas paternas, nominalmente y cabeza por cabeza, todos los varones de veinte años para arriba, todos los aptos para la guerra;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'y fueron contados de la tribu de Simeón cincuenta y nueve mil trescientos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Hijos de Gad. Fueron alistados nominalmente sus descendientes, según sus familias y casas paternas, los de veinte años para arriba, todos los aptos para la guerra;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'y fueron contados de la tribu de Gad cuarenta y cinco mil seiscientos cincuenta.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Hijos de Judá. Fueron alistados nominalmente sus descendientes, según sus familias y casas paternas, los de veinte años para arriba, todos los aptos para la guerra;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'y fueron contados de la tribu de Judá setenta y cuatro mil seiscientos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Hijos de Isacar. Fueron alistados nominalmente sus descendientes, según sus familias y casas paternas, los de veinte años para arriba, todos los aptos para la guerra;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'y fueron contados de la tribu de Isacar cincuenta y cuatro mil cuatrocientos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Hijos de Zabulón. Fueron alistados nominalmente sus descendientes, según sus familias y casas paternas, de veinte años para arriba, todos los aptos para la guerra;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'y fueron contados de la tribu de Zabulón cincuenta y siete mil cuatrocientos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Hijos de José, hijos de Efraím. Fueron alistados nominalmente sus descendientes, según sus familias y casas paternas, los de veinte años para arriba, todos los aptos para la guerra;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'y fueron contados de la tribu de Efraím cuarenta mil quinientos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Hijos de Manasés. Fueron alistados nominalmente sus descendientes, según sus familias y sus casas paternas, los de veinte años para arriba, todos los aptos para la guerra;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'y fueron contados de la tribu de Manasés treinta y dos mil doscientos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Hijos de Benjamín. Fueron alistados nominalmente sus descendientes, según sus familias y sus casas paternas, los de veinte años para arriba, todos los aptos para la guerra;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'y fueron contados de la tribu de Benjamín treinta y cinco mil cuatrocientos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Hijos de Dan. Fueron alistados nominalmente sus descendientes, según sus familias y casas paternas, los de veinte años para arriba, todos los aptos para la guerra;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'y fueron contados de la tribu de Dan sesenta y dos mil setecientos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Hijos de Aser. Fueron alistados nominalmente sus descendientes, según sus familias y casas paternas, los de veinte años para arriba, todos los aptos para la guerra;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'y fueron contados de la tribu de Aser cuarenta y un mil quinientos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Hijos de Neftalí. Fueron alistados nominalmente sus descendientes, según sus familias y casas paternas, los de veinte años para arriba, todos los aptos para la guerra;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'y fueron contados de la tribu de Neftalí cincuenta y tres mil cuatrocientos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Estos son los empadronados, a quienes contaron Moisés y Aarón, con los doce príncipes de Israel, uno por cada casa paterna,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'y fue el número de todos los empadronados de los hijos de Israel, según sus casas paternas, de veinte años para arriba, todos aptos para la guerra:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'el número de todos esos empadronados fue de seiscientos tres mil quinientos cincuenta.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Los levitas no fueron contados como los otros, según la tribu de sus padres;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'porque Yahvé habló a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, '“No contarás la tribu de Leví, y no harás su censo entre los hijos de Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'Encargarás a los levitas el cuidado del Tabernáculo del Testimonio, con todos sus utensilios, y todo cuanto le pertenece: ellos llevarán el Tabernáculo y todos sus utensilios, ejercerán allí su ministerio y acamparán alrededor del Tabernáculo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Al ponerse en marcha el Tabernáculo, los levitas lo desarmarán; y al pararse el Tabernáculo, los levitas lo armarán; y el extraño que se acercare morirá.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Los hijos de Israel fijarán sus tiendas, cada (tribu) en su campamento, y bajo su bandera, según sus escuadrones;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'los levitas, en cambio, acamparán alrededor del Tabernáculo del Testimonio, para que la ira (de Dios) no estalle contra la Congregación de los hijos de Israel. Los levitas estarán encargados de guardar el Tabernáculo del Testimonio.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, '');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Habló Yahvé a Moisés y a Aarón, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, '“Los hijos de Israel acamparán cada cual junto a su bandera, bajo las enseñas de sus casas paternas; acamparán frente al Tabernáculo de la Reunión, todo en torno a él.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Delante, al oriente, se fijará la bandera del campamento de Judá, según sus escuadrones, siendo el príncipe de los hijos de Judá, Naasón, hijo de Aminadab.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'Su ejército es, según el censo, de setenta y cuatro mil seiscientos hombres.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'A su lado acampará la tribu de Isacar, siendo el príncipe de los hijos de Isacar, Natanael, hijo de Suar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'Su ejército es, según el censo, de cincuenta y cuatro mil cuatrocientos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'Luego la tribu de Zabulón, siendo el príncipe de los hijos de Zabulón, Eliab, hijo de Helón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'Su ejército es, según el censo, de cincuenta y siete mil cuatrocientos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'El total del campamento de Judá es, según el censo, de ciento ochenta y seis mil cuatrocientos, divididos en sus escuadrones. Estos son los primeros en ponerse en marcha.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'Al mediodía se ubicará la bandera del campamento de Rubén, según sus escuadrones, siendo el príncipe de los hijos de Rubén, Elisur, hijo de Sedeur.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'Su ejército es, según el censo, de cuarenta y seis mil quinientos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'A su lado acampará la tribu de Simeón, siendo el príncipe de los hijos de Simeón, Selumiel, hijo de Surisadai.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'Su ejército es, según el censo, de cincuenta y nueve mil trescientos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Luego la tribu de Gad, siendo el príncipe de los hijos de Gad, Eliasaf, hijo de Deuel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'Su ejército es, según el censo, de cuarenta y cinco mil seiscientos cincuenta.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'El total del campamento de Rubén es, según el censo, de ciento cincuenta y un mil cuatrocientos cincuenta, repartidos en sus escuadrones. Ellos se pondrán en marcha los segundos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Después se pondrá en marcha el Tabernáculo de la Reunión, es decir, el campamento de los levitas, en medio de los campamentos. Según el orden en que acampen, así se pondrán en marcha, cada uno en su lugar y bajo su bandera.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Al occidente estará la bandera del campamento de Efraím, con sus tropas, siendo el príncipe de los hijos de Efraím, Elisamá, hijo de Amiud.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'Su ejército es según el censo, de cuarenta mil quinientos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Junto a él estará la tribu de Manasés, siendo el príncipe de los hijos de Manasés, Gamaliel, hijo de Pedasur.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'Su ejército es, según el censo, de treinta y dos mil doscientos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Luego la tribu de Benjamín, siendo el príncipe de los hijos de Benjamín, Abidán, hijo de Gedeoní.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'Su ejército es, según el censo, de treinta y cinco mil cuatrocientos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'El total del campamento de Efraím es, según el censo de ciento ocho mil cien, repartidos en sus escuadrones. Ellos se pondrán en marcha los terceros.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Al norte estará la bandera del campamento de Dan, según sus ejércitos, siendo el príncipe de los hijos de Dan, Ahiéser, hijo de Amisadai.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'Su ejército es, según el censo, de sesenta y dos mil setecientos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Junto a él acampará la tribu de Aser, siendo el príncipe de los hijos de Aser, Pagiel, hijo de Ocrán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'Su ejército es, según el censo, de cuarenta y un mil quinientos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Luego la tribu de Neftalí, siendo el príncipe de los hijos de Neftalí, Ahirá, hijo de Enán.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'Su ejército es, según el censo, de cincuenta y tres mil cuatrocientos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'El total del campamento de Dan es, según el censo, de ciento cincuenta y siete mil seiscientos. Ellos se pondrán en marcha los postreros, según sus banderas.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Estos son los hijos de Israel inscriptos en el censo, según sus casas paternas. El total de los campamentos, según sus ejércitos respectivos, sumaba seiscientos tres mil quinientos cincuenta.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Los levitas no figuran en este censo de los hijos de Israel; así lo había mandado Yahvé a Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'E hicieron los hijos de Israel conforme a todo lo que Yahvé había ordenado a Moisés: acampaban bajo sus banderas, y se ponían en marcha cada cual según su familia y su casa paterna.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'He aquí los descendientes de Aarón y de Moisés, el día en que Yahvé habló con Moisés en el monte Sinaí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Y he aquí los nombres de los hijos de Aarón: Nadab, el primogénito; Abiú, Eleazar e Itamar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Estos son los nombres de los hijos de Aarón, los sacerdotes ungidos y consagrados para el sacerdocio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Nadab y Abiú murieron delante de Yahvé cuando en el desierto del Sinaí llevaron a la presencia de Yahvé un fuego extraño, y no tuvieron hijos. Eleazar e Itamar ejercieron el oficio de sacerdotes a las órdenes de su padre Aarón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Yahvé habló a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, '“Manda que se acerque la tribu de Leví, y preséntala delante del sacerdote Aarón para que le sirvan.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'Ellos se encargarán de las obligaciones de Aarón y de toda la Congregación respecto del Tabernáculo de la Reunión, ejerciendo el servicio de la Morada.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'Guardarán todos los utensilios del Tabernáculo de la Reunión, y se encargarán de los trabajos de los hijos de Israel en el servicio de la Morada.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Darás, pues, los levitas a Aarón y a sus hijos; a él le serán enteramente entregados por parte de los hijos de Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Encargarás a Aarón y a sus hijos que se ocupen (exclusivamente) de su sacerdocio; el extraño que se acercare morirá.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, '“He aquí que Yo he tomado a los levitas de en medio de los hijos de Israel, en lugar de todos los primogénitos que abren el seno de su madre. Los levitas son míos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Porque todos los primogénitos son míos; el día en que Yo herí a todo primogénito en la tierra de Egipto, santifiqué para Mí todos los primogénitos de Israel, tanto de hombres como de animales, míos son. Yo, Yahvé.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Yahvé habló a Moisés en el desierto del Sinaí, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, '“Haz el censo de los hijos de Leví según sus casas paternas y según sus familias, contando a todos los varones de un mes para arriba.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Moisés los contó según la orden de Yahvé, tal como le fue mandado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'He aquí los hijos de Leví por sus nombres: Gersón, Caat y Merarí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Estos son los nombres de los hijos de Gersón, según sus familias: Libní y Simeí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Los hijos de Caat, según sus familias: Amram, Isar, Hebrón y Usiel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Los hijos de Merarí, según sus familias: Mahalí y Musí. Estas son las familias de los levitas, según sus casas paternas:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'De Gersón descienden la familia de los libnitas y la de los simeítas. Estas son las familias de los gersonitas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Sus empadronados, contando a todos los varones, de un mes para arriba, fueron, según el censo, siete mil quinientos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Las familias de los gersonitas acampaban detrás de la Morada, al poniente.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'El príncipe de la casa paterna de los gersonitas era Eliasaf, hijo de Lael.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'Los hijos de Gersón tenían a su cargo en el Tabernáculo de la Reunión el cuidado de la Morada y del Tabernáculo, su cubierta, la cortina de la entrada del Tabernáculo de la Reunión,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'las cortinas del atrio, la cortina de la entrada del atrio que rodea la Morada y el altar, y las cuerdas para todo su servicio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'De Caat descienden la familia de los amramitas, la familia de los isaritas, la familia de los hebronitas, y la familia de los usielitas. Estas son las familias de los caatitas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'El número de todos sus varones, de un mes para arriba, fue de ocho mil seiscientos, encargados del servicio del Santuario.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Las familias de los hijos de Caat acampaban al costado de la Morada, en el flanco meridional.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'El príncipe de la casa paterna de las familias de los caatitas era Elisafán, hijo de Usiel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Ellos tenían a su cargo el Arca, la mesa, el candelabro, los altares, los utensilios del Santuario que se usan en el ministerio, el velo y todo lo perteneciente a su servicio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'El primer príncipe de los levitas era Eleazar, hijo del sacerdote Aarón, que tenía la superintendencia de los encargados del cuidado del Santuario.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'De Merarí descienden la familia de los mahalitas y la de los musitas: estas son las familias de Merarí.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Sus empadronados, contando a todos los varones, de un mes para arriba, fueron seis mil doscientos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'El príncipe de la casa paterna de las familias de Merarí era Suriel, hijo de Abihail. Estos acampaban al lado norte de la Morada.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Los hijos de Merarí tenían a su cargo el cuidado de los tablones de la Morada, de sus travesaños, columnas y basas, y de todos sus utensilios con todo lo perteneciente a su servicio;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'además de las columnas en torno al atrio, de sus basas, estacas y cuerdas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Frente a la Morada, al oriente, delante del Tabernáculo de la Reunión, por donde se levanta el sol, tenían sus tiendas Moisés y Aarón y los hijos de este, que custodiaban el Santuario en nombre de los hijos de Israel; el extraño que se acercaba era castigado con la muerte.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'El total de los levitas empadronados según sus familias por Moisés y Aarón, conforme a la orden de Yahvé, todos los varones de un mes para arriba, fue de veinte y dos mil.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Yahvé dijo a Moisés: “Haz el censo de todos los varones primogénitos de los hijos de Israel, de un mes para arriba, y cuéntalos por sus nombres.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Y tomarás para Mí a los levitas —Yo soy Yahvé— en lugar de todos los primogénitos de los hijos de Israel, y el ganado de los levitas en lugar de todos los primogénitos del ganado de los hijos de Israel.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Contó, pues, Moisés a todos los primogénitos de los hijos de Israel, como Yahvé se lo había mandado.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Y fueron, según el censo, todos los varones primogénitos de un mes para arriba, contados por nombres, veinte y dos mil doscientos setenta y tres.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Entonces habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, '“Toma a los levitas en lugar de todos los primogénitos de los hijos de Israel, y el ganado de los levitas en lugar del ganado de aquellos; y los levitas serán míos. Yo, Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Para el rescate de los doscientos setenta y tres primogénitos de los hijos de Israel que exceden del número de los levitas,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'tomarás cinco siclos por cabeza; los tomaras según el siclo del Santuario, que es de veinte güeras;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'y darás el dinero a Aarón y a sus hijos como rescate de los que sobrepasan el número de los levitas.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Y Moisés cobró el dinero del rescate a los que sobrepasaban el número de los rescatados por los levitas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'Tomó el dinero de parte de los primogénitos de los hijos de Israel: mil trescientos sesenta y cinco siclos, según el siclo del Santuario.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'Moisés dio el dinero del rescate a Aarón y a sus hijos, según la orden de Yahvé, como Yahvé había mandado a Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Habló Yahvé a Moisés y a Aarón, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, '“Haced el censo de los hijos de Caat, de entre los hijos de Leví, según sus familias y casas paternas,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'de treinta años para arriba, hasta los cincuenta, todos los que han de prestar servicio o ejercer alguna función en el Tabernáculo de la Reunión.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'He aquí el oficio de los hijos de Caat relativo al Tabernáculo de la Reunión, el Santo de los Santos:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Siempre que haya de levantarse el campamento, entrará Aarón con sus hijos, para bajar la cortina del velo y cubrir con ella el Arca del Testimonio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'Pondrán encima una cubierta de pieles de tejón, sobre la cual extenderán un paño todo de jacinto, y colocarán las varas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'También sobre la mesa de la proposición extenderán un paño de jacinto, sobre el cual pondrán los platos, las cucharas, las tazas y las copas para las libaciones, quedando encima el pan perpetuo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Sobre ellos tenderán un paño carmesí, cubriéndolo con una cubierta de pieles de tejón, y colocarán las varas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Luego tomarán una tela de jacinto con que cubrirán el candelabro del alumbrado, con sus lámparas, sus despabiladeras, sus platillos, y todos sus vasos para el aceite, todo lo necesario para su servicio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'Lo envolverán, con todos sus utensilios, en una cubierta de pieles de tejón, y lo pondrán sobre las angarillas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'También sobre el altar de oro tenderán un paño de jacinto, que cubrirán con una cubierta de pieles de tejón; y colocarán las varas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Luego tomarán todos los utensilios que se usan para el servicio del Santuario, los envolverán en un paño de jacinto, cubriéndolos con una cubierta de pieles de tejón, y los pondrán sobre las angarillas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Después quitarán las cenizas del altar, sobre el cual extenderán un paño de púrpura;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'pondrán encima todos los utensilios necesarios para su servicio: los braseros, los tenedores, las paletas, los tazones, todos los utensilios del altar, extenderán sobre él una cubierta de pieles de tejón y colocarán sus varas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Cuando Aarón y sus hijos hayan acabado de cubrir el Santuario y todos los enseres del Santuario y se levante el campamento, se llegarán los hijos de Caat para alzarlos; mas no tocarán el Santuario, no sea que mueran. Esto es lo que toca a los hijos de Caat (en el transporte) del Tabernáculo de la Reunión.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Eleazar, hijo de Aarón el sacerdote, tendrá a su cargo el aceite del alumbrado, el incienso aromático, la oblación perpetua, el óleo de la unción, el cuidado de toda la Morada y de todo lo perteneciente a ella, de (todo) el Santuario con sus utensilios.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Yahvé habló a Moisés y a Aarón, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, '“No permitáis que el linaje de las familias de los caatitas sea extirpado de en medio de los levitas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'Para que vivan y no mueran, cuando se lleguen a las cosas santísimas, haced con ellos de esta manera: Aarón y sus hijos vendrán y señalarán a cada uno su servicio y lo que ha de transportar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'Pero ellos no deben entrar, ni aun por un solo instante, para ver las cosas santas, no sea que mueran.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Yahvé habló a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, '“Haz también el censo de los hijos de Gersón, según sus casas paternas y sus familias.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'Desde treinta años para arriba, hasta los cincuenta los contarás a todos los que han de prestar servicio o ejercer alguna función en el Tabernáculo de la Reunión.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'He aquí el cargo de las familias de los gersonitas, tanto en el servicio como en el transporte.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'Llevarán las cortinas de la Morada y el Tabernáculo de la Reunión, su cubierta, la cubierta de pieles de tejón que está encima de aquella, el velo que se halla en la entrada del Tabernáculo de la Reunión,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'las cortinas del atrio y la cortina de la puerta de la entrada del atrio que rodea la Morada y el altar, con sus cuerdas y todos los utensilios de su servicio; harán todo lo referente a su servicio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Todo el servicio de los gersonitas, en todo lo que han de transportar o de ejecutar, estará a las órdenes de Aarón y de sus hijos. Vosotros les señalaréis lo que es de su obligación, todo lo que han de transportar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Este es el servicio de las familias de los gersonitas, relativo al Tabernáculo de la Reunión; el servicio de ellos estará bajo la dirección de Itamar, hijo del sacerdote Aarón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Haz también el censo de los hijos de Merarí según sus familias y sus casas paternas,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'contándolos desde los treinta años para arriba, hasta los cincuenta, a todos los que han de prestar servicio o ejercer alguna función en el Tabernáculo de la Reunión.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'He aquí los objetos del Tabernáculo de la Reunión, que tienen que llevar en todo su servicio: los tablones de la Morada, sus travesaños, sus columnas y sus basas,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'las columnas que rodean el atrio, sus basas, estacas y cuerdas, todos sus utensilios, y todo lo perteneciente a su servicio. Les señalaréis por nombre los objetos que tienen que transportar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Este es el oficio de las familias de los hijos de Merarí, conforme a todo su servicio en el Tabernáculo de la Reunión, bajo la dirección de Itamar, hijo de Aarón el sacerdote.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Moisés y Aarón y los príncipes de la Congregación contaron a los caatitas, según sus familias y sus casas paternas,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'de treinta años para arriba, hasta los cincuenta, a todos los que habían de prestar servicio o ejercer alguna función en el Tabernáculo de la Reunión.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'Y fueron los empadronados, según sus familias, dos mil setecientos cincuenta.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Estos fueron los empadronados de las familias de los caatitas, todos aquellos que servían en el Tabernáculo de la Reunión, a quienes contaron Moisés y Aarón, conforme a la orden que Yahvé había dado por boca de Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Los empadronados de los hijos de Gersón, contados según sus familias y sus casas paternas,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'de treinta años para arriba, hasta los cincuenta, todos los que habían de prestar servicio o ejercer alguna función en el Tabernáculo de la Reunión;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'esos, empadronados según sus familias y sus casas paternas, fueron dos mil seiscientos treinta.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Estos son los empadronados de las familias de los hijos de Gersón, todos aquellos que servían en el Tabernáculo de la Reunión, a quienes Moisés y Aarón contaron por orden de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Los empadronados de las familias de los hijos de Merarí, según sus familias y sus casas paternas,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'de treinta años para arriba, hasta los cincuenta, todos los que habían de prestar algún servicio o ejercer alguna función en el Tabernáculo de la Reunión;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'esos empadronados según sus familias, fueron tres mil doscientos.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Estos son los empadronados de las familias de los hijos de Merarí, a quienes Moisés y Aarón contaron por orden de Yahvé dada a Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'El total de los levitas contados por Moisés y Aarón y los príncipes de Israel, según sus familias y sus casas paternas,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'de treinta años para arriba, hasta los cincuenta, todos aquellos que tenían una función en el servicio y en el transporte del Tabernáculo de la Reunión,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'su número fue de ocho mil quinientos ochenta.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Conforme a la orden de Yahvé dada a Moisés, este asignó a cada uno su ministerio y lo que había de transportar. Y los designados fueron aquellos que Yahvé había señalado a Moisés.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, '“Manda a los hijos de Israel que alejen del campamento a todo leproso, y a todo aquel que padece flujo, así como a todo manchado por un muerto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Alejad tanto a hombres como a mujeres, echadlos fuera del campamento para que no contaminen los campamentos de aquellos en medio de quienes Yo habito.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Así lo hicieron los hijos de Israel, y los echaron fuera del campamento. Según Yahvé había mandado a Moisés, así lo hicieron los hijos de Israel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Yahvé habló a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, '“Di a los hijos de Israel: Si un hombre o una mujer cometiere cualquier pecado de los que suelen cometer los hombres, ofendiendo a Yahvé, téngase por culpable,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'confiese el pecado cometido y restituya íntegramente aquello en que haya delinquido, añadiendo un quinto; lo restituirá a aquel contra quien se hizo culpable.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Si este ya no tiene pariente a quien se podría restituir el objeto de delito, la restitución del mismo ha de hacerse a Yahvé (y será entregado) al sacerdote, además del carnero expiatorio con que se hará la expiación por el culpable.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, '“Toda ofrenda alzada de todas las cosas santificadas que los hijos de Israel presentaren al sacerdote, a este pertenecerá.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Las (demás) cosas ofrecidas por cualquier persona pertenecen a esta; mas lo que uno da al sacerdote, a este le pertenecerá.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, '“Habla a los hijos de Israel y diles: Si la mujer de un hombre fornicare, cometiendo contra él infidelidad,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'y otro hombre se acostare con ella en relación carnal, sin saberlo el marido y quedando el hecho oculto —porque cuando ella se mancilló no hubo testigo contra ella, ni fue sorprendida—');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'si viniere sobre el (marido) espíritu de celos, de modo que tenga celos de su mujer, porque ella se ha mancillado, o si viniere espíritu de celos sobre él, de modo que tenga celos de su mujer, sin que ella se hubiese mancillado;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'entonces ese hombre llevará a su mujer al sacerdote, ofreciendo por ella, en oblación, un décimo de efa de harina de cebada, sin derramar aceite encima, ni poner sobre ella incienso; porque es ofrenda de celos, ofrenda de recuerdo, que trae el pecado a la memoria.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Luego el sacerdote hará que (la mujer) se acerque, y la colocará delante de Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'Y tomará el sacerdote agua santa en una vasija de barro, y polvo del suelo de la Morada, y lo echará en el agua.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'El sacerdote, después de mandar que la mujer se ponga de pie delante de Yahvé, soltará la cabellera de la mujer, y pondrá en sus manos la ofrenda de recuerdo, que es la ofrenda de los celos, teniendo él en su mano el agua amarga que acarrea maldición.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'Y conjurará el sacerdote a la mujer diciendo: Si no se ha acostado contigo ninguno, y si no te has descarriado contaminándote con quien no es tu marido, no te hará daño esta agua amarga que acarrea maldición.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Mas si te has descarriado con quien no es tu marido, y te has contaminado acostándose contigo algún hombre, que no sea tu marido,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'entonces el sacerdote conjurará a la mujer con juramento de maldición, y le dirá: “¡Que te ponga Yahvé por ejemplo de maldición e imprecación en medio de tu pueblo, y haga Yahvé que enflaquezcan tus caderas y se hinche tu vientre!');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, '¡Entre en tus entrañas esta agua que acarrea maldición, para que se hinche tu vientre y enflaquezcan tus caderas!” Y dirá la mujer: “¡Amén amén!”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Luego el sacerdote escribirá estas maldiciones en un rollo y las desleirá en las aguas amargas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'Y hará beber a la mujer el agua amarga que acarrea maldición; y penetrará en ella el agua de maldición para serle amarga.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Después tomará el sacerdote de mano de la mujer la oblación de celos, la mecerá ante Yahvé, y la presentará delante del altar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'Y tomando de la oblación un puñado como ofrenda de recuerdo, lo quemará en el altar; después dará de beber a la mujer el agua.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Dándosele a ella el agua sucederá que si ella se ha deshonrado, siendo infiel a su marido, en tal caso penetrará en ella el agua de maldición para serle amarga; y se le hinchará el vientre y enflaquecerán sus caderas, de modo que aquella mujer será una execración en medio de su pueblo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Pero si la mujer no se ha mancillado, siendo pura, quedará ilesa y tendrá hijos.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Esta es la ley de los celos, cuando una mujer se ha descarriado contaminándose con quien no es su marido;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'o cuando sobre un hombre viene espíritu de celos, de modo que tenga celos de su mujer: presentará a la mujer ante Yahvé, y el sacerdote hará con ella según toda esta ley.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'El marido quedará así libre de culpa, pero la mujer pagará su iniquidad.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, '“Habla a los hijos de Israel y diles: Si un hombre o una mujer hace un voto especial, el voto de nazareo, consagrándose a Yahvé,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'se abstendrá de vino y de bebida embriagante, no beberá vinagre de vino ni de (otra) bebida embriagante; no tomará zumo de uvas, ni comerá uvas frescas ni secas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'En todos los días de su nazareato no comerá producto alguno de la vid, desde los granos hasta el hollejo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Durante todo el tiempo de su voto de nazareato, no pasará navaja sobre su cabeza. Hasta cumplirse los días por los que se consagró a Yahvé, quedará santo, y dejará crecer libremente su cabellera.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'En todos los días de su consagración a Yahvé no entrará donde haya un muerto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'No ha de contaminarse (haciendo luto) por la muerte de su padre, ni de su madre, ni de su hermano, ni de su hermana; porque la consagración de su Dios está sobre su cabeza.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Durante todo el tiempo de su nazareato está consagrado a Yahvé.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Si junto a él muriere uno de repente, contaminándose así la cabeza de su nazareato, raerá su cabeza el día de su purificación; el día séptimo la raerá.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'Y al día octavo presentará al sacerdote dos tórtolas o dos palominos a la entrada del Tabernáculo de la Reunión.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'El sacerdote ofrecerá el uno por el pecado, y el otro como holocausto, haciendo por él la expiación a causa del pecado en el caso del muerto; y en ese mismo día consagrará (de nuevo) su cabeza.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'Renovará ante Yahvé los días de su nazareato, y presentará un cordero primal por la culpa. Los días precedentes serán nulos, porque fue contaminado su nazareato.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Esta es la ley del nazareo. Al cumplirse los días de su nazareato, será conducido a la entrada del Tabernáculo de la Reunión;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'y presentará como oblación suya a Yahvé un cordero primal sin tacha, en holocausto, una cordera primal sin tacha, para el sacrificio por el pecado, y un carnero sin tacha, para el sacrificio pacífico,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'un canasto de panes ácimos, tortas de flor de harina amasadas con aceite, y galletas sin levadura untadas de aceite, juntamente con la oblación y las libaciones respectivas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'El sacerdote lo presentará delante de Yahvé, y ofrecerá su sacrificio por el pecado y su holocausto.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Ofrecerá también a Yahvé el carnero como sacrificio pacífico, junto con el canasto de los panes ácimos; después presentará el sacerdote la ofrenda y la libación.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'El nazareo raerá la cabeza de su nazareato a la entrada del Tabernáculo de la Reunión; y tomando su cabellera consagrada, la echara al fuego que arde debajo del sacrificio pacífico.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'El sacerdote tomará entonces la espaldilla, ya cocida, del carnero, una torta ácima del canasto y una galleta sin levadura, y los pondrá en las manos del nazareo, después que este se haya raído la cabeza consagrada.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Y los mecerá el sacerdote como ofrenda mecida ante Yahvé —es cosa santa que pertenece al sacerdote, a más del pecho mecido y de la espaldilla alzada— y después podrá el nazareo beber vino.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Esta es la ley del nazareo que ha hecho voto, y de su oblación a Yahvé con motivo de su nazareato, fuera de lo que agregue según sus recursos. Conforme al voto que haya hecho, así ha de hacer, además de lo ordenado por la ley del nazareato.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Habló Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, '“Habla a Aarón y a sus hijos, y diles: De esta manera bendeciréis a los hijos de Israel; les diréis:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, '¡Yahvé te bendiga y te guarde!');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, '¡Haga Yahvé brillar sobre ti su Rostro y tenga misericordia de ti!');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, '¡Vuelva Yahvé su Rostro hacia ti y te conceda la paz!');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Así pondrán mi Nombre sobre los hijos de Israel, y Yo los bendeciré.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'Después de haber terminado Moisés la erección de la Morada y la unción y santificación de la misma con todos sus utensilios, y la unción y santificación del altar con todos sus utensilios,');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'presentaron sus ofrendas los príncipes de Israel, las cabezas de sus casas paternas: ellos eran los príncipes de las tribus, quienes habían presidido el censo.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'Presentaron como ofrenda suya delante de Yahvé, seis carros cubiertos y doce bueyes: un carro por cada dos príncipes, y un buey por cada uno de ellos, y los llevaron ante la Morada.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Habló entonces Yahvé a Moisés, diciendo:');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, '“Recibe de ellos estas cosas, para que sean destinadas al servicio del Tabernáculo de la Reunión; las darás a los levitas, a cada cual según su servicio.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Recibió, pues, Moisés los carros y los bueyes, y los entregó a los levitas.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Dio dos carros con cuatro bueyes a los hijos de Gersón, según las necesidades de su servicio.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'Cuatro carros con ocho bueyes dio a los hijos de Merarí, según las necesidades de su servicio (que cumplían) bajo la dirección de Itamar, hijo del sacerdote Aarón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Pero no dio nada a los hijos de Caat, porque a su cargo estaba el servicio de aquellos objetos sagrados cuyo transporte se hacía llevándolos a hombros.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Los príncipes presentaron también ofrendas para la dedicación del altar; el día en que fue ungido presentaron ellos mismos sus ofrendas ante el altar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Y Yahvé dijo a Moisés: “Que cada día uno de los príncipes presente su ofrenda para la dedicación del altar.”');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'El que presentó su oblación el día primero fue Naasón, hijo de Aminadab, de la tribu de Judá.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Era su ofrenda una fuente de plata, que pesaba ciento treinta siclos, una taza de plata de setenta siclos, según el siclo del Santuario, ambas llenas de flor de harina amasada con aceite, para la oblación;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'una naveta de oro de diez siclos, llena de incienso;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'un novillo, un carnero y un cordero primal para el holocausto;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'un macho cabrío para el sacrificio por el pecado;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'y para el sacrificio pacífico dos bueyes, cinco carneros, cinco machos cabríos y cinco corderos primales. Esta fue la ofrenda de Naasón, hijo de Aminadab.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'El segundo día presentó su ofrenda Natanael, hijo de Suar, príncipe de Isacar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Trajo como ofrenda suya una fuente de plata, que pesaba ciento treinta siclos, una taza de plata de setenta siclos, según él siclo del Santuario, ambas llenas de flor de harina amasada con aceite, para la oblación;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'una naveta de oro de diez siclos, llena de incienso;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'un novillo, un carnero y un cordero primal para el holocausto;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'un macho cabrío para el sacrificio por el pecado;');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'y para el sacrificio pacífico dos bueyes, cinco carneros, cinco machos cabríos y cinco corderos primales. Esta fue la ofrenda de Natanael, hijo de Suar.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'El tercer día (llegó) el príncipe de los hijos de Zabulón, Eliab, hijo de Helón.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'Era su ofrenda una fuente de plata, que pesaba ciento treinta siclos, una taza de plata de setenta siclos, según el siclo del Santuario, ambas llenas de flor de harina amasada con aceite, para la oblación;');
