INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'El cuarto día (se presentó) el príncipe de los hijos de Rubén, Elisur, hijo de Sedeur.');
