INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 42, 'EI sexto día (presentó su ofrenda) el príncipe de los hijos de Gad, Eliasaf, hijo de Deuel.');
INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 43, 'Era su ofrenda una fuente de plata, que pesaba ciento treinta siclos, una taza de plata de setenta siclos, según el siclo del Santuario, ambas llenas de flor de harina, amasada con aceite, para la oblación;');
