INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 48, 'El séptimo día (se presentó) el príncipe de los hijos de Efraím, Elisamá, hijo de Amiud.');
