INSERT INTO `SpaPlatense_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 54, 'El octavo día (llegó) el príncipe de los hijos de Manasés, Gamaliel, hijo de Pedasur.');
